/// { 0x6f6c00 } (ret 0xc, match_pl.cpp): ver `chute_com`.
unsafe extern "thiscall" fn chute(j: usize, forca: u32, x: u32, y: u32) {
    chute_com(j, forca as i16, x as i8, y as i8, &mut |rotina, this, a| despachar_dividida(rotina, this, a))
}

unsafe extern "thiscall" fn comparar_chute(j: usize, forca: u32, x: u32, y: u32) {
    let o = orig::<unsafe extern "thiscall" fn(usize, u32, u32, u32)>(301);
    if gravando_no_topo() {
        return o(j, forca, x, y);
    }
    let m = *((j + 0x19e) as *const usize);
    let mut reg = crate::aleatorio::REGIOES_DO_ESTADO.to_vec();
    reg.extend([(m, MOTOR), (0xb67a34, 4), (0xae1080, 4)]);
    let t = *((m + 0x4792) as *const usize);
    for clube in [*((t + 0x1c) as *const usize), *((t + 0x20) as *const usize)] {
        reg.extend(linhas_do_clube(clube));
    }
    let gravar = GRAVAR_716.swap(true, std::sync::atomic::Ordering::Relaxed);
    let (_, _, igual, sequencia, k) = comparar_com_fita(reg, || o(j, forca, x, y), |chamar| {
        chute_com(j, forca as i16, x as i8, y as i8, &mut |rotina, this, args| {
            let mascara = match rotina {
                0x6d6f70 => [0xffff, u32::MAX, 0xff, 0xff, 0xff],
                0x6cd770 => [0xff, 0xff, 0xffff, 0xff, u32::MAX],
                0x62ed70 => [u32::MAX, 0, 0, 0, 0],
                0x6d0980 => [0xff, 0xff, u32::MAX, u32::MAX, 0],
                0x897760 => [u32::MAX, 0xff, u32::MAX, 0, 0],
                0x6e1aa0 | 0x716c90 | 0x6f0630 | 0x7103e0 => [0, 0, 0, 0, 0],
                _ => [0xff, 0, 0, 0, 0],
            };
            chamar(rotina, this, args, mascara)
        })
    });
    GRAVAR_716.store(gravar, std::sync::atomic::Ordering::Relaxed);
    PLACAR.registrar(igual && sequencia, || format!("chute(forca {}, alvo {} {}) {} chamadas: {}", forca as i16, x as i8, y as i8, k, detalhe_fita()));
}

// ---------- centesima trigesima setima leva: a nota do arbitro (0x6d4a20, 0x79ce10) ----------

/// { 0x79ce10 } (ret 4, officials_manager.cpp): soma a nota `r` (dword id, bytes: cartoes, faltas,
/// nota) na ficha do arbitro (17 bytes em [this] + id x 17, id em 0..[0xae2390]): +0xf os cartoes,
/// as palavras +8 e +0xa as faltas e a nota, +0x10 a ultima nota, +0xc os jogos e +4 a media
/// (+0xa / +0xc, float).
unsafe extern "thiscall" fn registrar_nota_do_arbitro(this: usize, r: *const u8) {
    let base = *(this as *const usize);
    if base == 0 || r.is_null() {
        return;
    }
    let id = *(r as *const i32);
    if id < 0 || id >= *(0xae2390 as *const i32) {
        return;
    }
    let f = base + id as usize * 17;
    let b = |o: usize| (f + o) as *mut u8;
    let w = |o: usize| (f + o) as *mut i16;
    *b(0xf) = (*b(0xf)).wrapping_add(*r.add(4));
    *w(8) = (*w(8)).wrapping_add(*r.add(5) as i8 as i16);
    *w(0xa) = (*w(0xa)).wrapping_add(*r.add(6) as i8 as i16);
    *b(0x10) = *r.add(6);
    *w(0xc) = (*w(0xc)).wrapping_add(1);
    if *w(0xc) != 0 {
        *((f + 4) as *mut f32) = (*w(0xa) as f64 / *w(0xc) as f64) as f32;
    }
}

/// { 0x6d4a20 } (match_eng.cpp, chamada pela 0x6b98c0): a nota do arbitro da partida (+0xf5b6, id
/// != -1), fora das competicoes amistosas (0x5c6710 em [0xae2c74]). Os cartoes (+0xf5cb e +0xf601 dos
/// dois lados) e as faltas (+0xf5cc e +0xf602); a nota parte de +0xf5ba / 1000, perde 2 com mais de 2
/// cartoes, 1 com 2, ganha 1 sem cartao; perde 1 com mais de 5 faltas, ganha 1 com menos de 3. Abaixo
/// de 4 vira 4 (salvo 1 em 500), acima de 8 vira 8 (salvo 1 em 25), e fica entre 1 e 10. Grava pela
/// 0x79ce10 em [0xb74340].
unsafe extern "thiscall" fn nota_do_arbitro(m: usize) {
    let arbitro = *((m + 0xf5b6) as *const usize);
    if arbitro == 0 || *(arbitro as *const i32) == -1 {
        return;
    }
    let partida = *((m + 0x4792) as *const usize);
    if partida == 0 {
        return;
    }
    let comp = *((partida + 0x14) as *const usize);
    if comp == 0 {
        return;
    }
    let amistosos = *(0xae2c74 as *const usize);
    if amistosos != 0 {
        let amistosa: unsafe extern "thiscall" fn(usize, usize) -> u32 = core::mem::transmute(0x5c6710usize);
        if amistosa(amistosos, comp) != 0 {
            crate::comparacao::ramo("nota do arbitro amistoso");
            return;
        }
    }
    let cartoes = (*((m + 0xf601) as *const u8)).wrapping_add(*((m + 0xf5cb) as *const u8)) as i8;
    let faltas = (*((m + 0xf602) as *const u8)).wrapping_add(*((m + 0xf5cc) as *const u8)) as i8;
    let mut nota = (*((m + 0xf5ba) as *const i16) as i32 / 1000) as i8;
    if cartoes > 2 {
        nota = nota.wrapping_sub(2);
    } else if cartoes > 1 {
        nota = nota.wrapping_sub(1);
    } else if cartoes == 0 {
        nota = nota.wrapping_add(1);
    }
    if faltas > 5 {
        nota = nota.wrapping_sub(1);
    } else if faltas < 3 {
        nota = nota.wrapping_add(1);
    }
    if nota < 4 && sortear(500) != 0 {
        nota = 4;
    } else if nota > 8 && sortear(0x19) != 0 {
        nota = 8;
    } else if nota < 1 {
        crate::comparacao::ramo("nota do arbitro minima");
        nota = 1;
    } else if nota > 10 {
        crate::comparacao::ramo("nota do arbitro maxima");
        nota = 10;
    }
    let mut r = [0u8; 8];
    r[..4].copy_from_slice(&(*(arbitro as *const i32)).to_le_bytes());
    r[4] = cartoes as u8;
    r[5] = faltas as u8;
    r[6] = nota as u8;
    let registrar: unsafe extern "thiscall" fn(usize, *const u8) = core::mem::transmute(0x79ce10usize);
    registrar(*(0xb74340 as *const usize), r.as_ptr());
}

/// A ficha do arbitro que a 0x79ce10 mexe (vazia se o id nao vale).
unsafe fn ficha_do_arbitro(gerente: usize, id: i32) -> Vec<(usize, usize)> {
    let base = *(gerente as *const usize);
    if base == 0 || id < 0 || id >= *(0xae2390 as *const i32) {
        return Vec::new();
    }
    vec![(base + id as usize * 17, 17)]
}

unsafe extern "thiscall" fn comparar_registrar_nota_do_arbitro(this: usize, r: *const u8) {
    let o = orig::<unsafe extern "thiscall" fn(usize, *const u8)>(303);
    if gravando_no_topo() || r.is_null() {
        return o(this, r);
    }
    let reg = ficha_do_arbitro(this, *(r as *const i32));
    let (_, _, igual, mo, mr) = crate::comparacao::lado_a_lado(&reg, || o(this, r), || registrar_nota_do_arbitro(this, r));
    PLACAR.registrar(igual, || format!("registrar_nota_do_arbitro(nota {}) {:x?} x {:x?}", *r.add(6), mo, mr));
}

unsafe extern "thiscall" fn comparar_nota_do_arbitro(m: usize) {
    let o = orig::<unsafe extern "thiscall" fn(usize)>(302);
    if gravando_no_topo() {
        return o(m);
    }
    // o sorteio e a ficha do arbitro
    let mut reg = crate::aleatorio::REGIOES_DO_ESTADO.to_vec();
    let arbitro = *((m + 0xf5b6) as *const usize);
    if arbitro != 0 && *(0xb74340 as *const usize) != 0 {
        reg.extend(ficha_do_arbitro(*(0xb74340 as *const usize), *(arbitro as *const i32)));
    }
    let (_, _, igual, mo, mr) = crate::comparacao::lado_a_lado(&reg, || o(m), || nota_do_arbitro(m));
    PLACAR.registrar(igual, || format!("nota_do_arbitro {:x?} x {:x?}", mo, mr));
}

// ---------- centesima trigesima oitava leva: o batedor guardado, as instrucoes guardadas e o codigo da competicao ----------

/// { 0x897990 } (ret 0x10, tactics.cpp): quem bate a bola parada `tipo` (0..=4) no lado `lado`
/// (0..=1) pelo clube: a celula (dword) na linha tatica do clube (0x8982b0 com `humano`) em +0x601 +
/// linha x 0x91 + 0x5e + (lado + tipo x 2) x 4. Acima de [0xae2364] + 0x52d a celula vira -1 (0);
/// negativa, 0. A pessoa (0x6e bytes em [0xae23bc]) sem +0x61 apaga a celula (0); do clube (+0x39),
/// numa selecao (0x53b900) ou com o vinculo das selecoes (0x775790 em [0xb74318]) e devolvida; senao
/// a celula vira -1 (0). Clube nulo, tipo ou lado fora: a original (caixa de erro).
unsafe extern "thiscall" fn batedor_guardado(this: usize, clube: usize, tipo: u32, lado: u32, humano: u32) -> usize {
    let (t, l) = (tipo as u8 as i8, lado as u8 as i8);
    if clube == 0 || !(0..=4).contains(&t) || !(0..=1).contains(&l) {
        return orig::<unsafe extern "thiscall" fn(usize, usize, u32, u32, u32) -> usize>(304)(this, clube, tipo, lado, humano);
    }
    let linha: unsafe extern "stdcall" fn(usize, u32) -> i32 = core::mem::transmute(0x8982b0usize);
    let k = linha(clube, humano);
    if k == -1 {
        crate::comparacao::ramo("batedor sem linha");
        return 0;
    }
    let celula = (*((this + 0x601) as *const usize)).wrapping_add(k as usize * 0x91 + 0x5e + (l as i32 + t as i32 * 2) as usize * 4) as *mut i32;
    let v = *celula;
    if v > (*(0xae2364 as *const i32)).wrapping_add(0x52d) {
        crate::comparacao::ramo("batedor alem das pessoas");
        *celula = -1;
        return 0;
    }
    if v <= -1 {
        crate::comparacao::ramo("batedor vazio");
        return 0;
    }
    let pessoa = (*(0xae23bc as *const usize)).wrapping_add(v as usize * 0x6e);
    if *((pessoa + 0x61) as *const u32) == 0 {
        crate::comparacao::ramo("batedor sem ficha");
        *celula = -1;
        return 0;
    }
    if *((pessoa + 0x39) as *const usize) == clube {
        crate::comparacao::ramo("batedor do clube");
        return pessoa;
    }
    let selecao: unsafe extern "C" fn(usize) -> u32 = core::mem::transmute(0x53b900usize);
    let vinculo: unsafe extern "thiscall" fn(usize, usize) -> u32 = core::mem::transmute(0x775790usize);
    if selecao(clube) != 0 || vinculo(*(0xb74318 as *const usize), clube) != 0 {
        crate::comparacao::ramo("batedor de fora do clube");
        return pessoa;
    }
    crate::comparacao::ramo("batedor saiu do clube");
    *celula = -1;
    0
}

/// { 0x896fe0 } (ret 0x10, tactics.cpp): guarda (`volta` 0) ou devolve (`volta` != 0) as 20
/// instrucoes (dwords em +0x601 + linha x 0x91 + 2, linha da 0x8982b0 com `pessoa`) do clube num dos
/// 16 espacos de 0x5c bytes a partir de +0x30 (clube +0x30, pessoa +0x34, ocupado +0x38, instrucoes
/// +0x3c; ocupados em +0x5f0). O espaco e o do humano da vez ([0xb74c26 + [0xb77c7a] x 0x300]):
/// [0xae2364] - id dele - 1, em 0..16. Guardando (com `usar`), marca o espaco e copia; depois as 20
/// instrucoes viram -1. Devolvendo com `usar`, o espaco do mesmo clube e pessoa volta para a tabela
/// e e liberado; sem `usar`, libera todos os espacos do clube e pessoa. Clube nulo: a original (caixa
/// de erro); linha -1: 0; senao 1.
unsafe extern "thiscall" fn guardar_instrucoes(this: usize, clube: usize, pessoa: u32, usar: u32, volta: u32) -> u32 {
    if clube == 0 {
        return orig::<unsafe extern "thiscall" fn(usize, usize, u32, u32, u32) -> u32>(305)(this, clube, pessoa, usar, volta);
    }
    let linha: unsafe extern "stdcall" fn(usize, u32) -> i32 = core::mem::transmute(0x8982b0usize);
    let k = linha(clube, pessoa);
    if k == -1 {
        return 0;
    }
    let instrucao = |i: usize| (*((this + 0x601) as *const usize)).wrapping_add(k as usize * 0x91 + 2 + 4 * i) as *mut u32;
    let ocupados = (this + 0x5f0) as *mut u8;
    // o espaco do humano da vez, se houver
    let espaco = || {
        let humano = *((0xb74c26 + *(0xb77c7a as *const i16) as isize as usize * 0x300) as *const usize);
        if humano == 0 {
            return None;
        }
        let e = (*(0xae2364 as *const i32)).wrapping_sub(*(humano as *const i32)).wrapping_sub(1);
        if (0..16).contains(&e) { Some(this + e as usize * 0x5c) } else { None }
    };
    let u = |p: usize, o: usize| (p + o) as *mut u32;
    if volta == 0 {
        if usar != 0 {
            if let Some(s) = espaco() {
                crate::comparacao::ramo("instrucoes guardadas");
                if *u(s, 0x38) == 0 {
                    *ocupados = (*ocupados).wrapping_add(1);
                }
                *u(s, 0x30) = clube as u32;
                *u(s, 0x34) = pessoa;
                *u(s, 0x38) = 1;
                for i in 0..20 {
                    *u(s, 0x3c + 4 * i) = *instrucao(i);
                }
            }
        }
        crate::comparacao::ramo("instrucoes apagadas");
        for i in 0..20 {
            *instrucao(i) = u32::MAX;
        }
        return 1;
    }
    if usar != 0 {
        if let Some(s) = espaco() {
            if *u(s, 0x38) != 0 && *u(s, 0x30) == clube as u32 && *u(s, 0x34) == pessoa {
                crate::comparacao::ramo("instrucoes devolvidas");
                for i in 0..20 {
                    *instrucao(i) = *u(s, 0x3c + 4 * i);
                }
            }
            if *u(s, 0x38) != 0 {
                *ocupados = (*ocupados).wrapping_sub(1);
            }
            *u(s, 0x38) = 0;
        }
        return 1;
    }
    if *ocupados != 0 {
        for e in 0..16 {
            let s = this + e * 0x5c;
            if *u(s, 0x38) != 0 && *u(s, 0x30) == clube as u32 && *u(s, 0x34) == pessoa {
                crate::comparacao::ramo("instrucoes liberadas");
                *u(s, 0x38) = 0;
                *ocupados = (*ocupados).wrapping_sub(1);
            }
        }
    }
    1
}

/// { 0x6b6570 } (cdecl, match_day.cpp): o numero da competicao pelo codigo (0: 5/4, 1: 11/10, 0x1ef:
/// 1/0, 0x3de: 3/2, 0x483: 7/6, 0x528: 9/8; o primeiro com `segunda` 1). Outro codigo: a original
/// (caixa de erro).
unsafe extern "C" fn numero_da_competicao(codigo: u32, segunda: u32) -> u32 {
    let s = (segunda as u8 == 1) as u32;
    crate::comparacao::ramo("numero da competicao");
    match codigo as u16 as i16 {
        0 => 4 + s,
        1 => 10 + s,
        0x1ef => s,
        0x3de => 2 + s,
        0x483 => 6 + s,
        0x528 => 8 + s,
        _ => orig::<unsafe extern "C" fn(u32, u32) -> u32>(306)(codigo, segunda),
    }
}

unsafe extern "thiscall" fn comparar_batedor_guardado(this: usize, clube: usize, tipo: u32, lado: u32, humano: u32) -> usize {
    let o = orig::<unsafe extern "thiscall" fn(usize, usize, u32, u32, u32) -> usize>(304);
    let (t, l) = (tipo as u8 as i8, lado as u8 as i8);
    if gravando_no_topo() || clube == 0 || !(0..=4).contains(&t) || !(0..=1).contains(&l) {
        return o(this, clube, tipo, lado, humano);
    }
    let linha: unsafe extern "stdcall" fn(usize, u32) -> i32 = core::mem::transmute(0x8982b0usize);
    let k = linha(clube, humano);
    let mut reg = vec![(0xb67a34, 4)];
    if k != -1 {
        reg.push(((*((this + 0x601) as *const usize)).wrapping_add(k as usize * 0x91 + 0x5e + (l as i32 + t as i32 * 2) as usize * 4), 4));
    }
    let (r, n, igual, mo, mr) = crate::comparacao::lado_a_lado(&reg, || o(this, clube, tipo, lado, humano), || batedor_guardado(this, clube, tipo, lado, humano));
    PLACAR.registrar(igual && r == n, || format!("batedor_guardado(tipo {} lado {}) original={:#x} rust={:#x} {:x?} x {:x?}", t, l, r, n, mo, mr));
    r
}

unsafe extern "thiscall" fn comparar_guardar_instrucoes(this: usize, clube: usize, pessoa: u32, usar: u32, volta: u32) -> u32 {
    let o = orig::<unsafe extern "thiscall" fn(usize, usize, u32, u32, u32) -> u32>(305);
    if gravando_no_topo() || clube == 0 {
        return o(this, clube, pessoa, usar, volta);
    }
    let linha: unsafe extern "stdcall" fn(usize, u32) -> i32 = core::mem::transmute(0x8982b0usize);
    let k = linha(clube, pessoa);
    // os 16 espacos e o contador, e a linha de instrucoes do clube
    let mut reg = vec![(this + 0x30, 0x5c * 16), (this + 0x5f0, 1)];
    if k != -1 {
        reg.push(((*((this + 0x601) as *const usize)).wrapping_add(k as usize * 0x91 + 2), 80));
    }
    let (r, n, igual, mo, mr) = crate::comparacao::lado_a_lado(&reg, || o(this, clube, pessoa, usar, volta), || guardar_instrucoes(this, clube, pessoa, usar, volta));
    PLACAR.registrar(igual && r == n, || format!("guardar_instrucoes(usar {} volta {}) original={} rust={} {:x?} x {:x?}", usar, volta, r, n, mo, mr));
    r
}

unsafe extern "C" fn comparar_numero_da_competicao(codigo: u32, segunda: u32) -> u32 {
    let o = orig::<unsafe extern "C" fn(u32, u32) -> u32>(306);
    let r = o(codigo, segunda);
    if matches!(codigo as u16 as i16, 0 | 1 | 0x1ef | 0x3de | 0x483 | 0x528) {
        let n = numero_da_competicao(codigo, segunda);
        PLACAR.registrar(r as u8 == n as u8, || format!("numero_da_competicao({:#x}, {}) original={} rust={}", codigo as u16, segunda as u8, r as u8, n as u8));
    }
    r
}

// ---------- centesima quadragesima leva: a linha tatica (0x8983f0, 0x8984d0) e a simulacao rapida (0x6beeb0) ----------

/// { 0x8983f0 } (ret 0xc, tactics.cpp): copia a linha tatica do clube (0x91 bytes em +0x601 + linha
/// x 0x91, linha da 0x8982b0 com `humano`) para `destino`. Clube nulo: a original (caixa de erro);
/// linha -1: 0; senao 1.
unsafe extern "thiscall" fn ler_linha_tatica(this: usize, clube: usize, destino: *mut u8, humano: u32) -> u32 {
    if clube == 0 {
        return orig::<unsafe extern "thiscall" fn(usize, usize, *mut u8, u32) -> u32>(310)(this, clube, destino, humano);
    }
    let linha: unsafe extern "stdcall" fn(usize, u32) -> i32 = core::mem::transmute(0x8982b0usize);
    let k = linha(clube, humano);
    if k == -1 {
        return 0;
    }
    crate::comparacao::ramo("linha tatica lida");
    core::ptr::copy((*((this + 0x601) as *const usize)).wrapping_add(k as usize * 0x91) as *const u8, destino, 0x91);
    1
}

/// { 0x8984d0 } (ret 0xc, tactics.cpp): o inverso da 0x8983f0, grava `origem` (0x91 bytes) na linha
/// tatica do clube. Linha -1 ou alem do total (+0x605): 0.
unsafe extern "thiscall" fn gravar_linha_tatica(this: usize, clube: usize, origem: *const u8, humano: u32) -> u32 {
    if clube == 0 {
        return orig::<unsafe extern "thiscall" fn(usize, usize, *const u8, u32) -> u32>(311)(this, clube, origem, humano);
    }
    let linha: unsafe extern "stdcall" fn(usize, u32) -> i32 = core::mem::transmute(0x8982b0usize);
    let k = linha(clube, humano);
    if k == -1 || k >= *((this + 0x605) as *const i32) {
        return 0;
    }
    crate::comparacao::ramo("linha tatica gravada");
    core::ptr::copy(origem, (*((this + 0x601) as *const usize)).wrapping_add(k as usize * 0x91) as *mut u8, 0x91);
    1
}

/// Regioes das duas: o destino/origem e a linha do clube (se houver).
unsafe fn regioes_da_linha_tatica(this: usize, clube: usize, p: usize, humano: u32) -> Vec<(usize, usize)> {
    let linha: unsafe extern "stdcall" fn(usize, u32) -> i32 = core::mem::transmute(0x8982b0usize);
    let k = linha(clube, humano);
    let mut reg = vec![(0xb67a34, 4), (p, 0x91)];
    if k != -1 && k < *((this + 0x605) as *const i32) {
        reg.push(((*((this + 0x601) as *const usize)).wrapping_add(k as usize * 0x91), 0x91));
    }
    reg
}

unsafe extern "thiscall" fn comparar_ler_linha_tatica(this: usize, clube: usize, destino: *mut u8, humano: u32) -> u32 {
    let o = orig::<unsafe extern "thiscall" fn(usize, usize, *mut u8, u32) -> u32>(310);
    if gravando_no_topo() || clube == 0 {
        return o(this, clube, destino, humano);
    }
    let reg = regioes_da_linha_tatica(this, clube, destino as usize, humano);
    let (r, n, igual, mo, mr) = crate::comparacao::lado_a_lado(&reg, || o(this, clube, destino, humano), || ler_linha_tatica(this, clube, destino, humano));
    PLACAR.registrar(igual && r == n, || format!("ler_linha_tatica(humano {}) original={} rust={} {:x?} x {:x?}", humano, r, n, mo, mr));
    r
}

unsafe extern "thiscall" fn comparar_gravar_linha_tatica(this: usize, clube: usize, origem: *const u8, humano: u32) -> u32 {
    let o = orig::<unsafe extern "thiscall" fn(usize, usize, *const u8, u32) -> u32>(311);
    if gravando_no_topo() || clube == 0 {
        return o(this, clube, origem, humano);
    }
    let reg = regioes_da_linha_tatica(this, clube, origem as usize, humano);
    let (r, n, igual, mo, mr) = crate::comparacao::lado_a_lado(&reg, || o(this, clube, origem, humano), || gravar_linha_tatica(this, clube, origem, humano));
    PLACAR.registrar(igual && r == n, || format!("gravar_linha_tatica(humano {}) original={} rust={} {:x?} x {:x?}", humano, r, n, mo, mr));
    r
}

/// { 0x6beeb0 } (match_eng.cpp, chamada pelo passo do motor 0x6b98c0) com as chamadas que mexem fora
/// do motor injetadas (0x6d6f70 narra, 0x6d0980 lesiona; e as da saida do jogador 0x6cda20): a
/// partida simulada sem lances, em periodos de duas rodadas (contador +0x8ed0, codigo do periodo
/// +0x8ed4). Por periodo: a forca dos times (0x6c0c60) com quatro pares limitados entre metade e o
/// dobro do lado 1, e o lado que comeca (sorteio(2)). Por rodada, do lado da vez: tres ataques (o
/// terceiro so se o lado vencer o sorteio de forca) com duelo de um jogador ativo (+0xc5 + 20 contra
/// a forca do outro); o segundo duelo (0x6c2880, +0xdd + 15) e o terceiro (+0xad + 15); o desgaste
/// (0x6c2750, +0xb9 + 20); os cartoes do outro lado (expulsao 0x6c2310 modo 4, amarelo modo 2, o
/// segundo amarelo expulsa; mais de 4 expulsos e abandono, 3 x 0); o tipo do lance; o fator do placar
/// (diferenca, 1, 0,65 depois dos 60 ou 0,75), a disputa (0x6c06b0/0x6c07a0 ou 0x6c0a70) e, com
/// vantagem, o chute (0x6c23f0, 0x6c0890/0x6c0980) e o gol (0x6c2050; goleiros 0x717410; narra
/// 0x1fcc ou 0x1fcf, ou 0x1fce no erro do penalti). Nos minutos 45, 90, 105 e 120 grava os placares
/// (+0x45, +0x43, +0x47) e decide prorrogacao, gol de ouro (+0x38 & 0x80) e penaltis (+0x49/+0x4a,
/// sorteio(5)); o agregado (+0x4b/+0x4c). Depois: o gol do mando (sorteio(4) com placar igual), as
/// lesoes do ultimo lado da vez (0x6d0980), as notas (amistoso -2: ajuste pela reputacao do clube) e
/// os contadores +0xf5e2/+0xf618.
unsafe fn simulacao_rapida_com(m: usize, chamar: &mut dyn FnMut(usize, usize, [u32; 5]) -> u32) {
    let u = |p: usize, o: usize| *((p + o) as *const usize);
    let w = |o: usize| (m + o) as *mut i16;
    let b = |o: usize| (m + o) as *mut u8;
    let mais = |p: *mut u8| *p = (*p).wrapping_add(1);
    let mais16 = |p: *mut i16| *p = (*p).wrapping_add(1);
    let palavra = |o: usize, lado: usize| *((m + o + 2 * lado) as *const i16) as i32;
    let jog = |lado: usize, i: i8| (m as isize + 0x4796 + (i as isize + lado as isize * 20) * 0x1be) as usize;
    let somar = |p: usize, d: i16| {
        let q = (p + 0x35) as *mut i16;
        *q = (*q).wrapping_add(d);
    };
    let pt = || u(m, 0x4792);
    let pb = |o: usize| (u(m, 0x4792) + o) as *mut i8;
    let gols = |lado: usize| *b(0xf5bd + lado * 0x36) as i32;
    let narrar = |chamar: &mut dyn FnMut(usize, usize, [u32; 5]) -> u32, codigo: u32, c: u8, lado: usize| {
        chamar(0x6d6f70, u(m, 0x8f7a), [codigo, m as u32, c as u32, lado as u32, u32::MAX]);
    };
    // goleiros (tabela 1) ativos do lado sofrem o gol
    let goleiros = |lado: usize| {
        for i in 0..20 {
            let q = jog(lado, i);
            if byte(q, 0x19) >= 0 && tabela_do_jogador(q) == 1 {
                mais((q + 0xf) as *mut u8);
            }
        }
    };
    let mut fim = false;
    let mut decide = false;
    let mut local_28 = 0u8;
    let mut lado = 0usize;
    *w(0x8ed0) = 0;
    *w(0x8ed4) = 0x1ef;
    let penaltis = 'periodo: loop {
        forca_do_time(m, 0);
        forca_do_time(m, 1);
        for o in [0x1da, 0x1de, 0x1e2, 0x1e6] {
            let (a, x) = (*w(o) as f64, *w(o + 2) as f64);
            let meio = x * f64_em(0x968968);
            if !(a >= meio) {
                *w(o) = ftol(meio) as i16;
            } else if a > x + x {
                *w(o) = ftol(x + x) as i16;
            }
        }
        let c7 = sortear(2) as u8;
        let mut rodada = 0u8;
        'rodadas: while *b(0x1a8) == 0 {
            lado = if c7 != 0 { rodada as usize } else { (rodada == 0) as usize };
            let outro = (lado == 0) as usize;
            let forte = || sortear(palavra(0x1de, lado) + palavra(0x1da, lado)) > sortear(palavra(0x1da, outro) + palavra(0x1de, outro));
            // os tres ataques (o terceiro pela forca)
            for k in 0..3 {
                if k >= 2 && !forte() {
                    continue;
                }
                mais16(w(0xf5e2 + lado * 0x36));
                let mut t = 0u8;
                let i = loop {
                    let i = sortear(0x14) as i8;
                    t += 1;
                    if t >= 0x78 || byte(jog(lado, i), 0x19) >= 0 {
                        break i;
                    }
                };
                if t >= 0x78 {
                    fim = true;
                    break;
                }
                let p = jog(lado, i);
                let f = (f32_em(p + 0xc5) as f64 + f32_em(0x96afb0) as f64) as f32;
                let r = sortear((palavra(0x1da, outro) + 200) / 19);
                if !(r as f64 >= f as f64) {
                    mais16(w(0xf5e4 + lado * 0x36));
                    somar(p, 0x28);
                } else {
                    somar(p, -0x1e);
                }
            }
            if forte() {
                mais16(w(0xf5e6 + lado * 0x36));
                let c = escolher_por_papel_b(m, lado as u32);
                if c == 0xff {
                    fim = true;
                    break 'rodadas;
                }
                let p = jog(lado, c as i8);
                let f = (f32_em(p + 0xdd) as f64 + f32_em(0x96b020) as f64) as f32;
                let r = sortear(palavra(0x1de, outro) / 5);
                if !(r as f64 >= f as f64) {
                    somar(p, 0x28);
                    mais16(w(0xf5e8 + lado * 0x36));
                } else {
                    somar(p, -10);
                }
            }
            if forte() {
                mais16(w(0xf5ea + lado * 0x36));
                let mut t = 0u8;
                let i = loop {
                    let i = sortear(0x14) as i8;
                    t += 1;
                    if t >= 0x78 {
                        fim = true;
                        break 'rodadas;
                    }
                    if byte(jog(lado, i), 0x19) >= 0 {
                        break i;
                    }
                };
                let p = jog(lado, i);
                let f = (f32_em(p + 0xad) as f64 + f32_em(0x96b020) as f64) as f32;
                let r = sortear((palavra(0x1f2, outro) + 100) / 7);
                if !(r as f64 >= f as f64) {
                    mais16(w(0xf5ec + lado * 0x36));
                    somar(p, 0x14);
                } else {
                    somar(p, -8);
                }
            }
            if sortear(10) == 0 {
                mais(b(0xf5c8 + lado * 0x36));
            }
            let p = jog(lado, escolher_por_papel(m, lado as u32) as i8);
            let v = ftol(f32_em(p + 0xb9) as f64 + f32_em(0x96afb0) as f64);
            if sortear(v) < sortear(2) {
                somar(p, -0xf);
                mais(b(0xf5ca + lado * 0x36));
            }
            // os cartoes do outro lado, ou o tipo do lance
            local_28 = 0;
            let mut c20 = false;
            if sortear(palavra(0x1ea, outro)) > sortear(0x640) {
                let mo = m + outro * 0x36;
                mais((mo + 0xf5c9) as *mut u8);
                let expulsar = |c: u8, chamar: &mut dyn FnMut(usize, usize, [u32; 5]) -> u32| {
                    let p = jog(outro, c as i8);
                    mais((p + 0x23) as *mut u8);
                    mais((mo + 0xf5cb) as *mut u8);
                    jogador_saiu_com(m, p, 1, chamar);
                    forca_do_time(m, outro as i8);
                    narrar(chamar, 0x1ff8, c, outro);
                };
                if sortear(palavra(0x1ea, outro)) > sortear(0x61a8) {
                    crate::comparacao::ramo("simulacao rapida expulsao");
                    let c = escolher_pela_condicao(m, outro as i8, 4);
                    somar(jog(outro, c as i8), -0xfa);
                    expulsar(c, chamar);
                } else if sortear(palavra(0x1ea, outro)) > sortear(0x6a4) {
                    crate::comparacao::ramo("simulacao rapida amarelo");
                    let c = escolher_pela_condicao(m, outro as i8, 2);
                    let p = jog(outro, c as i8);
                    somar(p, -0x32);
                    mais((p + 0x24) as *mut u8);
                    mais((mo + 0xf5cc) as *mut u8);
                    if byte(p, 0x24) == 2 {
                        crate::comparacao::ramo("simulacao rapida segundo amarelo");
                        expulsar(c, chamar);
                    }
                    if *((mo + 0xf5cb) as *const u8) > 4 {
                        // abandono: 3 x 0 para o lado da vez
                        crate::comparacao::ramo("simulacao rapida abandono");
                        fim = true;
                        *b(0xf5bd + outro * 0x36) = 0;
                        let g = b(0xf5bd + lado * 0x36);
                        if *g <= 3 {
                            *g = 3;
                        }
                        let (x, y) = if lado != 0 { (3, 0) } else { (0, 3) };
                        *pb(0x43) = x;
                        *pb(0x44) = y;
                        if *pb(0x4b) != -1 && *pb(0x43) as i32 + *pb(0x4b) as i32 == *pb(0x4c) as i32 + *pb(0x44) as i32 {
                            *pb(0x43) = (*pb(0x43)).wrapping_add(1);
                            mais(b(0xf5bd));
                        }
                        break 'rodadas;
                    }
                }
                if sortear(0x1e) != 0 {
                    c20 = true;
                    mais((mo + 0xf5c6) as *mut u8);
                } else {
                    local_28 = 1;
                }
            } else if sortear(palavra(0x1de, lado)) > sortear(3000) {
                c20 = true;
                mais(b(0xf5c7 + lado * 0x36));
            }
            // o fator do placar
            let d = gols(lado) - gols(outro);
            let saldo = if lado == 0 { *pb(0x4b) as i32 - *pb(0x4c) as i32 } else { *pb(0x4c) as i32 - *pb(0x4b) as i32 };
            let x = if saldo + d > 3 {
                d as f64
            } else if gols(lado) + gols(outro) != 0 {
                f32_em(0x968e70) as f64
            } else if *w(0x8ed0) > 0x3c {
                f32_em(0x96d320) as f64
            } else {
                f32_em(0x96d248) as f64
            };
            let (v, repartir_outro): (f64, unsafe extern "thiscall" fn(usize, i8, i16)) = if c20 {
                (palavra(0x1f2, outro) as f64 * x * f64_em(0x96d310), repartir_c)
            } else {
                (palavra(0x1da, outro) as f64 * x * f64_em(0x96d318), repartir_b)
            };
            let r1 = sortear(ftol(v));
            let l24 = sortear(palavra(0x1de, lado)).wrapping_sub(r1) as i16;
            if l24 > 0 {
                repartir_a(m, lado as i8, 0x1c);
                repartir_outro(m, outro as i8, -0x14);
            } else {
                repartir_a(m, lado as i8, -6);
                repartir_outro(m, outro as i8, 0x28);
            }
            // o chute
            if l24 > 0 && sortear(gols(1) + gols(0)) <= 3 {
                let ml = m + lado * 0x36;
                if local_28 != 0 {
                    mais((ml + 0xf5c0) as *mut u8);
                }
                mais((ml + 0xf5be) as *mut u8);
                let c8 = escolher_por_papel_e(m, lado as u32, c20 as u32) as i8;
                let a = if c20 { sortear(palavra(0x1ee, lado)) } else { sortear(palavra(0x1e2, lado) * (local_28 as i32 + 1)) };
                let us = a as i16 as i32;
                if us + 0xa5 > sortear(0x172) + (0x168 - l24 as i32) {
                    mais((ml + 0xf5bf) as *mut u8);
                    if c20 {
                        repartir_d(m, lado as i8, a as i16);
                    } else {
                        repartir_e(m, lado as i8, a as i16);
                    }
                    if us + 0x2d > sortear((7 - local_28 as i32 * 3) * palavra(0x1e6, outro)) {
                        crate::comparacao::ramo("simulacao rapida gol");
                        let c9 = escolher_por_papel_c(m, lado as u32, local_28 as u32);
                        let p = jog(lado, c9 as i8);
                        mais((p + 0xc) as *mut u8);
                        somar(p, 0x1db);
                        goleiros(outro);
                        if local_28 != 0 {
                            crate::comparacao::ramo("simulacao rapida gol de penalti");
                            narrar(chamar, 0x1fcf, c9, lado);
                            mais((ml + 0xf5c1) as *mut u8);
                            mais((p + 0xd) as *mut u8);
                            mais((p + 0xe) as *mut u8);
                        } else {
                            narrar(chamar, 0x1fcc, c9, lado);
                            if c20 {
                                let o = match sortear(4) {
                                    0 | 1 => 0xf5c3,
                                    2 => 0xf5c5,
                                    _ => 0xf5c4,
                                };
                                mais((ml + o) as *mut u8);
                            }
                        }
                        if c8 > -1 {
                            let q = jog(lado, c8);
                            mais((q + 0x10) as *mut u8);
                            somar(q, 0x15e);
                        }
                        mais(b(0xf5c2 + outro * 0x36));
                        mais((ml + 0xf5bd) as *mut u8);
                        for (s, delta) in [(lado, 0x4b), (outro, -0x43)] {
                            for i in 0..20 {
                                let q = jog(s, i);
                                if byte(q, 0x19) >= 0 {
                                    somar(q, delta);
                                }
                            }
                        }
                        if decide {
                            crate::comparacao::ramo("simulacao rapida gol de ouro");
                            *b(0x1a8) = 1;
                            break 'rodadas;
                        }
                    } else {
                        repartir_f(m, outro as i8, 0xe1);
                        if local_28 != 0 {
                            crate::comparacao::ramo("simulacao rapida penalti perdido");
                            let c = escolher_por_papel_c(m, lado as u32, local_28 as u32);
                            narrar(chamar, 0x1fce, c, lado);
                            let p = jog(lado, c as i8);
                            mais((p + 0xd) as *mut u8);
                            somar(p, -500);
                        }
                    }
                }
            }
            rodada += 1;
            if rodada >= 2 {
                break;
            }
        }
        // o fim do periodo
        mais16(w(0x8ed0));
        let t = *w(0x8ed0);
        let w38 = *((pt() + 0x38) as *const u16);
        let igual_no_agregado = |a: usize, x: usize| *pb(a) as i32 + *pb(0x4b) as i32 == *pb(0x4c) as i32 + *pb(x) as i32;
        if fim {
            let (a, x) = if t <= 0x5a { (0x43, 0x44) } else { (0x47, 0x48) };
            *pb(a) = gols(0) as i8;
            *pb(x) = gols(1) as i8;
            let desempata = if *pb(0x4b) != -1 { igual_no_agregado(0x43, 0x44) } else { *pb(0x43) == *pb(0x44) && w38 & 0xa3 != 0 };
            if desempata {
                *pb(a) = (*pb(a)).wrapping_add(1);
            }
            break 'periodo false;
        }
        if *b(0x1a8) != 0 {
            *pb(0x47) = gols(0) as i8;
            *pb(0x48) = gols(1) as i8;
            break 'periodo false;
        }
        match t {
            0x2d => {
                *w(0x8ed4) = 0x3de;
                *pb(0x45) = gols(0) as i8;
                *pb(0x46) = gols(1) as i8;
            }
            0x5a => {
                *pb(0x43) = gols(0) as i8;
                *pb(0x44) = gols(1) as i8;
                *w(0x8ed4) = 0x483;
                let agregado = *pb(0x4b) != -1;
                if (agregado && !igual_no_agregado(0x43, 0x44)) || (!agregado && *pb(0x43) != *pb(0x44)) {
                    break 'periodo false;
                }
                if w38 & 0x80 != 0 {
                    crate::comparacao::ramo("simulacao rapida prorrogacao com gol de ouro");
                    decide = true;
                    continue 'periodo;
                }
                if w38 & 2 != 0 {
                    crate::comparacao::ramo("simulacao rapida prorrogacao");
                    continue 'periodo;
                }
                if agregado && w38 & 4 == 0 && *pb(0x44) != *pb(0x4b) && w38 & 0x4000 == 0 {
                    break 'periodo false;
                }
                break 'periodo w38 & 0x21 != 0;
            }
            0x69 => *w(0x8ed4) = 0x528,
            0x78 => {
                *pb(0x47) = gols(0) as i8;
                *pb(0x48) = gols(1) as i8;
                if *pb(0x4b) != -1 {
                    if !igual_no_agregado(0x47, 0x48) || (w38 & 0x4000 != 0 && *pb(0x48) != *pb(0x4b)) {
                        break 'periodo false;
                    }
                } else if *pb(0x47) != *pb(0x48) {
                    break 'periodo false;
                }
                break 'periodo w38 & 0x21 != 0;
            }
            _ => {}
        }
    };
    if penaltis {
        crate::comparacao::ramo("simulacao rapida penaltis");
        sortear(5);
        sortear(5);
        *pb(0x49) = sortear(5) as i8;
        sortear(5);
        sortear(5);
        *pb(0x4a) = sortear(5) as i8;
        if *pb(0x49) == *pb(0x4a) {
            let o = if sortear(2) != 0 { 0x49 } else { 0x4a };
            *pb(o) = (*pb(o)).wrapping_add(1);
        }
    }
    // o agregado
    if *pb(0x4b) != -1 {
        let (a, x) = if *pb(0x47) != -1 { (0x47, 0x48) } else { (0x43, 0x44) };
        *pb(0x4b) = (*pb(0x4b)).wrapping_add(*pb(a));
        *pb(0x4c) = (*pb(0x4c)).wrapping_add(*pb(x));
    }
    // o gol do mando
    let c1 = u(pt(), 0x1c);
    if c1 != 0 && u(pt(), 0x14) == u(c1, 0x57) && (*pb(0x43) as i32 + *pb(0x44) as i32) < 5 && *pb(0x43) == *pb(0x44) && sortear(4) == 0 {
        let (r0, r1) = (*((c1 + 0x80) as *const i16) as i32, *((u(pt(), 0x20) + 0x80) as *const i16) as i32);
        let s = if r0 > r1 { Some(0) } else if r0 + 0xfa < r1 { Some(1) } else { None };
        if let Some(s) = s {
            crate::comparacao::ramo("simulacao rapida gol do mando");
            mais(b(0xf5be + s * 0x36));
            let c = escolher_por_papel_c(m, s as u32, local_28 as u32);
            let p = jog(s, c as i8);
            mais((p + 0xc) as *mut u8);
            somar(p, 0x1db);
            goleiros(1 - s);
            narrar(chamar, 0x1fcc, c, s);
        }
    }
    // as lesoes (duas passadas pelo ultimo lado da vez)
    if *(pt() as *const i32) != -2 {
        for _ in 0..2 {
            for i in 0..20 {
                let p = jog(lado, i);
                let pessoa = u(p, 0x6d);
                if byte(p, 0x19) < 0 || pessoa == 0 {
                    continue;
                }
                let f = f32_em(p + 0x4d);
                let mut cl = (byte(pessoa, 0x2d) as u8).wrapping_mul(2).wrapping_add(5);
                if !(f >= f32_em(0x96d30c)) {
                    cl = cl.wrapping_add(0xf);
                } else if !(f >= f32_em(0x96d308)) {
                    cl = cl.wrapping_add(5);
                }
                if sortear(cl as i8 as i32) < sortear(400) {
                    continue;
                }
                let comp = u(pt(), 0x14);
                let liga = u(0xae2c74, 0);
                let teto = if comp == 0 || (liga != 0 && e_amistoso(liga, comp) != 0) { 0x5b } else { 0x66 };
                let g = sortear(teto) as u8;
                let tipo = match sortear(10) {
                    0 => 1,
                    1..=3 => 3,
                    4..=6 => 4,
                    7..=9 => 5,
                    _ => continue,
                };
                crate::comparacao::ramo("simulacao rapida lesao");
                chamar(0x6d0980, m, [tipo, g as u32, p as u32, 0, 0]);
            }
        }
    }
    // as notas
    for s in 0..2 {
        for i in 0..20i8 {
            let p = jog(s, i);
            let q = (p + 0x35) as *mut i16;
            if *(pt() as *const i32) == -2 && i < 11 {
                crate::comparacao::ramo("simulacao rapida nota do amistoso");
                let clube = if s != 0 { u(pt(), 0x20) } else { u(pt(), 0x1c) };
                let a = (*((p + 0x3b) as *const i16) as f64 - f64_em(0x968e30)) * f64_em(0x968ff8);
                let r = *((clube + 0x80) as *const i16) as f64 * f64_em(0x969018) - f64_em(0x96d300);
                let v = ftol(((a - r) * f64_em(0x96d2f8) + f64_em(0x967890)) * *q as f64) as i16;
                *q = v.clamp(0xdac, 0x2ee0);
            }
            let n = (ftol((*q as i32 + 0x1770) as f64 * f64_em(0x96a608) + f64_em(0x96d2f0)) as i8).clamp(1, 10);
            *((p + 0x1b) as *mut i8) = n;
            *((p + 0x51) as *mut u32) = *((p + 0x4d) as *const u32);
        }
    }
    for (a, x) in [(0xf5e2, 0xf5e4), (0xf618, 0xf61a)] {
        if *w(a) < 10 {
            crate::comparacao::ramo("simulacao rapida contador reiniciado");
            *w(a) = 0x14;
            *w(x) = (sortear(6) + 12) as i16;
        } else if *w(a) == *w(x) {
            crate::comparacao::ramo("simulacao rapida contador igual");
            let r = sortear(3);
            *w(x) = (*w(x)).wrapping_add((-1i32).wrapping_sub(r) as i16);
        }
    }
}

/// { 0x6beeb0 } (match_eng.cpp): ver `simulacao_rapida_com`.
unsafe extern "thiscall" fn simulacao_rapida(m: usize) {
    simulacao_rapida_com(m, &mut |r, t, a| despachar_dividida(r, t, a))
}

unsafe extern "thiscall" fn comparar_simulacao_rapida(m: usize) {
    let o = orig::<unsafe extern "thiscall" fn(usize)>(312);
    if gravando_no_topo() {
        return o(m);
    }
    // o motor inteiro, o sorteio, o erro, 0xae1080, a linha da tatica dos dois clubes (a expulsao
    // pode trocar o capitao) e o registro da partida (placares e agregado)
    let mut reg = crate::aleatorio::REGIOES_DO_ESTADO.to_vec();
    reg.extend([(m, MOTOR), (0xb67a34, 4), (0xae1080, 4)]);
    let t = *((m + 0x4792) as *const usize);
    reg.push((t, 0x50));
    for clube in [*((t + 0x1c) as *const usize), *((t + 0x20) as *const usize)] {
        reg.extend(linhas_do_clube(clube));
    }
    let gravar = GRAVAR_716.swap(true, std::sync::atomic::Ordering::Relaxed);
    let (_, _, igual, sequencia, k) = comparar_com_fita(reg, || {
        zerar_pilha();
        o(m)
    }, |chamar| {
        simulacao_rapida_com(m, &mut |rotina, this, args| {
            let mascara = match rotina {
                0x6d6f70 => [0xffff, u32::MAX, 0xff, 0xff, 0xff],
                0x6d0980 => [0xff, 0xff, u32::MAX, u32::MAX, 0],
                0x897760 => [u32::MAX, 0xff, u32::MAX, 0, 0],
                0x62ed70 => [u32::MAX, 0, 0, 0, 0],
                0x6e1aa0 => [0, 0, 0, 0, 0],
                _ => [0xff, 0, 0, 0, 0],
            };
            chamar(rotina, this, args, mascara)
        })
    });
    GRAVAR_716.store(gravar, std::sync::atomic::Ordering::Relaxed);
    PLACAR.registrar(igual && sequencia, || format!("simulacao_rapida {} chamadas: {}", k, detalhe_fita()));
}

// ---------- centesima quadragesima primeira leva: a lesao (0x6d0980, 0x62be00) e o destaque do jogador (0x717470) ----------

/// Unidades da fita da lesao: a 0x68d0d0 recebe o registro montado na pilha (confere o conteudo).
static GRAVAR_LESAO: std::sync::atomic::AtomicBool = std::sync::atomic::AtomicBool::new(false);

fn gravando_lesao() -> bool {
    GRAVAR_LESAO.load(std::sync::atomic::Ordering::Relaxed) && gravando()
}

/// { 0x62be00 } (ret 0xc, injury.cpp) com a copia na lista injetada (0x68d0d0): registra a lesao da
/// ficha na lista de lesoes do objeto (+0x28; sem lista, a original, que a cria). Ficha ja na lista
/// (pelo id): mesmo tipo soma a gravidade (+5, no maximo 100); outro tipo fica o mais grave. Ficha nova:
/// o registro (id, tipo, gravidade) vai para a lista. Devolve em `tipo` e `chance` o que ficou.
unsafe fn registrar_lesao_com(this: usize, ficha: usize, tipo: *mut u8, chance: *mut u8, chamar: &mut dyn FnMut(usize, usize, [u32; 5]) -> u32) {
    let l = *((this + 0x28) as *const usize);
    if l == 0 {
        crate::comparacao::ramo("lesao lista nova");
        let o = orig::<unsafe extern "thiscall" fn(usize, usize, *mut u8, *mut u8)>(314);
        return o(this, ficha, tipo, chance);
    }
    core::ptr::write_unaligned((l + 0xa) as *mut u32, core::ptr::read_unaligned((l + 2) as *const u32));
    let prox: unsafe extern "thiscall" fn(usize) -> usize = core::mem::transmute(0x68d1b0usize);
    let id = *(ficha as *const u32);
    let mut e = prox(l);
    while e != 0 && *(e as *const u32) != id {
        e = prox(l);
    }
    if e == 0 {
        crate::comparacao::ramo("lesao registrada");
        let mut r = [0u8; 6];
        r[..4].copy_from_slice(&id.to_le_bytes());
        r[4] = *tipo;
        r[5] = *chance;
        pedir_vetores(&[(r.as_ptr() as usize, 6)], &[]);
        chamar(0x68d0d0, l, [0, 6, 0, 0, 0]);
        return;
    }
    let (t, g) = ((e + 4) as *mut u8, (e + 5) as *mut u8);
    if *t == *tipo {
        crate::comparacao::ramo("lesao agravada");
        *g = if *chance as i8 as i32 + *g as i8 as i32 > 0x64 { 0x64 } else { (*chance).wrapping_add(*g) };
    } else if *chance as i8 > *g as i8 {
        crate::comparacao::ramo("lesao mais grave");
        *g = *chance;
        *t = *tipo;
    }
    *tipo = *t;
    *chance = *g;
}

unsafe fn despachar_lesao(rotina: usize, this: usize, a: [u32; 5]) -> u32 {
    // 0x68d0d0: o bloco pedido por ultimo (pedir_vetores) e o que vai para a lista
    let p = VETORES_PEDIDOS.lock().unwrap_or_else(|e| e.into_inner()).take().map_or(0, |v| v.0[0].0);
    let f: unsafe extern "thiscall" fn(usize, usize, u32) = core::mem::transmute(rotina);
    f(this, p, a[1]);
    0
}

/// { 0x62be00 }: ver `registrar_lesao_com`.
unsafe extern "thiscall" fn registrar_lesao(this: usize, ficha: usize, tipo: *mut u8, chance: *mut u8) {
    registrar_lesao_com(this, ficha, tipo, chance, &mut |r, t, a| despachar_lesao(r, t, a))
}

/// { 0x6d0980 } (ret 0x10, match_eng.cpp) com a copia na lista de lesoes injetada (0x68d0d0): a lesao
/// do jogador `p` na partida. Com mais de 3 lesoes no jogo (+0xf639), sorteio(lesoes) e sorteio(500)
/// nao nulos a evitam; mais de 6, nunca. Tipo valido: registra (0x62be00, que devolve tipo e
/// gravidade). +0x55 = `o` (o causador perde 10 em +0x31). Gravidade acima de 50: tira gravidade^2 do
/// folego (+0x4d) e marca +0x1c; senao tira sorteio(gravidade^2 / 2), grava sorteio(isso x 0,5) em
/// +0x59 e reduz +0xd5 a metade. Folego abaixo do limite: sai (+0x8eb5, +0x1d, +0x1c); senao para
/// (0x7160e0 com 5 ou 3) conforme a forca da pessoa (+0x2d x 25). Folego entre 1 e o teto; saindo,
/// mais uma lesao no jogo.
unsafe fn lesionar_com(m: usize, tipo: u32, chance: u32, p: usize, o: usize, chamar: &mut dyn FnMut(usize, usize, [u32; 5]) -> u32) {
    let w = |x: usize| (m + x) as *mut i16;
    let b = |q: usize, x: usize| (q + x) as *mut u8;
    let n = *w(0xf639);
    if n > 3 && sortear(n as i32) != 0 && sortear(0x1f4) != 0 {
        return;
    }
    if *w(0xf639) > 6 {
        return;
    }
    let (mut t, mut g) = (tipo as u8, chance as u8);
    if t as i8 > -1 {
        registrar_lesao_com(*(0xb63d28 as *const usize), *((p + 0x69) as *const usize), &mut t, &mut g, chamar);
    }
    *((p + 0x55) as *mut usize) = o;
    if o != 0 {
        let q = (o + 0x31) as *mut i16;
        *q = (*q).wrapping_sub(10);
    }
    let folego = (p + 0x4d) as *mut f32;
    let c = g as i8 as i32;
    let mut local = 0f32;
    if g as i8 > 0x32 {
        crate::comparacao::ramo("lesao grave");
        *b(p, 0x1c) = 1;
        *folego = (*folego as f64 - (c * c) as f64) as f32;
    } else {
        local = sortear(ftol((c * c) as f64 * f64_em(0x968968))) as f32;
        *folego = (*folego as f64 - local as f64) as f32;
        let r = sortear(ftol(local as f64 * f32_em(0x968f18) as f64));
        *((p + 0x59) as *mut f32) = r as f32;
        let d5 = (p + 0xd5) as *mut f32;
        *d5 = (*d5 as f64 * f32_em(0x968f18) as f64) as f32;
    }
    if !(*folego as f64 >= f64_em(0x9688e8)) {
        crate::comparacao::ramo("lesao sem folego");
        *b(m, 0x8eb5) = 1;
        *b(p, 0x1d) = 1;
        *b(p, 0x1c) = 1;
    } else {
        let pessoa = *((p + 0x6d) as *const usize);
        let v = (byte(pessoa, 0x2d) as i32 * 25) as f64 + f64_em(0x96d458);
        if v > *folego as f64 {
            crate::comparacao::ramo("lesao para 5");
            gravar_2b(p, 5);
            *b(m, 0x8eb5) = 1;
            *b(p, 0x1d) = 1;
        } else {
            gravar_2b(p, 3);
            if local >= f32_em(0x96d1a8) && *b(p, 0x1c) != 0 {
                crate::comparacao::ramo("lesao para 3 e sai");
                *b(m, 0x8eb5) = 1;
                *b(p, 0x1d) = 1;
            }
        }
    }
    let x = *folego as f64;
    if !(x >= f64_em(0x967890)) {
        *folego = f64_em(0x967890) as f32;
    } else if x > f64_em(0x968910) {
        *folego = f64_em(0x968910) as f32;
    }
    if *b(m, 0x8eb5) != 0 {
        *w(0xf639) = (*w(0xf639)).wrapping_add(1);
    }
}

/// { 0x6d0980 }: ver `lesionar_com`.
unsafe extern "thiscall" fn lesionar(m: usize, tipo: u32, chance: u32, p: usize, o: usize) {
    lesionar_com(m, tipo, chance, p, o, &mut |r, t, a| despachar_lesao(r, t, a))
}

/// As regioes da lesao: o ponteiro da lista de lesoes, o cabecalho, os nos (o ultimo ganha o
/// proximo quando a original acrescenta) e os registros de 6 bytes.
unsafe fn regioes_das_lesoes() -> Vec<(usize, usize)> {
    let mut reg = Vec::new();
    let dono = *(0xb63d28 as *const usize);
    let lista = if dono != 0 { *((dono + 0x28) as *const usize) } else { 0 };
    if lista != 0 {
        reg.extend([(dono + 0x28, 4), (lista, 0xe)]);
        let mut no = core::ptr::read_unaligned((lista + 2) as *const usize);
        for _ in 0..(*(lista as *const i16)).max(0) {
            if no == 0 {
                break;
            }
            reg.push((no, 0xa));
            let e = *(no as *const usize);
            if e != 0 {
                reg.push((e, 6));
            }
            no = core::ptr::read_unaligned((no + 6) as *const usize);
        }
    }
    reg
}

unsafe extern "thiscall" fn comparar_lesionar(m: usize, tipo: u32, chance: u32, p: usize, o: usize) {
    if gravando() {
        // unidade da fita de fora; por dentro, a propria comparacao (fita aninhada)
        chamar_gravando(0x6d0980, m, [tipo, chance, p as u32, o as u32, 0], || {
            fita_da_lesao(m, tipo, chance, p, o);
            0
        });
        return;
    }
    fita_da_lesao(m, tipo, chance, p, o);
}

unsafe fn fita_da_lesao(m: usize, tipo: u32, chance: u32, p: usize, o: usize) {
    use std::sync::atomic::Ordering::Relaxed;
    let f = orig::<unsafe extern "thiscall" fn(usize, u32, u32, usize, usize)>(313);
    let dono = *(0xb63d28 as *const usize);
    if dono == 0 || *((dono + 0x28) as *const usize) == 0 {
        // sem lista, a original a cria (aloca): fica sem comparacao
        return f(m, tipo, chance, p, o);
    }
    let mut reg = crate::aleatorio::REGIOES_DO_ESTADO.to_vec();
    reg.extend([(m, MOTOR), (0xb67a34, 4)]);
    if o != 0 {
        reg.push((o + 0x31, 2));
    }
    reg.extend(regioes_das_lesoes());
    let gravar = GRAVAR_LESAO.swap(true, Relaxed);
    let (_, _, igual, sequencia, k) = comparar_com_fita(reg, || f(m, tipo, chance, p, o), |chamar| {
        lesionar_com(m, tipo, chance, p, o, &mut |rotina, this, args| chamar(rotina, this, args, [0, u32::MAX, 0, 0, 0]))
    });
    GRAVAR_LESAO.store(gravar, Relaxed);
    PLACAR.registrar(igual && sequencia, || format!("lesionar(tipo {}, chance {}) {} chamadas: {}", tipo as u8 as i8, chance as u8 as i8, k, detalhe_fita()));
}

/// A 0x62be00 so e chamada pela 0x6d0980: a comparacao e a dela (a lista entra nas regioes).
unsafe extern "thiscall" fn comparar_registrar_lesao(this: usize, ficha: usize, tipo: *mut u8, chance: *mut u8) {
    orig::<unsafe extern "thiscall" fn(usize, usize, *mut u8, *mut u8)>(314)(this, ficha, tipo, chance)
}

/// { 0x717470 } (ret 4): o jogador pode ganhar o destaque `codigo` (0x1f40..=0x21e4) nesta partida?
/// Nao se o lado ja o teve (tabela de dwords em +0x21e do motor, 4000 bytes por lado) ou se a ficha
/// (+0x69) e de fora da base ([0xae2364]). Os codigos 0x219e..=0x21b8 tem regras proprias (atuacao
/// +0x35 contra um sorteio ou contra o tempo em campo, gols +0xc, cartoes, e a busca no historico
/// 0x757da0 nos ultimos 7 ou 30 dias, datas da 0x54c8e0); os demais da faixa, sim.
unsafe extern "thiscall" fn destaque_do_jogador(p: usize, codigo: u32) -> u32 {
    let m = *((p + 0x19e) as *const usize);
    let hoje = 0xae2c90usize;
    let datar: unsafe extern "thiscall" fn(usize, *mut [u8; 8], u32) = core::mem::transmute(0x54c8e0usize);
    let (mut d7, mut d30) = ([0u8; 8], [0u8; 8]);
    datar(hoje, &mut d7, 7);
    datar(hoje, &mut d30, 0x1e);
    let c = codigo as u16 as i16 as i32;
    if !(0x1f40..=0x21e4).contains(&c) {
        return 0;
    }
    let lado = byte(p, 0x27) as i32;
    if *((m as isize + ((c + lado * 1000) * 4) as isize - 0x7ae2) as *const u32) != 0 {
        return 0;
    }
    let ficha = *((p + 0x69) as *const usize);
    if ficha != 0 && *(ficha as *const i32) >= *(0xae2364 as *const i32) {
        return 0;
    }
    let atuacao = *((p + 0x35) as *const i16) as i32;
    let b = |o: usize| byte(p, o);
    let minuto = *((m + 0x8ed0) as *const i16) as i32 / 11;
    let em_campo = minuto - b(0x1f) as i32;
    let limite = |t: i32| (t * 33 + 0xfa0).min(0x1964);
    // as condicoes comuns: sem gol, sem cartao, +0x17 ate 8, +0x03 ate 2 e a atuacao ate o limite
    let comum = || b(0xc) == 0 && b(0x10) == 0 && b(0x17) <= 8 && (b(3) as u8) <= 2 && atuacao <= limite(em_campo);
    let buscar = |cod: u32, data: &[u8; 8]| {
        let f: unsafe extern "thiscall" fn(usize, usize, usize, i32, u32, *const [u8; 8]) -> u32 = core::mem::transmute(0x757da0usize);
        f(*(0xb6b7c8 as *const usize), ficha, *((p + 0xf9) as *const usize), -1, cod, data) != 0
    };
    let algum = |de: u32, ate: u32, data: &[u8; 8]| (de..=ate).any(|k| buscar(k as u16 as u32, data));
    let r = match c {
        0x219e => comum() && (algum(0, 0x1d, &d7) || algum(0x1e, 0x27, &d7)),
        0x219f => atuacao >= sortear(0x7d0) + 0x1b58 && algum(0, 0x1d, &d7),
        0x21a0 => {
            let dias: unsafe extern "thiscall" fn(usize, u32, u32) -> i32 = core::mem::transmute(0x54cdb0usize);
            if dias(hoje, *((ficha + 0x3e) as *const u32), *((ficha + 0x42) as *const u32)) < 0x5a || atuacao <= sortear(0x7d0) + 0x1b58 {
                false
            } else {
                let f: unsafe extern "thiscall" fn(usize, usize) -> u32 = core::mem::transmute(0x735780usize);
                f(*(0xb6b7c8 as *const usize), ficha) != 0
            }
        }
        0x21a1 | 0x21a2 => {
            let gols = b(0xa) as u8 as i32;
            if p != *((m + 0xf5aa) as *const usize) || *((m + 0xf5a6) as *const u32) == 0 {
                false
            } else if c == 0x21a1 {
                if gols <= 4 || *((p + 0x39) as *const i16) <= 0xfa {
                    false
                } else {
                    let r = sortear(6) + 12;
                    em_campo / gols < r && buscar(0x52, &d7)
                }
            } else if gols >= 3 || gols == 0 {
                false
            } else {
                let r = sortear(0x19) + 0x32;
                minuto > r && em_campo / gols > 0x1e && buscar(0x52, &d7)
            }
        }
        0x21b0 => atuacao > sortear(1000) + 0x1f40 && buscar(0x34, &d7),
        0x21b1 => comum() && buscar(0x34, &d7),
        0x21b2 => comum() && buscar(0x33, &d30),
        0x21b3 => atuacao > sortear(1000) + 0x1f40 && buscar(0x33, &d30),
        0x21b4 => atuacao >= sortear(0x7d0) + 0x1b58 && algum(0x28, 0x3b, &d7),
        0x21b5 => atuacao > sortear(1000) + 0x1f40 && b(0x30) != 0,
        0x21b6 => {
            let sim = atuacao > sortear(0x7d0) + 0x1c52 && b(0xc) == 1 && em_campo > 0x41 && b(0x30) != 0;
            if sim {
                crate::comparacao::ramo("destaque marca 21b5");
                *((m + 0xbf2 + lado as usize * 4000) as *mut u32) = 1;
            }
            sim
        }
        0x21b7 => b(0x30) != 0 && b(0xc) == 0 && b(0x10) == 0 && b(0x17) <= 8 && (b(3) as u8) <= 2 && em_campo >= 0x37 && atuacao <= limite(em_campo),
        0x21b8 => {
            atuacao < 0x1964
                && (b(0x14) as u8 as i32) > sortear(3)
                && tabela_do_jogador(p) & 4 != 0
                && byte(*((p + 0x6d) as *const usize), 0x11) as i32 > sortear(4) + 0xf
                && b(0xc) == 0
                && (b(0x17) as i32) < sortear(6)
                && em_campo > sortear(0x32) + 0x1e
        }
        _ => true,
    };
    crate::comparacao::ramo(if r { "destaque sim" } else { "destaque nao" });
    r as u32
}

unsafe extern "thiscall" fn comparar_destaque_do_jogador(p: usize, codigo: u32) -> u32 {
    let o = orig::<unsafe extern "thiscall" fn(usize, u32) -> u32>(315);
    if gravando_no_topo() {
        return o(p, codigo);
    }
    let m = *((p + 0x19e) as *const usize);
    let mut reg = crate::aleatorio::REGIOES_DO_ESTADO.to_vec();
    reg.extend([(m, MOTOR), (0xb67a34, 4)]);
    let (r, n, igual, mo, mr) = crate::comparacao::lado_a_lado(&reg, || o(p, codigo), || crate::aleatorio::sem_contar(|| destaque_do_jogador(p, codigo)));
    PLACAR.registrar(igual && r == n, || format!("destaque_do_jogador({:#x}) original={} rust={} {:x?} x {:x?}", codigo as u16, r, n, mo, mr));
    r
}

// ---------- centesima quadragesima segunda leva: o desfecho do chute (0x70c040) ----------

/// { 0x70c040 } (ret 4, match_pl.cpp) com as chamadas que mexem fora do motor injetadas (0x6d6f70
/// narra, 0x6cd770 bola parada, 0x716e10 e 0x6f0630; e as da falta 0x6bac40): o desfecho do chute de
/// `p` com a forca `f` (0 vale 1). A qualidade (sorteio(1000) - sorteio(2000)) x (+0x8eaa + 1) / f
/// contra a defesa do goleiro (0x6ce110, 0x700420, com rebote e saida) da o tipo: 1 no alvo, 2..11
/// para fora (so o placar 0x6ce310), 12/13 para fora com tiro de meta narrado (0x1fca/0x1fcb, bola
/// parada 2). No alvo, a parte do chute na soma com a defesa: acima de 71 e gol (disputa de penaltis
/// 0x6bba50, gol de ouro 0x6d4250, o goleiro sofre; narracoes pelo placar e o tempo, 0x6bb950 no
/// lado; o placar +0xf5bd do outro lado, as narracoes da torcida), acima de 61 defesa com escanteio,
/// acima de 51 defesa que sai pela linha (+0x8ea8, bola parada 3 e 0x1f75), senao defesa (0x6f0630);
/// nas defesas, o destaque do goleiro (0x717470) escolhe a narracao.
unsafe fn desfecho_do_chute_com(p: usize, f_in: f32, chamar: &mut dyn FnMut(usize, usize, [u32; 5]) -> u32) {
    let m = *((p + 0x19e) as *const usize);
    let u = |q: usize, o: usize| *((q + o) as *const usize);
    let bm = |o: usize| (m + o) as *mut u8;
    let lado = byte(p, 0x27);
    let outro = (lado == 0) as u8;
    let narrar = |chamar: &mut dyn FnMut(usize, usize, [u32; 5]) -> u32, codigo: u32, x: u32, y: u8, a7: i16| narrar_chute(chamar, m, codigo, x, y, a7);
    let tabela1 = |q: usize| u(q, 0x19e) != 0 && tabela_do_jogador(q) == 1;
    let somar = |q: usize, d: i16| {
        let w = (q + 0x35) as *mut i16;
        *w = (*w).wrapping_add(d);
    };
    let mais_2b = |q: usize, d: u8| {
        let b = (q + 0x2b) as *mut u8;
        *b = (*b).wrapping_add(d);
    };
    let f = if f_in as f64 == f64_em(0x9689a0) { 1.0f32 } else { f_in };
    let fator = byte(m, 0x8eaa);
    let r1 = sortear(0x7d0);
    let r2 = sortear(0x3e8);
    let qualidade = ftol(r2.wrapping_sub(r1).wrapping_mul(fator as i32 + 1) as f64 / f as f64);
    let g = manter_posicao_um(m, lado);
    if g == 0 {
        return orig::<unsafe extern "thiscall" fn(usize, f32)>(316)(p, f_in);
    }
    let mut b18 = 0u8;
    if byte(m, 0x8ea9) > 3 {
        b18 = 1;
    }
    let (mut b13, mut b16) = (0u8, 0u8);
    let defesa = if g != p {
        crate::comparacao::ramo("desfecho goleiro defende");
        defesa_do_goleiro(g, byte(p, 0x102), byte(p, 0x103), b18, -1, &mut b16, &mut b13)
    } else {
        // ponytail: com o proprio goleiro chutando, a original le b13/b16 sem valor (zerados no
        // original determinizado)
        0
    };
    let (mut b12, mut b14) = (0u8, 0u8);
    if b13 == 0 {
        if defesa as i16 > 0x177 {
            b12 = 1;
        } else if defesa as i16 > 0x104 {
            b14 = 1;
        }
    }
    let q = qualidade as i16;
    let tipo: u8 = if q > 0xf0 {
        1
    } else if q < 10 {
        if b18 != 0 { if sortear(4) != 0 { 3 } else { 4 } } else { 2 }
    } else {
        let d = 0xf0 - q as i32;
        if d > 0x32 {
            if b18 != 0 { if sortear(4) != 0 { 6 } else { 7 } } else { 5 }
        } else if d > 0xa {
            8 + (b18 != 0) as u8
        } else if d > 6 {
            0xa + (b18 != 0) as u8
        } else {
            0xc + (b18 != 0) as u8
        }
    };
    let (mut b10, mut b11, mut b15, mut b23, mut b17) = (0i8, 0i8, 0u8, 0u8, 0u8);
    placar_agregado(m, outro as i8, &mut b10, &mut b11, &mut b15, &mut b23, &mut b17, 1);
    if tipo != 1 {
        match tipo {
            0xc => narrar(chamar, 0x1fca, byte(p, 0x2e) as u8 as u32, outro, 0),
            0xd => narrar(chamar, 0x1fcb, byte(p, 0x2e) as u8 as u32, outro, 0),
            _ => {}
        }
        if !(0xc..=0xd).contains(&tipo) {
            crate::comparacao::ramo("desfecho para fora");
            return;
        }
        crate::comparacao::ramo("desfecho tiro de meta");
        if b13 != 0 && b16 == 0 && tabela1(g) {
            narrar(chamar, 0x20d5, byte(g, 0x2e) as u8 as u32, byte(g, 0x27) as u8, 0);
        }
        narrar(chamar, 0x211b, byte(p, 0x2e) as u8 as u32, lado as u8, 0);
        chamar(0x6cd770, m, [byte(m, 0x8ea7) as u8 as u32, byte(m, 0x8ea8) as u8 as u32, 2 | (lado as u8 as u32) << 8, 1, 0]);
        if tabela1(g) {
            mais_2b(g, sortear(3) as u8);
        }
        *bm(0x1cd) = 1;
        return;
    }
    // no alvo
    let k = defesa as i16 as i32;
    let parte = if k + q as i32 == 0 { 0 } else { (q as i32 * 100) / (k + q as i32) };
    let parte = parte as i16;
    if parte <= 0x47 {
        if b14 != 0 && tabela1(g) {
            crate::comparacao::ramo("desfecho defesa media");
            somar(g, 0x15e);
            if sortear(byte(g, 0x17) as i32 * 20 + 0x32) == 0 {
                let r = sortear(4);
                if ajustar_17(g, r as i8) != 0 {
                    desempenho_na_partida(g, 0);
                }
            }
        } else if b12 != 0 && tabela1(g) {
            crate::comparacao::ramo("desfecho defesa dificil");
            somar(g, 0x258);
            if sortear((byte(g, 0x17) as i32 + 1) * 20) == 0 {
                let r = sortear(7);
                if ajustar_17(g, r as i8) != 0 {
                    desempenho_na_partida(g, 0);
                }
            }
        }
    }
    if parte > 0x47 {
        desfecho_gol(m, p, g, lado, outro, b10, b11, b12, b13, b14, b15, b16, b17, chamar);
        return;
    }
    let codigos = [0x219f, 0x21a0, 0x21b0, 0x21b3, 0x21b4, 0x21b5];
    let destaque = |chamar: &mut dyn FnMut(usize, usize, [u32; 5]) -> u32, abertura: u32, comum: u32, quieta: u32| {
        let (g2e, g27) = (byte(g, 0x2e) as u8 as u32, byte(g, 0x27) as u8);
        if b12 != 0 {
            narrar(chamar, abertura, g2e, g27, 0);
            if let Some(&c) = codigos.iter().find(|&&c| destaque_do_jogador(g, c) != 0) {
                crate::comparacao::ramo("desfecho destaque do goleiro");
                narrar(chamar, c, g2e, g27, 0);
            }
        } else {
            narrar(chamar, if b14 != 0 { comum } else { quieta }, g2e, g27, 0);
        }
    };
    if parte > 0x3d {
        crate::comparacao::ramo("desfecho escanteio");
        destaque(chamar, 0x2111, 0x210f, 0x1fe6);
        somar(g, 0x8c);
        mais_2b(g, (sortear(3) + 1) as u8);
        chamar(0x6cd770, m, [byte(m, 0x8ea7) as u8 as u32, byte(m, 0x8ea8) as u8 as u32, (lado as u8 as u32) << 8, 0, 0]);
        narrar(chamar, 0x211b, byte(p, 0x2e) as u8 as u32, lado as u8, 0);
        *bm(0x1cd) = 1;
    } else if parte > 0x33 {
        crate::comparacao::ramo("desfecho linha de fundo");
        destaque(chamar, 0x2111, 0x210f, 0x1fe4);
        if lado == 1 {
            *bm(0x8ea8) = 0xff;
        } else if lado == 0 {
            *bm(0x8ea8) = 0xc;
        }
        *bm(0x8eae) = outro;
        *((m + 0xf582) as *mut u32) = 0;
        narrar(chamar, 0x211b, byte(p, 0x2e) as u8 as u32, lado as u8, 0);
        *bm(0x8eb2) = 3;
        narrar(chamar, 0x1f75, u32::MAX, outro, 0);
    } else {
        crate::comparacao::ramo("desfecho defesa");
        let r = sortear(3);
        somar(g, 0xc8);
        mais_2b(g, r as u8);
        destaque(chamar, 0x2112, 0x2110, 0x1fe5);
        narrar(chamar, 0x211b, byte(p, 0x2e) as u8 as u32, lado as u8, 0);
        chamar(0x6f0630, g, [0; 5]);
    }
}

/// O gol do desfecho (parte do chute acima de 71): ver `desfecho_do_chute_com`.
#[allow(clippy::too_many_arguments)]
unsafe fn desfecho_gol(m: usize, p: usize, g: usize, lado: i8, outro: u8, mut b10: i8, b11: i8, b12: u8, b13: u8, b14: u8, b15: u8, b16: u8, b17: u8, chamar: &mut dyn FnMut(usize, usize, [u32; 5]) -> u32) {
    let _ = (b12, b14);
    let u = |q: usize, o: usize| *((q + o) as *const usize);
    let bm = |o: usize| (m + o) as *mut u8;
    let narrar = |chamar: &mut dyn FnMut(usize, usize, [u32; 5]) -> u32, codigo: u32, x: u32, y: u8, a7: i16| narrar_chute(chamar, m, codigo, x, y, a7);
    let tabela1 = |q: usize| u(q, 0x19e) != 0 && tabela_do_jogador(q) == 1;
    let somar = |q: usize, d: i16| {
        let w = (q + 0x35) as *mut i16;
        *w = (*w).wrapping_add(d);
    };
    let minuto = || *((m + 0x8ed0) as *const i16) as i32 / 11;
    let tarde = |d: i32| (0x55..0x5a).contains(&d) || d >= 0x73;
    let (p2e, p27) = (byte(p, 0x2e) as u8 as u32, lado as u8);
    crate::comparacao::ramo("desfecho gol");
    if lado_do_lance(m) as i8 == -1 {
        if momento_marcado(m) as u8 != 0 {
            crate::comparacao::ramo("desfecho gol de ouro");
            *bm(0x1a8) = 1;
        }
        if tabela1(g) {
            *((g + 0xf) as *mut u8) = byte(g, 0xf).wrapping_add(1) as u8;
            let ficha = u(g, 0x69);
            if sortear(byte(ficha, 0x58) as i32 + 1) != 0 && sortear(byte(ficha, 0x5a) as i32 + 1) != 0 {
                let s = byte(g, 0xf) as u8 as i32;
                let r = sortear(s * s) as u8;
                let pf = byte(p, 0xf) as u8;
                let v = if ((r as i8) as i32) < pf as i32 { pf } else { r };
                *((g + 0x100) as *mut u8) = (byte(g, 0x100) as u8).wrapping_add(v);
                desempenho_na_partida(g, 0);
            }
            somar(g, -500);
            if b13 != 0 {
                somar(g, -600);
            }
        }
    }
    if tabela1(g) && g != p && b13 == 0 && sortear(0x32) == 0 && b16 == 0 {
        narrar(chamar, 0x20d6, byte(g, 0x2e) as u8 as u32, byte(g, 0x27) as u8, 0);
    }
    narrar(chamar, 0x1fff, p2e, outro, 0);
    let penaltis = |chamar: &mut dyn FnMut(usize, usize, [u32; 5]) -> u32, y: u8| {
        crate::comparacao::ramo("desfecho gol nos penaltis");
        narrar(chamar, 0x20ed, u32::MAX, y, 0);
        let bl = lado_do_lance(m);
        aplicar_falta_com(m, chamar);
        let k = if bl as i8 == lado {
            narrar(chamar, 0x20df, u32::MAX, p27, 0);
            if sortear((b11 as i32) - (b10 as i32) + 3) > 0 {
                narrar(chamar, 0x20d9, u32::MAX, p27, 0);
            }
            3.0f32
        } else {
            if (b10 == b11 || (b10 as i32) - 1 == b11 as i32) && sortear(0x28) == 0 {
                narrar(chamar, 0x20d9, u32::MAX, p27, 0);
            }
            f32::from_bits(0x3fb9999a)
        };
        aplicar_ao_time(m, p, k);
        chamar(0x716e10, p, [0; 5]);
    };
    if sortear(3) != 0 && lado_do_lance(m) as i8 > -1 {
        penaltis(chamar, outro);
        return;
    }
    let nos_penaltis = lado_do_lance(m) as i8 > -1;
    narrar(chamar, if nos_penaltis { 0x20fa } else { 0x1fcd }, p2e, p27, 0);
    if lado_do_lance(m) as i8 > -1 {
        penaltis(chamar, p27);
        return;
    }
    if tabela1(g) && g != p && b16 != 0 {
        narrar(chamar, 0x1fe1, byte(g, 0x2e) as u8 as u32, byte(g, 0x27) as u8, b16 as i8 as i16);
    }
    b10 = b10.wrapping_add(1);
    let k_lado = |k: u32| aplicar_ao_lado(m, lado, f32::from_bits(k));
    if *bm(0x1a8) != 0 {
        narrar(chamar, 0x1fd2, u32::MAX, outro, 0);
    } else if b17 != 0 {
        torcida(chamar, m, lado, outro, b15, &narrar);
    } else {
        let dif = b10 as i32 - b11 as i32;
        let t = minuto();
        let fase2 = *((m + 0x8ed4) as *const i16) == 0x3de;
        if dif == 2 && ((t >= 0x46 && fase2) || t >= 0x6a) {
            narrar(chamar, 0x1fd0, u32::MAX, outro, 0);
            k_lado(0x3fc66666);
        } else if (dif == 1 || b15 != 0) && ((t >= 0x50 && fase2) || t >= 0x6e) {
            narrar(chamar, 0x1fd1, u32::MAX, outro, 0);
            k_lado(0x3fb9999a);
        } else if b10 == b11 && b15 == 0 && t >= 0x46 {
            crate::comparacao::ramo("desfecho empate tardio");
            let a = contar_ativos(m, outro as i8) as i8;
            let b = contar_ativos(m, lado) as i8;
            let bl = if a < b { byte(m, 4 + outro as usize) } else { -1 };
            let d = minuto() as i16 as i32;
            let (codigo, k) = if bl == -1 {
                if tarde(d) { (0x1fd8, 0x3fb9999a) } else { (0x1fd6, 0x3faccccd) }
            } else if tarde(d) {
                (0x1fd9, 0x3fd33333)
            } else {
                (0x1fd7, 0x3fb33333)
            };
            k_lado(k);
            narrar(chamar, codigo, u32::MAX, outro, bl as i16);
        } else if dif < 0 && dif > -3 && (t >= 0x50 || (t >= 0x46 && b10 == 1) || (t >= 0x3c && b10 == 1 && 1 - b11 as i32 == -2)) {
            narrar(chamar, if tarde(t as i16 as i32) { 0x1fdb } else { 0x1fda }, u32::MAX, outro, 0);
        } else {
            torcida(chamar, m, lado, outro, b15, &narrar);
        }
    }
    if tabela1(g) && g != p && b13 != 0 && b16 == 0 {
        narrar(chamar, 0x20d5, byte(g, 0x2e) as u8 as u32, byte(g, 0x27) as u8, 0);
    }
    aplicar_ao_time(m, p, f32::from_bits(0x3fd9999a));
    let gols = bm(0xf5bd + outro as usize * 0x36);
    *gols = (*gols).wrapping_add(1);
    let r = sortear(5);
    let clube = || {
        let pt = u(m, 0x4792);
        u(if lado != 0 { pt + 0x1c } else { pt + 0x20 }, 0)
    };
    let tecnico_8 = || {
        let t = u(clube(), 0x53);
        t != 0 && byte(t, 0x77) == 8
    };
    let mut feito = false;
    if (b10 as i32 - b11 as i32) > r + 2 && sortear(7) == 0 && tecnico_8() {
        narrar(chamar, 0x2117, u32::MAX, outro, 0);
        feito = true;
    }
    if !feito && (b10 == b11 || b10 as i32 - 1 == b11 as i32 || b15 != 0) {
        let r1 = sortear(minuto());
        if r1 > sortear(0x78) && tecnico_8() {
            narrar(chamar, 0x2116, u32::MAX, outro, 0);
        }
    }
    *bm(0x8eae) = lado as u8;
    *((m + 0xf582) as *mut u32) = 0;
    *bm(0x8eb2) = 8;
    *bm(0x1ca) = 0;
}

/// O fim comum das narracoes do gol: a torcida (0x1fdc antes dos 80 com +0x15, fator 1,45) ou
/// so o fator 1,25 no lado.
unsafe fn torcida(chamar: &mut dyn FnMut(usize, usize, [u32; 5]) -> u32, m: usize, lado: i8, outro: u8, b15: u8, narrar: &dyn Fn(&mut dyn FnMut(usize, usize, [u32; 5]) -> u32, u32, u32, u8, i16)) {
    let t = *((m + 0x8ed0) as *const i16) as i32 / 11;
    if b15 != 0 && t < 0x50 {
        narrar(chamar, 0x1fdc, u32::MAX, outro, 0);
        aplicar_ao_lado(m, lado, f32::from_bits(0x3fb9999a));
    } else {
        aplicar_ao_lado(m, lado, f32::from_bits(0x3fa00000));
    }
}

/// A narracao dos chutes: o ultimo argumento (a7) vai em 16 bits no alto do codigo (contagens de gols
/// em palavra; a fita confere o byte baixo).
unsafe fn narrar_chute(chamar: &mut dyn FnMut(usize, usize, [u32; 5]) -> u32, m: usize, codigo: u32, x: u32, y: u8, a7: i16) {
    chamar(0x6d6f70, *((m + 0x8f7a) as *const usize), [codigo | (a7 as u16 as u32) << 16, m as u32, x, y as u32, u32::MAX]);
}

unsafe fn despachar_chute(rotina: usize, this: usize, a: [u32; 5]) -> u32 {
    if rotina == 0x6d6f70 {
        comentar(this, [a[0] & 0xffff, a[1], a[2], a[3], a[4] & 0xff, (a[4] >> 8) & 0xff, (a[0] >> 16) as u16 as i16 as i32 as u32]);
        return 0;
    }
    despachar_dividida(rotina, this, a)
}

