    let n = *((e + 6) as *const i16) as i32;
    *desc.add(1) = n as u32;
    *desc.add(2) = numero as u32;
    *(desc.add(3) as *mut u8) = humano;
    let r = escrever(e + 0x720, 0xe, *((e + 6) as *const i16) as i32 as u32, f);
    quantos += 1;
    buscar(f, 8, 0);
    escrever(&quantos as *const i32 as usize, 4, 1, f);
    fechar(f);
