/// tabela 0x6d5cd0) ou da um passo do motor (0x6b98c0 com 1) e marca o estado: fim (2/8), intervalo
/// (4), gols de cada lado (+0xf5bd/+0xf5f3 contra o resumo), lance, +0x8eb2, o minuto (+0x8ed0 / 11)
/// contra o resumo (espera 0x226 - 50 x +0x51); com estado, registra (0x729ff0) e a do humano do dia
/// (+0x34) passa a ser a de maior competicao (0x6b6570) ou mais adiantada. Devolve 1 se mudou.
unsafe extern "thiscall" fn passo_em_rede(dia: usize, p: usize) -> u32 {
    let u = |q: usize, o: usize| core::ptr::read_unaligned((q + o) as *const usize);
    let por = |q: usize, o: usize, v: u32| core::ptr::write_unaligned((q + o) as *mut u32, v);
    let andar: unsafe extern "thiscall" fn(usize, u32) -> u32 = core::mem::transmute(0x6b5ce0usize);
    let iniciar: unsafe extern "thiscall" fn(usize) -> u32 = core::mem::transmute(0x6b5a70usize);
    let relogio: unsafe extern "C" fn() -> u32 = core::mem::transmute(0x90c510usize);
    let sons: unsafe extern "thiscall" fn(usize, usize) -> u8 = core::mem::transmute(0x6d8c70usize);
    let proximo_evento: unsafe extern "thiscall" fn(usize, u32) -> usize = core::mem::transmute(0x6d78b0usize);
    let tabela: unsafe extern "thiscall" fn(usize, u32) -> u8 = core::mem::transmute(0x6d5cd0usize);
    let laco: unsafe extern "thiscall" fn(usize, i32) -> u32 = core::mem::transmute(0x6b98c0usize);
    let registrar: unsafe extern "thiscall" fn(usize, usize, usize, u32) = core::mem::transmute(0x729ff0usize);
    let competicao: unsafe extern "C" fn(u32, u32) -> u8 = core::mem::transmute(0x6b6570usize);
    let seguir = || {
        if andar(dia, 0) != 0 {
            iniciar(dia);
        }
        0u32
    };
    if p == 0 {
        return seguir();
    }
    let pl = u(p, 0x5b);
    crate::comparacao::ramo("passo em rede");
    let motor = u(p, 0x57);
    let estado = pl as *mut u8;
    let eu = *(0xb77c7a as *const i16) as isize;
    let visto = |i: isize| ((pl as isize) + 0x85 + 4 * i) as *mut u32;
    // todos viram de novo: so o humano da vez marca e espera
    let rever = || {
        core::ptr::write_bytes((pl + 0x85) as *mut u8, 0, 0x40);
        core::ptr::write_unaligned(visto(eu), 1);
        *((pl + 0x107) as *mut u8) = 1;
    };
    let mostrar_evento = |ev: usize| {
        if tabela(u(motor, 0x8f7a), *(ev as *const u16) as u32) == 2 {
            por(pl, 0x115, 1);
        }
        por(pl, 1, ev as u32);
        *estado = 8;
        rever();
        por(pl, 0x109, 0);
    };
    if *estado != 0 && *((pl + 0x107) as *const u8) != *((pl + 0x105) as *const u8) {
        if core::ptr::read_unaligned(visto(eu)) != 0 {
            return 0;
        }
        core::ptr::write_unaligned(visto(eu), 1);
        *((pl + 0x107) as *mut u8) += 1;
        por(pl, 0x10d, relogio());
        return 1;
    }
    if *((pl + 0x108) as *const u8) != 0 {
        return seguir();
    }
    if *estado & 8 != 0 && sons(u(motor, 0x8f7a), pl + 5) == 0 {
        return seguir();
    }
    let espera = if *((u(motor, 0x8f7a) + 0x2db0) as *const u8) == 0x14 { 0 } else { u(pl, 0x109) as u32 };
    if relogio() < (u(pl, 0x10d) as u32).wrapping_add(espera) {
        return seguir();
    }
    if *estado & 8 != 0 {
        let ev = proximo_evento(u(motor, 0x8f7a), 0);
        if ev != 0 {
            mostrar_evento(ev);
            por(pl, 0x10d, relogio());
            return 1;
        }
    }
    if u(pl, 0x111) != 0 {
        por(pl, 0x115, 0);
        let r = laco(motor, 1) as u8;
        *((p + 0x67) as *mut u8) = r;
        if r == 2 || r == 8 {
            *((dia + 0x25) as *mut i32) += 1;
        }
        if *((u(motor, 0x8f7a) + 5) as *const u8) != 0 {
            let ev = proximo_evento(u(motor, 0x8f7a), 0);
            if ev != 0 {
                mostrar_evento(ev);
                por(pl, 0x10d, relogio());
                por(pl, 0x111, 0);
                return 1;
            }
        }
    }
    *estado = 0;
    let fim = *((p + 0x67) as *const u8);
    let resumo = u(p, 0x5f);
    let marcar = |bit: u8| {
        por(pl, 0x109, 0);
        *(pl as *mut u8) |= bit;
    };
    if fim == 2 {
        *estado = 0x40;
        por(pl, 0x109, 0);
    }
    if *((p + 0x67) as *const u8) == 8 {
        marcar(0x40);
    }
    if *((p + 0x67) as *const u8) == 4 {
        marcar(0x20);
    }
    if byte(motor, 0xf5bd) as i32 > *((resumo + 0x11f) as *const u8) as i32 {
        marcar(1);
    }
    if byte(motor, 0xf5f3) as i32 > *((u(p, 0x5f) + 0x744) as *const u8) as i32 {
        marcar(2);
    }
    if u(pl, 0x115) != 0 {
        marcar(0x10);
    }
    if *((motor + 0x8eb2) as *const u8) != 0 {
        marcar(0x80);
    }
    let r = u(p, 0x5f);
    if *((motor + 0x8ed0) as *const i16) as i32 / 11 > *((r + 0x4d) as *const i16) as i32 {
        *estado |= 4;
        por(pl, 0x109, (0x226 - 50 * *((u(p, 0x5f) + 0x51) as *const i16) as i32) as u32);
    }
    por(pl, 0x111, 1);
    if *estado == 0 {
        return 0;
    }
    rever();
    por(pl, 0x10d, relogio());
    registrar(u(0xb6b7c0, 0), motor, u(p, 0x5f), 1);
    let s = u(u(dia, 0x34), 0x5f);
    let trocar = if s != 0 {
        let a = competicao(*((u(p, 0x5f) + 0x4f) as *const u16) as u32, 1) as i8;
        let b = competicao(*((s + 0x4f) as *const u16) as u32, 1) as i8;
        a > b || *((u(p, 0x5f) + 0x4d) as *const i16) > *((u(u(dia, 0x34), 0x5f) + 0x4d) as *const i16)
    } else {
        true
    };
    if trocar {
        por(dia, 0x34, p as u32);
    }
    1
}

// ponytail: os eventos gravados mexem em arquivos e o passo em rede so roda em jogo em rede; sem
// comparacao propria, validados pela carreira (Rust x original).
unsafe extern "thiscall" fn comparar_gravar_eventos(e: usize, desc: *mut u32, humano: u8) -> u8 {
    orig::<unsafe extern "thiscall" fn(usize, *mut u32, u8) -> u8>(339)(e, desc, humano)
}
/// Ler os eventos so le arquivo (sem efeito fora do registro): a original e a copia leem os mesmos
/// eventos (+6 quantos, +0x720 os eventos de 0xe bytes) e o resultado e conferido. Nasceu do erro
/// `Area.cpp 507` ao rever o relatorio de uma partida antiga (17/10/2026).
unsafe extern "thiscall" fn comparar_ler_eventos(e: usize, desc: *const u32) -> u8 {
    let o = orig::<unsafe extern "thiscall" fn(usize, *const u32) -> u8>(340);
    if desc.is_null() {
        return o(e, desc);
    }
    let n = (*desc.add(1) as usize).min(0x10000);
    let reg = [(e + 6, 2), (e + 0x720, 0xe * n)];
    let (r, rr, igual, mo, mr) = crate::comparacao::lado_a_lado(&reg, || o(e, desc), || ler_eventos(e, desc));
    PLACAR.registrar(igual && r == rr, || format!("ler_eventos(pos {} n {} numero {} humano {}) original={} rust={} {:x?} x {:x?}", *desc, *desc.add(1), *desc.add(2), *(desc.add(3) as *const u8), r, rr, mo, mr));
    r
}
unsafe extern "thiscall" fn comparar_passo_em_rede(dia: usize, p: usize) -> u32 {
    orig::<unsafe extern "thiscall" fn(usize, usize) -> u32>(341)(dia, p)
}

// ---------- centesima quinquagesima quinta leva: o leitor dos eventos da partida (0x6d9e50) ----------

/// Como `aviso_em`, e o jogo para (como a original: 0x5cc7d0, 0x5a8f60 e sai com -1).
unsafe fn erro_em(arquivo: usize, linha: u32) -> ! {
    let fechar1: unsafe extern "C" fn() = core::mem::transmute(0x5cc7d0usize);
    let fechar2: unsafe extern "C" fn() = core::mem::transmute(0x5a8f60usize);
    let sair: unsafe extern "C" fn(i32) -> ! = core::mem::transmute(0x945934usize);
    aviso_em(arquivo, linha);
    fechar1();
    fechar2();
    sair(-1)
}

/// { 0x6d9e50 } (match_events.cpp, ~5,2 KB): le o `events_<idioma>.cfg` (CM3_DATA; sem ele, o
/// `events_eng.cfg`, e sem este o jogo para, erro 0xcc4) para a tabela dos 677 codigos de evento em
/// [0xb68788] (0x12 bytes: 7 bytes de opcoes, +8 os sons de 0x110 bytes, +0xc quantos, +0xe o peso).
/// Com outro idioma desde a ultima leitura, 0x6d5b50 limpa antes; ja lida ([0xb6b723]), nada.
/// Linhas: `=id,o0..o6` abre um evento (o4 entre 0 e 11; o2 sem o0 avisa 0xd40), `>peso,tipo,nome`
/// acrescenta um som (com `-verifysounds` na linha de comando, confere o arquivo em CM3_SOUNDS),
/// `G`/`R` os dois textos do ultimo som (alocados; marcas `<X` desconhecidas avisam). No fim, os
/// pesos viram (maior x 10) / peso e +0xe a soma; evento sem som ganha o som padrao (0xb68670).
/// Le pelo `fgetc` do jogo e usa o buffer [0xde1f64], como a original.
unsafe extern "C" fn ler_eventos_cfg() {
    let idioma: unsafe extern "C" fn() -> i32 = core::mem::transmute(0x66f4d0usize);
    let limpar: unsafe extern "C" fn() = core::mem::transmute(0x6d5b50usize);
    let caminho: unsafe extern "C" fn(usize, usize) -> usize = core::mem::transmute(0x90bde0usize);
    let abrir: unsafe extern "C" fn(usize, usize) -> usize = core::mem::transmute(0x945b00usize);
    let fechar: unsafe extern "C" fn(usize) -> i32 = core::mem::transmute(0x945a09usize);
    let ler: unsafe extern "C" fn(usize) -> i32 = core::mem::transmute(0x9469e0usize);
    let numero: unsafe extern "C" fn(usize) -> i32 = core::mem::transmute(0x947311usize);
    let numero_curto: unsafe extern "C" fn(usize) -> i32 = core::mem::transmute(0x94739cusize);
    let realocar: unsafe extern "C" fn(usize, u32) -> usize = core::mem::transmute(0x945667usize);
    let alocar: unsafe extern "C" fn(u32) -> usize = core::mem::transmute(0x944e46usize);
    let procurar: unsafe extern "C" fn(usize, usize) -> usize = core::mem::transmute(0x945a60usize);
    let existe: unsafe extern "C" fn(usize) -> i32 = core::mem::transmute(0x90c120usize);
    let formatar: unsafe extern "C" fn(usize, usize, ...) -> i32 = core::mem::transmute(0x944c9fusize);
    let formatar_texto: unsafe extern "C" fn(usize, usize, ...) -> i32 = core::mem::transmute(0x66f4e0usize);
    let caixa: unsafe extern "C" fn(usize, usize, u32) = core::mem::transmute(0x5e8290usize);
    const FONTE: usize = 0xa159b0; // match_events.cpp
    const TABELA: usize = 0xb68788;
    const FIM: usize = 0xb6b723;
    const BUF: usize = 0xde1f64;
    let evento = |k: i32| TABELA.wrapping_add((k as isize * 0x12) as usize);
    let sons = |e: usize| core::ptr::read_unaligned((e + 8) as *const usize);
    let quantos = |e: usize| core::ptr::read_unaligned((e + 0xc) as *const i16);
    let peso = |e: usize| (e + 0xe) as *mut i32;

    if *(0xa1599c as *const i32) != idioma() {
        limpar();
    }
    if *(FIM as *const u8) != 0 {
        return;
    }
    let mut e = TABELA;
    while e < FIM {
        *(e as *mut u8) = 0xff;
        for o in 1..=7 {
            *((e + o) as *mut u8) = 0;
        }
        core::ptr::write_unaligned((e + 8) as *mut u32, 0);
        core::ptr::write_unaligned((e + 0xc) as *mut u16, 0);
        core::ptr::write_unaligned(peso(e), 0);
        e += 0x12;
    }
    let lingua = idioma();
    *(0xa1599c as *mut i32) = lingua;
    let nome = match lingua {
        2 => 0xa15cec,
        3 => 0xa15cdc,
        4 => 0xa15ccc,
        5 => 0xa15cbc,
        6 => 0xa15c6c,
        7 => 0xa15cac,
        8 => 0xa15c9c,
        9 => 0xa15c8c,
        10 => 0xa15c7c,
        11 => 0xa15c5c,
        12 => 0xa15c4c,
        _ => 0,
    };
    let mut f = if nome != 0 { abrir(caminho(0x9b5348, nome), 0x9899fc) } else { 0 };
    if f != 0 {
        *(FIM as *mut u8) = 1;
    } else {
        // ponytail: a original testa [0xb6b723] de novo aqui; ele acabou de ser visto zerado
        *(FIM as *mut u8) = 1;
        f = abrir(caminho(0x9b5348, 0xa15c3c), 0x9899fc);
        if f == 0 {
            erro_em(FONTE, 0xcc4);
        }
    }

    let fim_de_arquivo = || *((f + 0xc) as *const u8) & 0x10 != 0;
    let pula_brancos_e_le = || {
        let mut c = ler(f);
        while (c == 0x20 || c == 0xd) && c != -1 {
            c = ler(f);
        }
        c
    };
    // um campo ate a virgula ou o fim da linha, no buffer; devolve o ultimo caractere lido
    let campo = || {
        let mut c = pula_brancos_e_le();
        let mut n = 0usize;
        while c != 0x2c && c != 0xa && c != -1 {
            *((BUF + n) as *mut u8) = c as u8;
            n += 1;
            c = ler(f);
        }
        *((BUF + n) as *mut u8) = 0;
        c
    };
    // a linha inteira (virgulas inclusive) num texto alocado; marcas `<X` desconhecidas avisam
    let texto = |linha_alocacao: u32, linha_marca: u32| -> usize {
        let mut c = pula_brancos_e_le();
        let mut n = 0usize;
        while c != 0xa && c != -1 {
            *((BUF + n) as *mut u8) = c as u8;
            n += 1;
            c = ler(f);
        }
        *((BUF + n) as *mut u8) = 0;
        let t = alocar(n as u32 + 1);
        if t == 0 {
            erro_em(FONTE, linha_alocacao);
        }
        core::ptr::copy_nonoverlapping(BUF as *const u8, t as *mut u8, n + 1);
        let mut i = 0usize;
        while *((t + i) as *const u8) != 0 {
            if *((t + i) as *const u8) == b'<' {
                let x = *((t + i + 1) as *const i8);
                if !b"CDFNOPRTYcdfnoprty".contains(&(x as u8)) {
                    formatar_texto(BUF, 0xa15b74, x as i32);
                    aviso_em(FONTE, linha_marca);
                }
            }
            i += 1;
        }
        t
    };

    let mut atual = -1i32;
    while !fim_de_arquivo() {
        let c = ler(f);
        if c == -1 {
            continue;
        }
        match c {
            0xd => {}
            0x3d => {
                // `=`: confere o evento anterior e abre o novo
                if atual != -1 {
                    let e = evento(atual);
                    let s = sons(e);
                    if s == 0 {
                        formatar(BUF, 0xa15b38, atual);
                        erro_em(FONTE, 0xcdf);
                    }
                    for j in 0..quantos(e).max(0) as usize {
                        if core::ptr::read_unaligned((s + 0x110 * j + 0x108) as *const usize) == 0 {
                            formatar(BUF, 0xa15af0, atual);
                            erro_em(FONTE, 0xcea);
                        }
                    }
                }
                campo();
                atual = numero(BUF);
                if !(0..=0x2a4).contains(&atual) {
                    formatar(BUF, 0xa15aa0, atual);
                    erro_em(FONTE, 0xcfb);
                }
                let e = evento(atual);
                let mut c = 0;
                for o in 0..7usize {
                    c = campo();
                    let v = numero_curto(BUF) as u8;
                    *((e + o) as *mut u8) = v;
                    if o == 4 {
                        let b = (e + 4) as *mut i8;
                        if *b < 0 {
                            *b = 0;
                        }
                        if *b > 0xb {
                            *b = 0xb;
                        }
                    }
                }
                while c != 0xa && c != -1 {
                    c = ler(f);
                }
                if *((e + 2) as *const u8) != 0 && *(e as *const u8) == 0 {
                    formatar(BUF, 0xa15bf0, atual);
                    aviso_em(FONTE, 0xd40);
                }
            }
            0x3e => {
                // `>`: mais um som no evento aberto
                if atual == -1 {
                    erro_em(FONTE, 0xd49);
                }
                let e = evento(atual);
                let novo = realocar(sons(e), (quantos(e) as i32 + 1) as u32 * 0x110);
                if novo == 0 {
                    erro_em(FONTE, 0xd50);
                }
                core::ptr::write_unaligned((e + 8) as *mut usize, novo);
                let s = novo + 0x110 * quantos(e) as usize;
                campo();
                *(s as *mut i16) = numero_curto(BUF) as i16;
                let p = (*(s as *const i16) as i32).max(*peso(e));
                core::ptr::write_unaligned(peso(e), p);
                campo();
                *((s + 2) as *mut i16) = numero_curto(BUF) as i16;
                let mut c = ler(f);
                *((s + 4) as *mut u8) = 0;
                while (c == 0x20 || c == 0xd) && c != -1 {
                    c = ler(f);
                }
                let mut n = 0usize;
                while c != 0xa && c != -1 {
                    n += 1;
                    *((s + 3 + n) as *mut u8) = c as u8;
                    c = ler(f);
                }
                *((s + 4 + n) as *mut u8) = 0;
                if procurar(0xae2c98, 0xa15be0) != 0 && n != 0 && existe(caminho(0x9c382c, s + 4)) == 0 {
                    formatar(BUF, 0xa15bac, caminho(0x9c382c, s + 4));
                    caixa(0x9870e0, BUF, 0);
                }
                core::ptr::write_unaligned((s + 0x108) as *mut usize, 0);
                core::ptr::write_unaligned((s + 0x10c) as *mut usize, 0);
                core::ptr::write_unaligned((e + 0xc) as *mut i16, quantos(e) + 1);
            }
            0x47 | 0x67 | 0x52 | 0x72 => {
                // `G`/`R`: os dois textos do ultimo som
                let (o, sem, cheio, ja, alocacao, marca) = if c == 0x47 || c == 0x67 {
                    (0x108usize, 0xd80, 0xd82, 0xd84, 0xd97, 0xdc3)
                } else {
                    (0x10c, 0xdcf, 0xdd1, 0xdd3, 0xde6, 0xe12)
                };
                if atual == -1 {
                    erro_em(FONTE, sem);
                }
                let e = evento(atual);
                if quantos(e) == 0 {
                    erro_em(FONTE, cheio);
                }
                let campo_texto = (sons(e) as isize + quantos(e) as isize * 0x110 - 0x110 + o as isize) as usize;
                if core::ptr::read_unaligned(campo_texto as *const usize) != 0 {
                    erro_em(FONTE, ja);
                }
                let t = texto(alocacao, marca);
                // a original grava o ponteiro antes de copiar; o resultado e o mesmo
                core::ptr::write_unaligned(campo_texto as *mut usize, t);
            }
            _ => {
                let mut c = c;
                while c != 0xa && c != -1 {
                    c = ler(f);
                }
            }
        }
    }

    // os pesos: (maior x 10) / peso de cada som, e +0xe a soma; evento sem som ganha o padrao
    for k in 0..0x2a5i32 {
        let e = evento(k);
        if sons(e) == 0 {
            core::ptr::write_unaligned((e + 8) as *mut usize, 0xb68670);
            core::ptr::write_unaligned((e + 0xc) as *mut i16, 1);
            formatar(BUF, 0xa15b38, k);
            aviso_em(FONTE, 0xe46);
        } else {
            let total = (*peso(e)).wrapping_mul(10);
            core::ptr::write_unaligned(peso(e), total);
            let mut soma = 0i32;
            for j in 0..quantos(e).max(0) as usize {
                let s = (sons(e) + 0x110 * j) as *mut i16;
                *s = (core::ptr::read_unaligned(peso(e)) / *s as i32) as i16;
                soma += *s as i32;
            }
            core::ptr::write_unaligned(peso(e), soma);
        }
    }
    fechar(f);
}

// ponytail: le arquivo, aloca os textos e grava a tabela global; sem comparacao propria, validada
// pela carreira (Rust x original) e pela comparacao da tabela no fim da leitura.
unsafe extern "C" fn comparar_ler_eventos_cfg() {
    orig::<unsafe extern "C" fn()>(342)()
}

// ---------- centesima quinquagesima sexta leva: o texto dos eventos e o comeco da partida assistida (0x6d8d10, 0x6b5260) ----------

/// { 0x6d8d10 } (stdcall, ret 0x10, match_events.cpp): o texto do evento `ev` (+0 codigo, +2 qual
/// som, +5/+6 e +7/+8 os dois jogadores (lado, indice), +9 um numero) da partida `ctx` (+0/+4 os
/// clubes, +0x40 o arbitro), com `comp` a competicao (-1 sem) e `variante` o trecho entre `|` (0 o
/// primeiro). Le o texto `R` (+0x10c) do som escolhido (no maximo o ultimo) e troca as marcas:
/// `<P1>`/`<P>` jogador (0x6db2d0), `<T1>`/`<T2>` clube, `<C>` competicao, `<F>` a fase dela
/// (0x4bfa30/0x4bff70), `<D>`/`<D1>` o numero (+1), `<N>` o numero por extenso (0x90c310), `<rf>`/`<Rf>`
/// o arbitro ("Mr ..." ou "the referee" conforme o idioma e um resto de divisao por 5), `<O>`/`<Y>` nada.
/// `{...}` antes ou depois da marca sao prefixo e sufixo (0x6701f0, que aplica artigo e genero);
/// a letra seguinte `C` poe em maiusculas (0x90c2d0). Escreve em [0xb67ea0] (e devolve), recontando
/// o tamanho por `strlen` depois de cada marca, como a original; sem evento, sem texto ou sem o
/// trecho pedido, 0. Marca desconhecida avisa 0xb10.
unsafe extern "stdcall" fn texto_do_evento(ev: usize, ctx: usize, comp: i32, variante: u32) -> usize {
    const BUF: usize = 0xb67ea0;
    const TEMP: usize = 0xb67dd8;
    let formatar: unsafe extern "C" fn(usize, usize, ...) -> i32 = core::mem::transmute(0x944c9fusize);
    let formatar_texto: unsafe extern "C" fn(usize, usize, ...) -> i32 = core::mem::transmute(0x66f4e0usize);
    let nome_do_jogador: unsafe extern "C" fn(usize, i32, i32, *mut u8, u32, u32, u32, u32) -> usize = core::mem::transmute(0x6db2d0usize);
    let compor: unsafe extern "C" fn(usize, *const u8, *const u8, u32, u32) -> usize = core::mem::transmute(0x6701f0usize);
    let maiuscula: unsafe extern "C" fn(i32) -> u8 = core::mem::transmute(0x90c2d0usize);
    let por_extenso: unsafe extern "C" fn(i32, i32) -> usize = core::mem::transmute(0x90c310usize);
    let idioma: unsafe extern "C" fn() -> i32 = core::mem::transmute(0x66f4d0usize);
    let nome_do_arbitro: unsafe extern "C" fn(usize, *mut u8, u32, u32) = core::mem::transmute(0x53eab0usize);
    let fase: unsafe extern "C" fn(usize, u32, u32, u32, *mut u8, u32) = core::mem::transmute(0x4bfa30usize);
    let criterio: unsafe extern "C" fn(u32, u32, u32, u32) -> u8 = core::mem::transmute(0x4bff70usize);
    if ev == 0 || ctx == 0 {
        return 0;
    }
    let k = (((*(ev as *const u16) & 0x7fff) as i32 - 0x1f40) as i16) as isize;
    let e = (0xb68788isize + k * 18) as usize;
    let sons = core::ptr::read_unaligned((e + 8) as *const usize);
    if sons == 0 {
        return 0;
    }
    let n = core::ptr::read_unaligned((e + 0xc) as *const i16);
    let qual = (ev + 2) as *mut i16;
    if *qual as i32 > n as i32 - 1 {
        *qual = n.wrapping_sub(1);
    }
    let mut s = core::ptr::read_unaligned((sons as isize + *qual as isize * 0x110 + 0x10c) as *const usize);
    if s == 0 {
        return 0;
    }
    let v = variante as u16 as i16;
    if v > 0 {
        let mut resta = v as u8 as i8;
        let mut c = *(s as *const u8);
        if c != 0 {
            loop {
                if c == b'|' {
                    resta = resta.wrapping_sub(1);
                    if resta <= 0 {
                        s += 1;
                        break;
                    }
                }
                c = *((s + 1) as *const u8);
                s += 1;
                if c == 0 {
                    break;
                }
            }
        }
        if *(s as *const u8) == 0 {
            return 0;
        }
    }
    crate::comparacao::ramo("texto do evento");
    let t = |i: i16| *((s as isize + i as isize) as *const u8);
    let dest = |o: i16| (BUF as isize + o as isize) as usize;
    let b = |o: usize| *((ev + o) as *const u8);
    let mut pos: i16 = 0;
    let mut out: i16 = 0;
    // o prefixo `{...}` logo antes da marca
    let prefixo = |pos: i16, p: &mut [u8; 0x100]| {
        p[0] = 0;
        if pos > 1 && (t(pos - 1) == b'}' || t(pos - 1) == b']') {
            let mut a = pos - 2;
            while a >= 0 && t(a) != b'{' && t(a) != b'[' {
                a -= 1;
            }
            let j = a as i32;
            let fim = pos as i32 - j - 1;
            let mut c = 1i32;
            while c < fim {
                p[(c - 1) as usize] = t((j + c) as i16);
                c += 1;
            }
            p[(c - 1) as usize] = 0;
        }
    };
    // o sufixo `{...}` logo depois do `>` da marca (a procura comeca em `inicio`)
    let sufixo = |inicio: i16, x: &mut [u8; 0x100]| {
        x[0] = 0;
        let mut fe = inicio;
        while t(fe) != b'>' && t(fe) != 0 {
            fe += 1;
        }
        if t(fe + 1) == b'{' || t(fe + 1) == b'[' {
            let mut j = fe + 2;
            while t(j) != b'}' && t(j) != 0 {
                x[(j - fe - 2) as usize] = t(j);
                j += 1;
            }
            x[(j - fe - 2) as usize] = 0;
        }
    };
    let escrever = |out: i16, r: usize| {
        formatar(dest(out), 0x991944, r);
    };
    let em_maiusculas = |out: i16, r: usize| {
        let mut j: i16 = 0;
        while *((r as isize + j as isize) as *const u8) != 0 {
            let c = maiuscula(*((r as isize + j as isize) as *const u8) as i32);
            *(dest(out + j) as *mut u8) = c;
            j += 1;
        }
        *(dest(out + j) as *mut u8) = 0;
    };
    let mut pre = [0u8; 0x100];
    let mut suf = [0u8; 0x100];
    let mut nome = [0u8; 0xd0];
    let mut arb = [0u8; 0xd0];
    let mut texto_fase = [0u8; 0x800];

    if t(0) != 0 {
        loop {
            let c = t(pos);
            if c == b'|' {
                break;
            }
            if c != b'<' {
                if c != b'{' && c != b'[' {
                    *(dest(out) as *mut u8) = c;
                    out += 1;
                } else {
                    // `{...}`/`[...]` solto: pula ate o fecho
                    let mut j = pos;
                    let mut a = c;
                    loop {
                        if a == b']' || a == 0 {
                            break;
                        }
                        j += 1;
                        a = t(j);
                        if a == b'}' {
                            break;
                        }
                    }
                    pos = j;
                }
            } else {
                let x = t(pos + 1) as i8 as i32;
                match x as u8 {
                    b'P' | b'p' => {
                        let (lado, idx) = if t(pos + 2) == b'1' && b(5) != 0xff { (b(5), b(6)) } else { (b(7), b(8)) };
                        if lado != 0xff {
                            nome_do_jogador(ctx, lado as i8 as i32, idx as i8 as i32, nome.as_mut_ptr(), 0xc8, 0, 0, 1);
                            sufixo(pos + 3, &mut suf);
                            let r = compor(nome.as_ptr() as usize, 0xad9c64 as *const u8, suf.as_ptr(), 0x64, 0x64);
                            if t(pos + 3) == b'C' || t(pos + 3) == b'c' {
                                em_maiusculas(out, r);
                            } else {
                                escrever(out, r);
                            }
                        }
                    }
                    b'T' | b't' => {
                        let dois = t(pos + 2) == b'2';
                        let casa = b(6) != 0;
                        let id = if dois == casa { *(ctx as *const usize) } else { *((ctx + 4) as *const usize) };
                        let clube = (*(0xae23b4 as *const usize)).wrapping_add(id.wrapping_mul(0x245));
                        prefixo(pos, &mut pre);
                        sufixo(pos + 2, &mut suf);
                        let g = *((clube + 0x52) as *const u8) as u32;
                        let r = compor(clube + 0x38, pre.as_ptr(), suf.as_ptr(), g, g);
                        if t(pos + 2) == b'C' || t(pos + 2) == b'c' {
                            em_maiusculas(out, r);
                        } else {
                            escrever(out, r);
                        }
                    }
                    b'C' | b'c' | b'F' | b'f' => {
                        if comp >= 0 {
                            let cp = (*(0xae23d0 as *const usize)).wrapping_add((comp as usize).wrapping_mul(0x6b));
                            prefixo(pos, &mut pre);
                            sufixo(pos + 2, &mut suf);
                            let r = if x as u8 == b'C' || x as u8 == b'c' {
                                let g = *((cp + 0x52) as *const u8) as u32;
                                compor(cp + 0x38, pre.as_ptr(), suf.as_ptr(), g, g)
                            } else {
                                fase(cp, 0, 0x96, 3, texto_fase.as_mut_ptr(), 0x7d0);
                                let g = criterio(0, 0, 0x96, 3) as u32;
                                compor(texto_fase.as_ptr() as usize, pre.as_ptr(), suf.as_ptr(), g, g)
                            };
                            escrever(out, r);
                        }
                    }
                    b'D' | b'd' => {
                        let numero = core::ptr::read_unaligned((ev + 9) as *const i32);
                        formatar(dest(out), 0x98806c, if t(pos + 2) == b'1' { numero.wrapping_add(1) } else { numero });
                    }
                    b'N' | b'n' => {
                        let r = por_extenso(core::ptr::read_unaligned((ev + 9) as *const i32), -1);
                        escrever(out, r);
                    }
                    b'R' | b'r' => {
                        if t(pos + 2) == b'f' {
                            let fixo = if x as u8 == b'R' { 0xa15a14usize } else { 0xa159e0 };
                            let arbitro = core::ptr::read_unaligned((ctx + 0x40) as *const i32);
                            if arbitro <= -1 {
                                formatar_texto(dest(out), fixo);
                            } else {
                                let resto = ((b(7) as i8 as i32 + b(5) as i8 as i32 + core::ptr::read_unaligned((ctx + 4) as *const i32)) % 5) as i8;
                                let ficha = (*(0xae23e8 as *const usize)).wrapping_add((arbitro as usize).wrapping_mul(0x2b));
                                let modo = if idioma() == 4 && resto == 0 {
                                    1
                                } else if resto == 0 {
                                    5
                                } else if resto > 0 && resto <= 2 {
                                    1
                                } else {
                                    0
                                };
                                match modo {
                                    1 => {
                                        nome_do_arbitro(ficha, arb.as_mut_ptr(), 0xc8, 1);
                                        formatar_texto(TEMP, 0xa15a20, arb.as_ptr());
                                    }
                                    5 => {
                                        nome_do_arbitro(ficha, arb.as_mut_ptr(), 0xc8, 5);
                                        formatar_texto(TEMP, 0xa159ec, arb.as_ptr());
                                    }
                                    _ => {
                                        formatar_texto(TEMP, if x as u8 == b'R' { 0xa15a14 } else { 0xa159e0 });
                                    }
                                }
                                // como na original: o texto pronto vira o formato
                                formatar(dest(out), TEMP);
                            }
                        }
                    }
                    b'O' | b'o' | b'Y' | b'y' => {}
                    _ => aviso_em(0xa159b0, 0xb10),
                }
                // fim da marca: ate o `>`; o tamanho e recontado
                if t(pos) != b'>' {
                    let mut j = pos;
                    loop {
                        if t(j) == 0 {
                            break;
                        }
                        j += 1;
                        if t(j) == b'>' {
                            break;
                        }
                    }
                    pos = j;
                }
                if t(pos) == 0 {
                    pos -= 1;
                }
                let mut l = 0usize;
                while *((BUF + l) as *const u8) != 0 {
                    l += 1;
                }
                out = l as i16;
            }
            pos += 1;
            if t(pos) == 0 {
                break;
            }
        }
    }
    *(dest(out) as *mut u8) = 0;
    BUF
}

/// { 0x6b5260 } (thiscall, ret 4, match_day.cpp): o humano da vez ([0xb77c7a]) confirma a partida
/// `p` em rede (placar dos humanos +0x5b: +0x45 quem confirmou, +0x105 humanos, +0x106 confirmados).
/// Com todos: cria o motor (0x6b7e50) e o prepara para ver (0x6b7f20 com o ultimo 1). Se ele nao
/// for de ver (devolve 0), joga ate o fim (contando em [0xb67a50]+0x25), cria o resumo, registra
/// (0x7293f0), libera o motor, tira da fila e marca +0x119; se for, avisa o narrador (+0x8f7a = 3),
/// cria o resumo e registra para ver (0x729ff0) e devolve 1. Erros 0x4b8 (sem partida), 0x4d0, 0x4ea,
/// 0x511 (sem memoria).
unsafe extern "thiscall" fn confirmar_partida_em_rede(_dia: usize, p: usize) -> u32 {
    let u = |q: usize, o: usize| core::ptr::read_unaligned((q + o) as *const usize);
    let por = |q: usize, o: usize, v: usize| core::ptr::write_unaligned((q + o) as *mut usize, v);
    let novo: unsafe extern "C" fn(u32) -> usize = core::mem::transmute(0x944cf1usize);
    let liberar: unsafe extern "C" fn(usize) = core::mem::transmute(0x944c94usize);
    let construir: unsafe extern "thiscall" fn(usize) -> usize = core::mem::transmute(0x6b7e50usize);
    let preparar: unsafe extern "thiscall" fn(usize, usize, u32, usize, u32) -> u8 = core::mem::transmute(0x6b7f20usize);
    let laco: unsafe extern "thiscall" fn(usize, i32) -> u32 = core::mem::transmute(0x6b98c0usize);
    let vetor: unsafe extern "stdcall" fn(usize, u32, u32, usize, usize) = core::mem::transmute(0x9463afusize);
    let registrar: unsafe extern "thiscall" fn(usize, usize, usize) = core::mem::transmute(0x7293f0usize);
    let registrar_para_ver: unsafe extern "thiscall" fn(usize, usize, usize, u32) = core::mem::transmute(0x729ff0usize);
    let destruir_motor: unsafe extern "thiscall" fn(usize) = core::mem::transmute(0x6b97a0usize);
    let tirar: unsafe extern "thiscall" fn(usize, usize) = core::mem::transmute(0x90d6b0usize);
    const FONTE: usize = 0xa15708; // match_day.cpp
    if p == 0 {
        aviso_em(FONTE, 0x4b8);
        return 0;
    }
    let pl = u(p, 0x5b);
    let eu = *(0xb77c7a as *const i16) as isize;
    let confirmou = (pl as isize + eu * 4 + 0x45) as *mut u32;
    if core::ptr::read_unaligned(confirmou) == 0 {
        core::ptr::write_unaligned(confirmou, 1);
        *((pl + 0x106) as *mut u8) = (*((pl + 0x106) as *const u8)).wrapping_add(1);
    }
    if *((pl + 0x106) as *const u8) != *((pl + 0x105) as *const u8) {
        return 0;
    }
    crate::comparacao::ramo("partida em rede confirmada");
    let mem = novo(0xf63b);
    let motor = if mem != 0 { construir(mem) } else { 0 };
    por(p, 0x57, motor);
    if motor == 0 {
        aviso_em(FONTE, 0x4d0);
        return 0;
    }
    let novo_resumo = || {
        let r = novo(0xd7a);
        if r != 0 {
            vetor(r + 0x11f, 0x625, 2, 0x453c30, 0x453c10);
        }
        por(p, 0x5f, r);
        r
    };
    if preparar(motor, p + 4, 0, 0, 1) as i8 == 0 {
        let terminou = |e: u8| e == 2 || e == 8;
        let estado = (p + 0x67) as *mut u8;
        while !terminou(*estado) {
            let e = laco(u(p, 0x57), -1) as u8;
            *estado = e;
            if terminou(e) {
                *((u(0xb67a50, 0) + 0x25) as *mut i32) += 1;
            }
        }
        let r = novo_resumo();
        if r == 0 {
            aviso_em(FONTE, 0x4ea);
            return 0;
        }
        registrar(u(0xb6b7c0, 0), u(p, 0x57), r);
        let m = u(p, 0x57);
        if m != 0 {
            destruir_motor(m);
            liberar(m);
        }
        por(p, 0x57, 0);
        tirar(u(0xde2f70, 0), p + 4);
        por(pl, 0x119, 1);
        return 0;
    }
    let narrador = u(u(p, 0x57), 0x8f7a);
    if narrador != 0 {
        *(narrador as *mut u8) = 3;
    }
    let r = novo_resumo();
    if r == 0 {
        aviso_em(FONTE, 0x511);
        return 0;
    }
    registrar_para_ver(u(0xb6b7c0, 0), u(p, 0x57), r, 1);
    1
}

/// O texto do evento so escreve nos buffers de texto ([0xb67ea0], [0xb67dd8]) e no `qual` do evento:
/// a original e a copia montam o mesmo texto e o resultado e conferido.
unsafe extern "stdcall" fn comparar_texto_do_evento(ev: usize, ctx: usize, comp: i32, variante: u32) -> usize {
    let o = orig::<unsafe extern "stdcall" fn(usize, usize, i32, u32) -> usize>(343);
    if ev == 0 {
        return o(ev, ctx, comp, variante);
    }
    let reg = [(ev + 2, 2), (0xb67ea0, 0x400), (0xb67dd8, 0xc8)];
    let (r, rr, igual, mo, mr) = crate::comparacao::lado_a_lado(&reg, || o(ev, ctx, comp, variante) as u32, || texto_do_evento(ev, ctx, comp, variante) as u32);
    PLACAR.registrar(igual && r == rr, || format!("texto_do_evento(codigo {:#x} variante {}) original={:#x} rust={:#x} {:x?} x {:x?}", *(ev as *const u16), variante, r, rr, mo, mr));
    r as usize
}
// ponytail: so roda em jogo em rede (cria e libera motor e resumo); sem comparacao propria.
unsafe extern "thiscall" fn comparar_confirmar_partida_em_rede(dia: usize, p: usize) -> u32 {
    orig::<unsafe extern "thiscall" fn(usize, usize) -> u32>(344)(dia, p)
}

// ---------- centesima quinquagesima setima leva: a narracao no painel (0x6d7b00) ----------

/// { 0x6d7b00 } (thiscall, ret 0x20, match_events.cpp, ~4,4 KB): o narrador `nar` escreve o evento `ev`
/// da partida `ctx` no `painel` (0xb74450) e toca o som dele. Antes, o ruido da torcida do humano da
/// vez ([0xb77c7a]; canal +0x20, "fxloop2.wav") e reposto se parou. Com o codigo valido e a opcao 1
/// zerada, monta o texto `G` (+0x108) do som escolhido (o trecho +0xd entre `|`) como a 0x6d8d10, mas
/// numa linha propria e com cores: comeca nas do clube do lance (0x53b640 com o uniforme do lado),
/// `<O>` passa as do outro, `<Y>` e `<R>`/`<r>` sem `f` as padrao ([0xaebdea]/[0xaebdec] ou
/// [0xae31a8]); `<N>` e o numero, `<n>` por extenso; o nome do jogador e curto se o texto inteiro
/// cabe em menos de 300 (0x5e5ad0 com a `fonte`). Larga demais para `largura` - 16: quebra (0x90cb20)
/// ou corta numa palavra com "...". Desenha (0x801040, 0x801660, 0x801960, 0x801c70, 0x800d30,
/// 0x800580 com a opcao 3). Por fim, sem trecho (+0xd) e com volume (+0x2db0 >= 101), toca o som do
/// evento (0x8025e0 no canal pela opcao 6, lado pela opcao 5), e marca a hora e a duracao do som
/// (+0x2d6c, +0x2dac = peso x volume / 100).
#[allow(clippy::too_many_arguments)]
unsafe extern "thiscall" fn narrar_no_painel(nar: usize, ev: usize, ctx: usize, comp: i32, painel: u32, largura: i32, quebrar: u32, fonte: usize, modo: u32) -> u32 {
    let tocando: unsafe extern "thiscall" fn(usize, u32) -> u32 = core::mem::transmute(0x8029f0usize);
    let parar: unsafe extern "thiscall" fn(usize, u32) = core::mem::transmute(0x802a50usize);
    let tocar: unsafe extern "thiscall" fn(usize, usize, u32, usize, u32) = core::mem::transmute(0x8025e0usize);
    let caminho: unsafe extern "C" fn(usize, usize) -> usize = core::mem::transmute(0x90bde0usize);
    let largura_do_texto: unsafe extern "C" fn(usize, *const u8) -> i32 = core::mem::transmute(0x5e5ad0usize);
    let cores_do_clube: unsafe extern "C" fn(usize, u32, *mut u8, *mut u8) = core::mem::transmute(0x53b640usize);
    let formatar: unsafe extern "C" fn(usize, usize, ...) -> i32 = core::mem::transmute(0x944c9fusize);
    let formatar_texto: unsafe extern "C" fn(usize, usize, ...) -> i32 = core::mem::transmute(0x66f4e0usize);
    let nome_do_jogador: unsafe extern "C" fn(usize, i32, i32, *mut u8, u32, u32, u32, u32) -> usize = core::mem::transmute(0x6db2d0usize);
    let compor: unsafe extern "C" fn(usize, *const u8, *const u8, u32, u32) -> usize = core::mem::transmute(0x6701f0usize);
    let maiuscula: unsafe extern "C" fn(i32) -> u8 = core::mem::transmute(0x90c2d0usize);
    let por_extenso: unsafe extern "C" fn(i32, i32) -> usize = core::mem::transmute(0x90c310usize);
    let idioma: unsafe extern "C" fn() -> i32 = core::mem::transmute(0x66f4d0usize);
    let nome_do_arbitro: unsafe extern "C" fn(usize, *mut u8, u32, u32) = core::mem::transmute(0x53eab0usize);
    let fase: unsafe extern "C" fn(usize, u32, u32, u32, *mut u8, u32) = core::mem::transmute(0x4bfa30usize);
    let criterio: unsafe extern "C" fn(u32, u32, u32, u32) -> u8 = core::mem::transmute(0x4bff70usize);
    let quebrar_linha: unsafe extern "C" fn(*mut u8, u32, u32) = core::mem::transmute(0x90cb20usize);
    let cor_de_fundo: unsafe extern "thiscall" fn(usize, u32, u32) = core::mem::transmute(0x801040usize);
    let fonte_do_painel: unsafe extern "thiscall" fn(usize, u32, usize) = core::mem::transmute(0x801660usize);
    let cor_do_texto: unsafe extern "thiscall" fn(usize, u32, u32) = core::mem::transmute(0x801960usize);
    let texto_do_painel: unsafe extern "thiscall" fn(usize, u32, *const u8) = core::mem::transmute(0x801c70usize);
    let margem: unsafe extern "thiscall" fn(usize, u32, u32) = core::mem::transmute(0x800d30usize);
    let mostrar: unsafe extern "thiscall" fn(usize, u32, u32) = core::mem::transmute(0x800580usize);
    let relogio: unsafe extern "C" fn() -> u32 = core::mem::transmute(0x90c510usize);
    const SOM: usize = 0xb74450;
    const TABELA: isize = 0xb68788;

    if ev == 0 || ctx == 0 || painel as u16 == 0xffff {
        return 0;
    }
    let eu = || *(0xb77c7a as *const i16) as isize;
    let torcida = |n: usize| ((n as isize) + eu() + 0x20) as *mut u8;
    if *torcida(nar) != 0xff && tocando(SOM, *torcida(nar) as u32) == 0 {
        parar(SOM, *torcida(nar) as u32);
        *torcida(nar) = 0xff;
    }
    if *torcida(nar) == 0xff {
        let p = caminho(0x9c382c, 0xa159a0);
        tocar(SOM, torcida(nar) as usize, 2, p, 1);
    }
    let b = |o: usize| *((ev + o) as *const u8);
    let k = ((*(ev as *const u16) & 0x7fff) as i32 - 0x1f40) as i16;
    let e = (TABELA + k as isize * 18) as usize;
    let qual = || *((ev + 2) as *const i16) as isize;
    let sons = || core::ptr::read_unaligned((e + 8) as *const usize);
    let mut cor1 = [0u8; 4];
    let mut cor2 = [0u8; 4];

    let valido = (0..0x2a5).contains(&k) && *((e + 1) as *const u8) == 0;
    if valido {
        crate::comparacao::ramo("narracao no painel");
        if sons() == 0 {
            return 0;
        }
        if core::ptr::read_unaligned((sons() as isize + qual() * 0x110 + 0x108) as *const usize) == 0 {
            return 0;
        }
        // as cores do clube do lance (uniforme do lado)
        let lado = b(6);
        let mut clube_id = if lado != 0 { *((ctx + 4) as *const usize) } else { *(ctx as *const usize) };
        let uniforme = *((ctx as isize + lado as i8 as isize * 1573 + 0x152) as *const u8) as u32;
        cores_do_clube((*(0xae23b4 as *const usize)).wrapping_add(clube_id.wrapping_mul(0x245)), uniforme, cor1.as_mut_ptr(), cor2.as_mut_ptr());
        let mut s = core::ptr::read_unaligned((sons() as isize + qual() * 0x110 + 0x108) as *const usize);
        let v = b(0xd) as i8;
        if v > 0 {
            let mut resta = v;
            let mut c = *(s as *const u8);
            if c != 0 {
                loop {
                    if c == b'|' {
                        resta -= 1;
                        if resta <= 0 {
                            s += 1;
                            break;
                        }
                    }
                    c = *((s + 1) as *const u8);
                    s += 1;
                    if c == 0 {
                        break;
                    }
                }
            }
            if *(s as *const u8) == 0 {
                return 0;
            }
        }
        let t = |i: i16| *((s as isize + i as isize) as *const u8);
        let mut linha = [0u8; 0x800];
        let l = linha.as_mut_ptr() as usize;
        let dest = |o: i16| (l as isize + o as isize) as usize;
        let mut pos: i16 = 0;
        let mut out: i16 = 0;
        let prefixo = |pos: i16, p: &mut [u8; 0x100]| {
            p[0] = 0;
            if pos > 1 && (t(pos - 1) == b'}' || t(pos - 1) == b']') {
                let mut a = pos - 2;
                while a >= 0 && t(a) != b'{' && t(a) != b'[' {
                    a -= 1;
                }
                let j = a as i32;
                let fim = pos as i32 - j - 1;
                let mut c = 1i32;
                while c < fim {
                    p[(c - 1) as usize] = t((j + c) as i16);
                    c += 1;
                }
                p[(c - 1) as usize] = 0;
            }
        };
        let sufixo = |inicio: i16, x: &mut [u8; 0x100]| {
            x[0] = 0;
            let mut fe = inicio;
            while t(fe) != b'>' && t(fe) != 0 {
                fe += 1;
            }
            if t(fe + 1) == b'{' || t(fe + 1) == b'[' {
                let mut j = fe + 2;
                while t(j) != b'}' && t(j) != 0 {
                    x[(j - fe - 2) as usize] = t(j);
                    j += 1;
                }
                x[(j - fe - 2) as usize] = 0;
            }
        };
        let escrever = |out: i16, r: usize| {
            formatar(dest(out), 0x991944, r);
        };
        let em_maiusculas = |out: i16, r: usize| {
            let mut j: i16 = 0;
            while *((r as isize + j as isize) as *const u8) != 0 {
                let c = maiuscula(*((r as isize + j as isize) as *const u8) as i32);
                *(dest(out + j) as *mut u8) = c;
                j += 1;
            }
            *(dest(out + j) as *mut u8) = 0;
        };
        let mut pre = [0u8; 0x100];
        let mut suf = [0u8; 0x100];
        let mut nome = [0u8; 0xd0];
        let mut inteiro = [0u8; 0x800];
        let mut arb = [0u8; 0xd0];
        let mut texto_fase = [0u8; 0x800];
        let cores_padrao = |c1: &mut [u8; 4], c2: &mut [u8; 4], segunda: usize| {
            core::ptr::write_unaligned(c1.as_mut_ptr() as *mut u16, *(0xaebdea as *const u16));
            core::ptr::write_unaligned(c2.as_mut_ptr() as *mut u16, *(segunda as *const u16));
        };

        if t(0) != 0 {
            loop {
                let c = t(pos);
                if c == b'|' {
                    break;
                }
                if c != b'<' {
                    if c != b'{' && c != b'[' {
                        *(dest(out) as *mut u8) = c;
                        out += 1;
                    } else {
                        let mut j = pos;
                        let mut a = c;
                        loop {
                            if a == b']' || a == 0 {
                                break;
                            }
                            j += 1;
                            a = t(j);
                            if a == b'}' {
                                break;
                            }
                        }
                        pos = j;
                    }
                } else {
                    let x = t(pos + 1);
                    match x {
                        b'P' | b'p' => {
                            let (lado_j, idx) = if t(pos + 2) == b'1' && b(5) != 0xff { (b(5), b(6)) } else { (b(7), b(8)) };
                            if lado_j != 0xff {
                                // a largura do texto inteiro (ate o `|`) decide o nome curto
                                let mut n = 0usize;
                                while *((s + n) as *const u8) != 0 && *((s + n) as *const u8) != b'|' {
                                    inteiro[n] = *((s + n) as *const u8);
                                    n += 1;
                                }
                                inteiro[n] = 0;
                                let curto = (largura_do_texto(fonte, inteiro.as_ptr()) as i16) < 0x12c;
                                nome_do_jogador(ctx, lado_j as i8 as i32, idx as i8 as i32, nome.as_mut_ptr(), 0xc8, curto as u32, modo, 1);
                                sufixo(pos + 3, &mut suf);
                                let r = compor(nome.as_ptr() as usize, 0xad9c64 as *const u8, suf.as_ptr(), 0x64, 0x64);
                                if t(pos + 3) == b'C' || t(pos + 3) == b'c' {
                                    em_maiusculas(out, r);
                                } else {
                                    escrever(out, r);
                                }
                            }
                        }
                        b'T' | b't' => {
                            let dois = t(pos + 2) == b'2';
                            let casa = b(6) != 0;
                            let id = if dois == casa { *(ctx as *const usize) } else { *((ctx + 4) as *const usize) };
                            let clube = (*(0xae23b4 as *const usize)).wrapping_add(id.wrapping_mul(0x245));
                            prefixo(pos, &mut pre);
                            sufixo(pos + 2, &mut suf);
                            let g = *((clube + 0x52) as *const u8) as u32;
                            let r = compor(clube + 0x38, pre.as_ptr(), suf.as_ptr(), g, g);
                            if t(pos + 2) == b'C' || t(pos + 2) == b'c' {
                                em_maiusculas(out, r);
                            } else {
                                escrever(out, r);
                            }
                        }
                        b'C' | b'c' | b'F' | b'f' => {
                            if comp >= 0 {
                                let cp = (*(0xae23d0 as *const usize)).wrapping_add((comp as usize).wrapping_mul(0x6b));
                                prefixo(pos, &mut pre);
                                sufixo(pos + 2, &mut suf);
                                let r = if x == b'C' || x == b'c' {
                                    let g = *((cp + 0x52) as *const u8) as u32;
                                    compor(cp + 0x38, pre.as_ptr(), suf.as_ptr(), g, g)
                                } else {
                                    fase(cp, 0, 0x96, 3, texto_fase.as_mut_ptr(), 0x7d0);
                                    let g = criterio(0, 0, 0x96, 3) as u32;
                                    compor(texto_fase.as_ptr() as usize, pre.as_ptr(), suf.as_ptr(), g, g)
                                };
                                escrever(out, r);
                            }
                        }
                        b'D' | b'd' | b'N' => {
                            let numero = core::ptr::read_unaligned((ev + 9) as *const i32);
                            let v = if x != b'N' && t(pos + 2) == b'1' { numero.wrapping_add(1) } else { numero };
                            formatar(dest(out), 0x98806c, v);
                        }
                        b'n' => {
                            let r = por_extenso(core::ptr::read_unaligned((ev + 9) as *const i32), -1);
                            escrever(out, r);
                        }
                        b'O' | b'o' => {
                            // as cores do outro clube
                            let lado = b(6);
                            clube_id = if lado != 0 { *(ctx as *const usize) } else { *((ctx + 4) as *const usize) };
                            let a = (lado == 0) as isize;
                            let uniforme = *((ctx as isize + a * 1573 + 0x152) as *const u8) as u32;
                            cores_do_clube((*(0xae23b4 as *const usize)).wrapping_add(clube_id.wrapping_mul(0x245)), uniforme, cor1.as_mut_ptr(), cor2.as_mut_ptr());
                            *(dest(out) as *mut u8) = 0;
                        }
                        b'Y' | b'y' => {
                            cores_padrao(&mut cor1, &mut cor2, 0xaebdec);
                            *(dest(out) as *mut u8) = 0;
                        }
                        b'R' | b'r' => {
                            if t(pos + 2) != b'f' {
                                cores_padrao(&mut cor1, &mut cor2, 0xae31a8);
                                *(dest(out) as *mut u8) = 0;
                            } else {
                                let fixo = if x == b'R' { 0xa15a14usize } else { 0xa159e0 };
                                let arbitro = core::ptr::read_unaligned((ctx + 0x40) as *const i32);
                                if arbitro <= -1 {
                                    formatar_texto(dest(out), fixo);
                                } else {
                                    let soma = (b(7) as i8 as i32)
                                        .wrapping_add(b(5) as i8 as i32)
                                        .wrapping_add(core::ptr::read_unaligned((ctx + 4) as *const i32))
                                        .wrapping_add(clube_id as i32);
                                    let resto = (soma % 5) as i8;
                                    let ficha = (*(0xae23e8 as *const usize)).wrapping_add((arbitro as usize).wrapping_mul(0x2b));
                                    let modo_nome = if idioma() == 4 && resto == 0 {
                                        1
                                    } else if resto == 0 {
                                        5
                                    } else if resto > 0 && resto <= 2 {
                                        1
                                    } else {
                                        0
                                    };
                                    match modo_nome {
                                        1 => {
                                            nome_do_arbitro(ficha, arb.as_mut_ptr(), 0xc8, 1);
                                            formatar_texto(0xb67dd8, 0xa15a20, arb.as_ptr());
                                        }
                                        5 => {
                                            nome_do_arbitro(ficha, arb.as_mut_ptr(), 0xc8, 5);
                                            formatar_texto(0xb67dd8, 0xa159ec, arb.as_ptr());
                                        }
                                        _ => {
                                            formatar_texto(0xb67dd8, fixo);
                                        }
                                    }
                                    formatar(dest(out), 0xb67dd8);
                                }
                            }
                        }
                        _ => aviso_em(0xa159b0, 0x89d),
                    }
                    if t(pos) != b'>' {
                        let mut j = pos;
                        loop {
                            if t(j) == 0 {
                                break;
                            }
                            j += 1;
                            if t(j) == b'>' {
                                break;
                            }
                        }
                        pos = j;
                    }
                    if t(pos) == 0 {
                        pos -= 1;
                    }
                    let mut n = 0usize;
                    while linha[n] != 0 {
                        n += 1;
                    }
                    out = n as i16;
                }
                pos += 1;
                if t(pos) == 0 {
                    break;
                }
            }
        }
        *(dest(out) as *mut u8) = 0;
        // larga demais: quebra ou corta numa palavra com "..."
        if largura_do_texto(fonte, linha.as_ptr()) > largura - 0x10 {
            let mut n = 0usize;
            while linha[n] != 0 {
                n += 1;
            }
            let mut si = n as i16;
            if quebrar as u8 != 0 {
                quebrar_linha(dest(si / 5) as *mut u8, 0, 1);
            } else {
                loop {
                    si -= 1;
                    *(dest(si) as *mut u8) = 0;
                    if largura_do_texto(fonte, linha.as_ptr()) <= largura - 0x10 {
                        if si > 0 {
                            loop {
                                if *(dest(si - 1) as *const u8) == b' ' {
                                    if si > 0 && *(dest(si - 1) as *const u8) == b' ' {
                                        si -= 1;
                                        *(dest(si) as *mut u8) = 0;
                                    }
                                    break;
                                }
                                si -= 1;
                                *(dest(si) as *mut u8) = 0;
                                if si <= 0 {
                                    break;
                                }
                            }
                        }
                        break;
                    }
                    if si <= 0 {
                        break;
                    }
                }
                let mut n = 0usize;
                while linha[n] != 0 {
                    n += 1;
                }
                for (i, c) in b"...\0".iter().enumerate() {
                    linha[n + i] = *c;
                }
            }
        }
        cor_de_fundo(SOM, painel, core::ptr::read_unaligned(cor2.as_ptr() as *const u32));
        fonte_do_painel(SOM, painel, fonte);
        cor_do_texto(SOM, painel, core::ptr::read_unaligned(cor1.as_ptr() as *const u32));
        texto_do_painel(SOM, painel, linha.as_ptr());
        margem(SOM, painel, 0x30);
        mostrar(SOM, painel, if *((e + 3) as *const u8) != 0 { 0x1001 } else { 1 });
    }

    // o som do evento
    *(((nar as isize) + eu() + 0x10) as *mut u8) = 0xff;
    if b(0xd) as i8 <= 0 && *((nar + 0x2db0) as *const u8) >= 0x65 {
        let som = (sons() as isize + qual() * 0x110) as usize;
        if *((som + 4) as *const u8) != 0 {
            let canal = if *((e + 6) as *const u8) == 0 { 0xb6b722usize } else { ((nar as isize) + eu() + 0x10) as usize };
            *(0xb68780 as *mut usize) = canal;
            if canal != 0 {
                *(canal as *mut u8) = 0xfe;
                let lado = match *((e + 5) as *const u8) {
                    0 => (b(6) != 0) as u32,
                    2 => (b(6) == 0) as u32,
                    _ => 2,
                };
                let p = caminho(0x9c382c, som + 4);
                tocar(SOM, *(0xb68780 as *const usize), lado, p, 0);
            }
        }
    }
    let agora = relogio();
    core::ptr::write_unaligned(((nar as isize) + eu() * 4 + 0x2d6c) as *mut u32, agora);
    let peso = *((sons() as isize + qual() * 0x110 + 2) as *const i16) as i32;
    let volume = *((nar + 0x2db0) as *const u8) as i32;
    core::ptr::write_unaligned((nar + 0x2dac) as *mut i32, (peso.wrapping_mul(volume) / 100) as i16 as i32);
    0
}

// ponytail: desenha no painel e toca som; sem comparacao propria (so roda com a tela da partida).
#[allow(clippy::too_many_arguments)]
unsafe extern "thiscall" fn comparar_narrar_no_painel(nar: usize, ev: usize, ctx: usize, comp: i32, painel: u32, largura: i32, quebrar: u32, fonte: usize, modo: u32) -> u32 {
    orig::<unsafe extern "thiscall" fn(usize, usize, usize, i32, u32, i32, u32, usize, u32) -> u32>(345)(nar, ev, ctx, comp, painel, largura, quebrar, fonte, modo)
}

// ---------- centesima quinquagesima oitava leva: o save acima de 2 GB (o contêiner, em `conteiner.rs`) ----------

use crate::conteiner::{abrir_no_conteiner, buscar_no_conteiner, posicao_no_conteiner};

// ponytail: o conteiner abre arquivos, aloca 650 KB por item e le do disco; sem comparacao propria,
// validado pela carreira (Rust x original; o banco e os historicos passam por aqui o tempo todo) e
// pelo save de enchimento acima de 2 GB.
unsafe extern "C" fn comparar_abrir_no_conteiner(caminho: usize, nome: *const u8, modo: u32, a4: u32, tipo: u32) -> usize {
    orig::<unsafe extern "C" fn(usize, *const u8, u32, u32, u32) -> usize>(346)(caminho, nome, modo, a4, tipo)
}

unsafe extern "C" fn comparar_buscar_no_conteiner(z: usize, desloc: i32, origem: u32) -> i32 {
    orig::<unsafe extern "C" fn(usize, i32, u32) -> i32>(347)(z, desloc, origem)
}

unsafe extern "C" fn comparar_posicao_no_conteiner(z: usize) -> i32 {
    orig::<unsafe extern "C" fn(usize) -> i32>(348)(z)
}

// ---------- centesima trigesima nona leva: o fechamento da partida (0x6d1cc0, 0x547790, 0x5477d0) ----------

/// { 0x547790 } (cdecl): `b` tem `a` entre os tres favoritos (+0x9b, +0x9f, +0xa3)? No fechamento,
/// a pessoa e o clube adversario.
unsafe extern "C" fn favorito_de(a: usize, b: usize) -> u32 {
    if a == 0 || b == 0 {
        return 0;
    }
    [0x9b, 0x9f, 0xa3].iter().any(|&o| *((b + o) as *const usize) == a) as u32
}

/// { 0x5477d0 } (cdecl): `b` tem `a` entre os tres rejeitados (+0xa7, +0xab, +0xaf)?
unsafe extern "C" fn rejeitado_por(a: usize, b: usize) -> u32 {
    if a == 0 || b == 0 {
        return 0;
    }
    [0xa7, 0xab, 0xaf].iter().any(|&o| *((b + o) as *const usize) == a) as u32
}

/// Liga as unidades da fita do fechamento (0x6d26b0, 0x6d3610, 0x6d3de0 e o conteudo da 0x68d0d0).
static GRAVAR_FECHAMENTO: std::sync::atomic::AtomicBool = std::sync::atomic::AtomicBool::new(false);

fn gravando_fechamento() -> bool {
    GRAVAR_FECHAMENTO.load(std::sync::atomic::Ordering::Relaxed) && gravando()
}

/// { 0x6d1cc0 } (cdecl, match_eng.cpp, chamada pelo passo do motor 0x6b98c0) com as chamadas que
/// mexem fora do motor injetadas (0x6d26b0 a ficha de cada jogador, 0x6d3610 e 0x6d3de0 as
/// reputacoes, 0x68d0d0 a copia de um evento na lista [0xb67dc8]): o fechamento da partida. Com a
/// lista de eventos do dia (+0x478e) e a partida (+0x4792, +0x40 ligado), percorre os eventos (0x68d1b0):
/// 0x82 vai para a lista; 0x1e (proposta?) pelo placar (+0x43/+0x44, empate pela forca +0x80 dos
/// clubes x 1,2/0,8) e pelo tecnico do outro lado (+0xd3, 0x544410 sorteado contra 20 ou 5, +0x14 > 5)
/// marca o evento (+0xe 1, +0xf o tecnico) ou o compara com a forca do clube do evento (+0x80 com dois
/// sorteios de 1000, ou acima de 7000; no outro lado, 1 em 4) e o marca (+0xe 0, +0xf -1); os outros,
/// do jogador da partida: no 6 pelas marcas +0x24/+0x23, nos demais com +0x1b < 7 por sorteio(+0x17).
/// Depois, por lado, cada jogador em campo (reservas so se entraram, +0x1f) com ficha e contrato:
/// 0x6d26b0 com a nota +0x1b; com a lista: fora das selecoes e dos amistosos, sem ser o tecnico, quem
/// saiu (+0x20) sem ser substituido de volta (+0x22) e com contrato (+0x3d) e reputacao (+0xb >
/// 4250) pode pedir para sair (evento 0xa, 0x4000000) por sorteios de +0x1a2, +0x5d, folego (+0x4d) e
/// +0x57/+0x5b; a insatisfacao (-+0x31, +10 contra o rival +0xb3/+0xb7/+0xbb ou rejeitado pelo
/// adversario 0x5477d0, -10 favorito dele 0x547790, +10/-20 pelas preferencias 0x547d30/0x547d60) contra
/// sorteio((+0x5a x +0x5b x +0x5d + 20) x 100) gera o evento 0xb. A media das notas pelos minutos
/// jogados (90 no motor rapido; +0x21/+0x20/minuto, menos a entrada +0x1f) -0,25 em casa (+0x18) ou
/// +0,25 fora vai para 0x6d3610 e, fora das selecoes, 0x6d3de0. Sem minutos, a media fica a do lado
/// anterior (no 1o lado era lixo de pilha: 0 no original determinizado, como os 4 bytes finais do
/// evento montado na pilha).
unsafe fn fechamento_com(m: usize, chamar: &mut dyn FnMut(usize, usize, [u32; 5]) -> u32) {
    let proximo: unsafe extern "thiscall" fn(usize) -> usize = core::mem::transmute(0x68d1b0usize);
    let conhecer: unsafe extern "C" fn(usize, u32) -> i8 = core::mem::transmute(0x544410usize);
    let selecao: unsafe extern "C" fn(usize) -> u32 = core::mem::transmute(0x53b900usize);
    let contrato: unsafe extern "thiscall" fn(usize, usize, usize) -> usize = core::mem::transmute(0x4cf5f0usize);
    let amistoso: unsafe extern "thiscall" fn(usize, usize) -> u32 = core::mem::transmute(0x5c6710usize);
    let favorito: unsafe extern "C" fn(usize, usize) -> u32 = core::mem::transmute(0x547790usize);
    let rejeitado: unsafe extern "C" fn(usize, usize) -> u32 = core::mem::transmute(0x5477d0usize);
    let nao_gosta: unsafe extern "C" fn(usize, usize) -> u32 = core::mem::transmute(0x547d30usize);
    let gosta: unsafe extern "C" fn(usize, usize) -> u32 = core::mem::transmute(0x547d60usize);
    let d = |p: usize, o: usize| *((p + o) as *const usize);
    let w = |p: usize, o: usize| *((p + o) as *const i16);
    let lista_global = || *(0xb67dc8 as *const usize);
    // poe uma copia do bloco (0x19 bytes) na lista de eventos (o conteudo e conferido na fita)
    let mut evento = |chamar: &mut dyn FnMut(usize, usize, [u32; 5]) -> u32, p: usize| {
        pedir_vetores(&[(p, 0x19)], &[]);
        chamar(0x68d0d0, lista_global(), [0, 0x19, 0, 0, 0]);
    };
    let partida = || d(m, 0x4792);
    let pessoa_de = |id: i32| (*(0xae23bc as *const usize)).wrapping_add(id as usize * 0x6e);
    let lista = d(m, 0x478e);
    if lista != 0 && lista_global() != 0 && partida() != 0 && byte(partida(), 0x40) != 0 {
        *((lista + 0xa) as *mut u32) = core::ptr::read_unaligned((lista + 2) as *const u32);
        let mut i: i8 = 0;
        while (i as i16) < *(lista as *const i16) {
            let e = proximo(lista);
            if e == 0 {
                break;
            }
            let tipo = w(e, 0x13);
            crate::comparacao::ramo("fechamento evento do dia");
            let marcar = |valor: u8, quem: u32| {
                *((e + 0xe) as *mut u8) = valor;
                core::ptr::write_unaligned((e + 0xf) as *mut u32, quem);
            };
            let pt = partida();
            let clube_ev = || (*(0xae23b4 as *const usize)).wrapping_add(d(e, 4) * 0x245);
            let reputacao = || w(d(pessoa_de(*(e as *const i32)), 0x61), 0xb);
            if tipo == 0x82 {
                evento(chamar, e);
            } else if tipo == 0x1e {
                let (c1c, c20) = (d(pt, 0x1c), d(pt, 0x20));
                if byte(e, 0xd) != 0 {
                    let (a, b) = (byte(pt, 0x43), byte(pt, 0x44));
                    let ok = b < a || (b == a && (w(c1c, 0x80) as f64) < w(c20, 0x80) as f64 * f64_em(0x968e40));
                    let t = d(c20, 0xd3);
                    if ok && t != 0 && d(t, 0x69) != 0 {
                        let x = d(t, 0x69);
                        let r1 = sortear(conhecer(x, byte(x, 0x17) as u8 as u32) as i32);
                        if r1 > sortear(0x14) && byte(x, 0x14) > 5 {
                            crate::comparacao::ramo("fechamento proposta aceita");
                            marcar(1, *(t as *const u32));
                            evento(chamar, e);
                        } else {
                            let rep = reputacao();
                            let r = sortear(1000);
                            let forca = w(clube_ev(), 0x80) as i32 - r + sortear(1000);
                            if rep as i32 > forca || rep > 7000 {
                                marcar(0, u32::MAX);
                                evento(chamar, e);
                            }
                        }
                    }
                } else {
                    let (a, b) = (byte(pt, 0x43), byte(pt, 0x44));
                    let ok = b > a || (b == a && (w(c20, 0x80) as f64) < w(c1c, 0x80) as f64 * f64_em(0x968e48));
                    let t = d(c1c, 0xd3);
                    if ok && t != 0 && d(t, 0x69) != 0 {
                        let x = d(t, 0x69);
                        if sortear(conhecer(x, byte(x, 0x17) as u8 as u32) as i32) > 5 && byte(x, 0x14) > 5 {
                            crate::comparacao::ramo("fechamento proposta aceita");
                            marcar(1, *(t as *const u32));
                            evento(chamar, e);
                        } else {
                            if reputacao() > w(clube_ev(), 0x80) && sortear(4) == 0 {
                                marcar(0, u32::MAX);
                            }
                            evento(chamar, e);
                        }
                    }
                }
            } else {
                let pessoa = pessoa_de(*(e as *const i32));
                if pessoa != 0 {
                    // o jogador do evento num dos dois lados
                    let achar = |lado: usize| (0..20usize).find(|&k| {
                        let p = m + 0x4796 + (k + lado * 20) * 0x1be;
                        d(p, 0x69) == pessoa && byte(p, 0x19) >= 0
                    });
                    let achado = achar(0).map(|k| (k, 0)).or_else(|| achar(1).map(|k| (k, 1)));
                    if let Some((k, lado)) = achado {
                        let p = m + 0x4796 + (k + lado * 20) * 0x1be;
                        let vale = if tipo == 6 {
                            crate::comparacao::ramo("fechamento evento tipo 6");
                            byte(p, 0x24) == 2 || byte(p, 0x23) != 0
                        } else {
                            byte(p, 0x1b) < 7 && sortear(byte(p, 0x17) as i32) == 0
                        };
                        if vale {
                            crate::comparacao::ramo("fechamento evento do jogador");
                            marcar(0, u32::MAX);
                            evento(chamar, e);
                        }
                    }
                }
            }
            i = i.wrapping_add(1);
        }
    }
    let mut media = 0f64;
    for lado in 0..2usize {
        let (mut soma, mut somap) = (0i32, 0i32);
        let pt = partida();
        let (meu, outro) = if lado == 0 { (d(pt, 0x1c), d(pt, 0x20)) } else { (d(pt, 0x20), d(pt, 0x1c)) };
        for k in 0..20usize {
            let p = m + 0x4796 + (k + lado * 20) * 0x1be;
            if k > 10 && byte(p, 0x1f) == -1 {
                continue;
            }
            let pessoa = d(p, 0x69);
            if pessoa != 0 && d(p, 0x6d) != 0 && *(pessoa as *const i32) < *(0xae2364 as *const i32) {
                chamar(0x6d26b0, p, [pessoa as u32, meu as u32, outro as u32, (byte(p, 0x1b) as f32).to_bits(), *(m as *const u8) as u32 | 1 << 8]);
                if lista_global() != 0 && selecao(meu) == 0 && byte(pt, 0x40) != 0 {
                    let ct = contrato(*(0xae1050 as *const usize), pessoa, meu);
                    if ct != 0
                        && meu != 0
                        && pessoa != d(meu, 0xcf)
                        && d(pt, 0x14) != 0
                        && amistoso(*(0xae2c74 as *const usize), d(pt, 0x14)) == 0
                        && byte(p, 0x20) != -1
                        && byte(p, 0x22) == -1
                        && byte(ct, 0x3d) > 0
                        && w(d(p, 0x6d), 0xb) > 0x109a
                        && partida() != 0
                        && byte(partida(), 0x40) != 0
                    {
                        let r1 = sortear(ftol(f32_em(p + 0x1a2) as f64));
                        if r1 > sortear(100) {
                            let r3 = sortear(byte(pessoa, 0x5d) as i32);
                            if r3 < sortear(10) {
                                let f = f32_em(p + 0x4d);
                                if ((sortear(0x5dc) + 0x1d4c) as f64) < f as f64 {
                                    let b5b = byte(pessoa, 0x5b);
                                    if b5b < 6 && byte(pessoa, 0x57) > 10 {
                                        let r6 = sortear(byte(pessoa, 0x57) as i32);
                                        if sortear(b5b as i32) < r6 {
                                            crate::comparacao::ramo("fechamento pede para sair");
                                            let mut ev = [0u8; 0x19];
                                            ev[..4].copy_from_slice(&(*(pessoa as *const u32)).to_le_bytes());
                                            ev[4..8].copy_from_slice(&(*(meu as *const u32)).to_le_bytes());
                                            ev[8..12].copy_from_slice(&0x4000000u32.to_le_bytes());
                                            ev[0xd] = lado as u8;
                                            ev[0xf..0x13].copy_from_slice(&u32::MAX.to_le_bytes());
                                            ev[0x13..0x15].copy_from_slice(&10u16.to_le_bytes());
                                            evento(chamar, ev.as_ptr() as usize);
                                        }
                                    }
                                }
                            }
                        }
                    }
                    // a insatisfacao
                    let mut x = -(w(p, 0x31) as i32);
                    if [0xb3, 0xb7, 0xbb].iter().any(|&o| d(meu, o) == outro) {
                        x += 10;
                    }
                    if rejeitado(pessoa, outro) != 0 {
                        x += 10;
                    } else if favorito(pessoa, outro) != 0 {
                        x -= 10;
                    }
                    if nao_gosta(pessoa, outro) != 0 {
                        x += 10;
                    } else if gosta(pessoa, outro) != 0 {
                        x -= 20;
                    }
                    let (a, b, c) = (byte(pessoa, 0x5a) as i32, byte(pessoa, 0x5b), byte(pessoa, 0x5d));
                    if b < 6 && c < 10 {
                        let r1 = sortear((a * b as i32 * c as i32 + 0x14) * 100);
                        if r1 < sortear(x + 0x32) {
                            crate::comparacao::ramo("fechamento insatisfeito");
                            let mut ev = [0u8; 0x19];
                            ev[..4].copy_from_slice(&(*(pessoa as *const u32)).to_le_bytes());
                            ev[4..8].copy_from_slice(&(*(meu as *const u32)).to_le_bytes());
                            ev[0xd] = lado as u8;
                            ev[0xf..0x13].copy_from_slice(&u32::MAX.to_le_bytes());
                            ev[0x13..0x15].copy_from_slice(&11u16.to_le_bytes());
                            evento(chamar, ev.as_ptr() as usize);
                        }
                    }
                }
            }
            // os minutos jogados
            let minuto = (w(m, 0x8ed0) as i32 / 11) as i8;
            let v: i8 = if k >= 11 {
                let c = byte(p, 0x1f);
                if c == -1 {
                    continue;
                }
                let fim = if byte(p, 0x21) > -1 { byte(p, 0x21) } else if byte(p, 0x20) > -1 { byte(p, 0x20) } else { minuto };
                fim.wrapping_sub(c)
            } else if *(m as *const u8) != 0 {
                0x5a
            } else if byte(p, 0x21) > -1 {
                byte(p, 0x21)
            } else if byte(p, 0x20) > -1 {
                byte(p, 0x20)
            } else {
                minuto
            };
            if v == 0 {
                continue;
            }
            soma += v as i32;
            somap += byte(p, 0x1b) as i32 * v as i32;
        }
        if soma != 0 {
            let q = somap as f64 / soma as f64;
            media = if d(pt, 0x18) == d(meu, 0x69) { q - f64_em(0x967880) } else { q + f64_em(0x968918) };
        }
        crate::comparacao::ramo(if soma != 0 { "fechamento media do lado" } else { "fechamento lado sem minutos" });
        let valor = (media as f32).to_bits();
        let alt = *(m as *const u8) as u32;
        chamar(0x6d3610, m + 0x9032 + lado * 0xd0, [meu as u32, outro as u32, pt as u32, valor, alt | 1 << 8]);
        if selecao(meu) == 0 {
            chamar(0x6d3de0, m, [lado as u32, valor, alt | 1 << 8, 0, 0]);
        }
    }
}

/// Despacho real das chamadas injetadas do fechamento.
unsafe fn despachar_fechamento(rotina: usize, this: usize, a: [u32; 5]) -> u32 {
    let m = |p: usize| *((p + 0x19e) as *const usize);
    match rotina {
        0x6d26b0 => {
            let f: unsafe extern "C" fn(usize, usize, usize, usize, usize, f32, u32, u32) = core::mem::transmute(0x6d26b0usize);
            f(this, a[0] as usize, a[1] as usize, a[2] as usize, *((m(this) + 0x4792) as *const usize), f32::from_bits(a[3]), a[4] & 0xff, (a[4] >> 8) & 0xff);
        }
        0x6d3610 => {
            let f: unsafe extern "C" fn(usize, usize, usize, usize, f32, u8, u8) = core::mem::transmute(0x6d3610usize);
            f(this, a[0] as usize, a[1] as usize, a[2] as usize, f32::from_bits(a[3]), a[4] as u8, (a[4] >> 8) as u8);
        }
        0x6d3de0 => {
            let f: unsafe extern "C" fn(usize, i8, f32, u8, u8) = core::mem::transmute(0x6d3de0usize);
            f(this, a[0] as u8 as i8, f32::from_bits(a[1]), a[2] as u8, (a[2] >> 8) as u8);
        }
        _ => {
            // 0x68d0d0: o bloco pedido por ultimo (pedir_vetores) e o que vai para a lista
            let p = VETORES_PEDIDOS.lock().unwrap_or_else(|e| e.into_inner()).take().map_or(0, |v| v.0[0].0);
            let f: unsafe extern "thiscall" fn(usize, usize, u32) = core::mem::transmute(0x68d0d0usize);
            f(this, p, a[1]);
        }
    }
    0
}

/// Zera 8 KB da pilha logo abaixo (a rotina original chamada em seguida ocupa essa area): na
/// comparacao, a original determinizada roda com as variaveis sem valor em zero, como no desvio.
#[inline(never)]
fn zerar_pilha() {
    let mut a = [0u8; 0x2000];
    std::hint::black_box(&mut a);
}

unsafe extern "C" fn comparar_favorito_de(a: usize, b: usize) -> u32 {
    let r = orig::<unsafe extern "C" fn(usize, usize) -> u32>(307)(a, b);
    let n = favorito_de(a, b);
    PLACAR.registrar(r == n, || format!("favorito_de original={} rust={}", r, n));
    r
}

unsafe extern "C" fn comparar_rejeitado_por(a: usize, b: usize) -> u32 {
    let r = orig::<unsafe extern "C" fn(usize, usize) -> u32>(308)(a, b);
    let n = rejeitado_por(a, b);
    PLACAR.registrar(r == n, || format!("rejeitado_por original={} rust={}", r, n));
    r
}

/// As regioes do fechamento: o sorteio, o motor, a lista de eventos do dia (cabecalho e cursor) e os
/// eventos dela (+0xe e +0xf mudam).
unsafe fn regioes_do_fechamento(m: usize) -> Vec<(usize, usize)> {
    let mut reg = crate::aleatorio::REGIOES_DO_ESTADO.to_vec();
    reg.extend([(m, MOTOR), (0xb67a34, 4)]);
    let lista = *((m + 0x478e) as *const usize);
    if lista != 0 {
        reg.push((lista, 0xe));
        let mut no = core::ptr::read_unaligned((lista + 2) as *const usize);
        for _ in 0..(*(lista as *const i16)).max(0) {
            if no == 0 {
                break;
            }
            let e = *(no as *const usize);
            if e != 0 {
                reg.push((e, 0x19));
            }
            no = core::ptr::read_unaligned((no + 6) as *const usize);
        }
    }
    reg
}

unsafe extern "C" fn comparar_fechamento(m: usize) {
    use std::sync::atomic::Ordering::Relaxed;
    let o = orig::<unsafe extern "C" fn(usize)>(309);
    if gravando_no_topo() {
        return o(m);
    }
    let reg = regioes_do_fechamento(m);
    let gravar = GRAVAR_FECHAMENTO.swap(true, Relaxed);
    let (_, _, igual, sequencia, k) = comparar_com_fita(reg, || {
        zerar_pilha();
        o(m)
    }, |chamar| {
        fechamento_com(m, &mut |rotina, this, args| {
            let mascara = match rotina {
                0x68d0d0 => [0, u32::MAX, 0, 0, 0],
                _ => [u32::MAX; 5],
            };
            chamar(rotina, this, args, mascara)
        })
    });
    GRAVAR_FECHAMENTO.store(gravar, Relaxed);
    PLACAR.registrar(igual && sequencia, || format!("fechamento {} chamadas: {}", k, detalhe_fita()));
}

/// { 0x6d1cc0 } (cdecl, match_eng.cpp): ver `fechamento_com`.
unsafe extern "C" fn fechamento(m: usize) {
    fechamento_com(m, &mut |r, t, a| despachar_fechamento(r, t, a))
}

// ---------- centesima trigesima quarta leva: o interesse do humano no dia de jogos (0x6b5040) ----------

/// As regioes que a 0x6b5040 marca no dia `d`: +0x29 a +0x2e do dia, +0x14 de cada grupo, +0xc a
/// +0x13 de cada competicao e +0x53 de cada partida.
unsafe fn marcas_do_dia(d: usize) -> Vec<(usize, usize)> {
    let ler = |a: usize| core::ptr::read_unaligned(a as *const i32);
    let mut v = vec![(d + 0x29, 6)];
    for gi in 0..ler(d + 9).max(0) as usize {
        let grp = (ler(d + 1) as usize).wrapping_add(gi * 0x18);
        v.push((grp + 0x14, 4));
        for ci in ler(grp + 4)..=ler(grp + 8) {
            let comp = (ler(d + 0xd) as isize + ci as isize * 0x54) as usize;
            v.push((comp + 0xc, 8));
            for mi in ler(comp + 4)..=ler(comp + 8) {
                v.push(((ler(d + 0x19) as isize + mi as isize * 0x69) as usize + 0x53, 4));
            }
        }
    }
    v
}

/// { 0x6b5040 } (thiscall, match_day.cpp): marca no dia de jogos `d` o que interessa ao humano.
/// Primeiro a lista dos humanos (0x5fe8d0 em [0xb63c98]); zera +0x29, +0x2a e +0x2b. Para cada grupo
/// (+1, de 0x18 em 0x18, quantos em +9) e cada competicao dele (+4 a +8; em +0xd, de 0x54 em 0x54):
/// a competicao interessa (+0xc) se um dos 16 humanos no fim da tabela de pessoas tem o clube (+0x39)
/// ou o outro vinculo (+0x24) nela (0x48db80 da competicao em [[0xadadfc] + id x 4]). Cada partida
/// dela (+4 a +8; em +0x19, de 0x69 em 0x69): com clube humano (0x600a50 com +0x20/+0x44 ou
/// +0x24/+0x45) ou pela 0x5fe420 a partida e marcada (+0x53) e conta o grupo (+0x29) e a competicao
/// (+0x2a) na primeira vez (+0x14 do grupo, +0x10 da competicao); senao, pela 0x6b61e0, so a
/// competicao interessa. Qualquer marca liga +0x2b do dia. Devolve 1.
unsafe extern "thiscall" fn interesse_do_dia(d: usize) -> u32 {
    let lista: unsafe extern "thiscall" fn(usize) = core::mem::transmute(0x5fe8d0usize);
    let na_competicao: unsafe extern "thiscall" fn(usize, usize) -> u8 = core::mem::transmute(0x48db80usize);
    let humano: unsafe extern "C" fn(usize, u32, u32, u32, u32) -> i32 = core::mem::transmute(0x600a50usize);
    let f5fe420: unsafe extern "thiscall" fn(usize, usize) -> i32 = core::mem::transmute(0x5fe420usize);
    let f6b61e0: unsafe extern "C" fn(usize) -> i32 = core::mem::transmute(0x6b61e0usize);
    let g = |a: usize| *(a as *const usize);
    let ler = |a: usize| core::ptr::read_unaligned(a as *const i32);
    let pr = |a: usize, v: i32| core::ptr::write_unaligned(a as *mut i32, v);
    lista(g(0xb63c98));
    *((d + 0x29) as *mut u8) = 0;
    *((d + 0x2a) as *mut u8) = 0;
    pr(d + 0x2b, 0);
    let mut gi = 0i32;
    while gi < ler(d + 9) {
        let grp = (ler(d + 1) as usize).wrapping_add(gi as usize * 0x18);
        pr(grp + 0x14, 0);
        let mut ci = ler(grp + 4);
        while ci <= ler(grp + 8) {
            let comp = (ler(d + 0xd) as isize + ci as isize * 0x54) as usize;
            pr(comp + 0xc, 0);
            pr(comp + 0x10, 0);
            if ler(comp) > -1 {
                let objeto = g(g(0xadadfc) + ler(comp) as usize * 4);
                if (0..16).filter(|k| g((g(0xae23bc) as isize + (ler(0xae2364) + k - 16) as isize * 0x6e) as usize + 0x39) != 0).count() >= 2 {
                    crate::comparacao::ramo("interesse dois humanos com clube");
                }
                for k in 0..16 {
                    let pe = (g(0xae23bc) as isize + (ler(0xae2364) + k - 16) as isize * 0x6e) as usize;
                    let clube = g(pe + 0x39);
                    let outro = g(pe + 0x24);
                    if (clube != 0 && na_competicao(objeto, clube) != 0) || (outro != 0 && na_competicao(objeto, outro) != 0) {
                        crate::comparacao::ramo("interesse humano na competicao");
                        pr(comp + 0xc, 1);
                        pr(d + 0x2b, 1);
                    }
                }
            }
            let mut mi = ler(comp + 4);
            while mi <= ler(comp + 8) {
                let m = (ler(d + 0x19) as isize + mi as isize * 0x69) as usize;
                pr(m + 0x53, 0);
                let marcada = humano(g(m + 0x20), 0, *((m + 0x44) as *const u8) as u32, 0, 0) != 0
                    || humano(g(m + 0x24), 0, *((m + 0x45) as *const u8) as u32, 0, 0) != 0
                    || f5fe420(g(0xb63c98), m + 4) != 0;
                if marcada {
                    crate::comparacao::ramo("interesse partida marcada");
                    pr(m + 0x53, 1);
                    if ler(grp + 0x14) == 0 {
                        *((d + 0x29) as *mut u8) = (*((d + 0x29) as *const u8)).wrapping_add(1);
                    }
                    if ler(comp + 0x10) == 0 {
                        *((d + 0x2a) as *mut u8) = (*((d + 0x2a) as *const u8)).wrapping_add(1);
                    }
                    pr(grp + 0x14, 1);
                    pr(comp + 0x10, 1);
                    pr(comp + 0xc, 1);
                    pr(d + 0x2b, 1);
                } else if f6b61e0(m + 4) != 0 {
                    crate::comparacao::ramo("interesse pela 6b61e0");
                    pr(comp + 0xc, 1);
                    pr(d + 0x2b, 1);
                }
                mi += 1;
            }
            ci += 1;
        }
        gi += 1;
    }
    1
}

unsafe extern "thiscall" fn comparar_interesse_do_dia(d: usize) -> u32 {
    let o = orig::<unsafe extern "thiscall" fn(usize) -> u32>(299);
    if gravando_no_topo() {
        return o(d);
    }
    // ponytail: a 0x5fe8d0 (lista dos humanos) roda nas duas; ela refaz a lista do zero
    let reg = marcas_do_dia(d);
    let (r, n, igual, mo, mr) = crate::comparacao::lado_a_lado(&reg, || o(d), || interesse_do_dia(d));
    PLACAR.registrar(igual && r == n, || format!("interesse_do_dia original={} rust={} {:x?} x {:x?}", r, n, mo, mr));
    r
}

// ---------- centesima trigesima terceira leva: a partida sem o humano (0x6b66a0) ----------

/// As marcas das selecoes dos tecnicos humanos (0xb67a58 + id), que a 0x6b66a0 poe uma vez
/// (com [0xa15704] ligado): para cada vaga de humano em 0xb63d60 (de 0x48 em 0x48 ate 0xb64738) com
/// +0x11c bit 2 e selecao (+0x71).
unsafe fn marcas_das_selecoes() -> Vec<usize> {
    let mut v = Vec::new();
    for e in (0xb63d60usize..0xb64738).step_by(0x48) {
        let p = *(e as *const usize);
        if p != 0 && *((p + 0x11c) as *const u8) & 2 != 0 {
            let q = *((p + 0x71) as *const usize);
            if q != 0 {
                v.push(0xb67a58 + *(q as *const usize));
            }
        }
    }
    v
}

/// { 0x6b66a0 } (cdecl, match_day.cpp): 1 se a `partida` nao envolve o humano, pela 0x7f9720. Antes,
/// uma vez ([0xa15704]), marca as selecoes dos humanos em 0xb67a58. Sem [0xdd7118]: 1. Devolve 0 se:
/// algum dos clubes (+0x1c, +0x20) e de humano (0x600a50), ou o clube ligado a ele (0x540a50); a
/// competicao (+0) e uma de duas fixas ([0x9cf7bc], [0x9cf6e4]); e a de [0x9cf958] com um dos dois
/// clubes fixos ([0x9cf2e4], [0x9cf510], linhas de 0x122 em [0xae23a8]) humano (+0x11c bit 2); um dos
/// 16 humanos no fim da tabela de pessoas (+0x5f = 1) treina clube da mesma nacao (+0x57) de um dos
/// dois. Na competicao [0x9cf684] sem clube humano, direto a 0x7f9720. Fora de selecao (0x53b900) com
/// 0x5c2990, ou na competicao [0x9cf6f8]: 0 se o +0x80 dos dois somar mais de 12000. Senao a vaga da
/// 0x48dd70 (pela tabela em 0xb63d74): 0 ou 1 da 0; nas 3 a 7 com a selecao da competicao marcada, 0;
/// vaga de humano com +0x11c bit 2, 0. No fim: 1 se a 0x7f9720 der 0.
unsafe extern "C" fn partida_sem_humano(partida: usize) -> u32 {
    let humano: unsafe extern "C" fn(usize, u32, u32, u32, u32) -> i32 = core::mem::transmute(0x600a50usize);
    let ligado: unsafe extern "C" fn(usize, u32, u32) -> usize = core::mem::transmute(0x540a50usize);
    let selecao: unsafe extern "C" fn(usize) -> i32 = core::mem::transmute(0x53b900usize);
    let f5c2990: unsafe extern "thiscall" fn(usize, u32) -> i32 = core::mem::transmute(0x5c2990usize);
    let vaga_de: unsafe extern "C" fn(u32, usize) -> u32 = core::mem::transmute(0x48dd70usize);
    let f7f9720: unsafe extern "thiscall" fn(usize, usize) -> i32 = core::mem::transmute(0x7f9720usize);
    let g = |a: usize| *(a as *const usize);
    let ler = |a: usize| core::ptr::read_unaligned(a as *const i32);
    let w = |a: usize| core::ptr::read_unaligned(a as *const i16) as i32;
    if g(0xa15704) != 0 {
        for e in marcas_das_selecoes() {
            crate::comparacao::ramo("sem humano selecao de humano");
            *(e as *mut u8) = 1;
        }
        *(0xa15704 as *mut u32) = 0;
    }
    if g(0xdd7118) == 0 {
        return 1;
    }
    let (c1, c2) = (g(partida + 0x1c), g(partida + 0x20));
    if humano(c1, 1, 1, 0, 0) != 0 || humano(c2, 1, 1, 0, 0) != 0 {
        crate::comparacao::ramo("sem humano clube humano em campo");
        return 0;
    }
    for c in [c1, c2] {
        if ligado(c, 0, 1) != 0 && humano(ligado(c, 0, 1), 1, 1, 0, 0) != 0 {
            crate::comparacao::ramo("sem humano clube ligado");
            return 0;
        }
    }
    let final_ = || (f7f9720(g(0xb74448), partida) == 0) as u32;
    let comp = ler(partida);
    if comp == ler(0x9cf7bc) || comp == ler(0x9cf6e4) {
        return 0;
    }
    if comp == ler(0x9cf958) {
        let base = g(0xae23a8);
        for k in [ler(0x9cf2e4), ler(0x9cf510)] {
            if *((base as isize + k as isize * 0x122 + 0x11c) as *const u8) & 2 != 0 {
                return 0;
            }
        }
    }
    if comp == ler(0x9cf684) && humano(c1, 1, 1, 0, 0) == 0 && humano(c2, 1, 1, 0, 0) == 0 {
        crate::comparacao::ramo("sem humano competicao direta");
        return final_();
    }
    // os 16 humanos no fim da tabela de pessoas
    let base = g(0xae23bc);
    for k in 0..16isize {
        let pe = (base as isize + (ler(0xae2364) as isize - 1 - k) * 0x6e) as usize;
        if pe != 0 && *((pe + 0x5f) as *const u8) == 1 && g(pe + 0x39) != 0 {
            let nacao = ler(g(pe + 0x39) + 0x57);
            if nacao == ler(c1 + 0x57) || nacao == ler(c2 + 0x57) {
                crate::comparacao::ramo("sem humano tecnico da nacao");
                return 0;
            }
        }
    }
    if (selecao(c2) == 0 && f5c2990(g(0xae2c74), ler(partida + 0x14) as u32) != 0) || comp == ler(0x9cf6f8) {
        crate::comparacao::ramo("sem humano pela reputacao");
        return if w(c2 + 0x80) + w(c1 + 0x80) > 0x2ee0 { 0 } else { final_() };
    }
    let mut x = vaga_de(ler(partida + 0x14) as u32, partida) as u8;
    if let Some(k) = (0xb63d74usize..0xb6474c).step_by(0x48).position(|e| *(e as *const u8) == x) {
        x = k as u8;
    }
    if x == 0 || x == 1 {
        return 0;
    }
    if matches!(x, 3..=7) {
        let q = g(g(partida + 0x14) + 0x59);
        if q != 0 && *((0xb67a58 + g(q)) as *const u8) != 0 {
            crate::comparacao::ramo("sem humano selecao marcada");
            return 0;
        }
    }
    if (x as i8) > -1 {
        let e = g(0xb63d60 + x as usize * 0x48);
        if e != 0 && *((e + 0x11c) as *const u8) & 2 != 0 {
            return 0;
        }
    }
    crate::comparacao::ramo("sem humano 7f9720");
    final_()
}

unsafe extern "C" fn comparar_partida_sem_humano(partida: usize) -> u32 {
    let o = orig::<unsafe extern "C" fn(usize) -> u32>(298);
    if gravando_no_topo() {
        return o(partida);
    }
    let mut reg = vec![(0xa15704usize, 4usize)];
    if *(0xa15704 as *const usize) != 0 {
        reg.extend(marcas_das_selecoes().into_iter().map(|e| (e, 1)));
    }
    let (r, n, igual, mo, mr) = crate::comparacao::lado_a_lado(&reg, || o(partida), || partida_sem_humano(partida));
    PLACAR.registrar(igual && r == n, || format!("partida_sem_humano original={} rust={} {:x?} x {:x?}", r, n, mo, mr));
    r
}

// ---------- centesima trigesima segunda leva: o clube no pos-jogo (0x6b79a0) ----------

/// { 0x6b79a0 } (cdecl, match_day.cpp; chamada duas vezes em 0x6b61a9/0x6b61bd, uma por clube): o
/// `clube` depois da partida contra `outro`. Sem clube, outro ou partida: caixa de erro. Sem tecnico
/// (+0xcf) nada; sem 0x600a50, com +0x80 abaixo de 4750 e sorteio(100) != 0, nada. Com 0x6b7cf0,
/// partida +0x40 e +0x41 e o clube nao fora (0x53b900): entre os 50 de +0xd7, com contrato (0x4cf5a0)
/// sem +0x45, +0xb da ficha acima de 4250, +0x59 acima de 5, +0x57 acima de 15, +0x58 acima de 10,
/// `n` acima de 2 e sorteio(n) != 0: 0x5896d0(pessoa, clube, outro, n) e fim. Depois, os 20 da
/// linha do clube no registro `t` (lado pelo clube em t+0; linhas de 0x49 a partir de +0x1ce, pessoa
/// em -0x3e, so os com +0 na linha): ficha, da base, idade (+0x18) ate 20, contrato sem +0x45, a
/// partida da competicao do clube (+0x14 = +0x57, com +0x40/+0x41), o clube nao fora, +0x59 acima
/// de 15, +0x57 acima de sorteio(5) + 10, +0xb da ficha abaixo de 4250 e 0x7c3a40 zero: 0x589bc0 e,
/// sem 0x547d60, 0x547d90(pessoa, clube, 1), e fim.
unsafe fn clube_do_pos_jogo_com(clube: usize, outro: usize, partida: usize, n: u32, t: usize, chamar: &mut dyn FnMut(usize, usize, [u32; 5]) -> u32) {
    let contrato: unsafe extern "thiscall" fn(usize, usize) -> usize = core::mem::transmute(0x4cf5a0usize);
    let teste_547d60: unsafe extern "C" fn(usize, usize) -> i32 = core::mem::transmute(0x547d60usize);
    let ch = core::cell::RefCell::new(chamar);
    let saida = |s: usize, c: usize, o: usize, n: i32| (ch.borrow_mut())(0x5896d0, 0, [s as u32, c as u32, o as u32, n as u32, 0]);
    let f589bc0 = |p: usize, c: usize| (ch.borrow_mut())(0x589bc0, 0, [p as u32, c as u32, 0, 0, 0]);
    let f547d90 = |p: usize, c: usize, um: u32| (ch.borrow_mut())(0x547d90, 0, [p as u32, c as u32, um, 0, 0]);
    let teste_600a50 = |c: usize, a: u32, b: u32, d: u32, e: u32| (ch.borrow_mut())(0x600a50, 0, [c as u32, a, b, d, e]) as i32;
    let teste_6b7cf0 = |pa: usize, c: usize| (ch.borrow_mut())(0x6b7cf0, 0, [pa as u32, c as u32, 0, 0, 0]) as u8;
    let fora = |c: usize| (ch.borrow_mut())(0x53b900, 0, [c as u32, 0, 0, 0, 0]) as i32;
    let teste_7c3a40 = |n: usize, p: usize, c: usize| (ch.borrow_mut())(0x7c3a40, n, [p as u32, c as u32, 0, 0, 0]) as u16;
    let g = |a: usize| *(a as *const usize);
    let ler = |a: usize| core::ptr::read_unaligned(a as *const i32);
    let w = |a: usize| core::ptr::read_unaligned(a as *const i16);
    let ub = |a: usize| *(a as *const u8);
    if clube == 0 || partida == 0 || outro == 0 {
        // ponytail: a original mostra a caixa "Error" (match_day.cpp, linhas 0xc45/0xc4a/0xc4f); nao
        // acontece no jogo
        *(0xb67a34 as *mut u32) = 0;
        return;
    }
    if g(clube + 0xcf) == 0 {
        return;
    }
    if teste_600a50(clube, 0, 1, 0, 0) == 0 && w(clube + 0x80) < 0x128e && sortear(100) != 0 {
        return;
    }
    crate::comparacao::ramo("clube segue");
    let n = n as u8 as i8;
    if teste_6b7cf0(partida, clube) != 0 && ub(partida + 0x40) != 0 && ub(partida + 0x41) != 0 && fora(clube) == 0 {
        for k in 0..50 {
            let s = g(clube + 0xd7 + 4 * k);
            if s == 0 {
                continue;
            }
            let c = contrato(g(0xae1050), s);
            let livre = c != 0 && ler(c + 0x45) == 0;
            if livre {
                crate::comparacao::ramo("clube elenco");
            }
            if livre
                && g(s + 0x61) != 0
                && w(g(s + 0x61) + 0xb) > 0x109a
                && byte(s, 0x59) > 5
                && byte(s, 0x57) > 0xf
                && byte(s, 0x58) > 0xa
                && n > 2
                && sortear(n as i32) != 0
            {
                crate::comparacao::ramo("clube 5896d0");
                saida(s, clube, outro, n as i32);
                return;
            }
        }
    }
    let lado = (ler(clube) != ler(t)) as usize;
    for k in 0..20 {
        let linha = t + 0x625 * lado + 0x1ce + k * 0x49;
        let id = ler(linha - 0x3e);
        if id == -1 || ub(linha) == 0 {
            continue;
        }
        let p = (g(0xae23bc) as isize + id as isize * 0x6e) as usize;
        if g(p + 0x61) == 0 || (p != 0 && ler(p) >= ler(0xae2364)) || byte(p, 0x18) > 0x14 {
            continue;
        }
        let c = contrato(g(0xae1050), p);
        if c == 0 || ler(c + 0x45) != 0 || ub(partida + 0x40) == 0 || ub(partida + 0x41) == 0 {
            continue;
        }
        if ler(partida + 0x14) == 0 || ler(partida + 0x14) != ler(clube + 0x57) || fora(clube) != 0 || byte(p, 0x59) <= 0xf {
            continue;
        }
        crate::comparacao::ramo("clube jovem");
        let r = sortear(5);
        if byte(p, 0x57) <= (r as u8).wrapping_add(10) as i8 || g(p + 0x61) == 0 || w(g(p + 0x61) + 0xb) >= 0x109a {
            continue;
        }
        if teste_7c3a40(g(0xb74350), p, clube) == 0 {
            crate::comparacao::ramo("clube 589bc0");
            f589bc0(p, clube);
            if teste_547d60(p, clube) == 0 {
                crate::comparacao::ramo("clube 547d90");
                f547d90(p, clube, 1);
            }
            return;
        }
    }
}

/// { 0x6b74a0 }: ver `eventos_do_pos_jogo_com`.
unsafe extern "C" fn eventos_do_pos_jogo(partida: usize) {
    eventos_do_pos_jogo_com(partida, &mut |r, t, a| despachar_pos(r, t, a))
}

/// { 0x6b6cc0 }: ver `jogadores_do_pos_jogo_com`.
unsafe extern "C" fn jogadores_do_pos_jogo(partida: usize, t: usize) {
    jogadores_do_pos_jogo_com(partida, t, &mut |r, tt, a| despachar_pos(r, tt, a))
}

/// { 0x6b79a0 }: ver `clube_do_pos_jogo_com`.
unsafe extern "C" fn clube_do_pos_jogo(clube: usize, outro: usize, partida: usize, n: u32, t: usize) {
    clube_do_pos_jogo_com(clube, outro, partida, n, t, &mut |r, tt, a| despachar_pos(r, tt, a))
}

/// As rotinas do banco com efeitos chamadas pelo pos-jogo, pelo endereco do jogo (`this` 0: cdecl).
unsafe fn despachar_pos(rotina: usize, this: usize, a: [u32; 5]) -> u32 {
    type T1 = unsafe extern "thiscall" fn(usize, u32) -> u32;
    type T2 = unsafe extern "thiscall" fn(usize, u32, u32) -> u32;
    type T3 = unsafe extern "thiscall" fn(usize, u32, u32, u32) -> u32;
    type T4 = unsafe extern "thiscall" fn(usize, u32, u32, u32, u32) -> u32;
    type T5 = unsafe extern "thiscall" fn(usize, u32, u32, u32, u32, u32) -> u32;
    type C4 = unsafe extern "C" fn(u32, u32, u32, u32) -> u32;
    type C5 = unsafe extern "C" fn(u32, u32, u32, u32, u32) -> u32;
    match rotina {
        0x4cf5f0 | 0x7c3a40 => core::mem::transmute::<usize, T2>(rotina)(this, a[0], a[1]),
        0x600a50 => core::mem::transmute::<usize, C5>(rotina)(a[0], a[1], a[2], a[3], a[4]),
        0x8676d0 | 0x8674e0 | 0x867560 => core::mem::transmute::<usize, T1>(rotina)(this, a[0]),
        0x867700 | 0x733a60 | 0x5afe00 => core::mem::transmute::<usize, T2>(rotina)(this, a[0], a[1]),
        0x759610 => core::mem::transmute::<usize, T3>(rotina)(this, a[0], a[1], a[2]),
        0x744240 => core::mem::transmute::<usize, T4>(rotina)(this, a[0], a[1], a[2], a[3]),
        0x72c1f0 => core::mem::transmute::<usize, T5>(rotina)(this, a[0], a[1], a[2], a[3], a[4]),
        // cdecl: quem chama limpa a pilha, os argumentos a mais nao sao lidos
        _ => core::mem::transmute::<usize, C4>(rotina)(a[0], a[1], a[2], a[3]),
    }
}

// --- portas do pos-jogo: as 14 rotinas do banco com efeitos (e a consulta 0x7c3a40), gravadas na fita so durante as
// comparacoes do pos-jogo (GRAVAR_POS); para os outros chamadores do jogo so repassam. Devolvem
// edx:eax inteiro (nenhuma devolve ponto flutuante: conferido na 132a leva).
static GRAVAR_POS: std::sync::atomic::AtomicBool = std::sync::atomic::AtomicBool::new(false);
static mut PORTAS_POS: [usize; 15] = [0; 15];
const PROLOGOS_POS: [Prologo; 15] = [
    Prologo { endereco: 0x8676d0, bytes: &[0x8b, 0x44, 0x24, 0x04, 0x8b, 0x51, 0x40] },
    Prologo { endereco: 0x8674e0, bytes: &[0x56, 0x57, 0x8b, 0x7c, 0x24, 0x0c] },
    Prologo { endereco: 0x867560, bytes: &[0x81, 0xec, 0x00, 0x02, 0x00, 0x00] },
    Prologo { endereco: 0x867700, bytes: &[0x53, 0x56, 0x8b, 0xf1, 0x8b, 0x15, 0xb4, 0x23, 0xae, 0x00] },
    Prologo { endereco: 0x733a60, bytes: &[0x6a, 0xff, 0x68, 0xe6, 0xd6, 0x95, 0x00] },
    Prologo { endereco: 0x5afe00, bytes: &[0x51, 0x53, 0x55, 0x8b, 0x6c, 0x24, 0x10] },
    Prologo { endereco: 0x759610, bytes: &[0x6a, 0xff, 0x68, 0x83, 0xd9, 0x95, 0x00] },
    Prologo { endereco: 0x744240, bytes: &[0x6a, 0xff, 0x68, 0x06, 0xd8, 0x95, 0x00] },
    Prologo { endereco: 0x72c1f0, bytes: &[0x6a, 0xff, 0x68, 0x86, 0xd6, 0x95, 0x00] },
    Prologo { endereco: 0x7daf50, bytes: &[0x6a, 0xff, 0x68, 0x70, 0xfd, 0x95, 0x00] },
    Prologo { endereco: 0x547af0, bytes: &[0x53, 0x8b, 0x5c, 0x24, 0x08] },
    Prologo { endereco: 0x5896d0, bytes: &[0x64, 0xa1, 0x00, 0x00, 0x00, 0x00] },
    Prologo { endereco: 0x589bc0, bytes: &[0x64, 0xa1, 0x00, 0x00, 0x00, 0x00] },
    Prologo { endereco: 0x547d90, bytes: &[0x56, 0x57, 0x8b, 0x7c, 0x24, 0x0c] },
    Prologo { endereco: 0x7c3a40, bytes: &[0x8b, 0x44, 0x24, 0x04, 0x81, 0xec, 0x04, 0x02, 0x00, 0x00] },
];

/// Dentro de uma comparacao do pos-jogo, com a fita aberta.
fn gravando_pos() -> bool {
    GRAVAR_POS.load(std::sync::atomic::Ordering::Relaxed) && gravando()
}

/// Repassa ou grava (durante uma comparacao do pos-jogo, no nivel de cima da fita).
unsafe fn passar_pos(rotina: usize, this: usize, a: [u32; 5], f: impl FnOnce() -> u64) -> u64 {
    use std::sync::atomic::Ordering::Relaxed;
    if GRAVAR_POS.load(Relaxed) && gravando() {
        let mut r = 0u64;
        chamar_gravando(rotina, this, a, || {
            r = f();
            r as u32
        });
        return r;
    }
    f()
}

unsafe extern "thiscall" fn porta_8676d0(c: usize, a: u32) -> u64 {
    let f: unsafe extern "thiscall" fn(usize, u32) -> u64 = core::mem::transmute(PORTAS_POS[0]);
    passar_pos(0x8676d0, c, [a, 0, 0, 0, 0], || f(c, a))
}
