// ---------- 251a leva: as listas de posição da lista de observação: montar as listas, ordená-las a cada dia e os clubes interessados no jogador (shortlist_manager.cpp) ----------

unsafe fn cpo8_d(a: usize) -> usize {
    core::ptr::read_unaligned(a as *const usize)
}

unsafe fn cpo8_i(a: usize) -> i32 {
    core::ptr::read_unaligned(a as *const i32)
}

unsafe fn cpo8_b(a: usize) -> u8 {
    *(a as *const u8)
}

unsafe fn cpo8_w(a: usize, v: u32) {
    core::ptr::write_unaligned(a as *mut u32, v)
}

/// O registro de clube de id `id` ([0xae23b4], 0x245 bytes).
unsafe fn cpo8_clube(id: usize) -> usize {
    cpo8_d(0xae23b4).wrapping_add(id.wrapping_mul(0x245))
}

/// A pessoa de id `id` ([0xae23bc], 0x6e bytes).
unsafe fn cpo8_pessoa(id: usize) -> usize {
    cpo8_d(0xae23bc).wrapping_add(id.wrapping_mul(0x6e))
}

/// O contrato principal da pessoa (0x4cf5a0, guardado em [0xae1080]), o clube dele (id em +4) e o contrato com esse
/// clube (0x4cf5f0).
unsafe fn cpo8_contrato_com_o_clube(p: usize) -> usize {
    let contrato_de: unsafe extern "thiscall" fn(usize, usize) -> usize = core::mem::transmute(0x4cf5a0usize);
    let com_clube: unsafe extern "thiscall" fn(usize, usize, usize) -> usize = core::mem::transmute(0x4cf5f0usize);
    let c = contrato_de(cpo8_d(0xae1050), p);
    *(0xae1080 as *mut usize) = c;
    let clube = if c != 0 { cpo8_clube(cpo8_d(c + 4)) } else { 0 };
    com_clube(cpo8_d(0xae1050), p, clube)
}

/// { 0x839e60 } (thiscall, ret 4, shortlist_manager.cpp): `Shortlist_Manager::build_position_lists(não usado)`: libera
/// os 32 vetores das listas de posição (+0x18: 16 pela pessoa, +0x58: 16 pela chave do contrato); o tamanho deles
/// (+0xd8) é o maior número de pessoas (todas, humanos inclusive) que servem para uma das 16 vagas (0x844300); aloca os
/// 32 com 12 bytes por entrada (sem memória: a caixa "Error" e o jogo para) e zera as contas (+0x98). Depois, cada
/// pessoa fora dos 16 humanos, em cada vaga que serve (conta no limite: a caixa e o jogo para): as duas entradas com o
/// id dela (+0), o id da nação (+4; sem nação em +0x1a, a 0x90cfc0 sorteia uma e a grava na pessoa), na primeira o valor
/// (+0x52) e na segunda o +0x3d do contrato com o clube do contrato (sem contrato: 100). Roda a cada 30 dias.
unsafe extern "thiscall" fn montar_listas_de_posicao(this: usize, _nao_usado: u32) {
    let livrar: unsafe extern "C" fn(usize) = core::mem::transmute(0x9452causize);
    let alocar: unsafe extern "C" fn(u32) -> usize = core::mem::transmute(0x944e46usize);
    // ponytail: a original empurra a vaga num dword com 3 bytes de lixo da pilha acima; a 0x844300 só lê o byte
    let serve: unsafe extern "stdcall" fn(usize, u32) -> u8 = core::mem::transmute(0x844300usize);
    crate::comparacao::ramo("cpo_8 montar listas");
    for k in 0..32usize {
        let v = this + 0x18 + k * 4;
        if cpo8_d(v) != 0 {
            livrar(cpo8_d(v));
            cpo8_w(v, 0);
        }
    }
    cpo8_w(this + 0xd8, 0);
    for vaga in 0..16u32 {
        let base = cpo8_d(0xae23bc);
        let mut n = 0i32;
        let mut i = 0usize;
        while (i as i32) < cpo8_i(0xae2364) {
            if serve(base.wrapping_add(i * 0x6e), vaga) != 0 {
                n += 1;
            }
            i += 1;
        }
        if n > cpo8_i(this + 0xd8) {
            cpo8_w(this + 0xd8, n as u32);
        }
    }
    for k in 0..32usize {
        let v = alocar(cpo8_d(this + 0xd8).wrapping_mul(12) as u32);
        cpo8_w(this + 0x18 + k * 4, v as u32);
        if v == 0 {
            erro_em(0xa825a4, 0x10c);
        }
    }
    for k in 0..16usize {
        cpo8_w(this + 0x98 + k * 4, 0);
    }
    let base = cpo8_d(0xae23bc);
    let mut i = 0usize;
    while (i as i32) < cpo8_i(0xae2364).wrapping_sub(0x10) {
        let p = base.wrapping_add(i * 0x6e);
        for vaga in 0..16u32 {
            if serve(p, vaga) == 0 {
                continue;
            }
            let pv = vaga as usize;
            let conta = cpo8_i(this + 0x98 + pv * 4);
            if conta >= cpo8_i(this + 0xd8) {
                erro_em(0xa825a4, 0x121);
            }
            let o = (conta as usize).wrapping_mul(12);
            let (l1, l2) = (cpo8_d(this + 0x18 + pv * 4).wrapping_add(o), cpo8_d(this + 0x58 + pv * 4).wrapping_add(o));
            cpo8_w(l1, i as u32);
            cpo8_w(l2, i as u32);
            let mut nacao = cpo8_d(p + 0x1a);
            if nacao == 0 {
                let sortear: unsafe extern "C" fn(i32) -> i32 = core::mem::transmute(0x90cfc0usize);
                nacao = cpo8_d(0xae23a8).wrapping_add((sortear(cpo8_i(0xae2350)) as usize).wrapping_mul(0x122));
                cpo8_w(p + 0x1a, nacao as u32);
            }
            cpo8_w(l1 + 4, cpo8_d(nacao) as u32);
            cpo8_w(l2 + 4, cpo8_d(cpo8_d(p + 0x1a)) as u32);
            cpo8_w(l1 + 8, cpo8_d(p + 0x52) as u32);
            let k = cpo8_contrato_com_o_clube(p);
            cpo8_w(l2 + 8, if k != 0 { cpo8_b(k + 0x3d) as i8 as i32 as u32 } else { 100 });
            cpo8_w(this + 0x98 + pv * 4, (conta + 1) as u32);
        }
        i += 1;
    }
}

/// { 0x83a780 } (thiscall, ret 0, shortlist_manager.cpp): `Shortlist_Manager::sort_position_lists()`: a cada dia,
/// refaz a chave (+8) das entradas das 16 vagas e ordena os dois vetores de cada uma (0x945333 com 0x83b670: pela chave
/// e pelo +4). Na primeira lista: o valor da pessoa (+0x52) se o contrato com o clube existe e a faixa do vencimento
/// (0x867d30) é 0, senão 0; o jogador de clube humano (0x600a50) na lista de transferências (0x5444a0) perde 1.500.000,
/// no mínimo um terço do valor. Na vaga 15 só a primeira, com o valor. Na segunda: −1000 com o bit 2 do +0x4e do
/// contrato, 2000 com os bits 0 ou 3 ou sem jogador (+0x61), sem clube, sem divisão (+0x57) ou divisão sem marca em
/// [0xadadfc] com reputação abaixo de 6000, ou sem contrato; senão o +0x3d do contrato.
unsafe extern "thiscall" fn ordenar_listas_de_posicao(this: usize) {
    let faixa: unsafe extern "thiscall" fn(usize) -> u8 = core::mem::transmute(0x867d30usize);
    let humano: unsafe extern "C" fn(usize, u32, u32, usize, u32) -> u32 = core::mem::transmute(0x600a50usize);
    let listado: unsafe extern "C" fn(usize, usize) -> u32 = core::mem::transmute(0x5444a0usize);
    let ordenar: unsafe extern "C" fn(usize, u32, u32, usize) = core::mem::transmute(0x945333usize);
    for vaga in 0..16usize {
        let mut j = 0i32;
        let mut o = 0usize;
        while j < cpo8_i(this + 0x98 + vaga * 4) {
            let p = cpo8_pessoa(cpo8_d(cpo8_d(this + 0x18 + vaga * 4) + o));
            let k = cpo8_contrato_com_o_clube(p);
            if vaga == 15 {
                cpo8_w(cpo8_d(this + 0x54) + o + 8, cpo8_d(p + 0x52) as u32);
                j += 1;
                o += 12;
                continue;
            }
            if k != 0 && faixa(k) == 0 {
                cpo8_w(cpo8_d(this + 0x18 + vaga * 4) + o + 8, cpo8_d(p + 0x52) as u32);
                let clube = cpo8_d(p + 0x39);
                if clube != 0 && humano(clube, 0, 1, 0, 0) != 0 && listado(p, 0) != 0 {
                    let e = cpo8_d(this + 0x18 + vaga * 4) + o + 8;
                    cpo8_w(e, cpo8_i(e).wrapping_add(-0x16e360) as u32);
                    let terco = cpo8_i(p + 0x52) / 3;
                    if cpo8_i(e) < terco {
                        cpo8_w(e, terco as u32);
                    }
                }
            } else {
                if k != 0 {
                    crate::comparacao::ramo("cpo_8 faixa do contrato");
                }
                cpo8_w(cpo8_d(this + 0x18 + vaga * 4) + o + 8, 0);
            }
            // a segunda lista
            let p2 = cpo8_pessoa(cpo8_d(cpo8_d(this + 0x58 + vaga * 4) + o));
            let k2 = cpo8_contrato_com_o_clube(p2);
            let clube = cpo8_d(p2 + 0x39);
            let chave: i32 = if cpo8_d(p2 + 0x61) == 0 || clube == 0 || cpo8_d(clube + 0x57) == 0 {
                0x7d0
            } else if cpo8_d(cpo8_d(0xadadfc) + cpo8_d(cpo8_d(clube + 0x57)).wrapping_mul(4)) == 0
                && core::ptr::read_unaligned((clube + 0x80) as *const i16) < 0x1770
            {
                0x7d0
            } else if k2 == 0 {
                0x7d0
            } else if cpo8_b(k2 + 0x4e) & 2 != 0 {
                -1000
            } else if cpo8_b(k2 + 0x4e) & 9 != 0 {
                0x7d0
            } else {
                cpo8_b(k2 + 0x3d) as i8 as i32
            };
            cpo8_w(cpo8_d(this + 0x58 + vaga * 4) + o + 8, chave as u32);
            j += 1;
            o += 12;
        }
        let n = cpo8_d(this + 0x98 + vaga * 4) as u32;
        ordenar(cpo8_d(this + 0x18 + vaga * 4), n, 12, 0x83b670);
        let n = cpo8_d(this + 0x98 + vaga * 4) as u32;
        ordenar(cpo8_d(this + 0x58 + vaga * 4), n, 12, 0x83b670);
    }
}

/// { 0x842180 } (thiscall, ret 0x14, shortlist_manager.cpp): `Shortlist_Manager::collect_interested_clubs(jogador,
/// saída, ignorar, modo, só_humanos)`: esvazia a lista `saída` (0x68d080) e acrescenta (0x68d0d0, 8 bytes: id do
/// jogador, id do clube) os clubes interessados: com modo ≠ 3, os 16 humanos (do último para o primeiro) com +0x5f e
/// clube que têm o jogador na lista do olheiro (0x7f7490; com modo 2, fora os clubes que o humano da vez controla,
/// 0x600c90); sem `só_humanos`, os pares (jogador, clube) do vetor pela pessoa (+0, conta +0x10; 0x946464 até o primeiro
/// do jogador) cujo clube não está suspenso (+8 da entrada de 9 bytes do clube em +0xdc abaixo de 100, salvo com
/// `ignorar`), não é o do jogador e põe nele (+7 da vaga de 0x25 bytes com o jogador em +0xf; sem vaga, a primeira)
/// mais que o valor (+0x52).
unsafe extern "thiscall" fn clubes_interessados_no_jogador(this: usize, jogador: usize, saida: usize, ignorar: u32, modo: u32, so_humanos: u32) {
    let acrescentar: unsafe extern "thiscall" fn(usize, usize, u32) -> usize = core::mem::transmute(0x68d0d0usize);
    if saida != 0 {
        let limpar: unsafe extern "thiscall" fn(usize) = core::mem::transmute(0x68d080usize);
        limpar(saida);
    }
    if modo as u8 != 3 {
        let controla: unsafe extern "C" fn(usize, u32, u32) -> u32 = core::mem::transmute(0x600c90usize);
        let na_lista: unsafe extern "thiscall" fn(usize, usize, usize) -> u32 = core::mem::transmute(0x7f7490usize);
        for k in 0..16i32 {
            let h = cpo8_pessoa(cpo8_i(0xae2364).wrapping_sub(k).wrapping_sub(1) as usize);
            let clube = cpo8_d(h + 0x39);
            if cpo8_b(h + 0x5f) == 0 || clube == 0 {
                continue;
            }
            if controla(clube, 0, 1) != 0 && modo as u8 == 2 {
                continue;
            }
            if na_lista(cpo8_d(0xb74448), jogador, h) != 0 {
                let par = [cpo8_d(jogador) as u32, cpo8_d(clube) as u32];
                acrescentar(saida, par.as_ptr() as usize, 8);
            }
        }
    }
    if so_humanos != 0 {
        return;
    }
    let bsearch: unsafe extern "C" fn(*const u32, usize, i32, u32, usize) -> usize = core::mem::transmute(0x946464usize);
    let chave = [cpo8_d(jogador) as u32, 0xffff_ffff];
    let mut e = bsearch(chave.as_ptr(), cpo8_d(this), cpo8_i(this + 0x10), 8, 0x757ea0);
    if e == 0 {
        return;
    }
    let base = cpo8_d(this);
    let ultimo = base.wrapping_add((cpo8_i(this + 0x10) as usize).wrapping_mul(8)).wrapping_sub(8);
    let id = cpo8_d(jogador);
    if e > base {
        loop {
            let x = cpo8_d(e - 8);
            e -= 8;
            if x != id {
                e += 8;
                break;
            }
            if e <= base {
                break;
            }
        }
    }
    if cpo8_d(e) != id {
        return;
    }
    loop {
        let clube_id = cpo8_d(e + 4);
        let entrada = cpo8_d(this + 0xdc).wrapping_add(clube_id.wrapping_mul(9));
        let vagas = cpo8_d(entrada);
        let mut k = 0usize;
        while k < 0x28 && cpo8_d(vagas + 0xf + k * 0x25) != cpo8_d(jogador) {
            k += 1;
        }
        let valor = if k < 0x28 { cpo8_i(vagas + k * 0x25 + 7) } else { cpo8_i(vagas + 7) };
        if !(ignorar == 0 && cpo8_b(entrada + 8) >= 100) && valor > cpo8_i(jogador + 0x52) {
            let c = cpo8_d(jogador + 0x39);
            if !(c != 0 && cpo8_d(c) == clube_id) {
                crate::comparacao::ramo("cpo_8 clube interessado");
                acrescentar(saida, e, 8);
            }
        }
        if e == ultimo {
            return;
        }
        let prox = cpo8_d(e + 8);
        e += 8;
        if prox != cpo8_d(jogador) {
            return;
        }
    }
}

/// Os itens (8 bytes) de uma LLIST (+2 o primeiro nó; nó: +0 o dado, +6 o próximo).
unsafe fn cpo8_itens(lista: usize) -> Vec<(u32, u32)> {
    let mut v = Vec::new();
    let mut no = cpo8_d(lista + 2);
    while no != 0 {
        let x = cpo8_d(no);
        v.push((cpo8_d(x) as u32, cpo8_d(x + 4) as u32));
        no = cpo8_d(no + 6);
    }
    v
}

/// Comparador: só a original.
// ponytail: a original solta e aloca os 32 vetores (e pode sortear a nação de quem não tem); não roda duas vezes. Confere
// o resultado: as duas listas de cada vaga com os mesmos ids, cada entrada servindo para a vaga, a conta no limite.
unsafe extern "thiscall" fn comparar_montar_listas_de_posicao(this: usize, nao_usado: u32) {
    orig::<unsafe extern "thiscall" fn(usize, u32)>(988)(this, nao_usado);
    let serve: unsafe extern "stdcall" fn(usize, u32) -> u8 = core::mem::transmute(0x844300usize);
    let mut ruim = None;
    'f: for vaga in 0..16usize {
        let n = cpo8_i(this + 0x98 + vaga * 4);
        if n > cpo8_i(this + 0xd8) {
            ruim = Some((vaga, -1));
            break;
        }
        for j in 0..n.max(0) as usize {
            let (a, b) = (cpo8_d(this + 0x18 + vaga * 4) + j * 12, cpo8_d(this + 0x58 + vaga * 4) + j * 12);
            if cpo8_d(a) != cpo8_d(b) || serve(cpo8_pessoa(cpo8_d(a)), vaga as u32) == 0 {
                ruim = Some((vaga, j as i32));
                break 'f;
            }
        }
    }
    PLACAR.registrar(ruim.is_none(), || format!("montar_listas_de_posicao: vaga e entrada {:?}", ruim));
}

/// Comparador: lado a lado pelos 32 vetores (12 bytes por entrada) e por [0xae1080].
unsafe extern "thiscall" fn comparar_ordenar_listas_de_posicao(this: usize) {
    let o = orig::<unsafe extern "thiscall" fn(usize)>(989);
    let mut reg = vec![(0xae1080usize, 4usize)];
    for vaga in 0..16usize {
        let n = cpo8_i(this + 0x98 + vaga * 4);
        if n > 0 {
            reg.push((cpo8_d(this + 0x18 + vaga * 4), n as usize * 12));
            reg.push((cpo8_d(this + 0x58 + vaga * 4), n as usize * 12));
        }
    }
    let (_, _, igual, mo, mr) = crate::comparacao::lado_a_lado(&reg, || o(this), || ordenar_listas_de_posicao(this));
    PLACAR.registrar(igual, || {
        let dif: Vec<usize> = mo.0.iter().zip(mr.0.iter()).filter(|(a, b)| a.1 != b.1).map(|(a, _)| a.0).take(8).collect();
        format!("ordenar_listas_de_posicao: vetores diferentes {:x?}", dif)
    });
}

/// Comparador: a original na lista de saída e a cópia numa lista nova (0x68d020, solta com 0x68d080); compara os pares.
unsafe extern "thiscall" fn comparar_clubes_interessados_no_jogador(this: usize, jogador: usize, saida: usize, ignorar: u32, modo: u32, so_humanos: u32) {
    let o = orig::<unsafe extern "thiscall" fn(usize, usize, usize, u32, u32, u32)>(990);
    o(this, jogador, saida, ignorar, modo, so_humanos);
    if saida == 0 {
        return;
    }
    let criar: unsafe extern "thiscall" fn(usize) -> usize = core::mem::transmute(0x68d020usize);
    let limpar: unsafe extern "thiscall" fn(usize) = core::mem::transmute(0x68d080usize);
    let mut nova = [0u8; 0x10];
    let l = nova.as_mut_ptr() as usize;
    criar(l);
    clubes_interessados_no_jogador(this, jogador, l, ignorar, modo, so_humanos);
    let (a, b) = (cpo8_itens(saida), cpo8_itens(l));
    limpar(l);
    PLACAR.registrar(a == b, || format!("clubes_interessados_no_jogador({:#x}) original={:x?} rust={:x?}", jogador, a, b));
}

// ---------- 251a leva: a lista de observação e o empréstimo: acrescentar o par na lista, prever a resposta do clube vendedor e o período do empréstimo (shortlist_manager.cpp, transfer_manager.cpp) ----------

unsafe fn cpo9_d(a: usize) -> usize {
    core::ptr::read_unaligned(a as *const usize)
}

unsafe fn cpo9_i(a: usize) -> i32 {
    core::ptr::read_unaligned(a as *const i32)
}

unsafe fn cpo9_h(a: usize) -> i16 {
    core::ptr::read_unaligned(a as *const i16)
}

unsafe fn cpo9_b(a: usize) -> u8 {
    *(a as *const u8)
}

unsafe fn cpo9_w(a: usize, v: u32) {
    core::ptr::write_unaligned(a as *mut u32, v)
}

/// Acrescenta o par (id da pessoa, id do clube) no fim do vetor `[this + vet]` (conta em `this + conta`) e o ordena
/// (0x945333 com `cmp`).
unsafe fn cpo9_inserir(this: usize, vet: usize, conta: usize, pessoa: usize, clube: usize, cmp: usize) {
    let ordenar: unsafe extern "C" fn(usize, u32, u32, usize) = core::mem::transmute(0x945333usize);
    let n = cpo9_i(this + conta);
    let e = cpo9_d(this + vet).wrapping_add((n as usize).wrapping_mul(8));
    cpo9_w(e, cpo9_d(pessoa) as u32);
    cpo9_w(e + 4, cpo9_d(clube) as u32);
    cpo9_w(this + conta, (n + 1) as u32);
    ordenar(cpo9_d(this + vet), (n + 1) as u32, 8, cmp);
}

/// { 0x8423f0 } (thiscall, ret 8, shortlist_manager.cpp): `Shortlist_Manager::add_shortlist_entry(pessoa, clube)`: cria
/// os dois vetores de pares na primeira vez (0x944e46 de 0x320 bytes, capacidade +8/+0xc = 100; sem memória: a caixa
/// "Error" e o jogo para); com o par (pessoa, clube; sem clube −1) já no vetor pela pessoa (0x946464 com 0x757ea0), nada.
/// Senão cresce de 100 em 100 o vetor cheio (0x945667), acrescenta o par nos dois e os ordena (pela pessoa com
/// 0x757ea0, pelo clube com 0x844740) e, fora de clube humano (0x600a50), soma 1 no nibble baixo do +0xb do registro de
/// 79 bytes da pessoa ([0xae2d0c]: quantas listas a têm).
unsafe extern "thiscall" fn acrescentar_na_lista_de_observacao(this: usize, pessoa: usize, clube: usize) {
    let alocar: unsafe extern "C" fn(u32) -> usize = core::mem::transmute(0x944e46usize);
    let realocar: unsafe extern "C" fn(usize, u32) -> usize = core::mem::transmute(0x945667usize);
    if cpo9_d(this) == 0 {
        let v = alocar(0x320);
        cpo9_w(this, v as u32);
        if v == 0 {
            erro_em(0xa825a4, 0x1594);
        }
        cpo9_w(this + 8, 100);
    }
    if cpo9_d(this + 4) == 0 {
        let v = alocar(0x320);
        cpo9_w(this + 4, v as u32);
        if v == 0 {
            erro_em(0xa825a4, 0x159d);
        }
        cpo9_w(this + 0xc, 100);
    }
    if cpo9_d(this) != 0 {
        let bsearch: unsafe extern "C" fn(*const u32, usize, i32, u32, usize) -> usize = core::mem::transmute(0x946464usize);
        let chave = [cpo9_d(pessoa) as u32, if clube != 0 { cpo9_d(clube) as u32 } else { 0xffff_ffff }];
        if bsearch(chave.as_ptr(), cpo9_d(this), cpo9_i(this + 0x10), 8, 0x757ea0) != 0 {
            return;
        }
    }
    crate::comparacao::ramo("cpo_9 nova entrada");
    if cpo9_i(this + 8) == cpo9_i(this + 0x10) {
        let v = realocar(cpo9_d(this), (cpo9_i(this + 8) as u32).wrapping_mul(8).wrapping_add(0x320));
        cpo9_w(this, v as u32);
        if v == 0 {
            erro_em(0xa825a4, 0x15b5);
        }
        cpo9_w(this + 8, cpo9_i(this + 8).wrapping_add(100) as u32);
    }
    if cpo9_i(this + 0xc) == cpo9_i(this + 0x14) {
        let v = realocar(cpo9_d(this + 4), (cpo9_i(this + 0xc) as u32).wrapping_mul(8).wrapping_add(0x320));
        cpo9_w(this + 4, v as u32);
        if v == 0 {
            erro_em(0xa825a4, 0x15be);
        }
        cpo9_w(this + 0xc, cpo9_i(this + 0xc).wrapping_add(100) as u32);
    }
    cpo9_inserir(this, 0, 0x10, pessoa, clube, 0x757ea0); // o vetor pela pessoa
    cpo9_inserir(this, 4, 0x14, pessoa, clube, 0x844740); // o vetor pelo clube
    let humano: unsafe extern "C" fn(usize, u32, u32, usize, u32) -> u32 = core::mem::transmute(0x600a50usize);
    if humano(clube, 0, 1, 0, 0) == 0 {
        let r = (cpo9_d(0xae2d0c).wrapping_add(cpo9_d(pessoa).wrapping_mul(0x4f)) + 0xb) as *mut u8;
        let a = *r;
        *r = (a & 0xf0) | (a.wrapping_add(1) & 0xf);
    }
}

/// { 0x84af00 } (stdcall, ret 0x20, shortlist_manager.cpp): `shortlist_manager_predict_selling_club_response(vendedor,
/// jogador, oferta, comprador, pedido, empréstimo)`: 0 aceita, 1 negocia, 2 recusa. Sem vendedor ou com o contrato com
/// ele (0x4cf5f0) marcado em +0x49: 0; o técnico do vendedor é o jogador: 2; sem contrato de tipo 2 (+0x35): 2 no
/// empréstimo, 0 senão. Empréstimo: clube humano (0x600a50): 0; listado para empréstimo (0x544590) com a reputação do
/// comprador × [0x968928] acima do +0xb da ficha: 0; estatuto 6/7 (+0x4f) ou +0xf da ficha 20, com a reputação acima de
/// +0xb × [0x969040], +0x3d do contrato abaixo de −50 e o +0x1db do vendedor diferente de [0x9cf6e8]: 0; senão 2.
/// Compra: o preço (humano: 0x4d42d0 × [0x9689b0], sem cláusula 0x867b50 e com o técnico de férias 0x5fd210 a opção 0
/// 0x5fea50: 1 recusa, 2 o valor +0x52; senão o `pedido` não negativo, o valor sem ficha ou 0x4d1600); oferta no preço:
/// 0; humano com a oferta acima do preço − 1.500.000 e listado (0x5444a0): 1; preço × [0x96f9c0] acima da oferta: 2; 1.
unsafe extern "stdcall" fn prever_resposta_do_vendedor(vendedor: usize, jogador: usize, oferta: i64, comprador: usize, pedido: i64, emprestimo: u32) -> u8 {
    let com_clube: unsafe extern "thiscall" fn(usize, usize, usize) -> usize = core::mem::transmute(0x4cf5f0usize);
    let humano: unsafe extern "C" fn(usize, u32, u32, usize, u32) -> u32 = core::mem::transmute(0x600a50usize);
    let k = com_clube(cpo9_d(0xae1050), jogador, vendedor);
    if vendedor == 0 || (k != 0 && cpo9_b(k + 0x49) != 0) {
        return 0;
    }
    if cpo9_d(vendedor + 0xcf) == jogador {
        return 2;
    }
    if k == 0 || cpo9_b(k + 0x35) & 0x3f != 2 {
        return if emprestimo as u8 != 0 { 2 } else { 0 };
    }
    if emprestimo as u8 != 0 {
        if humano(vendedor, 0, 1, 0, 0) != 0 {
            return 0;
        }
        let listado: unsafe extern "C" fn(usize, usize) -> u32 = core::mem::transmute(0x544590usize);
        let rep = cpo9_h(comprador + 0x80) as f64;
        if listado(jogador, 0) != 0 && rep * f64_em(0x968928) > cpo9_h(cpo9_d(jogador + 0x61) + 0xb) as f64 {
            return 0;
        }
        let st = cpo9_b(k + 0x4f) & 0xf0;
        if st == 0x60 || st == 0x70 || cpo9_b(cpo9_d(jogador + 0x61) + 0xf) == 0x14 {
            let v = cpo9_h(cpo9_d(jogador + 0x61) + 0xb) as f64 * f64_em(0x969040);
            if rep > v && (cpo9_b(k + 0x3d) as i8) < -50 && cpo9_d(vendedor + 0x1db) != cpo9_d(0x9cf6e8) {
                return 0;
            }
        }
        return 2;
    }
    let preco: i32 = if humano(vendedor, 0, 1, 0, 0) != 0 {
        let pedido_humano: unsafe extern "thiscall" fn(usize, usize, usize, usize) -> i32 = core::mem::transmute(0x4d42d0usize);
        let mut v = ftol(pedido_humano(cpo9_d(0xae1050), vendedor, comprador, jogador) as f64 * f64_em(0x9689b0));
        let clausula: unsafe extern "thiscall" fn(usize) -> u32 = core::mem::transmute(0x867b50usize);
        if clausula(k) == 0 {
            let tecnico: unsafe extern "C" fn(usize) -> usize = core::mem::transmute(0x53ca90usize);
            let ferias: unsafe extern "thiscall" fn(usize, usize) -> u32 = core::mem::transmute(0x5fd210usize);
            if ferias(cpo9_d(0xb63c98), tecnico(vendedor)) != 0 {
                let opcao: unsafe extern "thiscall" fn(usize, u32, usize) -> u8 = core::mem::transmute(0x5fea50usize);
                match opcao(cpo9_d(0xb63c98), 0, tecnico(vendedor)) as i8 {
                    1 => return 2,
                    2 => v = cpo9_i(jogador + 0x52),
                    _ => {}
                }
            }
        }
        v
    } else if pedido >= 0 {
        pedido as i32
    } else if cpo9_d(jogador + 0x61) == 0 {
        cpo9_i(jogador + 0x52)
    } else {
        let calcular: unsafe extern "thiscall" fn(usize, usize, usize, usize, u32, u32, u32) -> i32 = core::mem::transmute(0x4d1600usize);
        calcular(cpo9_d(0xae1050), vendedor, comprador, jogador, 0, 1, 1)
    };
    if oferta >= preco as i64 {
        return 0;
    }
    let listado: unsafe extern "C" fn(usize, usize) -> u32 = core::mem::transmute(0x5444a0usize);
    if humano(vendedor, 0, 1, 0, 0) != 0 && (preco.wrapping_sub(0x16e360) as i64) < oferta && listado(jogador, 0) != 0 {
        return 1;
    }
    if preco as f64 * f64_em(0x96f9c0) > oferta as f64 {
        return 2;
    }
    crate::comparacao::ramo("cpo_9 negocia");
    1
}

/// O ano da data padrão (0x54a110: dia 40 de 1972).
unsafe fn cpo9_ano_padrao() -> u16 {
    let padrao: unsafe extern "thiscall" fn(usize) -> usize = core::mem::transmute(0x54a110usize);
    let mut data = [0u8; 8];
    let p = padrao(data.as_mut_ptr() as usize);
    cpo9_h(p + 2) as u16
}

/// A data (dia do ano +0, ano +2) passa do fim do contrato `c` (+0x2d dia, +0x2f ano)?
unsafe fn cpo9_depois_do_contrato(dia: i16, ano: u16, c: usize) -> bool {
    let fim = cpo9_h(c + 0x2f) as u16;
    ano > fim || (ano == fim && dia > cpo9_h(c + 0x2d))
}

/// { 0x8d0590 } (thiscall, ret 0x1c, transfer_manager.cpp): `TRANSFER_MANAGER::get_loan_period(clube, a2, jogador,
/// início_mês, início_ano, fim_mês, fim_ano)`: as regras da nação do clube (+0x53; das 28 em +0x8ac, a primeira sem
/// achar) dão o período (método +0x28). Sem contrato de tipo 2 (0x4cf5a0), com o contrato já vencido hoje ou o fim mais
/// de 5 anos à frente: o fim vira o ano da data padrão (1972). Senão, enquanto a data (dia do mês de hoje, fim_mês,
/// fim_ano; 0x549f70) passar do fim do contrato, recua um mês (o início acompanha se ficar depois do fim); fim antes do
/// ano de hoje: o ano padrão.
unsafe extern "thiscall" fn periodo_do_emprestimo(this: usize, clube: usize, a2: u32, jogador: usize, ini_mes: *mut i8, ini_ano: *mut u16, mes: *mut i8, ano: *mut u16) {
    let nacao = cpo9_d(clube + 0x53);
    let mut regra = cpo9_d(this + 0x8ac);
    for k in 0..0x1cusize {
        let r = cpo9_d(this + 0x8ac + k * 4);
        if cpo9_d(r + 0xa) == nacao {
            if r != 0 {
                regra = r;
            }
            break;
        }
    }
    let periodo: unsafe extern "thiscall" fn(usize, usize, u32, *mut i8, *mut u16, *mut i8, *mut u16, usize) = core::mem::transmute(cpo9_d(cpo9_d(regra) + 0x28));
    periodo(regra, clube, a2, ini_mes, ini_ano, mes, ano, jogador);
    let dia_do_mes: unsafe extern "thiscall" fn(usize) -> i32 = core::mem::transmute(0x54cf70usize);
    let dia = dia_do_mes(0xae2c90);
    let contrato_de: unsafe extern "thiscall" fn(usize, usize) -> usize = core::mem::transmute(0x4cf5a0usize);
    let c = contrato_de(cpo9_d(0xae1050), jogador);
    if c == 0 || cpo9_b(c + 0x35) & 0x3f != 2 || cpo9_depois_do_contrato(cpo9_h(0xae2c90), cpo9_h(0xae2c92) as u16, c) {
        *ano = cpo9_ano_padrao();
        return;
    }
    if *ano as i32 > cpo9_h(0xae2c92) as u16 as i32 + 5 {
        *ano = cpo9_ano_padrao();
        return;
    }
    // ponytail: a original empurra o mês e o ano em registradores com lixo acima; a 0x549f70 lê o byte e a palavra
    let data_de: unsafe extern "thiscall" fn(usize, i32, i32, u32, i32) -> usize = core::mem::transmute(0x549f70usize);
    loop {
        let mut data = [0u8; 8];
        let d = data_de(data.as_mut_ptr() as usize, dia, *mes as i32, *ano as u32, -1);
        if !cpo9_depois_do_contrato(cpo9_h(d), cpo9_h(d + 2) as u16, c) {
            return;
        }
        crate::comparacao::ramo("cpo_9 recua o mes");
        let m = (*mes).wrapping_sub(1);
        *mes = m;
        if m < 0 {
            *ano = (*ano).wrapping_sub(1);
            *mes = 11;
        }
        if *ini_ano > *ano || (*ini_ano == *ano && *ini_mes > *mes) {
            *ini_mes = *mes;
            *ini_ano = *ano;
        }
        if *ano < cpo9_h(0xae2c92) as u16 {
            *ano = cpo9_ano_padrao();
            return;
        }
    }
}

/// Comparador: só a original, conferindo o plano (feito antes): o par já estava (nada muda) ou entra nos dois vetores
/// (contas + 1, o par achado depois) e o nibble da pessoa soma 1 fora de clube humano.
// ponytail: a original realoca os vetores (0x945667) e os ordena; não roda duas vezes.
unsafe extern "thiscall" fn comparar_acrescentar_na_lista_de_observacao(this: usize, pessoa: usize, clube: usize) {
    let o = orig::<unsafe extern "thiscall" fn(usize, usize, usize)>(991);
    let bsearch: unsafe extern "C" fn(*const u32, usize, i32, u32, usize) -> usize = core::mem::transmute(0x946464usize);
    let humano: unsafe extern "C" fn(usize, u32, u32, usize, u32) -> u32 = core::mem::transmute(0x600a50usize);
    let chave = [cpo9_d(pessoa) as u32, if clube != 0 { cpo9_d(clube) as u32 } else { 0xffff_ffff }];
    let tinha = cpo9_d(this) != 0 && bsearch(chave.as_ptr(), cpo9_d(this), cpo9_i(this + 0x10), 8, 0x757ea0) != 0;
    let (n0, n1) = if cpo9_d(this) != 0 { (cpo9_i(this + 0x10), cpo9_i(this + 0x14)) } else { (0, 0) };
    let r = cpo9_d(0xae2d0c).wrapping_add(cpo9_d(pessoa).wrapping_mul(0x4f)) + 0xb;
    let nib = cpo9_b(r);
    let soma = !tinha && humano(clube, 0, 1, 0, 0) == 0;
    o(this, pessoa, clube);
    let esperado = if soma { (nib & 0xf0) | (nib.wrapping_add(1) & 0xf) } else { nib };
    let (d0, d1) = (if tinha { n0 } else { n0 + 1 }, if tinha { n1 } else { n1 + 1 });
    let achado = bsearch(chave.as_ptr(), cpo9_d(this), cpo9_i(this + 0x10), 8, 0x757ea0) != 0;
    let ok = cpo9_i(this + 0x10) == d0 && cpo9_i(this + 0x14) == d1 && cpo9_b(r) == esperado && (achado || clube == 0);
    PLACAR.registrar(ok, || {
        format!("acrescentar_na_lista_de_observacao({:#x}, {:#x}) tinha={} contas {}/{} -> {}/{} nibble {:#x} -> {:#x} (esperado {:#x})",
            pessoa, clube, tinha, n0, n1, cpo9_i(this + 0x10), cpo9_i(this + 0x14), nib, cpo9_b(r), esperado)
    });
}

/// Comparador: pelo valor (o byte baixo) e lado a lado pelo sorteio e [0xae1080] (as chamadas de preço podem sortear).
unsafe extern "stdcall" fn comparar_prever_resposta_do_vendedor(vendedor: usize, jogador: usize, oferta: i64, comprador: usize, pedido: i64, emprestimo: u32) -> u8 {
    let o = orig::<unsafe extern "stdcall" fn(usize, usize, i64, usize, i64, u32) -> u8>(992);
    let mut reg = vec![(0xae1080usize, 4usize)];
    reg.extend(crate::aleatorio::REGIOES_DO_ESTADO);
    let (r, n, igual, mo, mr) = crate::comparacao::lado_a_lado_leve(
        &reg,
        || o(vendedor, jogador, oferta, comprador, pedido, emprestimo),
        || crate::aleatorio::sem_contar(|| prever_resposta_do_vendedor(vendedor, jogador, oferta, comprador, pedido, emprestimo)),
    );
    PLACAR.registrar(igual && r == n, || format!("prever_resposta_do_vendedor({:#x}, {:#x}, {}, {:#x}, {}, {}) original={} rust={} {:x?} x {:x?}", vendedor, jogador, oferta, comprador, pedido, emprestimo as u8, r, n, mo, mr));
    r
}

/// Comparador: lado a lado pelas quatro saídas, o sorteio e [0xae1080].
unsafe extern "thiscall" fn comparar_periodo_do_emprestimo(this: usize, clube: usize, a2: u32, jogador: usize, ini_mes: *mut i8, ini_ano: *mut u16, mes: *mut i8, ano: *mut u16) {
    let o = orig::<unsafe extern "thiscall" fn(usize, usize, u32, usize, *mut i8, *mut u16, *mut i8, *mut u16)>(993);
    let mut reg = vec![(ini_mes as usize, 1usize), (ini_ano as usize, 2), (mes as usize, 1), (ano as usize, 2), (0xae1080, 4)];
    reg.extend(crate::aleatorio::REGIOES_DO_ESTADO);
    let (_, _, igual, mo, mr) = crate::comparacao::lado_a_lado_leve(
        &reg,
        || o(this, clube, a2, jogador, ini_mes, ini_ano, mes, ano),
        || crate::aleatorio::sem_contar(|| periodo_do_emprestimo(this, clube, a2, jogador, ini_mes, ini_ano, mes, ano)),
    );
    PLACAR.registrar(igual, || format!("periodo_do_emprestimo({:#x}, {:#x}) {:x?} x {:x?}", clube, jogador, mo, mr));
}

// ---------- 251a leva: as transferências: o prazo da resposta à oferta, pagar as prestações do mês e tirar a oferta (transfer_manager.cpp) ----------

unsafe fn cpo10_d(a: usize) -> usize {
    core::ptr::read_unaligned(a as *const usize)
}

unsafe fn cpo10_i(a: usize) -> i32 {
    core::ptr::read_unaligned(a as *const i32)
}

unsafe fn cpo10_h(a: usize) -> i16 {
    core::ptr::read_unaligned(a as *const i16)
}

unsafe fn cpo10_b(a: usize) -> u8 {
    *(a as *const u8)
}

unsafe fn cpo10_w(a: usize, v: u32) {
    core::ptr::write_unaligned(a as *mut u32, v)
}

/// O registro de clube de id `id` ([0xae23b4], 0x245 bytes).
unsafe fn cpo10_clube(id: usize) -> usize {
    cpo10_d(0xae23b4).wrapping_add(id.wrapping_mul(0x245))
}

/// A pessoa de id `id` ([0xae23bc], 0x6e bytes).
unsafe fn cpo10_pessoa(id: usize) -> usize {
    cpo10_d(0xae23bc).wrapping_add(id.wrapping_mul(0x6e))
}

/// A regra de transferência da nação `nacao` entre as 28 de `this + 0x8ac` (a de +0xa igual), ou 0.
unsafe fn cpo10_regra(this: usize, nacao: usize) -> usize {
    for k in 0..0x1cusize {
        let r = cpo10_d(this + 0x8ac + k * 4);
        if cpo10_d(r + 0xa) == nacao {
            return r;
        }
    }
    0
}

/// { 0x8cc5b0 } (thiscall, ret 0xc, transfer_manager.cpp): `TRANSFER_MANAGER::get_offer_response_delay(oferta, dias,
/// fatias)`: o prazo é o de fechar a janela (0x8e8ed0) da nação do comprador (+8; sem regra: 365) e, com o +4 da oferta,
/// o menor com o da nação do clube do contrato do jogador (+0xc; contrato de tipo 5 não conta). Abaixo de 3: 0 dia e 1
/// fatia; abaixo de 6 ou de 11: 1 ou 2 dias e 1..3 fatias sorteadas. Senão o valor pelo estatuto do contrato com o clube
/// (+0x3d; sem ele −100): o jogador (0x53b620 do +0x11; sem ficha, a caixa "Error") de habilidade +7 da ficha acima de
/// 130 e da reputação do clube / 60, menos de 26 anos, em menos de 3 listas e estatuto positivo, com o interesse
/// (0x846920) acima de [0x968e58]: o prazo × [0x968e18] até [0x968dd8]; senão um sorteio até estatuto/10 + 12 (o maior
/// com 1..3). Dias = valor / 3, fatias = valor % 3.
unsafe extern "thiscall" fn prazo_da_resposta_a_oferta(this: usize, oferta: usize, dias: *mut u8, fatias: *mut u8) {
    let contrato_de: unsafe extern "thiscall" fn(usize, usize) -> usize = core::mem::transmute(0x4cf5a0usize);
    let com_clube: unsafe extern "thiscall" fn(usize, usize, usize) -> usize = core::mem::transmute(0x4cf5f0usize);
    let janela: unsafe extern "thiscall" fn(usize) -> u32 = core::mem::transmute(0x8e8ed0usize);
    let sortear: unsafe extern "C" fn(i32) -> i32 = core::mem::transmute(0x90cfc0usize);
    let comprador = cpo10_clube(cpo10_d(oferta + 8));
    let p = cpo10_pessoa(cpo10_d(oferta + 0xc));
    let c = contrato_de(cpo10_d(0xae1050), p);
    *(0xae1080 as *mut usize) = c;
    let dono = if c != 0 && cpo10_b(c + 0x35) & 0x3f != 5 { cpo10_clube(cpo10_d(c + 4)) } else { 0 };
    let k = com_clube(cpo10_d(0xae1050), p, dono);
    let mut prazo: u16 = 0x16d;
    let r = cpo10_regra(this, cpo10_d(comprador + 0x53));
    if r != 0 {
        prazo = janela(r) as u16;
    }
    if cpo10_d(oferta + 4) != 0 {
        let r = cpo10_regra(this, cpo10_d(dono + 0x53));
        if r != 0 && prazo >= janela(r) as u16 {
            prazo = janela(r) as u16;
        }
    }
    if prazo < 3 {
        *dias = 0;
        *fatias = 1;
        return;
    }
    if prazo < 0xb {
        *dias = if prazo < 6 { 1 } else { 2 };
        *fatias = (sortear(3) as u8).wrapping_add(1);
        return;
    }
    let estatuto: i8 = if k != 0 { cpo10_b(k + 0x3d) as i8 } else { -100 };
    // ponytail: a original empurra o cargo num registrador com lixo acima; a 0x53b620 só lê o byte
    let e_jogador: unsafe extern "C" fn(u32) -> u32 = core::mem::transmute(0x53b620usize);
    if e_jogador(cpo10_b(oferta + 0x11) as u32) != 0 && cpo10_d(p + 0x61) == 0 {
        aviso_em(0xa8d514, 0x29c3);
    }
    let mut valor: Option<u8> = None;
    if dono != 0 && e_jogador(cpo10_b(oferta + 0x11) as u32) != 0 {
        let hab = cpo10_h(cpo10_d(p + 0x61) + 7);
        if hab > 0x82
            && hab as i32 > cpo10_h(dono + 0x80) as i32 / 60
            && (cpo10_b(p + 0x18) as i8) < 0x1a
            && cpo10_b(cpo10_d(0xae2d0c).wrapping_add(cpo10_d(p).wrapping_mul(0x4f)) + 0xb) & 0xf < 3
            && estatuto > 0
        {
            let interesse: unsafe extern "thiscall" fn(usize, usize, usize, u32, u32, u32, u32) -> f64 = core::mem::transmute(0x846920usize);
            if interesse(cpo10_d(this + 0x856), p, comprador, 0, 0, 1, 0) > f64_em(0x968e58) {
                let x = prazo as i32 as f64 * f64_em(0x968e18);
                let teto = f64_em(0x968dd8);
                valor = Some(ftol(if teto < x || x.is_nan() { teto } else { x }) as u8);
            }
        }
    }
    let v = match valor {
        Some(v) => v,
        None => {
            crate::comparacao::ramo("cpo_10 prazo sorteado");
            let s = sortear(estatuto as i32 / 10 + 0xc) as i8;
            if sortear(3) + 1 > s as i32 {
                (sortear(3) as u8).wrapping_add(1)
            } else {
                s as u8
            }
        }
    } as i8 as i32;
    *dias = (v / 3) as u8;
    *fatias = (v % 3) as u8;
}

/// { 0x8caee0 } (thiscall, ret 0, transfer_manager.cpp): `TRANSFER_MANAGER::pay_transfer_instalments()`: no fim do mês,
/// cada prestação da lista (+0x872; 13 bytes: +0 o valor, +4 o clube que paga, +8 o que recebe, +0xc as que faltam) é
/// paga (0x599890 nas finanças do pagador, 0x599800 nas do recebedor, 0x5a0590) e conta uma a menos; faltando menos de
/// 4 ou de 8, a figura das prestações (+0x1c das finanças) recebe as frações ([0x968918]/[0x968f30] ou
/// [0x967880]/[0x969518]); acabada, sai da lista (0x68d1f0); senão os dois clubes ficam marcados (0x945501). Depois, em
/// cada clube com finanças, a figura zera: sem marca; positiva só pagando; negativa só recebendo.
unsafe extern "thiscall" fn pagar_prestacoes_das_transferencias(this: usize) {
    let calloc: unsafe extern "C" fn(u32, u32) -> usize = core::mem::transmute(0x945501usize);
    let livrar: unsafe extern "C" fn(usize) = core::mem::transmute(0x9452causize);
    let proximo: unsafe extern "thiscall" fn(usize) -> usize = core::mem::transmute(0x68d1b0usize);
    let financas: unsafe extern "thiscall" fn(usize, usize) -> usize = core::mem::transmute(0x5a0590usize);
    let pagar: unsafe extern "thiscall" fn(usize, i64) = core::mem::transmute(0x599890usize);
    let receber: unsafe extern "thiscall" fn(usize, i64) = core::mem::transmute(0x599800usize);
    let tirar: unsafe extern "thiscall" fn(usize, usize) -> u32 = core::mem::transmute(0x68d1f0usize);
    let recebe = calloc(cpo10_d(0xae235c) as u32, 1);
    let paga = calloc(cpo10_d(0xae235c) as u32, 1);
    let lista = this + 0x872;
    cpo10_w(lista + 0xa, cpo10_d(this + 0x874) as u32);
    loop {
        let e = proximo(lista);
        if e == 0 {
            break;
        }
        let fr = financas(cpo10_d(0xae2a38), cpo10_clube(cpo10_d(e + 8)));
        let fp = financas(cpo10_d(0xae2a38), cpo10_clube(cpo10_d(e + 4)));
        pagar(fp, cpo10_i(e) as i64);
        receber(fr, cpo10_i(e) as i64);
        let n = (cpo10_b(e + 0xc) as i8).wrapping_sub(1);
        *((e + 0xc) as *mut i8) = n;
        let fracoes = if n < 4 { Some((0x968918, 0x968f30)) } else if n < 8 { Some((0x967880, 0x969518)) } else { None };
        if let Some((a, b)) = fracoes {
            cpo10_w(fp + 0x1c, cpo10_i(fp + 0x1c).wrapping_add(ftol(cpo10_i(e) as f64 * f64_em(a))) as u32);
            cpo10_w(fr + 0x1c, cpo10_i(fr + 0x1c).wrapping_add(ftol(cpo10_i(e) as f64 * f64_em(b))) as u32);
        }
        if cpo10_b(e + 0xc) == 0 {
            crate::comparacao::ramo("cpo_10 prestacao acabada");
            tirar(lista, e);
        } else {
            *((recebe + cpo10_d(cpo10_clube(cpo10_d(e + 8)))) as *mut u8) = 1;
            *((paga + cpo10_d(cpo10_clube(cpo10_d(e + 4)))) as *mut u8) = 1;
        }
    }
    let mut i = 0usize;
    while (i as i32) < cpo10_i(0xae235c) {
        let f = financas(cpo10_d(0xae2a38), cpo10_d(0xae23b4).wrapping_add(i * 0x245));
        if f != 0 {
            let (r, p) = (cpo10_b(recebe + i) != 0, cpo10_b(paga + i) != 0);
            let v = cpo10_i(f + 0x1c);
            let zerar = match (r, p) {
                (false, false) => true,
                (false, true) => v > 0,
                (true, false) => v < 0,
                (true, true) => false,
            };
            if zerar {
                cpo10_w(f + 0x1c, 0);
            }
        }
        i += 1;
    }
    if recebe != 0 {
        livrar(recebe);
    }
    if paga != 0 {
        livrar(paga);
    }
}

/// { 0x8d0f60 } (thiscall, ret 4, transfer_manager.cpp): `TRANSFER_MANAGER::remove_offer(oferta)`: a oferta ligada
/// (+0x28 ≠ −1, em +0xc) é destruída (0x8e5710, 0x944c94), a vaga zera e a conta +0x14 baixa; com o +0x1f em 1, sai da
/// lista de empréstimos (+0x946) o par (clube +8, jogador +0xc); para cada jogador da troca (+4): a proposta de contrato
/// ligada à vaga +0x20 sai (0x4ccb30, se o jogador da oferta tem contrato) e o +2 do registro de 8 bytes dele (+0x86e)
/// baixa; sai a proposta de contrato do jogador com o comprador (0x4cca70), o +1 do registro do jogador baixa, a menor
/// vaga livre (+0x85e) acompanha, a vaga +0x20 do vetor (+0) zera, a oferta é destruída e a conta +8 baixa.
unsafe extern "thiscall" fn tirar_oferta_de_transferencia(this: usize, oferta: usize) {
    let destruir: unsafe extern "thiscall" fn(usize) = core::mem::transmute(0x8e5710usize);
    let apagar: unsafe extern "C" fn(usize) = core::mem::transmute(0x944c94usize);
    let proximo: unsafe extern "thiscall" fn(usize) -> usize = core::mem::transmute(0x68d1b0usize);
    crate::comparacao::ramo("cpo_10 tirar oferta");
    if cpo10_i(oferta + 0x28) != -1 {
        let x = cpo10_d(cpo10_d(this + 0xc).wrapping_add((cpo10_i(oferta + 0x28) as usize).wrapping_mul(4)));
        if x != 0 {
            destruir(x);
            apagar(x);
        }
        cpo10_w(cpo10_d(this + 0xc).wrapping_add((cpo10_i(oferta + 0x28) as usize).wrapping_mul(4)), 0);
        cpo10_w(this + 0x14, cpo10_i(this + 0x14).wrapping_sub(1) as u32);
    }
    if cpo10_b(oferta + 0x1f) == 1 && cpo10_d(this + 0x946) != 0 {
        let l = cpo10_d(this + 0x946);
        cpo10_w(l + 0xa, cpo10_d(l + 2) as u32);
        loop {
            let e = proximo(cpo10_d(this + 0x946));
            if e == 0 {
                break;
            }
            if cpo10_d(e + 4) == cpo10_d(oferta + 8) && cpo10_d(e) == cpo10_d(oferta + 0xc) {
                let tirar: unsafe extern "thiscall" fn(usize, usize) -> u32 = core::mem::transmute(0x68d1f0usize);
                tirar(cpo10_d(this + 0x946), e);
                break;
            }
        }
    }
    if cpo10_d(oferta + 4) != 0 {
        let contrato_de: unsafe extern "thiscall" fn(usize, usize) -> usize = core::mem::transmute(0x4cf5a0usize);
        let tirar_proposta: unsafe extern "thiscall" fn(usize, usize, i32) = core::mem::transmute(0x4ccb30usize);
        let l = cpo10_d(oferta + 4);
        cpo10_w(l + 0xa, cpo10_d(l + 2) as u32);
        loop {
            let e = proximo(cpo10_d(oferta + 4));
            if e == 0 {
                break;
            }
            let c = contrato_de(cpo10_d(0xae1050), cpo10_pessoa(cpo10_d(oferta + 0xc)));
            *(0xae1080 as *mut usize) = c;
            if c != 0 && cpo10_clube(cpo10_d(c + 4)) != 0 {
                tirar_proposta(cpo10_d(0xae1050), cpo10_pessoa(cpo10_d(e)), cpo10_i(oferta + 0x20));
            }
            let q = (cpo10_d(this + 0x86e).wrapping_add(cpo10_d(e).wrapping_mul(8)) + 2) as *mut u8;
            *q = (*q).wrapping_sub(1);
        }
    }
    let tirar_do_clube: unsafe extern "thiscall" fn(usize, usize, usize) = core::mem::transmute(0x4cca70usize);
    tirar_do_clube(cpo10_d(0xae1050), cpo10_pessoa(cpo10_d(oferta + 0xc)), cpo10_clube(cpo10_d(oferta + 8)));
    let q = (cpo10_d(this + 0x86e).wrapping_add(cpo10_d(oferta + 0xc).wrapping_mul(8)) + 1) as *mut u8;
    *q = (*q).wrapping_sub(1); // as ofertas pela pessoa
    if cpo10_i(oferta + 0x20) < cpo10_i(this + 0x85e) {
        cpo10_w(this + 0x85e, cpo10_d(oferta + 0x20) as u32);
    }
    cpo10_w(cpo10_d(this).wrapping_add((cpo10_i(oferta + 0x20) as usize).wrapping_mul(4)), 0);
    if oferta != 0 {
        destruir(oferta);
        apagar(oferta);
    }
    cpo10_w(this + 8, cpo10_i(this + 8).wrapping_sub(1) as u32);
}

/// Os dados dos nós de uma LLIST (+2 o primeiro nó; nó: +0 o dado, +6 o próximo).
unsafe fn cpo10_itens(lista: usize) -> Vec<usize> {
    let mut v = Vec::new();
    let mut no = cpo10_d(lista + 2);
    while no != 0 {
        v.push(cpo10_d(no));
        no = cpo10_d(no + 6);
    }
    v
}

/// Comparador: lado a lado pelas duas saídas, o sorteio, [0xae1080] e [0xb67a34] (a caixa da falta de ficha).
unsafe extern "thiscall" fn comparar_prazo_da_resposta_a_oferta(this: usize, oferta: usize, dias: *mut u8, fatias: *mut u8) {
    let o = orig::<unsafe extern "thiscall" fn(usize, usize, *mut u8, *mut u8)>(994);
    let mut reg = vec![(dias as usize, 1usize), (fatias as usize, 1), (0xae1080, 4), (0xb67a34, 4)];
    reg.extend(crate::aleatorio::REGIOES_DO_ESTADO);
    let (_, _, igual, mo, mr) = crate::comparacao::lado_a_lado_leve(
        &reg,
        || o(this, oferta, dias, fatias),
        || crate::aleatorio::sem_contar(|| prazo_da_resposta_a_oferta(this, oferta, dias, fatias)),
    );
    PLACAR.registrar(igual, || format!("prazo_da_resposta_a_oferta({:#x}) {:x?} x {:x?}", oferta, mo, mr));
}

/// Comparador: só a original, conferindo o plano (feito antes): saem da lista as prestações que tinham 1 a pagar.
// ponytail: a original paga (finanças), tira itens da lista (libera) e aloca as marcas; não roda duas vezes. A cópia
// tem os ramos e a prova é pela carreira.
unsafe extern "thiscall" fn comparar_pagar_prestacoes_das_transferencias(this: usize) {
    let lista = this + 0x872;
    let antes = cpo10_itens(lista);
    let acabam = antes.iter().filter(|&&e| cpo10_b(e + 0xc) == 1).count();
    orig::<unsafe extern "thiscall" fn(usize)>(995)(this);
    let depois = cpo10_itens(lista).len();
    PLACAR.registrar(depois + acabam == antes.len(), || format!("pagar_prestacoes_das_transferencias: {} prestações, {} acabando, {} depois", antes.len(), acabam, depois));
}

/// Comparador: só a original, conferindo o plano (feito antes): a vaga zerada, as contas +8 e +0x14, a menor vaga livre
/// e o +1 do registro do jogador.
// ponytail: a original destrói e libera a oferta e mexe nas listas; não roda duas vezes.
unsafe extern "thiscall" fn comparar_tirar_oferta_de_transferencia(this: usize, oferta: usize) {
    let vaga = cpo10_i(oferta + 0x20);
    let ligada = cpo10_i(oferta + 0x28) != -1;
    let (n8, n14, livre) = (cpo10_i(this + 8), cpo10_i(this + 0x14), cpo10_i(this + 0x85e));
    let q = cpo10_d(this + 0x86e).wrapping_add(cpo10_d(oferta + 0xc).wrapping_mul(8)) + 1;
    let ofertas = cpo10_b(q);
    orig::<unsafe extern "thiscall" fn(usize, usize)>(996)(this, oferta);
    let ok = cpo10_d(cpo10_d(this).wrapping_add((vaga as usize).wrapping_mul(4))) == 0
        && cpo10_i(this + 8) == n8 - 1
        && cpo10_i(this + 0x14) == n14 - ligada as i32
        && cpo10_i(this + 0x85e) == livre.min(vaga)
        && cpo10_b(q) == ofertas.wrapping_sub(1);
    PLACAR.registrar(ok, || format!("tirar_oferta_de_transferencia: vaga {} contas {}/{} -> {}/{} livre {} -> {} ofertas {} -> {}",
        vaga, n8, n14, cpo10_i(this + 8), cpo10_i(this + 0x14), livre, cpo10_i(this + 0x85e), ofertas, cpo10_b(q)));
}

// ---------- 251a leva: as suspensões na troca de clube: acrescentar a suspensão, soltar as vagas que não valem no clube novo e devolver as suspensões guardadas no fim do empréstimo (discipline.cpp) ----------

unsafe fn cpo11_d(a: usize) -> usize {
    core::ptr::read_unaligned(a as *const u32) as usize
}

unsafe fn cpo11_w(a: usize) -> i16 {
    core::ptr::read_unaligned(a as *const i16)
}

unsafe fn cpo11_por(a: usize, v: u32) {
    core::ptr::write_unaligned(a as *mut u32, v);
}

unsafe fn cpo11_por_w(a: usize, v: u16) {
    core::ptr::write_unaligned(a as *mut u16, v);
}

/// O órgão disciplinar da regra `regra` (byte com sinal): [[this] + 4 × regra].
unsafe fn cpo11_orgao(this: usize, regra: u8) -> usize {
    cpo11_d(cpo11_d(this).wrapping_add((regra as i8 as isize as usize).wrapping_mul(4)))
}

/// A entrada (14 bytes; +0 livre = −1, +6 o índice da suspensão, −1 sem) da pessoa no órgão: 0x7e82e0 sem criar
/// (só lê: acha pela vaga da pessoa no registro de 29 bytes, 0x55cae0).
unsafe fn cpo11_entrada(orgao: usize, id: u32) -> usize {
    let achar: unsafe extern "thiscall" fn(usize, u32, u32) -> usize = core::mem::transmute(0x7e82e0usize);
    achar(orgao, id, 0)
}

/// O registro de 29 bytes da pessoa `id` em [this+0x14] (4 vagas de 5 bytes: a regra e o índice da entrada; +0x14/+0x18
/// o histórico; +0x1c quantas suspensões guardadas).
unsafe fn cpo11_registro(this: usize, id: u32) -> usize {
    cpo11_d(this + 0x14).wrapping_add((id as usize).wrapping_mul(29))
}

/// O órgão vale para o clube? Com nação (+0x17 ≠ −1): a nação do clube (+0x53) é ela; sem nação, com continente
/// (+0x1b ≠ −1): o continente da nação do clube (+0x71) é ele; sem os dois, vale sempre. Clube nulo ou sem nação: não.
unsafe fn cpo11_cobre(orgao: usize, clube: usize) -> bool {
    let nacao = cpo11_d(orgao + 0x17) as u32;
    if nacao == 0xffff_ffff {
        let continente = cpo11_d(orgao + 0x1b) as u32;
        if continente == 0xffff_ffff {
            return true;
        }
        if clube == 0 || cpo11_d(clube + 0x53) == 0 {
            return false;
        }
        let c = cpo11_d(cpo11_d(clube + 0x53) + 0x71);
        return c != 0 && cpo11_d(c) as u32 == continente;
    }
    clube != 0 && cpo11_d(clube + 0x53) != 0 && cpo11_d(cpo11_d(clube + 0x53)) as u32 == nacao
}

/// Solta a suspensão da entrada (se tem: +6 > −1) e libera a vaga `k` do registro da pessoa (regra 0xff, índice −1) e a
/// entrada (+0 = −1). O índice vai no ax; o alto do eax é o do ponteiro da entrada (a 0x556d00 só lê a palavra).
unsafe fn cpo11_liberar(this: usize, id: u32, e: usize) {
    let i = cpo11_w(e + 6);
    if i > -1 {
        let soltar: unsafe extern "thiscall" fn(usize, u32, u32) -> usize = core::mem::transmute(0x556d00usize);
        soltar(this, id, (e as u32 & 0xffff_0000) | i as u16 as u32);
    }
}

unsafe fn cpo11_limpar_vaga(this: usize, id: u32, k: usize, e: usize) {
    let v = cpo11_registro(this, id).wrapping_add(k * 5);
    *(v as *mut u8) = 0xff;
    cpo11_por(v + 1, 0xffff_ffff);
    cpo11_por(e, 0xffff_ffff);
}

/// { 0x556940 } (thiscall, ret 8, discipline.cpp): `Discipline::add_ban(id, suspensao)`: se alguma das 4 regras da
/// suspensão nova (+0xc..+0xf) já tem suspensão da pessoa (a entrada do órgão com +6 > −1), estende a velha (jogos +0
/// somados, ou, com algum dos dois por dias (0xff), os dias +2) e marca as duas (+0x13 bit 0); senão (o bit 0 da nova
/// limpo a cada regra sem suspensão) copia a nova (0x556c70) na primeira vaga livre do vetor (+0 = 0xff e +2 = −1), ou
/// no fim (conta +0xa, capacidade +8; cresce 100, até 0x7d00, malloc/realloc, as vagas novas livres), liga cada regra
/// ao índice (0x7e8510) e, com a quarta regra, põe {id, nação} no índice das nações (+0xc, capacidade +0x10, conta
/// +0x12; cresce 20; qsort 0x55e5f0). Caixas "Error" (capacidade no máximo, sem memória) pela aviso_em.
unsafe extern "thiscall" fn acrescentar_suspensao(this: usize, id: u32, ban: usize) {
    for k in 0..4usize {
        let regra = *((ban + 0xc + k) as *const u8);
        if regra == 0xff {
            continue;
        }
        let e = cpo11_entrada(cpo11_orgao(this, regra), id);
        if e != 0 && cpo11_w(e + 6) > -1 {
            crate::comparacao::ramo("cpo_11 suspensao estendida");
            let s = cpo11_d(this + 4).wrapping_add((cpo11_w(e + 6) as i32 as usize).wrapping_mul(20));
            let jogos = *(s as *const u8);
            let novos = *(ban as *const u8);
            if jogos != 0xff && novos != 0xff {
                *(s as *mut u8) = novos.wrapping_add(jogos);
            } else {
                cpo11_por_w(s + 2, (cpo11_w(s + 2) as u16).wrapping_add(cpo11_w(ban + 2) as u16));
            }
            *((ban + 0x13) as *mut u8) |= 1;
            *((s + 0x13) as *mut u8) |= 1;
            return;
        }
        *((ban + 0x13) as *mut u8) &= 0xfe;
    }
    let copiar: unsafe extern "thiscall" fn(usize, usize) -> usize = core::mem::transmute(0x556c70usize);
    let n = cpo11_w(this + 0xa);
    let mut vaga: i16 = -1;
    for i in 0..n.max(0) {
        let s = cpo11_d(this + 4).wrapping_add(i as usize * 20);
        if *(s as *const u8) == 0xff && cpo11_w(s + 2) == -1 {
            vaga = i;
            copiar(s, ban);
            break;
        }
    }
    if vaga == -1 {
        let conta = cpo11_w(this + 0xa);
        let cap = cpo11_w(this + 8);
        if conta < cap {
            cpo11_por_w(this + 0xa, conta.wrapping_add(1) as u16);
            copiar(cpo11_d(this + 4).wrapping_add((conta as i32 as usize).wrapping_mul(20)), ban);
            vaga = cpo11_w(this + 0xa).wrapping_sub(1);
        } else {
            if cap >= 0x7d00 {
                aviso_em(0x9b8f18, 0x401);
                return;
            }
            let nova = cap.wrapping_add(100);
            cpo11_por_w(this + 8, nova as u16);
            let tamanho = (nova as i32 as u32).wrapping_mul(20);
            let p = if cpo11_d(this + 4) == 0 {
                let malloc: unsafe extern "C" fn(u32) -> usize = core::mem::transmute(0x944e46usize);
                malloc(tamanho)
            } else {
                let realloc: unsafe extern "C" fn(usize, u32) -> usize = core::mem::transmute(0x945667usize);
                realloc(cpo11_d(this + 4), tamanho)
            };
            cpo11_por(this + 4, p as u32);
            if p == 0 {
                aviso_em(0x9b8f18, 0x410);
                return;
            }
            vaga = cpo11_w(this + 0xa);
            cpo11_por_w(this + 0xa, vaga.wrapping_add(1) as u16);
            copiar(p.wrapping_add((vaga as i32 as usize).wrapping_mul(20)), ban);
            let mut i = cpo11_w(this + 0xa);
            while i < cpo11_w(this + 8) {
                let s = cpo11_d(this + 4).wrapping_add((i as i32 as usize).wrapping_mul(20));
                *(s as *mut u8) = 0xff;
                cpo11_por_w(s + 2, 0xffff);
                i = i.wrapping_add(1);
            }
        }
    }
    crate::comparacao::ramo("cpo_11 suspensao nova");
    let ligar: unsafe extern "thiscall" fn(usize, u32, u32) = core::mem::transmute(0x7e8510usize);
    for k in 0..4usize {
        let regra = *((ban + 0xc + k) as *const u8);
        if regra != 0xff {
            ligar(cpo11_orgao(this, regra), id, vaga as u16 as u32); // liga a regra à suspensão
        }
    }
    if *((ban + 0xf) as *const u8) == 0xff {
        return;
    }
    let cap = cpo11_w(this + 0x10);
    if cap == cpo11_w(this + 0x12) {
        let nova = cap.wrapping_add(0x14);
        cpo11_por_w(this + 0x10, nova as u16);
        let realloc: unsafe extern "C" fn(usize, u32) -> usize = core::mem::transmute(0x945667usize);
        let p = realloc(cpo11_d(this + 0xc), (nova as i32 as u32).wrapping_mul(8));
        cpo11_por(this + 0xc, p as u32);
        if p == 0 {
            aviso_em(0x9b8f18, 0x43e);
            return;
        }
    }
    let n = cpo11_w(this + 0x12);
    let item = cpo11_d(this + 0xc).wrapping_add((n as i32 as usize).wrapping_mul(8));
    cpo11_por(item, id);
    let pessoa = cpo11_d(0xae23bc).wrapping_add((id as usize).wrapping_mul(0x6e));
    cpo11_por(item + 4, cpo11_d(cpo11_d(pessoa + 0x1a)) as u32); // a nação
    cpo11_por_w(this + 0x12, n.wrapping_add(1) as u16);
    let qsort: unsafe extern "C" fn(usize, i32, u32, usize) = core::mem::transmute(0x945333usize);
    qsort(cpo11_d(this + 0xc), cpo11_w(this + 0x12) as i32, 8, 0x55e5f0);
}

/// { 0x556270 } (thiscall, ret 0xc, discipline.cpp): `Discipline::clear_bans_invalid_for_club(pessoa, _, clube)`: cada
/// vaga ocupada das 4 do registro da pessoa cujo órgão não vale para o clube novo (`cpo11_cobre`) é liberada: a
/// suspensão solta (0x556d00), a vaga livre e a entrada do órgão livre. Com suspensões guardadas (+0x1c ≠ 0), a caixa
/// "Error" antes (e segue). Da troca de clube (0x8c9720).
unsafe extern "thiscall" fn tirar_suspensoes_de_fora_do_clube(this: usize, pessoa: usize, _nada: u32, clube: usize) {
    let id = cpo11_d(pessoa) as u32;
    let r = cpo11_registro(this, id);
    for k in 0..4usize {
        let regra = *((r + k * 5) as *const u8);
        if regra == 0xff {
            continue;
        }
        let orgao = cpo11_orgao(this, regra);
        if cpo11_cobre(orgao, clube) {
            continue;
        }
        let e = cpo11_entrada(orgao, id);
        if e == 0 {
            continue;
        }
        crate::comparacao::ramo("cpo_11 transferido solta a vaga");
        cpo11_liberar(this, id, e);
        if *((r + 0x1c) as *const u8) != 0 {
            aviso_em(0x9b8f18, 0x239);
        }
        cpo11_limpar_vaga(this, id, k, e);
    }
}

/// O que a 0x556570 vai fazer, lido antes (a lista das guardadas perde e libera os itens): o contrato e o clube, os
/// itens guardados da pessoa (a vaga e os 5 bytes) e, depois deles, as vagas 0..2 não devolvidas que o clube não cobre.
struct Cpo11Devolver {
    contrato: usize,
    clube: usize,
    guardadas: Vec<(usize, [u8; 5])>,
    resto: u8,
    soltas: Vec<(usize, usize)>,
}

/// O plano da 0x556570 (o cursor da lista é zerado pela original na entrada; a busca sem criar só lê).
unsafe fn cpo11_plano_devolver(this: usize, pessoa: usize) -> Cpo11Devolver {
    let id = cpo11_d(pessoa) as u32;
    let r = cpo11_registro(this, id);
    let contrato_de: unsafe extern "thiscall" fn(usize, usize) -> usize = core::mem::transmute(0x4cf5a0usize);
    let contrato = contrato_de(cpo11_d(0xae1050), pessoa);
    let clube = if contrato == 0 { 0 } else { cpo11_d(0xae23b4).wrapping_add(cpo11_d(contrato + 4).wrapping_mul(0x245)) };
    let mut p = Cpo11Devolver { contrato, clube, guardadas: Vec::new(), resto: *((r + 0x1c) as *const u8), soltas: Vec::new() };
    let lista = this + 0x1c;
    cpo11_por(lista + 0xa, cpo11_d(this + 0x1e) as u32);
    let proximo: unsafe extern "thiscall" fn(usize) -> usize = core::mem::transmute(0x68d1b0usize);
    let mut vagas = [0u8; 20];
    core::ptr::copy_nonoverlapping(r as *const u8, vagas.as_mut_ptr(), 20);
    let mut marcas = [false; 4];
    let mut item = proximo(lista);
    while item != 0 && (p.resto as i8) > 0 {
        if cpo11_d(item) as u32 == id {
            let k = (*((item + 4) as *const u8) as i8 as isize as usize) & 3;
            let mut b = [0u8; 5];
            core::ptr::copy_nonoverlapping((item + 5) as *const u8, b.as_mut_ptr(), 5);
            vagas[k * 5..k * 5 + 5].copy_from_slice(&b);
            marcas[k] = true;
            p.guardadas.push((k, b));
            p.resto = p.resto.wrapping_sub(1);
        }
        item = proximo(lista);
    }
    for k in 0..3usize {
        if marcas[k] || vagas[k * 5] == 0xff {
            continue;
        }
        let orgao = cpo11_orgao(this, vagas[k * 5]);
        if !cpo11_cobre(orgao, clube) {
            let e = cpo11_entrada(orgao, id);
            if e != 0 {
                p.soltas.push((k, e));
            }
        }
    }
    p
}

/// { 0x556570 } (thiscall, ret 4, discipline.cpp): `Discipline::restore_held_bans(pessoa)`: no fim do empréstimo
/// (0x4d07e0): o contrato (0x4cf5a0, guardado em [0xae1080]) dá o clube; cada suspensão guardada da pessoa na lista
/// [this+0x1c] (id, vaga +4, os 5 bytes +5), enquanto houver guardadas (+0x1c do registro, com sinal): a vaga ocupada é
/// liberada antes (a suspensão solta, 0x556d00), a guardada volta para a vaga, sai da lista (0x68d1f0, que a libera) e a
/// conta cai. Depois, as vagas 0..2 não devolvidas (a quarta nunca: `k != 3` da original) cujo órgão não vale para o
/// clube são liberadas.
unsafe extern "thiscall" fn restaurar_suspensoes_guardadas(this: usize, pessoa: usize) {
    let id = cpo11_d(pessoa) as u32;
    let r = cpo11_registro(this, id);
    let contrato_de: unsafe extern "thiscall" fn(usize, usize) -> usize = core::mem::transmute(0x4cf5a0usize);
    let contrato = contrato_de(cpo11_d(0xae1050), pessoa);
    cpo11_por(0xae1080, contrato as u32);
    let clube = if contrato == 0 { 0 } else { cpo11_d(0xae23b4).wrapping_add(cpo11_d(contrato + 4).wrapping_mul(0x245)) };
    let lista = this + 0x1c;
    cpo11_por(lista + 0xa, cpo11_d(this + 0x1e) as u32);
    let proximo: unsafe extern "thiscall" fn(usize) -> usize = core::mem::transmute(0x68d1b0usize);
    let remover: unsafe extern "thiscall" fn(usize, usize) -> u32 = core::mem::transmute(0x68d1f0usize);
    let mut marcas = [0u32; 4];
    let mut item = proximo(lista);
    while item != 0 && *((r + 0x1c) as *const i8) > 0 {
        if cpo11_d(item) as u32 == id {
            let k = *((item + 4) as *const u8) as i8 as isize as usize;
            let regra = *(r.wrapping_add(k.wrapping_mul(5)) as *const u8);
            if regra != 0xff {
                let e = cpo11_entrada(cpo11_orgao(this, regra), id);
                if e != 0 {
                    cpo11_liberar(this, id, e);
                    cpo11_limpar_vaga(this, id, k, e);
                }
            }
            crate::comparacao::ramo("cpo_11 guardada devolvida");
            marcas[k & 3] = 1;
            let v = r.wrapping_add(k.wrapping_mul(5));
            cpo11_por(v, cpo11_d(item + 5) as u32);
            *((v + 4) as *mut u8) = *((item + 9) as *const u8);
            remover(lista, item); // libera o item
            *((r + 0x1c) as *mut u8) = (*((r + 0x1c) as *const u8)).wrapping_sub(1);
        }
        item = proximo(lista);
    }
    for k in 0..4usize {
        let regra = *((r + k * 5) as *const u8);
        if marcas[k] != 0 || k == 3 || regra == 0xff {
            continue;
        }
        let orgao = cpo11_orgao(this, regra);
        if cpo11_cobre(orgao, clube) {
            continue;
        }
        let e = cpo11_entrada(orgao, id);
        if e != 0 {
            crate::comparacao::ramo("cpo_11 fim do emprestimo solta a vaga");
            cpo11_liberar(this, id, e);
            cpo11_limpar_vaga(this, id, k, e);
        }
    }
}

/// O caminho da 0x556940, lido antes: a suspensão velha estendida (e os valores novos dela), ou a vaga da nova e a
/// conta do vetor depois; `None` nas caixas (capacidade no máximo).
enum Cpo11Plano {
    Estender { s: usize, jogos: u8, dias: i16 },
    Nova { vaga: i16, conta: i16 },
    Caixa,
}

unsafe fn cpo11_plano_suspensao(this: usize, id: u32, ban: usize) -> Cpo11Plano {
    for k in 0..4usize {
        let regra = *((ban + 0xc + k) as *const u8);
        if regra == 0xff {
            continue;
        }
        let e = cpo11_entrada(cpo11_orgao(this, regra), id);
        if e != 0 && cpo11_w(e + 6) > -1 {
            let s = cpo11_d(this + 4).wrapping_add((cpo11_w(e + 6) as i32 as usize).wrapping_mul(20));
            let (jogos, novos) = (*(s as *const u8), *(ban as *const u8));
            return if jogos != 0xff && novos != 0xff {
                Cpo11Plano::Estender { s, jogos: novos.wrapping_add(jogos), dias: cpo11_w(s + 2) }
            } else {
                Cpo11Plano::Estender { s, jogos, dias: cpo11_w(s + 2).wrapping_add(cpo11_w(ban + 2)) }
            };
        }
    }
    let n = cpo11_w(this + 0xa);
    for i in 0..n.max(0) {
        let s = cpo11_d(this + 4).wrapping_add(i as usize * 20);
        if *(s as *const u8) == 0xff && cpo11_w(s + 2) == -1 {
            return Cpo11Plano::Nova { vaga: i, conta: n };
        }
    }
    if n < cpo11_w(this + 8) || cpo11_w(this + 8) < 0x7d00 {
        return Cpo11Plano::Nova { vaga: n, conta: n.wrapping_add(1) };
    }
    Cpo11Plano::Caixa
}

/// Comparador: a 0x556940 realoca os vetores e liga os órgãos (não pode rodar duas vezes): o plano antes, a original
/// roda; confere a velha estendida (jogos, dias, bit 0 das duas), ou a nova na vaga (jogos, dias, as 4 regras), a
/// conta, as entradas das regras apontando para a vaga e, com a quarta regra, o índice das nações com um a mais.
unsafe extern "thiscall" fn comparar_acrescentar_suspensao(this: usize, id: u32, ban: usize) {
    let plano = cpo11_plano_suspensao(this, id, ban);
    let indice = cpo11_w(this + 0x12);
    let mut regras = [0u8; 4];
    core::ptr::copy_nonoverlapping((ban + 0xc) as *const u8, regras.as_mut_ptr(), 4);
    orig::<unsafe extern "thiscall" fn(usize, u32, usize)>(997)(this, id, ban);
    let (ok, detalhe) = match plano {
        Cpo11Plano::Caixa => return,
        Cpo11Plano::Estender { s, jogos, dias } => {
            let ok = *(s as *const u8) == jogos && cpo11_w(s + 2) == dias && *((s + 0x13) as *const u8) & 1 == 1
                && *((ban + 0x13) as *const u8) & 1 == 1;
            (ok, format!("estender: jogos {} (esperava {}), dias {} (esperava {})", *(s as *const u8), jogos, cpo11_w(s + 2), dias))
        }
        Cpo11Plano::Nova { vaga, conta } => {
            let s = cpo11_d(this + 4).wrapping_add((vaga as i32 as usize).wrapping_mul(20));
            let mut ok = cpo11_w(this + 0xa) == conta && *(s as *const u8) == *(ban as *const u8) && cpo11_w(s + 2) == cpo11_w(ban + 2);
            for k in 0..4usize {
                ok &= *((s + 0xc + k) as *const u8) == regras[k];
                if regras[k] != 0xff {
                    let e = cpo11_entrada(cpo11_orgao(this, regras[k]), id);
                    ok &= e != 0 && cpo11_w(e + 6) == vaga;
                }
            }
            if regras[3] != 0xff {
                ok &= cpo11_w(this + 0x12) == indice.wrapping_add(1);
            }
            (ok, format!("nova: vaga {} conta {} (esperava {}), índice {} (antes {})", vaga, cpo11_w(this + 0xa), conta, cpo11_w(this + 0x12), indice))
        }
    };
    PLACAR.registrar(ok, || format!("acrescentar_suspensao({}) {}", id, detalhe));
}

/// Comparador: a 0x556270 solta suspensões (índice das nações, órgãos): o plano antes (as vagas que o clube não cobre
/// e as entradas), a original roda; confere as vagas liberadas (0xff, −1, a entrada −1) e as outras intactas. Uma
/// entrada repetida em duas vagas não entra na conferência da segunda.
unsafe extern "thiscall" fn comparar_tirar_suspensoes_de_fora_do_clube(this: usize, pessoa: usize, nada: u32, clube: usize) {
    let id = cpo11_d(pessoa) as u32;
    let r = cpo11_registro(this, id);
    let mut antes = [0u8; 29];
    core::ptr::copy_nonoverlapping(r as *const u8, antes.as_mut_ptr(), 29);
    let mut plano: [Option<usize>; 4] = [None; 4];
    let mut duvida = [false; 4];
    for k in 0..4usize {
        let regra = antes[k * 5];
        if regra == 0xff {
            continue;
        }
        let orgao = cpo11_orgao(this, regra);
        if !cpo11_cobre(orgao, clube) {
            let e = cpo11_entrada(orgao, id);
            if e != 0 {
                duvida[k] = plano[..k].iter().any(|x| *x == Some(e));
                plano[k] = Some(e);
            }
        }
    }
    orig::<unsafe extern "thiscall" fn(usize, usize, u32, usize)>(998)(this, pessoa, nada, clube);
    let mut depois = [0u8; 29];
    core::ptr::copy_nonoverlapping(r as *const u8, depois.as_mut_ptr(), 29);
    let mut ok = depois[20..] == antes[20..];
    for k in 0..4usize {
        if duvida[k] {
            continue;
        }
        let v = &depois[k * 5..k * 5 + 5];
        ok &= match plano[k] {
            Some(e) => v == [0xff; 5] && cpo11_d(e) as u32 == 0xffff_ffff,
            None => *v == antes[k * 5..k * 5 + 5],
        };
    }
    PLACAR.registrar(ok, || format!("tirar_suspensoes_de_fora_do_clube({}) plano {:x?} antes {:02x?} depois {:02x?}", id, plano, antes, depois));
}

/// Comparador: a 0x556570 tira e libera itens da lista (lição 1: o esperado é montado ANTES; nenhum item é lido depois)
/// e solta suspensões: o plano antes, a original roda; confere [0xae1080], as vagas devolvidas (os 5 bytes guardados), as
/// soltas (0xff, −1, a entrada −1), a conta de guardadas e as outras vagas intactas.
unsafe extern "thiscall" fn comparar_restaurar_suspensoes_guardadas(this: usize, pessoa: usize) {
    let id = cpo11_d(pessoa) as u32;
    let r = cpo11_registro(this, id);
    let p = cpo11_plano_devolver(this, pessoa);
    let mut antes = [0u8; 29];
    core::ptr::copy_nonoverlapping(r as *const u8, antes.as_mut_ptr(), 29);
    orig::<unsafe extern "thiscall" fn(usize, usize)>(999)(this, pessoa);
    let mut depois = [0u8; 29];
    core::ptr::copy_nonoverlapping(r as *const u8, depois.as_mut_ptr(), 29);
    let mut esperado = antes;
    for (k, b) in &p.guardadas {
        esperado[k * 5..k * 5 + 5].copy_from_slice(b);
    }
    let mut ok = cpo11_d(0xae1080) == p.contrato;
    for (k, e) in &p.soltas {
        esperado[k * 5..k * 5 + 5].copy_from_slice(&[0xff; 5]);
        ok &= cpo11_d(*e) as u32 == 0xffff_ffff;
    }
    esperado[0x1c] = p.resto;
    ok &= depois == esperado;
    PLACAR.registrar(ok, || format!("restaurar_suspensoes_guardadas({}) clube {:x} esperado {:02x?} depois {:02x?}", id, p.clube, esperado, depois));
}

// ---------- 251a leva: os idiomas do jogador (acrescentar e melhorar) e zerar as estatísticas do jogador regenerado (player_stats.cpp) ----------

unsafe fn cpo12_d(a: usize) -> usize {
    core::ptr::read_unaligned(a as *const u32) as usize
}

unsafe fn cpo12_por(a: usize, v: u32) {
    core::ptr::write_unaligned(a as *mut u32, v);
}

/// O registro de idioma (6 bytes: +0 id da pessoa, +4 idioma, +5 fluência) da `pessoa` no `idioma`: bsearch
/// (0x946464, comparação 0x7c6d40) na tabela [this+0x3c], [this+0x44] registros. 0 sem achar.
unsafe fn cpo12_idioma(this: usize, pessoa: usize, idioma: u8) -> usize {
    let bsearch: unsafe extern "C" fn(*const u8, usize, u32, u32, usize) -> usize = core::mem::transmute(0x946464usize);
    let mut chave = [0u8; 8];
    core::ptr::write_unaligned(chave.as_mut_ptr() as *mut u32, cpo12_d(pessoa) as u32);
    chave[4] = idioma; // a comparação só lê o byte +4 da chave
    bsearch(chave.as_ptr(), cpo12_d(this + 0x3c), cpo12_d(this + 0x44) as u32, 6, 0x7c6d40)
}

/// { 0x7c6a30 } (thiscall, ret 0x10, player_stats.cpp): `PlayerStats::add_language(pessoa, idioma, fluencia,
/// ordenar)`: a tabela dos idiomas (6 bytes por registro em [this+0x3c], capacidade +0x40, conta +0x44) nasce com 100
/// (malloc 0x258) e cresce 100 (realloc) quando cheia; o registro novo no fim: o id da pessoa, o idioma e a fluência
/// (no máximo 10, com sinal); com `ordenar`, qsort pela comparação 0x7c6d40. Sem memória: caixa fatal.
unsafe extern "thiscall" fn acrescentar_idioma(this: usize, pessoa: usize, idioma: u32, fluencia: u32, ordenar: u32) {
    if cpo12_d(this + 0x3c) == 0 {
        let malloc: unsafe extern "C" fn(u32) -> usize = core::mem::transmute(0x944e46usize);
        let p = malloc(0x258);
        cpo12_por(this + 0x3c, p as u32);
        if p == 0 {
            aviso_em(0xa78310, 0x11fd);
            erro_fatal();
        }
        cpo12_por(this + 0x40, 0x64);
    }
    let cap = cpo12_d(this + 0x40);
    if cap == cpo12_d(this + 0x44) {
        let realloc: unsafe extern "C" fn(usize, u32) -> usize = core::mem::transmute(0x945667usize);
        let p = realloc(cpo12_d(this + 0x3c), (cap as u32).wrapping_mul(3).wrapping_add(0x12c).wrapping_mul(2));
        cpo12_por(this + 0x3c, p as u32);
        if p == 0 {
            aviso_em(0xa78310, 0x1208);
            erro_fatal();
        }
        cpo12_por(this + 0x40, (cpo12_d(this + 0x40) as u32).wrapping_add(0x64));
    }
    crate::comparacao::ramo("cpo_12 idioma novo");
    let n = cpo12_d(this + 0x44);
    let r = cpo12_d(this + 0x3c).wrapping_add(n.wrapping_mul(6));
    cpo12_por(r, cpo12_d(pessoa) as u32);
    *((r + 4) as *mut u8) = idioma as u8;
    let f = fluencia as u8;
    *((r + 5) as *mut u8) = if (f as i8) > 10 { 10 } else { f };
    cpo12_por(this + 0x44, (n as u32).wrapping_add(1));
    if ordenar != 0 {
        crate::comparacao::ramo("cpo_12 idiomas ordenados");
        let qsort: unsafe extern "C" fn(usize, u32, u32, usize) = core::mem::transmute(0x945333usize);
        qsort(cpo12_d(this + 0x3c), cpo12_d(this + 0x44) as u32, 6, 0x7c6d40);
    }
}

/// { 0x7c6ca0 } (thiscall, ret 0x10, player_stats.cpp): `PlayerStats::improve_language(pessoa, idioma, aumento,
/// ordenar)`: sem tabela, ou sem o registro da pessoa no idioma (`cpo12_idioma`), acrescenta-o com a fluência
/// `aumento` (0x7c6a30); com ele, soma o aumento à fluência (byte), no máximo 10 (com sinal).
unsafe extern "thiscall" fn melhorar_idioma(this: usize, pessoa: usize, idioma: u32, aumento: u32, ordenar: u32) {
    let acrescentar: unsafe extern "thiscall" fn(usize, usize, u32, u32, u32) = core::mem::transmute(0x7c6a30usize);
    if cpo12_d(this + 0x3c) == 0 {
        acrescentar(this, pessoa, idioma, aumento, ordenar);
        return;
    }
    let r = cpo12_idioma(this, pessoa, idioma as u8);
    if r == 0 {
        acrescentar(this, pessoa, idioma, aumento, ordenar);
        return;
    }
    crate::comparacao::ramo("cpo_12 idioma melhorado");
    let f = (*((r + 5) as *const u8)).wrapping_add(aumento as u8);
    *((r + 5) as *mut u8) = f;
    if (f as i8) > 10 {
        *((r + 5) as *mut u8) = 10;
    }
}

/// { 0x7c6650 } (thiscall, ret 4, player_stats.cpp): `PlayerStats::reset_player(pessoa)`: no registro de 39 bytes da
/// pessoa ([this+0x30] + id × 39), cada uma das 6 categorias (+0..+0x14) com registro (≠ −1) o libera (+0xe = −1 no
/// registro de 32 bytes de [this+4]; +1 nos livres [this+0x38]) e fica −1; zera +0x20, +0x22 (palavras) e +0x24..+0x26
/// (as notas recentes) e esvazia o histórico (0x58f110 sobre [this] com +0x18/+0x1c). Pessoa nula ou não jogadora
/// (+0x61): a original (caixa fatal). Devolve o que a 0x58f110 devolve. Do regen (0x7a59e0).
unsafe extern "thiscall" fn zerar_estatisticas_do_jogador(this: usize, pessoa: usize) -> usize {
    if pessoa == 0 || cpo12_d(pessoa + 0x61) == 0 {
        return orig::<unsafe extern "thiscall" fn(usize, usize) -> usize>(1002)(this, pessoa); // caixa fatal: só a original
    }
    let r = cpo12_d(this + 0x30).wrapping_add(cpo12_d(pessoa).wrapping_mul(39));
    for k in 0..6usize {
        let i = cpo12_d(r + 4 * k);
        if i as u32 == 0xffff_ffff {
            continue;
        }
        core::ptr::write_unaligned((cpo12_d(this + 4).wrapping_add(i << 5) + 0xe) as *mut u16, 0xffff);
        cpo12_por(this + 0x38, (cpo12_d(this + 0x38) as u32).wrapping_add(1));
        cpo12_por(r + 4 * k, 0xffff_ffff);
    }
    core::ptr::write_unaligned((r + 0x20) as *mut u16, 0);
    core::ptr::write_unaligned((r + 0x22) as *mut u16, 0);
    *((r + 0x26) as *mut u8) = 0;
    *((r + 0x25) as *mut u8) = 0;
    *((r + 0x24) as *mut u8) = 0;
    let esvaziar: unsafe extern "thiscall" fn(usize, usize, usize) -> usize = core::mem::transmute(0x58f110usize);
    esvaziar(cpo12_d(this), r + 0x18, r + 0x1c)
}

/// Comparador: a 0x7c6a30 aloca e realoca a tabela (não pode rodar duas vezes): o plano antes (a conta e a
/// capacidade depois, a fluência), a original roda; confere a conta, a capacidade e o registro novo (no fim sem ordenar;
/// com `ordenar`, em algum lugar da tabela).
unsafe extern "thiscall" fn comparar_acrescentar_idioma(this: usize, pessoa: usize, idioma: u32, fluencia: u32, ordenar: u32) {
    let (n, cap) = if cpo12_d(this + 0x3c) == 0 { (cpo12_d(this + 0x44), 100) } else { (cpo12_d(this + 0x44), cpo12_d(this + 0x40)) };
    let cap = if cap == n { cap.wrapping_add(100) } else { cap };
    let f = fluencia as u8;
    let novo = (cpo12_d(pessoa) as u32, idioma as u8, if (f as i8) > 10 { 10 } else { f });
    orig::<unsafe extern "thiscall" fn(usize, usize, u32, u32, u32)>(1000)(this, pessoa, idioma, fluencia, ordenar);
    let base = cpo12_d(this + 0x3c);
    let e = |i: usize| {
        let r = base.wrapping_add(i * 6);
        (cpo12_d(r) as u32, *((r + 4) as *const u8), *((r + 5) as *const u8))
    };
    let conta = cpo12_d(this + 0x44);
    let mut ok = conta == n.wrapping_add(1) && cpo12_d(this + 0x40) == cap;
    if ok {
        ok = if ordenar == 0 { e(n) == novo } else { (0..conta).any(|i| e(i) == novo) };
    }
    PLACAR.registrar(ok, || format!("acrescentar_idioma({:?}, ordenar {}) conta {} (esperava {}) capacidade {} (esperava {})",
        novo, ordenar, conta, n.wrapping_add(1), cpo12_d(this + 0x40), cap));
}

/// Comparador: sem tabela ou sem o registro, só a original (o acréscimo 0x7c6a30 tem o comparador dele); com o
/// registro, lado a lado nos 6 bytes dele.
unsafe extern "thiscall" fn comparar_melhorar_idioma(this: usize, pessoa: usize, idioma: u32, aumento: u32, ordenar: u32) {
    let o = orig::<unsafe extern "thiscall" fn(usize, usize, u32, u32, u32)>(1001);
    let r = if cpo12_d(this + 0x3c) == 0 { 0 } else { cpo12_idioma(this, pessoa, idioma as u8) };
    if r == 0 {
        return o(this, pessoa, idioma, aumento, ordenar);
    }
    let (_, _, igual, mo, mr) = crate::comparacao::lado_a_lado_leve(&[(r, 6)],
        || o(this, pessoa, idioma, aumento, ordenar), || melhorar_idioma(this, pessoa, idioma, aumento, ordenar));
    PLACAR.registrar(igual, || format!("melhorar_idioma({}, idioma {}, +{}) {:x?} x {:x?}", cpo12_d(pessoa), idioma as u8, aumento as u8, mo, mr));
}

/// Comparador: lado a lado no registro de 39 bytes, na conta dos livres (+0x38) e na marca +0xe dos registros de
/// categoria liberados (a 0x58f110 só grava +0x1c, dentro do registro). Pessoa nula ou não jogadora: só a original.
unsafe extern "thiscall" fn comparar_zerar_estatisticas_do_jogador(this: usize, pessoa: usize) -> usize {
    let o = orig::<unsafe extern "thiscall" fn(usize, usize) -> usize>(1002);
    if pessoa == 0 || cpo12_d(pessoa + 0x61) == 0 {
        return o(this, pessoa);
    }
    let r = cpo12_d(this + 0x30).wrapping_add(cpo12_d(pessoa).wrapping_mul(39));
    let mut reg = vec![(r, 39), (this + 0x38, 4)];
    for k in 0..6usize {
        let i = cpo12_d(r + 4 * k);
        if i as u32 != 0xffff_ffff {
            reg.push((cpo12_d(this + 4).wrapping_add(i << 5) + 0xe, 2));
        }
    }
    let (a, b, igual, mo, mr) = crate::comparacao::lado_a_lado(&reg, || o(this, pessoa), || zerar_estatisticas_do_jogador(this, pessoa));
    PLACAR.registrar(igual && a == b, || format!("zerar_estatisticas_do_jogador({}) {:x?} x {:x?}", cpo12_d(pessoa), mo, mr));
    a
}

// ---------- 251a leva: as seleções: a competição atual da nação e os clubes com jogo na data; a disciplina: tirar o jogador regenerado (national_teams.cpp, discipline.cpp) ----------

unsafe fn cpo13_d(a: usize) -> usize {
    core::ptr::read_unaligned(a as *const u32) as usize
}

unsafe fn cpo13_por(a: usize, v: u32) {
    core::ptr::write_unaligned(a as *mut u32, v);
}

/// A competição (id) é uma das fases finais grandes ([0x9cf79c], [0x9cf7a0], [0x9cf7a4], [0x9cf7a8], [0x9cf7ac],
/// [0x9cf790], [0x9cf8a0], [0x9cf78c], [0x9cf964])?
unsafe fn cpo13_final(id: u32) -> bool {
    [0x9cf79c, 0x9cf7a0, 0x9cf7a4, 0x9cf7a8, 0x9cf7ac, 0x9cf790, 0x9cf8a0, 0x9cf78c, 0x9cf964usize]
        .iter()
        .any(|&g| cpo13_d(g) as u32 == id)
}

/// O que a 0x775220 grava: a competição atual da nação ([this+4] + id × 110 + 4), a da fila ([this+8] + id × 4) e se
/// avisa o gerenciador dos técnicos.
struct Cpo13Atual {
    vaga: usize,
    nova: Option<u32>,
    fila: usize,
    na_fila: Option<u32>,
    avisa: bool,
}

/// O plano da 0x775220 (só lê): com competição atual (≠ −1) que é fase final grande, a nova vai para a fila e a atual
/// fica (sem aviso); senão, se a nova é fase final grande e há atual, a atual vai para a fila; a nova vira a atual e o
/// gerenciador dos técnicos ([0xb67a44], se existe) é avisado.
unsafe fn cpo13_plano_atual(this: usize, nacao: usize, comp: usize) -> Cpo13Atual {
    let id = cpo13_d(nacao);
    let vaga = cpo13_d(this + 4).wrapping_add(id.wrapping_mul(110)) + 4;
    let fila = cpo13_d(this + 8).wrapping_add(id.wrapping_mul(4));
    let atual = cpo13_d(vaga) as u32;
    let nova = cpo13_d(comp) as u32;
    let mut p = Cpo13Atual { vaga, nova: Some(nova), fila, na_fila: None, avisa: cpo13_d(0xb67a44) != 0 };
    if atual != 0xffff_ffff {
        let r = cpo13_d(0xae23d0).wrapping_add((atual as usize).wrapping_mul(107)); // registros de 107 bytes
        if r != 0 && cpo13_final(cpo13_d(r) as u32) {
            return Cpo13Atual { vaga, nova: None, fila, na_fila: Some(nova), avisa: false };
        }
        if cpo13_final(nova) {
            p.na_fila = Some(atual);
        }
    }
    p
}

/// { 0x775220 } (thiscall, ret 8, national_teams.cpp): `NationalTeams::set_current_competition(nacao, comp)`: a
/// competição atual da nação vira `comp` (plano em `cpo13_plano_atual`: a fase final grande em curso fica na frente e a
/// outra vai para a fila) e o gerenciador dos técnicos é avisado (0x6a3770 com o clube da seleção principal, 0x53b3d0,
/// e 1). Nação ou competição nula: a caixa "Error" (e volta).
unsafe extern "thiscall" fn definir_competicao_da_selecao(this: usize, nacao: usize, comp: usize) {
    if nacao == 0 || comp == 0 {
        aviso_em(0xa5b2a4, 0x1bb2);
        return;
    }
    let p = cpo13_plano_atual(this, nacao, comp);
    if let Some(f) = p.na_fila {
        cpo13_por(p.fila, f);
    }
    let Some(nova) = p.nova else {
        crate::comparacao::ramo("cpo_13 fase final fica");
        return;
    };
    crate::comparacao::ramo("cpo_13 competicao atual");
    cpo13_por(p.vaga, nova);
    let g = cpo13_d(0xb67a44);
    if g != 0 {
        let principal: unsafe extern "C" fn(usize) -> usize = core::mem::transmute(0x53b3d0usize);
        let avisar: unsafe extern "thiscall" fn(usize, usize, u32) = core::mem::transmute(0x6a3770usize);
        avisar(g, principal(nacao), 1);
    }
}

/// Comparador: a 0x6a3770 (o aviso) não pode rodar duas vezes: o plano antes, a original roda; confere a competição
/// atual e a da fila. Nação ou competição nula: só a original (caixa).
unsafe extern "thiscall" fn comparar_definir_competicao_da_selecao(this: usize, nacao: usize, comp: usize) {
    let o = orig::<unsafe extern "thiscall" fn(usize, usize, usize)>(1003);
    if nacao == 0 || comp == 0 {
        return o(this, nacao, comp);
    }
    let p = cpo13_plano_atual(this, nacao, comp);
    let (atual, fila) = (cpo13_d(p.vaga) as u32, cpo13_d(p.fila) as u32);
    o(this, nacao, comp);
    let (atual2, fila2) = (cpo13_d(p.vaga) as u32, cpo13_d(p.fila) as u32);
    let ok = atual2 == p.nova.unwrap_or(atual) && fila2 == p.na_fila.unwrap_or(fila);
    PLACAR.registrar(ok, || format!("definir_competicao_da_selecao(nação {}, comp {}) atual {:#x} -> {:#x} (esperava {:x?}), fila {:#x} -> {:#x} (esperava {:x?})",
        cpo13_d(nacao), cpo13_d(comp), atual, atual2, p.nova, fila, fila2, p.na_fila));
}

/// Marca o clube `c` (se existe e o id < n) com o código na tabela [this+0x24].
unsafe fn cpo13_marcar(this: usize, c: usize, n: i32, codigo: u8) {
    if c != 0 && (cpo13_d(c) as i32) < n {
        *(cpo13_d(this + 0x24).wrapping_add(cpo13_d(c)) as *mut u8) = codigo;
    }
}

/// O clube tem nação marcada (+0x53, +0x11c ≠ 0)?
unsafe fn cpo13_nacao_marcada(c: usize) -> bool {
    let n = cpo13_d(c + 0x53);
    n != 0 && *((n + 0x11c) as *const u8) != 0
}

/// { 0x7775c0 } (thiscall, ret 4, national_teams.cpp): `NationalTeams::mark_clubs_with_fixtures(data)`: a tabela de um
/// byte por clube ([this+0x24], n = clubes [0xae235c] − 2 × nações [0xae2350]; calloc na primeira, sem memória a
/// caixa "Error") recebe, para cada jogo não amistoso (0x5c6710) da data nas 3 fatias (0x5ae6a0) de cada uma das 0x21
/// entradas de 0x48 bytes de 0xb63df0 (a nação +0 ativa em +0x11c, ou sem nação; o grupo +0x14): sem nação, 3 para os
/// clubes (+0x1c, +0x20) de nação ativa; com nação, 1 quando a competição do jogo (+0x14) é a da liga do mandante (+0x57)
/// ou a +0x60 do visitante, senão 2, para os dois. Lida pela remarcação dos jogos dos clubes com convocados (0x7777e0).
unsafe extern "thiscall" fn marcar_clubes_com_jogo(this: usize, data: usize) {
    let n = (cpo13_d(0xae235c) as i32).wrapping_sub((cpo13_d(0xae2350) as i32).wrapping_mul(2));
    if cpo13_d(this + 0x24) == 0 {
        let calloc: unsafe extern "C" fn(i32, u32) -> usize = core::mem::transmute(0x945501usize);
        let p = calloc(n, 1);
        cpo13_por(this + 0x24, p as u32);
        if p == 0 {
            aviso_em(0xa5b2a4, 0x2229);
            return;
        }
    }
    let lista_da_data: unsafe extern "stdcall" fn(usize, u32, u32) -> usize = core::mem::transmute(0x5ae6a0usize);
    let proximo: unsafe extern "thiscall" fn(usize) -> usize = core::mem::transmute(0x68d1b0usize);
    let amistoso: unsafe extern "thiscall" fn(usize, usize) -> u32 = core::mem::transmute(0x5c6710usize);
    for i in 0..0x21usize {
        let e = 0xb63df0 + i * 0x48;
        let nacao = cpo13_d(e);
        if nacao != 0 && *((nacao + 0x11c) as *const u8) == 0 {
            continue;
        }
        for fatia in 0..3u32 {
            // a original empurra a fatia num dword de pilha com o alto de lixo e o grupo no al: a 0x5abf10 só lê os bytes
            let lista = lista_da_data(data, fatia, *((e + 0x14) as *const u8) as u32);
            if lista == 0 {
                continue;
            }
            cpo13_por(lista + 0xa, cpo13_d(lista + 2) as u32);
            let mut jogo = proximo(lista);
            while jogo != 0 {
                if amistoso(cpo13_d(0xae2c74), cpo13_d(jogo + 0x14)) == 0 {
                    let (casa, fora) = (cpo13_d(jogo + 0x1c), cpo13_d(jogo + 0x20));
                    if cpo13_d(e) == 0 {
                        if casa != 0 && cpo13_nacao_marcada(casa) {
                            cpo13_marcar(this, casa, n, 3);
                        }
                        if fora != 0 && cpo13_nacao_marcada(fora) {
                            cpo13_marcar(this, fora, n, 3);
                        }
                    } else {
                        let comp = cpo13_d(jogo + 0x14);
                        // o visitante +0x60 é lido sem conferir o ponteiro (como a original)
                        let codigo = if casa != 0 && (cpo13_d(casa + 0x57) == comp || cpo13_d(fora + 0x60) == comp) { 1 } else { 2 };
                        crate::comparacao::ramo("cpo_13 clubes com jogo");
                        cpo13_marcar(this, casa, n, codigo); // o mandante
                        cpo13_marcar(this, fora, n, codigo); // o visitante
                    }
                }
                jogo = proximo(lista);
            }
        }
    }
}

/// Comparador: na primeira (sem tabela: calloc) só a original; depois, lado a lado na tabela (n bytes). A lista do
/// dia e o amistoso só leem (o cursor da lista volta ao começo a cada uso).
unsafe extern "thiscall" fn comparar_marcar_clubes_com_jogo(this: usize, data: usize) {
    let o = orig::<unsafe extern "thiscall" fn(usize, usize)>(1004);
    let n = (cpo13_d(0xae235c) as i32).wrapping_sub((cpo13_d(0xae2350) as i32).wrapping_mul(2));
    if cpo13_d(this + 0x24) == 0 || n <= 0 {
        return o(this, data);
    }
    let (_, _, igual, mo, mr) = crate::comparacao::lado_a_lado(&[(cpo13_d(this + 0x24), n as usize)], || o(this, data), || marcar_clubes_com_jogo(this, data));
    PLACAR.registrar(igual, || {
        let (a, b) = (&mo.0[0].1, &mr.0[0].1);
        let dif: Vec<(usize, u8, u8)> = (0..a.len()).filter(|&i| a[i] != b[i]).take(16).map(|i| (i, a[i], b[i])).collect();
        format!("marcar_clubes_com_jogo({:x}) clube, original, rust: {:?}", core::ptr::read_unaligned(data as *const u32), dif)
    });
}

/// O órgão disciplinar da regra `regra` (byte com sinal): [[this] + 4 × regra].
unsafe fn cpo13_orgao(this: usize, regra: u8) -> usize {
    cpo13_d(cpo13_d(this).wrapping_add((regra as i8 as isize as usize).wrapping_mul(4)))
}

/// A entrada da pessoa no órgão pela vaga dela (0x7e82e0 sem criar: só lê).
unsafe fn cpo13_entrada(orgao: usize, id: u32) -> usize {
    let achar: unsafe extern "thiscall" fn(usize, u32, u32) -> usize = core::mem::transmute(0x7e82e0usize);
    achar(orgao, id, 0)
}

/// { 0x556830 } (thiscall, ret 4, discipline.cpp): `Discipline::remove_player(id)`: do regen (0x7abac0): apaga o
/// histórico de suspensões (0x55e1d0), libera as 4 vagas do registro de 29 bytes (com entrada no órgão: a suspensão
/// solta, 0x556d00, a vaga livre e a entrada +0 = −1), tira da lista [this+0x1c] as suspensões guardadas dele
/// (0x68d1f0, enquanto a conta +0x1c > 0) e o registro fica 0xff com a conta 0.
unsafe extern "thiscall" fn tirar_jogador_da_disciplina(this: usize, id: u32) {
    let r = cpo13_d(this + 0x14).wrapping_add((id as usize).wrapping_mul(29));
    let apagar: unsafe extern "thiscall" fn(usize, usize) -> usize = core::mem::transmute(0x55e1d0usize);
    apagar(this, cpo13_d(0xae23bc).wrapping_add((id as usize).wrapping_mul(0x6e)));
    for k in 0..4usize {
        let regra = *((r + k * 5) as *const u8);
        if regra == 0xff {
            continue;
        }
        let e = cpo13_entrada(cpo13_orgao(this, regra), id);
        if e == 0 {
            continue;
        }
        crate::comparacao::ramo("cpo_13 regen solta a vaga");
        let i = core::ptr::read_unaligned((e + 6) as *const i16);
        if i > -1 {
            // o índice no ax; o alto do eax é o do ponteiro da entrada (a 0x556d00 só lê a palavra)
            let soltar: unsafe extern "thiscall" fn(usize, u32, u32) -> usize = core::mem::transmute(0x556d00usize);
            soltar(this, id, (e as u32 & 0xffff_0000) | i as u16 as u32);
        }
        let v = cpo13_d(this + 0x14).wrapping_add((id as usize).wrapping_mul(29) + k * 5);
        *(v as *mut u8) = 0xff;
        cpo13_por(v + 1, 0xffff_ffff);
        cpo13_por(e, 0xffff_ffff);
    }
    let lista = this + 0x1c;
    cpo13_por(lista + 0xa, cpo13_d(this + 0x1e) as u32);
    let proximo: unsafe extern "thiscall" fn(usize) -> usize = core::mem::transmute(0x68d1b0usize);
    let remover: unsafe extern "thiscall" fn(usize, usize) -> u32 = core::mem::transmute(0x68d1f0usize);
    let mut item = proximo(lista);
    while item != 0 && *((r + 0x1c) as *const i8) > 0 {
        if cpo13_d(item) as u32 == id {
            remover(lista, item); // libera o item
            *((r + 0x1c) as *mut u8) = (*((r + 0x1c) as *const u8)).wrapping_sub(1);
        }
        item = proximo(lista);
    }
    core::ptr::write_bytes(r as *mut u8, 0xff, 29);
    *((r + 0x1c) as *mut u8) = 0;
}

/// Comparador: a 0x556830 solta suspensões e tira (e libera) itens da lista: o plano antes (as entradas das vagas), a
/// original roda; confere o registro (0xff, conta 0) e as entradas livres (+0 = −1).
unsafe extern "thiscall" fn comparar_tirar_jogador_da_disciplina(this: usize, id: u32) {
    let r = cpo13_d(this + 0x14).wrapping_add((id as usize).wrapping_mul(29));
    let mut entradas = Vec::new();
    for k in 0..4usize {
        let regra = *((r + k * 5) as *const u8);
        if regra != 0xff {
            let e = cpo13_entrada(cpo13_orgao(this, regra), id);
            if e != 0 {
                entradas.push(e);
            }
        }
    }
    orig::<unsafe extern "thiscall" fn(usize, u32)>(1005)(this, id);
    let mut depois = [0u8; 29];
    core::ptr::copy_nonoverlapping(r as *const u8, depois.as_mut_ptr(), 29);
    let ok = depois[..0x1c].iter().all(|&b| b == 0xff) && depois[0x1c] == 0
        && entradas.iter().all(|&e| cpo13_d(e) as u32 == 0xffff_ffff);
    PLACAR.registrar(ok, || format!("tirar_jogador_da_disciplina({}) registro {:02x?} entradas {:x?}", id, depois, entradas));
}

// ---------- 250a leva: a entrega das notícias: pelo alcance, ao técnico do clube e na caixa do técnico humano (news.cpp) ----------

unsafe fn cpn1_d(a: usize) -> usize {
    core::ptr::read_unaligned(a as *const usize)
}

unsafe fn cpn1_i(a: usize) -> i32 {
    core::ptr::read_unaligned(a as *const i32)
}

unsafe fn cpn1_por(a: usize, v: usize) {
    core::ptr::write_unaligned(a as *mut usize, v);
}

/// A notícia guardada na caixa: 0xdf bytes (+4 importante, +0xd6 id, +0xda livre/lida, +0xde alcance).
const CPN1_NOTICIA: usize = 0xdf;

/// A entrada do técnico humano na tabela das caixas (News +8, 12 bytes: início do anel, a próxima vaga, a conta):
/// índice = id da pessoa − [0xae2364] + 16 (os humanos são as 16 últimas pessoas). Negativo: não é humano.
unsafe fn cpn1_indice_humano(tecnico: usize) -> i32 {
    cpn1_i(tecnico).wrapping_sub(cpn1_i(0xae2364)).wrapping_add(0x10)
}

/// { 0x786090 } (thiscall, ret 0x18, news.cpp): `News::send_by_scope(noticia, clube, competicao, nacao, continente,
/// alcance)`: o alcance (char) escolhe a entrega: 0 o técnico do clube (0x7861e0), 1 os da divisão (0x7862d0, pela
/// competição), 2 os do país (0x7863f0, pela nação), 3 os do continente (0x786640), 4 todos (0x786780), 5 os da região
/// da competição (0x786860). Fora disso, a caixa "Error" e 0. Devolve o que a entrega devolve.
unsafe extern "thiscall" fn noticia_pelo_alcance(this: usize, noticia: usize, clube: usize, competicao: usize, nacao: usize, continente: usize, alcance: u32) -> u32 {
    let dois: unsafe extern "thiscall" fn(usize, usize, usize) -> u32;
    let alvo = match alcance as u8 as i8 {
        0 => {
            crate::comparacao::ramo("cpn_1 alcance do clube");
            dois = core::mem::transmute(0x7861e0usize);
            clube // o técnico do clube
        }
        1 => {
            dois = core::mem::transmute(0x7862d0usize);
            competicao
        }
        2 => {
            dois = core::mem::transmute(0x7863f0usize);
            nacao
        }
        3 => {
            dois = core::mem::transmute(0x786640usize);
            continente
        }
        4 => {
            let todos: unsafe extern "thiscall" fn(usize, usize) -> u32 = core::mem::transmute(0x786780usize);
            return todos(this, noticia);
        }
        5 => {
            dois = core::mem::transmute(0x786860usize);
            competicao
        }
        _ => {
            aviso_em(0xa693ec, 0x1fd3);
            return 0;
        }
    };
    dois(this, noticia, alvo)
}

/// { 0x7861e0 } (thiscall, ret 8, news.cpp): `News::send_to_club_manager(noticia, clube)`: marca o alcance da notícia
/// como clube (+0xde = 0) e a entrega (0x785d40) ao técnico do clube (+0xcf) se ele for humano (id entre as 16 últimas
/// pessoas). Sem notícia ou sem clube: a caixa "Error" e 0; sem técnico ou técnico da máquina: 0.
unsafe extern "thiscall" fn noticia_ao_tecnico_do_clube(this: usize, noticia: usize, clube: usize) -> u32 {
    if noticia == 0 {
        aviso_em(0xa693ec, 0x2026);
        return 0;
    }
    if clube == 0 {
        aviso_em(0xa693ec, 0x202e);
        return 0;
    }
    let tecnico = cpn1_d(clube + 0xcf);
    *((noticia + 0xde) as *mut u8) = 0;
    if tecnico == 0 {
        return 0;
    }
    if cpn1_i(tecnico) < cpn1_i(0xae2364).wrapping_sub(0x10) { // a máquina
        return 0;
    }
    crate::comparacao::ramo("cpn_1 noticia ao tecnico humano");
    let entregar: unsafe extern "thiscall" fn(usize, usize, usize, u32) -> u32 = core::mem::transmute(0x785d40usize);
    entregar(this, noticia, tecnico, 0)
}

/// { 0x785d40 } (thiscall, ret 0xc, news.cpp): `News::deliver_to_manager(noticia, tecnico, _)`: grava se a notícia é
/// importante para ele (+4, 0x784eb0) e zera +0xda; acha a entrada do humano (News +8); na primeira notícia dele, o anel
/// de 100 vagas no fim do vetor das notícias (News +0, conta de vagas em +4, realloc 0x945667; sem memória, caixa e 0)
/// com as vagas zeradas (+0xd6 = 0, +0xda = 1). Notícia sem id (+0xd6) recebe o próximo (News +0x10). Se a vaga anterior
/// tem o mesmo id, não repete (devolve 1). Senão copia a notícia (0x786010) na próxima vaga (a vaga ainda não lida, +0xda
/// = 0, sai da conta), avança o anel e, com todos de férias ([0xdd6bec]) ou o técnico de férias (0x5fd210), dá a
/// resposta automática (0x784100) pelo clube (+0x39) e pela seleção (+0x24). Soma 1 na conta e devolve 1.
unsafe extern "thiscall" fn entregar_noticia_ao_tecnico(this: usize, noticia: usize, tecnico: usize, _livre: u32) -> u32 {
    if noticia == 0 {
        aviso_em(0xa693ec, 0x1f3f);
        return 0;
    }
    if tecnico == 0 {
        aviso_em(0xa693ec, 0x1f47);
        return 0;
    }
    let importante: unsafe extern "thiscall" fn(usize, usize) -> u32 = core::mem::transmute(0x784eb0usize);
    *((noticia + 4) as *mut u8) = importante(noticia, tecnico) as u8;
    cpn1_por(noticia + 0xda, 0);
    let idx = cpn1_indice_humano(tecnico);
    if idx < 0 {
        aviso_em(0xa693ec, 0x1f58);
        return 0;
    }
    let e = cpn1_d(this + 8) + idx as usize * 12;
    if cpn1_i(e) == -1 {
        let realocar: unsafe extern "C" fn(usize, u32) -> usize = core::mem::transmute(0x945667usize);
        cpn1_por(e, cpn1_d(this + 4));
        cpn1_por(e + 4, cpn1_d(this + 4));
        let total = cpn1_d(this + 4).wrapping_add(0x64);
        cpn1_por(this + 4, total);
        let p = realocar(cpn1_d(this), total.wrapping_mul(CPN1_NOTICIA) as u32);
        cpn1_por(this, p);
        if p == 0 {
            aviso_em(0xa693ec, 0x1f6d);
            return 0;
        }
        for k in 0..0x64usize {
            let v = cpn1_d(this) + (cpn1_d(e) + k).wrapping_mul(CPN1_NOTICIA);
            cpn1_por(v + 0xd6, 0);
            cpn1_por(v + 0xda, 1);
        }
    }
    if cpn1_d(noticia + 0xd6) == 0 {
        let id = cpn1_d(this + 0x10).wrapping_add(1);
        cpn1_por(this + 0x10, id);
        cpn1_por(noticia + 0xd6, id);
    }
    let atual = cpn1_i(e + 4);
    let mut anterior = atual.wrapping_sub(1);
    if anterior < cpn1_i(e) {
        anterior = cpn1_i(e) + 0x63;
    }
    let vaga = |k: i32| cpn1_d(this).wrapping_add((k as usize).wrapping_mul(CPN1_NOTICIA));
    if cpn1_d(vaga(anterior) + 0xd6) == cpn1_d(noticia + 0xd6) {
        return 1; // a mesma notícia de novo
    }
    if cpn1_d(vaga(atual) + 0xda) == 0 {
        cpn1_por(e + 8, cpn1_d(e + 8).wrapping_sub(1));
    }
    let copiar: unsafe extern "thiscall" fn(usize, usize) = core::mem::transmute(0x786010usize);
    copiar(vaga(atual), noticia);
    let atual = cpn1_i(e + 4);
    let inicio = cpn1_i(e);
    cpn1_por(e + 4, atual.wrapping_add(1) as usize);
    if atual.wrapping_add(1) == inicio.wrapping_add(0x64) {
        cpn1_por(e + 4, inicio as usize);
    }
    let ferias: unsafe extern "thiscall" fn(usize, usize) -> u32 = core::mem::transmute(0x5fd210usize);
    if *(0xdd6bec as *const i16) != 0 || ferias(cpn1_d(0xb63c98), tecnico) != 0 {
        let responder: unsafe extern "thiscall" fn(usize, usize, usize) = core::mem::transmute(0x784100usize);
        crate::comparacao::ramo("cpn_1 resposta automatica");
        responder(vaga(atual), tecnico, cpn1_d(tecnico + 0x39)); // o clube
        let selecao = cpn1_d(tecnico + 0x24);
        if selecao != 0 {
            responder(vaga(atual), tecnico, selecao);
        }
    }
    cpn1_por(e + 8, cpn1_d(e + 8).wrapping_add(1));
    1
}

/// Comparador: a entrega pode cair na caixa do humano (realloc, ids, resposta automática): roda só a original e confere
/// o alcance; alcance fora de 0..5 devolve 0.
unsafe extern "thiscall" fn comparar_noticia_pelo_alcance(this: usize, noticia: usize, clube: usize, competicao: usize, nacao: usize, continente: usize, alcance: u32) -> u32 {
    let r = orig::<unsafe extern "thiscall" fn(usize, usize, usize, usize, usize, usize, u32) -> u32>(946)(this, noticia, clube, competicao, nacao, continente, alcance);
    let fora = !(0..=5).contains(&(alcance as u8 as i8));
    PLACAR.registrar(!fora || r == 0, || format!("noticia_pelo_alcance alcance {} devolveu {}", alcance as u8 as i8, r));
    r
}

/// Comparador: roda só a original (a entrega não pode rodar duas vezes) e confere o plano: o alcance zerado e, sem técnico
/// humano, a devolução 0 (com humano, a entrega devolve 1 ou 0 sem memória).
unsafe extern "thiscall" fn comparar_noticia_ao_tecnico_do_clube(this: usize, noticia: usize, clube: usize) -> u32 {
    let o = orig::<unsafe extern "thiscall" fn(usize, usize, usize) -> u32>(947);
    if noticia == 0 || clube == 0 {
        return o(this, noticia, clube);
    }
    let tecnico = cpn1_d(clube + 0xcf);
    let humano = tecnico != 0 && cpn1_i(tecnico) >= cpn1_i(0xae2364).wrapping_sub(0x10);
    let r = o(this, noticia, clube);
    let ok = *((noticia + 0xde) as *const u8) == 0 && (humano || r == 0) && r <= 1;
    PLACAR.registrar(ok, || format!("noticia_ao_tecnico_do_clube(clube {:x}, técnico {:x}, humano {}) devolveu {}", clube, tecnico, humano, r));
    r
}

/// Comparador: a original realoca o vetor, numera e responde: roda só ela e confere o plano feito antes: o id da notícia,
/// o contador de ids (News +0x10), o anel do humano (início, próxima vaga, conta), a vaga escrita com o id e +0xda = 0.
unsafe extern "thiscall" fn comparar_entregar_noticia_ao_tecnico(this: usize, noticia: usize, tecnico: usize, livre: u32) -> u32 {
    let o = orig::<unsafe extern "thiscall" fn(usize, usize, usize, u32) -> u32>(948);
    if noticia == 0 || tecnico == 0 || cpn1_indice_humano(tecnico) < 0 {
        return o(this, noticia, tecnico, livre);
    }
    let idx = cpn1_indice_humano(tecnico) as usize;
    let e = cpn1_d(this + 8) + idx * 12;
    // o plano
    let novo = cpn1_i(e) == -1;
    let (inicio, atual, conta) = if novo { (cpn1_i(this + 4), cpn1_i(this + 4), cpn1_i(e + 8)) } else { (cpn1_i(e), cpn1_i(e + 4), cpn1_i(e + 8)) };
    let contador = cpn1_d(this + 0x10);
    let (id, contador_depois) = if cpn1_d(noticia + 0xd6) == 0 { (contador.wrapping_add(1), contador.wrapping_add(1)) } else { (cpn1_d(noticia + 0xd6), contador) };
    let mut anterior = atual - 1;
    if anterior < inicio {
        anterior = inicio + 0x63;
    }
    let (repetida, livre_atual) = if novo {
        (id == 0, true)
    } else {
        let v = |k: i32| cpn1_d(this).wrapping_add((k as usize).wrapping_mul(CPN1_NOTICIA));
        (cpn1_d(v(anterior) + 0xd6) == id, cpn1_d(v(atual) + 0xda) != 0)
    };
    let (prox, conta_depois) = if repetida {
        (atual, conta)
    } else {
        let p = if atual + 1 == inicio + 0x64 { inicio } else { atual + 1 };
        (p, conta + if livre_atual { 1 } else { 0 })
    };
    let r = o(this, noticia, tecnico, livre);
    if r == 0 {
        PLACAR.registrar(novo, || format!("entregar_noticia_ao_tecnico devolveu 0 sem anel novo")); // só sem memória
        return r;
    }
    let vaga = cpn1_d(this).wrapping_add((atual as usize).wrapping_mul(CPN1_NOTICIA));
    let ok = r == 1 && cpn1_i(e) == inicio && cpn1_i(e + 4) == prox && cpn1_i(e + 8) == conta_depois
        && cpn1_d(this + 0x10) == contador_depois && cpn1_d(noticia + 0xd6) == id && cpn1_d(noticia + 0xda) == 0
        && (repetida || cpn1_d(vaga + 0xd6) == id);
    PLACAR.registrar(ok, || format!("entregar_noticia_ao_tecnico(humano {}) id {} (esperava {}), anel {}/{}/{} (esperava {}/{}/{}), repetida {}",
        idx, cpn1_d(noticia + 0xd6), id, cpn1_i(e), cpn1_i(e + 4), cpn1_i(e + 8), inicio, prox, conta_depois, repetida));
    r
}

// ---------- 250a leva: a caixa do técnico humano: responder a todas as notícias, se há notícia pendente e o texto num campo da notícia (news.cpp) ----------

unsafe fn cpn2_d(a: usize) -> usize {
    core::ptr::read_unaligned(a as *const usize)
}

unsafe fn cpn2_i(a: usize) -> i32 {
    core::ptr::read_unaligned(a as *const i32)
}

/// A notícia guardada na caixa: 0xdf bytes (+4 importante, +5 os 50 campos de 4 bytes, +0xcc fim do texto, +0xd6 id,
/// +0xda lida).
const CPN2_NOTICIA: usize = 0xdf;

/// A entrada do humano na tabela das caixas (News +8, 12 bytes: início do anel, próxima vaga, conta), ou None (com a
/// caixa "Error" da `linha`) se a pessoa não está entre as 16 últimas.
unsafe fn cpn2_entrada(this: usize, tecnico: usize, linha: u32) -> Option<usize> {
    let idx = cpn2_i(tecnico).wrapping_sub(cpn2_i(0xae2364)).wrapping_add(0x10);
    if idx < 0 {
        aviso_em(0xa693ec, linha);
        return None;
    }
    Some(cpn2_d(this + 8) + idx as usize * 12)
}

/// A vaga anterior a `k` no anel que começa em `inicio` (100 vagas).
fn cpn2_volta(k: i32, inicio: i32) -> i32 {
    if k < inicio { inicio + 0x63 } else { k }
}

/// { 0x7874b0 } (thiscall, ret 8, news.cpp): `News::auto_respond_all(tecnico, clube)`: da notícia mais nova para a mais
/// antiga do anel do humano, até a primeira vaga vazia (+0xd6 = 0), dá a resposta automática (0x784100) pelo `clube`.
/// Sem técnico ou técnico da máquina: a caixa "Error" e 0; sem anel ou no fim: 1. Chamada ao sair de férias, ao ser
/// demitido e ao ser contratado.
unsafe extern "thiscall" fn responder_todas_as_noticias(this: usize, tecnico: usize, clube: usize) -> u32 {
    if tecnico == 0 {
        aviso_em(0xa693ec, 0x2460);
        return 0;
    }
    let e = match cpn2_entrada(this, tecnico, 0x246b) {
        Some(e) => e,
        None => return 0,
    };
    if cpn2_i(e) == -1 {
        return 1;
    }
    let responder: unsafe extern "thiscall" fn(usize, usize, usize) = core::mem::transmute(0x784100usize);
    let mut k = cpn2_i(e + 4) - 1;
    loop {
        k = cpn2_volta(k, cpn2_i(e));
        let vaga = cpn2_d(this).wrapping_add((k as usize).wrapping_mul(CPN2_NOTICIA));
        if cpn2_d(vaga + 0xd6) == 0 {
            return 1;
        }
        crate::comparacao::ramo("cpn_2 responder todas");
        responder(vaga, tecnico, clube); // a resposta automática
        k -= 1;
        if k == cpn2_i(e + 4) - 1 {
            return 1;
        }
    }
}

/// { 0x787350 } (thiscall, ret 8, news.cpp): `News::has_urgent_items(tecnico, so_urgentes)`: sem `so_urgentes`, se há
/// notícia não lida (0x786fe0 > 0). Com ele, da mais nova para a mais antiga do anel do humano, até a primeira vaga vazia:
/// 1 se uma pede resposta (o texto 0x782b70 em 0xde1f64 devolve 2) ou é importante (+4 = 1) e não lida (+0xda = 0).
/// Técnico da máquina: a caixa "Error" e 0.
unsafe extern "thiscall" fn tecnico_tem_noticia_pendente(this: usize, tecnico: usize, so_urgentes: u32) -> u32 {
    if so_urgentes == 0 {
        let nao_lidas: unsafe extern "thiscall" fn(usize, usize, u32) -> i32 = core::mem::transmute(0x786fe0usize);
        return (nao_lidas(this, tecnico, 0) > 0) as u32;
    }
    let e = match cpn2_entrada(this, tecnico, 0x241e) {
        Some(e) => e,
        None => return 0,
    };
    if cpn2_i(e) == -1 {
        return 0;
    }
    let texto: unsafe extern "thiscall" fn(usize, usize, usize, u32, *mut u32) -> u32 = core::mem::transmute(0x782b70usize);
    let mut k = cpn2_i(e + 4) - 1;
    loop {
        k = cpn2_volta(k, cpn2_i(e));
        let vaga = cpn2_d(this).wrapping_add((k as usize).wrapping_mul(CPN2_NOTICIA));
        if cpn2_d(vaga + 0xd6) == 0 {
            return 0;
        }
        let mut saida = 0u32;
        if texto(vaga, tecnico, 0xde1f64, 0x7d0, &mut saida) as u8 == 2 {
            return 1; // pede resposta
        }
        let vaga = cpn2_d(this).wrapping_add((k as usize).wrapping_mul(CPN2_NOTICIA));
        if *((vaga + 4) as *const u8) == 1 && cpn2_d(vaga + 0xda) == 0 {
            return 1; // importante e não lida
        }
        k -= 1;
        if k == cpn2_i(e + 4) - 1 {
            return 0;
        }
    }
}

/// { 0x7858c0 } (thiscall, ret 0xc, news.cpp): `NewsItem::set_slot_string(campo, texto, proximo)`: copia o `texto` nos
/// campos da notícia a partir do `campo` (strncpy 0x9466d0 em +5 + 4·campo, até 200 − 4·campo bytes), termina a área
/// (+0xcc = 0) e, com `proximo`, grava o primeiro campo livre depois do texto (o tamanho com o zero arredondado para
/// 4, em campos, mais o `campo`; no máximo 50). Campo fora de 0..49 ou sem texto: a caixa "Error" e 0; senão 1.
unsafe extern "thiscall" fn gravar_texto_na_noticia(this: usize, campo: u32, texto: *const u8, proximo: *mut u8) -> u32 {
    let campo = campo as u8 as i8;
    if !(0..0x32).contains(&campo) {
        aviso_em(0xa693ec, 0x1e8d);
        return 0;
    }
    if texto.is_null() {
        aviso_em(0xa693ec, 0x1e95);
        return 0;
    }
    let copiar: unsafe extern "C" fn(usize, *const u8, u32) -> usize = core::mem::transmute(0x9466d0usize);
    let d = 4 * campo as i32;
    copiar(this + 5 + d as usize, texto, (0xc8 - d) as u32);
    *((this + 0xcc) as *mut u8) = 0;
    if !proximo.is_null() {
        let mut n = 0i32;
        while *texto.add(n as usize) != 0 {
            n += 1;
        }
        let quartos = ((n + 1 + 3) & !3) / 4; // o tamanho com o zero, em campos de 4 bytes
        let mut p = (quartos as u8).wrapping_add(campo as u8);
        crate::comparacao::ramo("cpn_2 proximo campo do texto");
        if p as i8 > 0x32 {
            p = 0x32;
        }
        *proximo = p; // o próximo campo livre
    }
    1
}

/// Comparador: a original responde (convites, propostas, emprego): roda só ela e confere a devolução (0 só sem técnico
/// ou com técnico da máquina; senão 1).
unsafe extern "thiscall" fn comparar_responder_todas_as_noticias(this: usize, tecnico: usize, clube: usize) -> u32 {
    let humano = tecnico != 0 && cpn2_i(tecnico).wrapping_sub(cpn2_i(0xae2364)).wrapping_add(0x10) >= 0;
    let r = orig::<unsafe extern "thiscall" fn(usize, usize, usize) -> u32>(949)(this, tecnico, clube);
    PLACAR.registrar(r == humano as u32, || format!("responder_todas_as_noticias(técnico {:x}, humano {}) devolveu {}", tecnico, humano, r));
    r
}

/// Comparador: lado a lado pela devolução e pelo texto montado em 0xde1f64 (a 0x782b70 não sorteia; a caixa não muda).
unsafe extern "thiscall" fn comparar_tecnico_tem_noticia_pendente(this: usize, tecnico: usize, so_urgentes: u32) -> u32 {
    let o = orig::<unsafe extern "thiscall" fn(usize, usize, u32) -> u32>(950);
    if so_urgentes != 0 && cpn2_i(tecnico).wrapping_sub(cpn2_i(0xae2364)).wrapping_add(0x10) < 0 {
        return o(this, tecnico, so_urgentes); // a caixa "Error"
    }
    let reg = [(0xde1f64usize, 0x7d0usize)];
    let (r, n, igual, mo, mr) = crate::comparacao::lado_a_lado(&reg, || o(this, tecnico, so_urgentes), || tecnico_tem_noticia_pendente(this, tecnico, so_urgentes));
    PLACAR.registrar(igual && r == n, || format!("tecnico_tem_noticia_pendente(urgentes {}) {} x {} {:x?} x {:x?}", so_urgentes, r, n, mo, mr));
    r
}

/// Comparador: lado a lado pelos campos da notícia (+5..+0xcc) e pelo próximo campo.
unsafe extern "thiscall" fn comparar_gravar_texto_na_noticia(this: usize, campo: u32, texto: *const u8, proximo: *mut u8) -> u32 {
    let o = orig::<unsafe extern "thiscall" fn(usize, u32, *const u8, *mut u8) -> u32>(951);
    if !(0..0x32).contains(&(campo as u8 as i8)) || texto.is_null() {
        return o(this, campo, texto, proximo); // a caixa "Error"
    }
    let mut reg = vec![(this + 5, 0xc8usize)];
    if !proximo.is_null() {
        reg.push((proximo as usize, 1));
    }
    let (r, n, igual, mo, mr) = crate::comparacao::lado_a_lado(&reg, || o(this, campo, texto, proximo), || gravar_texto_na_noticia(this, campo, texto, proximo));
    PLACAR.registrar(igual && r == n, || format!("gravar_texto_na_noticia(campo {}) {:x?} x {:x?}", campo as u8 as i8, mo, mr));
    r
}

// ---------- 250a leva: a mídia e a caixa: a nota do jogador para uma história, o texto da crise financeira e as notícias da caixa do humano (media.cpp, news.cpp) ----------

unsafe fn cpn3_d(a: usize) -> usize {
    core::ptr::read_unaligned(a as *const usize)
}

unsafe fn cpn3_i(a: usize) -> i32 {
    core::ptr::read_unaligned(a as *const i32)
}

unsafe fn cpn3_b(a: usize) -> i8 {
    *(a as *const i8)
}

unsafe fn cpn3_w(a: usize) -> i16 {
    core::ptr::read_unaligned(a as *const i16)
}

/// A notícia guardada na caixa: 0xdf bytes (+0xd6 id).
const CPN3_NOTICIA: usize = 0xdf;

/// A razão entre a reputação do jogador (+0xb do registro +0x61, no mínimo 2000) e a do clube (+0x80, entre 2000 e
/// 7500), como o fild/fidiv do original.
unsafe fn cpn3_razao_das_reputacoes(jogador: usize, clube: usize) -> f64 {
    let a = cpn3_w(cpn3_d(jogador + 0x61) + 0xb);
    let a = if a < 2000 { 2000 } else { a as i32 };
    let b = cpn3_w(clube + 0x80);
    let b = if b < 2000 { 2000 } else if b > 7500 { 7500 } else { b as i32 };
    a as f64 / b as f64
}

/// O tipo de história (0..0x52) → o caso do original (a tabela de bytes de 0x736b8c; 12 = a nota como está).
fn cpn3_caso(tipo: i16) -> u8 {
    match tipo {
        0 => 0,
        1 | 2 | 9 => 1,
        3 => 2,
        4 => 3,
        6 => 4,
        7 => 5,
        12 => 6,
        13 => 7,
        17 => 8,
        30 => 9,
        35 => 10,
        82 => 11,
        _ => 12,
    }
}

/// { 0x736720 } (thiscall, ret 0x18, media.cpp): `Media::rate_player_form_for_story(jogador, clube, contrato, tipo,
/// modo, peso)`: a nota (x87, em st0) do jogador para uma história da mídia. Sem contrato, o do jogador com o clube
/// (0x4cf5f0); sem nenhum, 0. Base: a nota média da liga x ([0xb74350] +0x10 / +0x18, sem jogos 6,8), as estatísticas
/// do jogador (0x7c1e30, categoria 6: s1 campo 1, s2 campo 0x11, s3 campo 2, padrão 6,5) e a média das notas
/// (0x7c1950) × 0,2: r = (s2 − x) + (média − x) − peso/60; com s1 < 12, r × s1/12; negativa, × a razão das
/// reputações. Depois, pelo tipo (0..0x52), somas do tipo de contrato (+0x4f >> 4), da idade, dos dias de casa
/// (0x54cdb0), de atributos do registro +0x61, do peso; o tipo 0x52 dá r × 0,75 + s3/max(s1, 1) − 0,4.
unsafe extern "thiscall" fn nota_do_jogador_para_a_historia(_this: usize, jogador: usize, clube: usize, contrato: usize, tipo: u32, modo: u32, peso: f32) -> f64 {
    let mut contrato = contrato;
    if contrato == 0 {
        let com_clube: unsafe extern "thiscall" fn(usize, usize, usize) -> usize = core::mem::transmute(0x4cf5f0usize);
        contrato = com_clube(cpn3_d(0xae1050), jogador, clube);
        if contrato == 0 {
            return 0.0;
        }
    }
    let estat: unsafe extern "thiscall" fn(usize, usize, u32, u32, f32) -> f64 = core::mem::transmute(0x7c1e30usize);
    let media_notas: unsafe extern "thiscall" fn(usize, usize) -> u32 = core::mem::transmute(0x7c1950usize);
    let g = cpn3_d(0xb74350);
    let jogos = core::ptr::read_unaligned((g + 0x18) as *const f64);
    let x = if jogos == 0.0 || jogos.is_nan() { 6.8 } else { core::ptr::read_unaligned((g + 0x10) as *const f64) / jogos };
    let xf = x as f32;
    let s1f = estat(cpn3_d(0xb74350), cpn3_d(jogador + 0x61), 6, 1, 6.5) as f32;
    let s2f = estat(cpn3_d(0xb74350), cpn3_d(jogador + 0x61), 6, 0x11, 6.5) as f32;
    let media = media_notas(cpn3_d(0xb74350), cpn3_d(jogador + 0x61)) as u8 as i8 as i32;
    let mut l0 = (media as f64 * 0.2) as f32;
    let y = if s1f as f64 > 1.0 { s1f as f64 } else { 1.0 }; // as partidas, no mínimo 1
    let s3 = estat(cpn3_d(0xb74350), cpn3_d(jogador + 0x61), 6, 2, 6.5);
    let l2 = (s3 / y) as f32;
    l0 = (l0 as f64 - xf as f64) as f32;
    let dif = s2f as f64 - xf as f64;
    let dif_f = dif as f32;
    crate::comparacao::ramo("cpn_3 nota do jogador");
    let mut r = dif + l0 as f64 - peso as f64 * (1.0f32 / 60.0) as f64; // o peso da história
    if !(s1f as f64 >= 12.0) {
        crate::comparacao::ramo("cpn_3 poucas partidas");
        r = r * s1f as f64 * (1.0f32 / 12.0) as f64; // menos de 12 partidas
    }
    if !(r >= 0.0) {
        crate::comparacao::ramo("cpn_3 nota negativa");
        r = r * cpn3_razao_das_reputacoes(jogador, clube); // a negativa pela reputação
    }
    let rf = r as f32;
    let tipo = tipo as u16 as i16;
    if !(0..=0x52).contains(&tipo) {
        return r;
    }
    let c = *((contrato + 0x4f) as *const u8) >> 4; // o tipo de contrato
    match cpn3_caso(tipo) {
        0 => match c {
            1 => r - 0.5,
            2 => r - 0.35f32 as f64,
            3 => r - 0.2f32 as f64,
            _ => r + 0.25,
        },
        1 => {
            let dias: unsafe extern "thiscall" fn(usize, u32, u32) -> i32 = core::mem::transmute(0x54cdb0usize);
            let d = dias(0xae2c90, cpn3_d(jogador + 0x3e) as u32, cpn3_d(jogador + 0x42) as u32);
            (200i32.wrapping_sub(d)) as f64 * 0.1f32 as f64 + rf as f64
        }
        2 => {
            let r2 = r + dif_f as f64;
            match c {
                1 => r2 + 2.0,
                2 => r2 + 1.5,
                3 => r2 + 1.0,
                _ => r2,
            }
        }
        3 => r + (0x23 - cpn3_b(jogador + 0x18) as i32) as f64 * (1.0f32 / 3.0) as f64,
        4 => r + (10 - cpn3_b(cpn3_d(jogador + 0x61) + 0x25) as i32) as f64 * 0.2f32 as f64,
        5 => r + (cpn3_b(jogador + 0x18) as i32 - 0x13) as f64 * (1.0f32 / 3.0) as f64,
        6 => r + (cpn3_b(cpn3_d(jogador + 0x61) + 0x2f) as i32 - 10) as f64 * (1.0f32 / 3.0) as f64,
        7 => r + l0 as f64,
        8 => {
            let r2 = if r > 0.0 { r / cpn3_razao_das_reputacoes(jogador, clube) } else { r };
            match c {
                1 => r2 - 0.5,
                2 => r2 - 0.35f32 as f64,
                3 => r2 - 0.2f32 as f64,
                _ => r2,
            }
        }
        9 => r - peso as f64 * 0.1f32 as f64,
        10 => match c {
            0 => r - 1.0,
            1 => r + 2.0,
            2 => r + 1.5,
            3 => r + 1.0,
            7 => {
                if modo as u8 == 3 { 0.0 } else { r - 3.0 }
            }
            _ => r,
        },
        11 => r * 0.75 + l2 as f64 - 0.4f32 as f64,
        _ => r,
    }
}

/// { 0x74af60 } (thiscall, ret 0xc, media.cpp): `Media::write_financial_trouble_news_text(noticia, corpo, saida)`: o
/// título ou o corpo da notícia do clube em crise: lê os campos 0 (o clube), 1 (a gravidade) e 2 da notícia (0x785830),
/// monta em 0xde1f64 (0x66f4e0) o texto pela gravidade (> 0x1a5e, > 0xcb2 no corpo; > 0x1a5e no título) com o nome do
/// clube (+0x38) e o gênero (+0x52), põe na `saida` (0x4ae660) e liga o nome ao clube (0x4ae8a0, tipo 0x7d5).
unsafe extern "thiscall" fn texto_da_crise_financeira(_this: usize, noticia: usize, corpo: u32, saida: usize) {
    let campo: unsafe extern "thiscall" fn(usize, u32) -> i32 = core::mem::transmute(0x785830usize);
    let formatar: unsafe extern "C" fn(usize, usize, ...) -> i32 = core::mem::transmute(0x66f4e0usize);
    let por_texto: unsafe extern "thiscall" fn(usize, usize) = core::mem::transmute(0x4ae660usize);
    let ligar: unsafe extern "thiscall" fn(usize, usize, u32, usize) = core::mem::transmute(0x4ae8a0usize);
    crate::comparacao::ramo("cpn_3 texto da crise financeira");
    let id = campo(noticia, 0);
    let gravidade = campo(noticia, 1);
    campo(noticia, 2);
    let clube = cpn3_d(0xae23b4).wrapping_add((id as usize).wrapping_mul(0x245));
    let nome = clube + 0x38;
    let genero = cpn3_b(clube + 0x52) as i32;
    let modelo = if corpo != 0 {
        if gravidade > 0x1a5e {
            0xa436fc
        } else if gravidade > 0xcb2 {
            0xa43644
        } else {
            0xa43594
        }
    } else if gravidade > 0x1a5e {
        0xa43560 // "... financial mess"
    } else {
        0xa43528 // "Financial trouble at ..."
    };
    formatar(0xde1f64, modelo, genero, genero, nome);
    por_texto(saida, 0xde1f64);
    ligar(saida, nome, 0x7d5, clube);
}

/// { 0x786960 } (thiscall, ret 0xc, news.cpp): `News::get_inbox_items(tecnico, conta, categoria)`: um vetor novo de 100
/// notícias (malloc 0x944e46 de 0x571c, na primeira achada; `*conta` = 0) com as notícias do anel do humano, da mais nova
/// para a mais antiga até a vaga vazia, só as da `categoria` (0x785670) se ela não for 0, copiadas (0x786010); `*conta`
/// soma uma por notícia. Devolve o vetor (0 sem nenhuma; `*conta` intocada). Sem técnico ou técnico da máquina: a caixa
/// "Error" e 0.
unsafe extern "thiscall" fn noticias_da_caixa(this: usize, tecnico: usize, conta: *mut i32, categoria: u32) -> usize {
    if tecnico == 0 {
        aviso_em(0xa693ec, 0x21fa);
        return 0;
    }
    let idx = cpn3_i(tecnico).wrapping_sub(cpn3_i(0xae2364)).wrapping_add(0x10);
    if idx < 0 {
        aviso_em(0xa693ec, 0x2205);
        return 0;
    }
    let e = cpn3_d(this + 8) + idx as usize * 12;
    if cpn3_i(e) == -1 {
        return 0;
    }
    let tipo: unsafe extern "thiscall" fn(usize) -> u32 = core::mem::transmute(0x785670usize);
    let copiar: unsafe extern "thiscall" fn(usize, usize) = core::mem::transmute(0x786010usize);
    let alocar: unsafe extern "C" fn(u32) -> usize = core::mem::transmute(0x944e46usize);
    let mut vetor = 0usize;
    let mut k = cpn3_i(e + 4) - 1;
    loop {
        if k < cpn3_i(e) {
            k = cpn3_i(e) + 0x63;
        }
        let vaga = cpn3_d(this).wrapping_add((k as usize).wrapping_mul(CPN3_NOTICIA));
        if cpn3_d(vaga + 0xd6) == 0 {
            return vetor;
        }
        if categoria as u8 == 0 || tipo(vaga) as u8 == categoria as u8 {
            if vetor == 0 {
                vetor = alocar(0x571c);
                if vetor == 0 {
                    aviso_em(0xa693ec, 0x222a);
                    return 0;
                }
                *conta = 0;
            }
            let n = *conta;
            *conta = n + 1;
            copiar(vetor.wrapping_add((n as usize).wrapping_mul(CPN3_NOTICIA)), cpn3_d(this).wrapping_add((k as usize).wrapping_mul(CPN3_NOTICIA)));
        }
        k -= 1;
        if k == cpn3_i(e + 4) - 1 {
            return vetor;
        }
    }
}

/// Comparador: a nota é pura (as estatísticas, as datas e o contrato só leem; nada sorteia): compara a devolução bit a
/// bit (a original e a cópia na mesma precisão dupla do x87).
unsafe extern "thiscall" fn comparar_nota_do_jogador_para_a_historia(this: usize, jogador: usize, clube: usize, contrato: usize, tipo: u32, modo: u32, peso: f32) -> f64 {
    let o = orig::<unsafe extern "thiscall" fn(usize, usize, usize, usize, u32, u32, f32) -> f64>(952)(this, jogador, clube, contrato, tipo, modo, peso);
    let n = nota_do_jogador_para_a_historia(this, jogador, clube, contrato, tipo, modo, peso);
    PLACAR.registrar(o.to_bits() == n.to_bits() || (o.is_nan() && n.is_nan()),
        || format!("nota_do_jogador_para_a_historia(tipo {}, modo {}, peso {}) {} x {}", tipo as u16 as i16, modo as u8, peso, o, n));
    o
}

/// Comparador: o texto vai para o objeto de saída (0x4ae660/0x4ae8a0 acrescentam e alocam): roda só a original (a cópia
/// prova no modo Rust, pelo ramo).
unsafe extern "thiscall" fn comparar_texto_da_crise_financeira(this: usize, noticia: usize, corpo: u32, saida: usize) {
    // ponytail: o objeto de texto não pode receber o texto duas vezes; só a original roda aqui
    orig::<unsafe extern "thiscall" fn(usize, usize, u32, usize)>(953)(this, noticia, corpo, saida);
}

/// Comparador: a original aloca o vetor: roda só ela e confere o plano feito antes (a conta e os ids, na ordem).
unsafe extern "thiscall" fn comparar_noticias_da_caixa(this: usize, tecnico: usize, conta: *mut i32, categoria: u32) -> usize {
    let o = orig::<unsafe extern "thiscall" fn(usize, usize, *mut i32, u32) -> usize>(954);
    if tecnico == 0 || cpn3_i(tecnico).wrapping_sub(cpn3_i(0xae2364)).wrapping_add(0x10) < 0 {
        return o(this, tecnico, conta, categoria);
    }
    let e = cpn3_d(this + 8) + (cpn3_i(tecnico).wrapping_sub(cpn3_i(0xae2364)).wrapping_add(0x10)) as usize * 12;
    let mut ids = Vec::new();
    if cpn3_i(e) != -1 {
        let tipo: unsafe extern "thiscall" fn(usize) -> u32 = core::mem::transmute(0x785670usize);
        let mut k = cpn3_i(e + 4) - 1;
        loop {
            if k < cpn3_i(e) {
                k = cpn3_i(e) + 0x63;
            }
            let vaga = cpn3_d(this).wrapping_add((k as usize).wrapping_mul(CPN3_NOTICIA));
            if cpn3_d(vaga + 0xd6) == 0 {
                break;
            }
            if categoria as u8 == 0 || tipo(vaga) as u8 == categoria as u8 {
                ids.push(cpn3_d(vaga + 0xd6));
            }
            k -= 1;
            if k == cpn3_i(e + 4) - 1 {
                break;
            }
        }
    }
    let r = o(this, tecnico, conta, categoria);
    let ok = if ids.is_empty() {
        r == 0
    } else {
        r == 0 || (*conta as usize == ids.len() && ids.iter().enumerate().all(|(i, &id)| cpn3_d(r + i * CPN3_NOTICIA + 0xd6) == id))
    };
    PLACAR.registrar(ok, || format!("noticias_da_caixa(categoria {}) {} notícias, esperava {:?}", categoria as u8, if r == 0 { 0 } else { *conta }, ids));
    r
}

// ---------- 250a leva: o jogador que se aposenta sai dos elencos e a escolha do clube do jovem: o de maior nota entre todos e o sorteado da lista da nação (player_regen.cpp) ----------

unsafe fn cpn4_d(a: usize) -> usize {
    core::ptr::read_unaligned(a as *const usize)
}

unsafe fn cpn4_w(a: usize) -> i16 {
    core::ptr::read_unaligned(a as *const i16)
}

unsafe fn cpn4_b(a: usize) -> i8 {
    *(a as *const i8)
}

unsafe fn cpn4_por(a: usize, v: i8) {
    *(a as *mut i8) = v;
}

/// Tira a pessoa `p` do time em `p + campo` (+0x39 o clube, +0x24 a seleção): a tática (0x896c60 de [0xde1d08], com 0
/// e depois com 1 no 3º argumento) e a primeira das 50 vagas (+0xd7) com ela, que esvazia. O time é relido depois de
/// cada chamada, como na original.
unsafe fn cpn4_tirar_do_time(p: usize, campo: usize) {
    let tirar: unsafe extern "thiscall" fn(usize, usize, usize, u32, u32) -> u32 = core::mem::transmute(0x896c60usize);
    tirar(cpn4_d(0xde1d08), cpn4_d(p + campo), p, 0, 1);
    tirar(cpn4_d(0xde1d08), cpn4_d(p + campo), p, 1, 1);
    let time = cpn4_d(p + campo);
    if let Some(k) = (0..0x32usize).find(|&k| cpn4_d(time + 0xd7 + 4 * k) == p) {
        core::ptr::write_unaligned((time + 0xd7 + 4 * k) as *mut usize, 0);
    }
}

/// O aviso "already retired" no buffer [0xde1f64] (nome +4, sobrenome +8, id +0).
unsafe fn cpn4_ja_aposentado(p: usize) {
    let formatar: unsafe extern "C" fn(usize, usize, ...) -> i32 = core::mem::transmute(0x944c9fusize);
    formatar(0xde1f64, 0xa70150, cpn4_d(p + 4), cpn4_d(p + 8), cpn4_d(p));
}

/// { 0x7aace0 } (stdcall, ret 4, player_regen.cpp): `PLAYER_REGEN::retire_from_playing_staff(p)`: tira `p` do clube
/// (+0x39) e da seleção (+0x24) (`cpn4_tirar_do_time`) e troca o cargo de jogador pelo da comissão (tabelas 0x7aae60 e
/// 0x7aae90): pelo cargo no clube (+0x3d, byte com sinal; fora de 0..16 vale o padrão) 12 → 5, 13 → 6, 15 → 8 (fica no
/// clube), 0 e 16 (aviso "already retired") nada, 1 a 10 a rotina acaba ali, os outros 0x10 (aposentado). Depois pelo
/// cargo na seleção (+0x28) do mesmo jeito, mas 12/13/15 gravam no +0x3d (a original grava ali, não no +0x28) e o
/// padrão grava 0x10 no +0x28. Sem cargo que fica, o clube (+0x39) e a seleção (+0x24) zeram. Sem SEH, sem sorteio.
unsafe extern "stdcall" fn aposentar_do_elenco(p: usize) {
    if cpn4_d(p + 0x39) != 0 {
        cpn4_tirar_do_time(p, 0x39);
    }
    if cpn4_d(p + 0x24) != 0 {
        cpn4_tirar_do_time(p, 0x24);
    }
    let fica_no_clube = match cpn4_b(p + 0x3d) as i32 {
        0 => false,
        1..=10 => return, // comissão: a original sai pelo fim da rotina
        12 => {
            cpn4_por(p + 0x3d, 5);
            true
        }
        13 => {
            cpn4_por(p + 0x3d, 6);
            true
        }
        15 => {
            cpn4_por(p + 0x3d, 8);
            true
        }
        16 => {
            cpn4_ja_aposentado(p);
            false
        }
        _ => {
            crate::comparacao::ramo("cpn_4 jogador aposentado");
            cpn4_por(p + 0x3d, 0x10); // aposentado
            false
        }
    };
    let fica_na_selecao = match cpn4_b(p + 0x28) as i32 {
        0 => false,
        1..=10 => return,
        12 => {
            cpn4_por(p + 0x3d, 5); // no +0x3d, como a original
            true
        }
        13 => {
            cpn4_por(p + 0x3d, 6);
            true
        }
        15 => {
            cpn4_por(p + 0x3d, 8);
            true
        }
        16 => {
            cpn4_ja_aposentado(p);
            false
        }
        _ => {
            cpn4_por(p + 0x28, 0x10);
            false
        }
    };
    if !fica_no_clube {
        core::ptr::write_unaligned((p + 0x39) as *mut usize, 0);
    }
    if !fica_na_selecao {
        core::ptr::write_unaligned((p + 0x24) as *mut usize, 0);
    }
}

/// O jovem com a segunda nacionalidade (+0x1e) igual a [0x9cf424] só vai para os clubes de id [0x9d0120], [0x9d0134],
/// [0x9d0128], [0x9d01a0] e [0x9d0124]: `true` para os outros clubes.
unsafe fn cpn4_vetado(jogador: usize, clube: usize) -> bool {
    let e = cpn4_d(jogador + 0x1e);
    if e == 0 || cpn4_d(e) != cpn4_d(0x9cf424) {
        return false;
    }
    let id = cpn4_d(clube);
    ![0x9d0120usize, 0x9d0134, 0x9d0128, 0x9d01a0, 0x9d0124].iter().any(|&g| cpn4_d(g) == id)
}

/// O clube pode chegar ao jogador (0x8ce990 de [0xde1f54], sem ignorar as ofertas abertas)? O motivo fica numa local
/// (a original o grava na vaga do argumento, que ninguém lê depois).
unsafe fn cpn4_pode_contratar(jogador: usize, clube: usize) -> bool {
    let pode: unsafe extern "thiscall" fn(usize, usize, usize, *mut i16, u32) -> u32 = core::mem::transmute(0x8ce990usize);
    let mut motivo = 0i16;
    pode(cpn4_d(0xde1f54), jogador, clube, &mut motivo, 0) != 0
}

/// { 0x7ad0e0 } (thiscall, ret 4, player_regen.cpp): `PLAYER_REGEN::pick_best_club_for_player(jogador)`: entre os
/// clubes ([0xae23b4], 0x245 bytes; os [0xae235c] − 2 × [0xae2350] primeiros, relidos a cada volta) em que o jogador
/// não é estrangeiro (0x53d980 com a nação +0x53 e 1), que não são o time B de um par (0x540a50 com 1 achando o
/// parceiro com 0), não vetados (`cpn4_vetado`), que podem chegar a ele (0x8ce990) e com elenco (0x53c590) abaixo de 50,
/// o de maior nota (0x7ad220, sorteia; comparada em 16 bits, a partir de −25000). Nenhum: 0. Sem SEH; a local do
/// parceiro só é lida quando a 0x540a50 o acha (e a grava).
unsafe extern "thiscall" fn melhor_clube_para_o_jovem(_this: usize, jogador: usize) -> usize {
    let estrangeiro: unsafe extern "C" fn(usize, usize, u32) -> u32 = core::mem::transmute(0x53d980usize);
    let parceiro: unsafe extern "C" fn(usize, *mut u32, u32) -> usize = core::mem::transmute(0x540a50usize);
    let elenco_de: unsafe extern "C" fn(usize, u32, u32) -> u8 = core::mem::transmute(0x53c590usize);
    let nota_de: unsafe extern "stdcall" fn(usize, usize, u32) -> i32 = core::mem::transmute(0x7ad220usize);
    let total = || (cpn4_d(0xae235c) as i32).wrapping_sub((cpn4_d(0xae2350) as i32).wrapping_mul(2));
    let (mut melhor, mut melhor_nota) = (0usize, -25000i16);
    let mut eh_a = 0u32;
    let mut clube = cpn4_d(0xae23b4);
    let mut i = 0i32;
    while i < total() {
        let candidato = estrangeiro(jogador, cpn4_d(clube + 0x53), 1) == 0
            && (parceiro(clube, &mut eh_a, 1) == 0 || eh_a != 0)
            && !cpn4_vetado(jogador, clube);
        if candidato {
            let elenco = elenco_de(clube, 0, 0);
            if cpn4_pode_contratar(jogador, clube) && (elenco as i8) < 0x32 {
                // ponytail: a original empurra o byte do elenco com lixo nos bits altos; a 0x7ad220 só lê o byte
                let s = nota_de(jogador, clube, elenco as u32) as i16;
                if s > melhor_nota {
                    crate::comparacao::ramo("cpn_4 clube melhor para o jovem");
                    melhor = clube;
                    melhor_nota = s;
                }
            }
        }
        i += 1;
        clube += 0x245;
    }
    melhor
}

/// A nação da lista do jovem: a nação (+0x1a) dele; [0x9cf510] e [0x9cf2dc] vão para [0x9cf2e4], e [0x9cf3e4] também
/// com sorteio(5) < 2.
unsafe fn cpn4_nacao_da_lista(jogador: usize) -> usize {
    let sorteio: unsafe extern "C" fn(i32) -> i32 = core::mem::transmute(0x90cfc0usize);
    let n = cpn4_d(cpn4_d(jogador + 0x1a));
    if n == cpn4_d(0x9cf510) || n == cpn4_d(0x9cf2dc) || (n == cpn4_d(0x9cf3e4) && sorteio(5) < 2) {
        return cpn4_d(0x9cf2e4);
    }
    n
}

/// A lista de clubes da nação `n`: [[this] + 4n].
unsafe fn cpn4_lista(this: usize, n: usize) -> usize {
    cpn4_d(cpn4_d(this).wrapping_add(n.wrapping_mul(4)))
}

/// { 0x7ad590 } (thiscall, ret 4, player_regen.cpp): `PLAYER_REGEN::pick_club_from_nation_list(jogador)`: percorre a
/// lista de clubes da nação do jovem (`cpn4_nacao_da_lista`; a palavra +0 é a conta, o cursor +0xa recomeça de +2, o
/// iterador 0x68d1b0 devolve o id) e, entre os clubes não vetados (`cpn4_vetado`), que podem chegar a ele (0x8ce990) e
/// com elenco (0x53c590) abaixo de 50, fica com o de maior sorteio da nota (5000 + reputação +0x80 menos as distâncias
/// dela à habilidade da ficha +0x61: +0xb, +7 × 50 e +5 × 50, em 16 bits), comparado em 16 bits a partir de −25000.
/// Sem lista ou lista vazia: 0. A lista que acaba antes da conta: a caixa "Error" (linha 0x19e9) e 0. Sem SEH.
unsafe extern "thiscall" fn clube_da_nacao_para_o_jovem(this: usize, jogador: usize) -> usize {
    let proximo: unsafe extern "thiscall" fn(usize) -> usize = core::mem::transmute(0x68d1b0usize);
    let elenco_de: unsafe extern "C" fn(usize, u32, u32) -> u8 = core::mem::transmute(0x53c590usize);
    let sorteio: unsafe extern "C" fn(i32) -> i32 = core::mem::transmute(0x90cfc0usize);
    let n = cpn4_nacao_da_lista(jogador);
    let l = cpn4_lista(this, n);
    if l == 0 || cpn4_w(l) == 0 {
        return 0;
    }
    core::ptr::write_unaligned((l + 0xa) as *mut usize, cpn4_d(l + 2));
    let (mut melhor, mut melhor_nota) = (0usize, -25000i16);
    if cpn4_w(cpn4_lista(this, n)) <= 0 {
        return 0;
    }
    let mut i = 0i32;
    loop {
        let item = proximo(cpn4_lista(this, n));
        if item == 0 {
            aviso_em(0xa6bf9c, 0x19e9);
            return 0;
        }
        let clube = cpn4_d(0xae23b4).wrapping_add(cpn4_d(item).wrapping_mul(0x245));
        if !cpn4_vetado(jogador, clube) && cpn4_pode_contratar(jogador, clube) && (elenco_de(clube, 0, 0) as i8) < 0x32 {
            let ficha = cpn4_d(jogador + 0x61);
            let rep = cpn4_w(clube + 0x80) as i32;
            let c = rep
                .wrapping_sub((cpn4_w(ficha + 0xb) as i32).wrapping_sub(rep).wrapping_abs())
                .wrapping_sub((cpn4_w(ficha + 7) as i32).wrapping_mul(50).wrapping_sub(rep).wrapping_abs())
                .wrapping_sub((cpn4_w(ficha + 5) as i32).wrapping_mul(50).wrapping_sub(rep).wrapping_abs())
                .wrapping_add(0x1388);
            crate::comparacao::ramo("cpn_4 sorteio do clube da nacao");
            let nota = sorteio(c as i16 as i32) as i16;
            if nota > melhor_nota {
                melhor = clube;
                melhor_nota = nota;
            }
        }
        i += 1;
        if i as i16 >= cpn4_w(cpn4_lista(this, n)) {
            break;
        }
    }
    melhor
}

/// Comparador: lado a lado pela pessoa (+0x24..+0x3d), pelas 50 vagas do clube e da seleção e pelo aviso em
/// [0xde1f64]. A 0x896c60 tira a pessoa da tática: na segunda vez (a cópia) já não a acha, então a tática fica fora.
unsafe extern "stdcall" fn comparar_aposentar_do_elenco(p: usize) {
    let o = orig::<unsafe extern "stdcall" fn(usize)>(955);
    let mut reg = vec![(p + 0x24, 0x1a), (0xde1f64, 0x80)];
    for campo in [0x39usize, 0x24] {
        let time = cpn4_d(p + campo);
        if time != 0 {
            reg.push((time + 0xd7, 200));
        }
    }
    let (antes_clube, antes_cargo) = (cpn4_d(p + 0x39), cpn4_b(p + 0x3d));
    let (_, _, igual, mo, mr) = crate::comparacao::lado_a_lado(&reg, || o(p), || aposentar_do_elenco(p));
    PLACAR.registrar(igual, || format!("aposentar_do_elenco(id {}, clube {:x}, cargo {}) {:x?} x {:x?}", cpn4_d(p), antes_clube, antes_cargo, mo, mr));
}

/// Comparador: lado a lado a partir do mesmo estado do sorteio (a 0x7ad220 sorteia), pelo clube devolvido.
unsafe extern "thiscall" fn comparar_melhor_clube_para_o_jovem(this: usize, jogador: usize) -> usize {
    let o = orig::<unsafe extern "thiscall" fn(usize, usize) -> usize>(956);
    let reg = crate::aleatorio::REGIOES_DO_ESTADO;
    let (r, n, igual, mo, mr) = crate::comparacao::lado_a_lado_leve(&reg, || o(this, jogador), || crate::aleatorio::sem_contar(|| melhor_clube_para_o_jovem(this, jogador)));
    PLACAR.registrar(igual && r == n, || format!("melhor_clube_para_o_jovem(id {}) original={:x} rust={:x} {:x?} x {:x?}", cpn4_d(jogador), r, n, mo, mr));
    r
}

/// Comparador: lado a lado a partir do mesmo estado do sorteio, pelo clube devolvido e pelo cursor (+0xa) das listas
/// que podem ser percorridas (a da nação do jovem e a de [0x9cf2e4]).
unsafe extern "thiscall" fn comparar_clube_da_nacao_para_o_jovem(this: usize, jogador: usize) -> usize {
    let o = orig::<unsafe extern "thiscall" fn(usize, usize) -> usize>(957);
    let mut reg = crate::aleatorio::REGIOES_DO_ESTADO.to_vec();
    for n in [cpn4_d(cpn4_d(jogador + 0x1a)), cpn4_d(0x9cf2e4)] {
        let l = cpn4_lista(this, n);
        if l != 0 {
            reg.push((l + 0xa, 4));
        }
    }
    let (r, n, igual, mo, mr) = crate::comparacao::lado_a_lado(&reg, || o(this, jogador), || crate::aleatorio::sem_contar(|| clube_da_nacao_para_o_jovem(this, jogador)));
    PLACAR.registrar(igual && r == n, || format!("clube_da_nacao_para_o_jovem(id {}) original={:x} rust={:x} {:x?} x {:x?}", cpn4_d(jogador), r, n, mo, mr));
    r
}

// ---------- 250a leva: as vagas de técnico e o agendamento das ofertas: abrir as vagas que faltam, a melhor nota de candidato a técnico e agendar a oferta (manager_manager.cpp, transfer_manager.cpp) ----------

unsafe fn cpn5_d(a: usize) -> usize {
    core::ptr::read_unaligned(a as *const usize)
}

unsafe fn cpn5_w(a: usize) -> i16 {
    core::ptr::read_unaligned(a as *const i16)
}

unsafe fn cpn5_b(a: usize) -> u8 {
    *(a as *const u8)
}

/// O `clube` já tem vaga na lista [this+8] (+0 conta, cursor +0xa recomeçado de +2, iterador 0x68d1b0; +0xe da vaga o
/// id do clube)? `None`: a lista acabou antes da conta (a caixa da original).
unsafe fn cpn5_tem_vaga(this: usize, clube: usize) -> Option<bool> {
    let proximo: unsafe extern "thiscall" fn(usize) -> usize = core::mem::transmute(0x68d1b0usize);
    let l = cpn5_d(this + 8);
    core::ptr::write_unaligned((l + 0xa) as *mut usize, cpn5_d(l + 2));
    if cpn5_w(cpn5_d(this + 8)) <= 0 {
        return Some(false);
    }
    let mut j = 0i32;
    loop {
        let v = proximo(cpn5_d(this + 8));
        if v == 0 {
            return None;
        }
        if cpn5_d(v + 0xe) == cpn5_d(clube) {
            crate::comparacao::ramo("cpn_5 clube com vaga aberta");
            return Some(true);
        }
        j += 1;
        if j >= cpn5_w(cpn5_d(this + 8)) as i32 {
            return Some(false);
        }
    }
}

/// O `clube` está sem técnico (0x53ca90), pode ser dirigido (0x544820), não é o time B de um par (0x540a50 com 1
/// achando o parceiro com 0 em `eh_a`) e não tem vaga aberta? `None`: a caixa da lista.
unsafe fn cpn5_falta_vaga(this: usize, clube: usize, eh_a: &mut u32) -> Option<bool> {
    let tecnico: unsafe extern "C" fn(usize) -> usize = core::mem::transmute(0x53ca90usize);
    let dirigivel: unsafe extern "C" fn(usize) -> u8 = core::mem::transmute(0x544820usize);
    let parceiro: unsafe extern "C" fn(usize, *mut u32, u32) -> usize = core::mem::transmute(0x540a50usize);
    if tecnico(clube) != 0 || dirigivel(clube) == 0 {
        return Some(false);
    }
    if parceiro(clube, eh_a, 1) != 0 && *eh_a == 0 {
        return Some(false);
    }
    cpn5_tem_vaga(this, clube).map(|tem| !tem)
}

/// { 0x69d060 } (thiscall, ret 0, manager_manager.cpp): `MANAGER_MANAGER::fix_missing_jobs()`: cada clube
/// ([0xae23b4], 0x245 bytes, [0xae235c] relido a cada volta) sem técnico, dirigível, que não é time B e sem vaga
/// aberta (`cpn5_falta_vaga`) ganha o aviso "Job not found for %s" (nome +4) em [0xde1f64] e a vaga (0x69ba50 sem
/// técnico anterior). A lista que acaba antes da conta: a caixa "Error" (linha 0x311e) e a rotina acaba. Sem SEH, sem
/// sorteio; a local do parceiro começa em 0 uma vez só e só é lida quando a 0x540a50 o acha (e a grava).
unsafe extern "thiscall" fn abrir_vagas_que_faltam(this: usize) {
    let formatar: unsafe extern "C" fn(usize, usize, ...) -> i32 = core::mem::transmute(0x944c9fusize);
    let abrir: unsafe extern "thiscall" fn(usize, usize, usize) -> u32 = core::mem::transmute(0x69ba50usize);
    let mut eh_a = 0u32;
    let mut clube = cpn5_d(0xae23b4);
    let mut i = 0i32;
    while i < cpn5_d(0xae235c) as i32 {
        match cpn5_falta_vaga(this, clube, &mut eh_a) {
            None => {
                aviso_em(0x9f18a4, 0x311e);
                return;
            }
            Some(true) => {
                formatar(0xde1f64, 0xa05298, clube + 4);
                abrir(this, clube, 0);
            }
            Some(false) => {}
        }
        i += 1;
        clube += 0x245;
    }
}

/// { 0x69c540 } (thiscall, ret 8, manager_manager.cpp): `MANAGER_MANAGER::best_manager_candidate_score(clube,
/// atual)`: a maior nota de técnico (0x69d1b0 com 0 e o cargo 5) entre as pessoas ([0xae23bc], 0x6e bytes,
/// [0xae2364] relido a cada volta) com ficha da comissão (+0x69), das 16 últimas só as humanas (+0x5f), que não são o
/// `atual`, sem as marcas 0x30 no byte +0xb do registro de 79 bytes ([0xae2d0c]), sem contrato de empréstimo (0x4cf6d0),
/// que não são candidatas de outra vaga (0x69fc60), com nação (+0x1a) e o clube com nação (+0x53): de outra nação só
/// com reputação (+0x69 → +0xa) a partir de 3750; de outro continente (+0x75) com +0x69 → +0xc a partir de 4250 e o
/// clube com reputação (+0x80) a partir de 4750; jogador (+0x61) com clube (+0x39) e cargo 11, 12, 13 ou 15 não pode ter
/// contrato com o clube (0x4cf5f0) marcado em +0x49; e aceita para o cargo (0x69f810 com 3,5). Ninguém: −10000.
unsafe extern "thiscall" fn melhor_nota_de_candidato_a_tecnico(this: usize, clube: usize, atual: usize) -> i32 {
    let emprestimo: unsafe extern "thiscall" fn(usize, usize) -> usize = core::mem::transmute(0x4cf6d0usize);
    let candidato: unsafe extern "thiscall" fn(usize, usize) -> u8 = core::mem::transmute(0x69fc60usize);
    let contrato: unsafe extern "thiscall" fn(usize, usize, usize) -> usize = core::mem::transmute(0x4cf5f0usize);
    let serve: unsafe extern "thiscall" fn(usize, usize, usize, f64) -> u8 = core::mem::transmute(0x69f810usize);
    let nota_de: unsafe extern "thiscall" fn(usize, usize, usize, u32, u32) -> i32 = core::mem::transmute(0x69d1b0usize);
    let mut melhor = -10000i32;
    let mut p = cpn5_d(0xae23bc);
    let mut i = 0i32;
    while i < cpn5_d(0xae2364) as i32 {
        let reg79 = cpn5_d(0xae2d0c).wrapping_add((i as usize).wrapping_mul(0x4f));
        let pula = 'f: {
            if cpn5_d(p + 0x69) == 0 {
                break 'f true;
            }
            if i >= (cpn5_d(0xae2364) as i32).wrapping_sub(0x10) && cpn5_b(p + 0x5f) == 0 {
                break 'f true;
            }
            if atual == p {
                crate::comparacao::ramo("cpn_5 o tecnico atual fica de fora");
                break 'f true; // o atual fica de fora
            }
            if cpn5_b(reg79 + 0xb) & 0x30 != 0 || emprestimo(cpn5_d(0xae1050), p) != 0 || candidato(this, p) != 0 {
                break 'f true;
            }
            let (nc, np) = (cpn5_d(clube + 0x53), cpn5_d(p + 0x1a));
            if nc != np && cpn5_w(cpn5_d(p + 0x69) + 0xa) < 0xea6 {
                break 'f true;
            }
            if nc == 0 || np == 0 {
                break 'f true;
            }
            if cpn5_b(nc + 0x75) != cpn5_b(np + 0x75) && (cpn5_w(cpn5_d(p + 0x69) + 0xc) < 0x109a || cpn5_w(clube + 0x80) < 0x128e) {
                break 'f true;
            }
            if cpn5_d(p + 0x61) != 0 && cpn5_d(p + 0x39) != 0 && matches!(cpn5_b(p + 0x3d), 0xb | 0xc | 0xd | 0xf) {
                let k = contrato(cpn5_d(0xae1050), p, clube);
                if k != 0 && cpn5_b(k + 0x49) != 0 {
                    break 'f true;
                }
            }
            serve(this, p, clube, 3.5) == 0
        };
        if !pula {
            let s = nota_de(this, p, clube, 0, 5);
            if s > melhor {
                melhor = s;
            }
        }
        i += 1;
        p += 0x6e;
    }
    melhor
}

/// O plano do agendamento: a data da oferta (hoje [0xae2c90] + `dias`; com `dias` ≥ 50 a original mostra a caixa e
/// usa 10) com a fatia [0xae2c88] + `fatias` trazida para 0..2 (cada 3 fatias, mais um dia), e o balde da lista: os
/// dias desde a data base (+0x84d; ainda sem ano em +0x84f, hoje) mais o começo (+0x84c), módulo 50 de 50 a 127, × 3 +
/// fatia, nas listas de 14 bytes a partir de +0x18. Só lê (0x54c5b0 e 0x54cdb0 sobre cópias das datas).
unsafe fn cpn5_plano(this: usize, dias: u8, fatias: u8) -> ([u8; 8], i8, usize) {
    let somar: unsafe extern "thiscall" fn(usize, *mut u8, u32) -> usize = core::mem::transmute(0x54c5b0usize);
    let desde: unsafe extern "thiscall" fn(usize, u32, u32) -> i32 = core::mem::transmute(0x54cdb0usize);
    let base = if cpn5_w(this + 0x84f) == 0 { 0xae2c90 } else { this + 0x84d };
    let (b0, b1) = (cpn5_d(base) as u32, cpn5_d(base + 4) as u32);
    let dias = if dias as i8 >= 0x32 { 10 } else { dias as i8 };
    let (mut data, mut tmp) = ([0u8; 8], [0u8; 8]);
    // a 0x54c5b0 lê os dias em 16 bits (a original empurra o registro com lixo nos bits altos)
    let r = somar(0xae2c90, tmp.as_mut_ptr(), dias as i16 as i32 as u32);
    core::ptr::copy_nonoverlapping(r as *const u8, data.as_mut_ptr(), 8);
    let mut fatia = cpn5_b(0xae2c88).wrapping_add(fatias) as i8;
    while fatia > 2 {
        fatia -= 3;
        let r = somar(data.as_ptr() as usize, tmp.as_mut_ptr(), 1);
        core::ptr::copy_nonoverlapping(r as *const u8, data.as_mut_ptr(), 8);
    }
    let mut c = (desde(data.as_ptr() as usize, b0, b1) as u8).wrapping_add(cpn5_b(this + 0x84c));
    if c as i8 >= 0x32 {
        let q = (c as i8 as i32 as u32) / 50;
        c = c.wrapping_add((q as u8).wrapping_mul(0xce)); // − 50 × q
    }
    let balde = (c as i8 as i32).wrapping_mul(3).wrapping_add(fatia as i32);
    (data, fatia, this.wrapping_add(0x18).wrapping_add((balde as usize).wrapping_mul(14)))
}

/// { 0x8c6220 } (thiscall, ret 0xc, transfer_manager.cpp): `TRANSFER_MANAGER::schedule_offer(oferta, dias, fatias)`:
/// sem data base (ano +0x84f zerado), ela vira hoje (0x417c10 de [0xae2c90] em +0x84d) e a fatia +0x855 a de hoje
/// ([0xae2c88]); `dias` ≥ 50: a caixa "Error" (linha 0x18b9) e 10 dias. A oferta ganha a data (+0x12) e a fatia (+0x1a)
/// do plano (`cpn5_plano`) e o +0x20 dela (4 bytes) entra no balde (0x68d0d0, que aloca); devolve o que a 0x68d0d0
/// devolve. Sem SEH, sem sorteio.
unsafe extern "thiscall" fn agendar_oferta(this: usize, oferta: usize, dias: u32, fatias: u32) -> u32 {
    crate::comparacao::ramo("cpn_5 agendar oferta");
    if cpn5_w(this + 0x84f) == 0 {
        let copiar: unsafe extern "thiscall" fn(usize, *mut u8, usize) -> usize = core::mem::transmute(0x417c10usize);
        let mut tmp = [0u8; 8];
        copiar(this + 0x84d, tmp.as_mut_ptr(), 0xae2c90);
        *((this + 0x855) as *mut u8) = cpn5_b(0xae2c88);
    }
    if dias as u8 as i8 >= 0x32 {
        aviso_em(0xa8d514, 0x18b9);
    }
    // ponytail: as datas são feitas no plano sobre cópias (0x54c5b0, 0x54cdb0 e 0x417c10 só leem e copiam) e gravadas
    // de uma vez; a original grava a data e a fatia a cada volta da fatia, com o mesmo fim
    let (data, fatia, balde) = cpn5_plano(this, dias as u8, fatias as u8);
    core::ptr::copy_nonoverlapping(data.as_ptr(), (oferta + 0x12) as *mut u8, 8);
    *((oferta + 0x1a) as *mut i8) = fatia;
    let acrescentar: unsafe extern "thiscall" fn(usize, usize, u32) -> u32 = core::mem::transmute(0x68d0d0usize);
    acrescentar(balde, oferta + 0x20, 4)
}

/// Comparador: sem vaga a abrir (o plano pelo mesmo teste, com o cursor da lista devolvido), lado a lado pelo cursor
/// da lista; com vaga a abrir (ou a caixa), só a original.
unsafe extern "thiscall" fn comparar_abrir_vagas_que_faltam(this: usize) {
    let o = orig::<unsafe extern "thiscall" fn(usize)>(958);
    let l = cpn5_d(this + 8);
    let cursor = cpn5_d(l + 0xa);
    let mut eh_a = 0u32;
    let mut clube = cpn5_d(0xae23b4);
    let mut vazio = true;
    for _ in 0..(cpn5_d(0xae235c) as i32).max(0) {
        if cpn5_falta_vaga(this, clube, &mut eh_a) != Some(false) {
            vazio = false;
            break;
        }
        clube += 0x245;
    }
    core::ptr::write_unaligned((l + 0xa) as *mut usize, cursor);
    if !vazio {
        // ponytail: a 0x69ba50 abre a vaga (aloca, sorteia o candidato): não roda duas vezes; o modo Rust e a carreira provam
        return o(this);
    }
    let reg = [(l + 0xa, 4)];
    let (_, _, igual, mo, mr) = crate::comparacao::lado_a_lado_leve(&reg, || o(this), || abrir_vagas_que_faltam(this));
    PLACAR.registrar(igual, || format!("abrir_vagas_que_faltam (nenhuma a abrir) {:x?} x {:x?}", mo, mr));
}

/// Comparador: lado a lado a partir do mesmo estado do sorteio (a 0x69d1b0 e a 0x69f810 podem sortear), pela nota e
/// pelo cursor da lista de vagas (a 0x69fc60 o devolve).
unsafe extern "thiscall" fn comparar_melhor_nota_de_candidato_a_tecnico(this: usize, clube: usize, atual: usize) -> i32 {
    let o = orig::<unsafe extern "thiscall" fn(usize, usize, usize) -> i32>(959);
    let mut reg = crate::aleatorio::REGIOES_DO_ESTADO.to_vec();
    reg.push((cpn5_d(this + 8) + 0xa, 4));
    let (r, n, igual, mo, mr) = crate::comparacao::lado_a_lado(&reg, || o(this, clube, atual), || crate::aleatorio::sem_contar(|| melhor_nota_de_candidato_a_tecnico(this, clube, atual)));
    PLACAR.registrar(igual && r == n, || format!("melhor_nota_de_candidato_a_tecnico(clube {}, atual {:x}) original={} rust={} {:x?} x {:x?}", cpn5_d(clube), atual, r, n, mo, mr));
    r
}

/// Comparador: a original roda (a 0x68d0d0 aloca o nó) e o resultado é conferido com o plano feito antes: a data
/// (+0x12) e a fatia (+0x1a) da oferta, a conta do balde mais 1 e a data base (+0x84d, 8 bytes) igual a hoje quando
/// não havia.
unsafe extern "thiscall" fn comparar_agendar_oferta(this: usize, oferta: usize, dias: u32, fatias: u32) -> u32 {
    let sem_base = cpn5_w(this + 0x84f) == 0;
    let (data, fatia, balde) = cpn5_plano(this, dias as u8, fatias as u8);
    let conta = cpn5_w(balde);
    let r = orig::<unsafe extern "thiscall" fn(usize, usize, u32, u32) -> u32>(960)(this, oferta, dias, fatias);
    let gravada = core::slice::from_raw_parts((oferta + 0x12) as *const u8, 8);
    let base_ok = !sem_base || core::slice::from_raw_parts((this + 0x84d) as *const u8, 8) == core::slice::from_raw_parts(0xae2c90 as *const u8, 8);
    let ok = gravada == &data[..] && *((oferta + 0x1a) as *const i8) == fatia && cpn5_w(balde) == conta.wrapping_add(1) && base_ok;
    PLACAR.registrar(ok, || format!("agendar_oferta(dias {}, fatias {}): data {:x?} (plano {:x?}), fatia {} (plano {}), balde {:x} conta {} -> {}, base {}",
        dias as u8 as i8, fatias as u8 as i8, gravada, data, *((oferta + 0x1a) as *const i8), fatia, balde, conta, cpn5_w(balde), base_ok));
    r
}

// ---------- 250a leva: a lista de observação do clube: o estatuto no elenco que o clube dá à pessoa, a estimativa do clube humano e soltar os alvos que não são do clube (shortlist_manager.cpp) ----------

unsafe fn cpn6_d(a: usize) -> usize {
    core::ptr::read_unaligned(a as *const usize)
}

unsafe fn cpn6_b(a: usize) -> u8 {
    *(a as *const u8)
}

/// O clube do contrato `c` (id em +4; o registro de clube tem 0x245 bytes em [0xae23b4]), ou 0 sem contrato.
unsafe fn cpn6_clube_do_contrato(c: usize) -> usize {
    if c == 0 {
        return 0;
    }
    cpn6_d(0xae23b4).wrapping_add(cpn6_d(c + 4).wrapping_mul(0x245))
}

/// { 0x849f00 } (thiscall, ret 0xc, shortlist_manager.cpp): `Shortlist_Manager::get_squad_status_for_club(pessoa,
/// clube, cargo)`: o estatuto no elenco que o `clube` dá à `pessoa`. Clube nulo: 7. A entrada da pessoa na lista do
/// clube (0x849ce0: a de tipo ≠ 11 para jogador, +0x61; tendo +0x69, a de tipo 11 também): o cargo (+0 da entrada) e
/// os bits 1..4 do +0x24. Senão o cargo é o +0x3d da pessoa e vale o contrato (0x4cf5a0, guardado em [0xae1080]): do
/// próprio clube, o nibble alto do +0x4f do contrato com o clube (0x4cf5f0; sem ele, 7); clube humano (0x600a50) com
/// cargo 11 a 15 (0x53b620): a estimativa 0x849d60; senão, o clube da pessoa (+0x39) sendo o clube ou o parceiro dele
/// (0x540a50) leva ao contrato com o clube; nenhum: 7.
unsafe extern "thiscall" fn estatuto_no_elenco_pelo_clube(this: usize, pessoa: usize, clube: usize, cargo: *mut u8) -> u8 {
    if clube == 0 {
        return 7;
    }
    let entrada: unsafe extern "thiscall" fn(usize, usize, usize, u32, u32) -> usize = core::mem::transmute(0x849ce0usize);
    let mut e = entrada(this, clube, pessoa, (cpn6_d(pessoa + 0x61) == 0) as u32, 0);
    if e == 0 && cpn6_d(pessoa + 0x69) != 0 {
        e = entrada(this, clube, pessoa, 1, 0);
    }
    if e != 0 {
        if !cargo.is_null() {
            *cargo = cpn6_b(e);
        }
        crate::comparacao::ramo("cpn_6 estatuto pela lista");
        return (cpn6_b(e + 0x24) >> 1) & 0xf; // os bits 1..4 da entrada
    }
    if !cargo.is_null() {
        *cargo = cpn6_b(pessoa + 0x3d);
    }
    let contrato_de: unsafe extern "thiscall" fn(usize, usize) -> usize = core::mem::transmute(0x4cf5a0usize);
    let c = contrato_de(cpn6_d(0xae1050), pessoa);
    *(0xae1080 as *mut usize) = c;
    let pelo_contrato = if cpn6_clube_do_contrato(c) == clube {
        true
    } else {
        // ponytail: o 3º argumento é empurrado como dword 1; o cargo vai num byte (a 0x53b620 só lê o byte)
        let humano: unsafe extern "C" fn(usize, u32, u32, usize, u32) -> u32 = core::mem::transmute(0x600a50usize);
        let tipo_11_a_15: unsafe extern "C" fn(i8) -> u32 = core::mem::transmute(0x53b620usize);
        if humano(clube, 1, 1, 0, 0) != 0 && tipo_11_a_15(cpn6_b(pessoa + 0x3d) as i8) != 0 {
            let estimar: unsafe extern "stdcall" fn(usize, usize) -> u32 = core::mem::transmute(0x849d60usize);
            return estimar(pessoa, clube) as u8;
        }
        cpn6_d(pessoa + 0x39) == clube || {
            let parceiro: unsafe extern "C" fn(usize, usize, u32) -> usize = core::mem::transmute(0x540a50usize);
            cpn6_d(pessoa + 0x39) == parceiro(clube, 0, 1)
        }
    };
    if !pelo_contrato {
        return 7;
    }
    let com_clube: unsafe extern "thiscall" fn(usize, usize, usize) -> usize = core::mem::transmute(0x4cf5f0usize);
    let k = com_clube(cpn6_d(0xae1050), pessoa, clube);
    if k == 0 {
        return 7;
    }
    crate::comparacao::ramo("cpn_6 estatuto pelo contrato");
    cpn6_b(k + 0x4f) >> 4 // o nibble alto do contrato
}

/// { 0x849d60 } (stdcall, ret 8, shortlist_manager.cpp): `shortlist_manager_estimate_squad_status(pessoa, clube)`: o
/// estatuto que o clube humano daria. A reputação da pessoa vista pelo técnico do clube (0x53ca90, 0x5407e0; até 1:
/// 1, senão as duas chamadas de novo) e a do clube (+0x80, no mínimo 1); pessoa na lista do humano (0x7f7490 do
/// [0xb74448]): a reputação passa a ser o maior de 1,5 × ela e 0,75 × a do clube (truncado, 16 bits). A razão (limitada
/// a 0,1..2): acima de 1,5: 1; o float dela acima de 1,2 com o clube abaixo de 8500: 2; até 1,2 com a reputação até
/// 6500: 5 (acima de 0,6 e idade +0x18 abaixo de 23), 4 (24 ou mais) ou 6; senão 3. Só roda para o clube humano.
unsafe extern "stdcall" fn estimar_estatuto_no_elenco(pessoa: usize, clube: usize) -> u32 {
    let tecnico: unsafe extern "C" fn(usize) -> usize = core::mem::transmute(0x53ca90usize);
    let reputacao: unsafe extern "C" fn(usize, usize, u32) -> u16 = core::mem::transmute(0x5407e0usize);
    let mut rep = if reputacao(pessoa, tecnico(clube), 0) as i16 > 1 { reputacao(pessoa, tecnico(clube), 0) as i16 } else { 1 };
    let mut rc = core::ptr::read_unaligned((clube + 0x80) as *const i16);
    if rc <= 1 {
        rc = 1;
    }
    let t = tecnico(clube);
    let na_lista: unsafe extern "thiscall" fn(usize, usize, usize) -> u32 = core::mem::transmute(0x7f7490usize);
    if na_lista(cpn6_d(0xb74448), pessoa, t) != 0 {
        let a = rep as f64 * f64_em(0x968940);
        let b = rc as f64 * f64_em(0x969040);
        rep = ftol(if a > b { a } else { b }) as i16;
    }
    let mut q = rep as f64 / rc as f64;
    if q < f64_em(0x967880) {
        q = f64_em(0x967880);
    } else if !(q <= f64_em(0x968950)) {
        q = f64_em(0x968950);
    }
    let f = q as f32 as f64; // a original guarda a razão num float e compara o resto por ele
    if q > f64_em(0x968940) {
        return 1;
    }
    if f > f64_em(0x968978) && rc < 0x2134 {
        return 2;
    }
    let idade = cpn6_b(pessoa + 0x18) as i8;
    if !(f > f64_em(0x968978)) && rep <= 0x1964 {
        if f > f64_em(0x968e48) && idade < 0x17 {
            return 5;
        }
        return if idade >= 0x18 { 4 } else { 6 };
    }
    3
}

/// { 0x844660 } (thiscall, ret 8, shortlist_manager.cpp): `shortlist_manager_release_club_slot_targets(clube,
/// entrada)`: nas 40 vagas de 0x25 bytes de [entrada], o alvo (+0xf) acima do último id de pessoa ([0xae2364] − 1)
/// vira −1; o alvo válido cujo contrato (0x4cf5a0, guardado em [0xae1080]; o de tipo 5 em +0x35 não conta) não é do
/// clube, nem o clube dele (+0x39) é o clube, e com o +0x17 da vaga em −1: o evento 3 da lista (0x843e10) com o tipo
/// "não é 11" do +0 da vaga (no byte baixo do endereço da vaga, como a original).
unsafe extern "thiscall" fn liberar_alvos_da_lista_do_clube(this: usize, clube: usize, entrada: usize) {
    let contrato_de: unsafe extern "thiscall" fn(usize, usize) -> usize = core::mem::transmute(0x4cf5a0usize);
    let atualizar: unsafe extern "thiscall" fn(usize, usize, usize, u32, u32) -> u32 = core::mem::transmute(0x843e10usize);
    for k in 0..40usize {
        let o = k * 0x25;
        let v = cpn6_d(entrada).wrapping_add(o + 0xf);
        if cpn6_d(v) as i32 > (*(0xae2364 as *const i32)).wrapping_sub(1) {
            core::ptr::write_unaligned(v as *mut i32, -1);
        }
        let id = cpn6_d(cpn6_d(entrada).wrapping_add(o + 0xf)) as i32;
        if id <= -1 {
            continue;
        }
        let p = cpn6_d(0xae23bc).wrapping_add((id as usize).wrapping_mul(0x6e));
        let c = contrato_de(cpn6_d(0xae1050), p);
        *(0xae1080 as *mut usize) = c;
        let do_contrato = if c != 0 && cpn6_b(c + 0x35) & 0x3f != 5 { cpn6_clube_do_contrato(c) } else { 0 };
        if do_contrato == clube || cpn6_d(p + 0x39) == clube {
            continue;
        }
        let s = cpn6_d(entrada).wrapping_add(o);
        if cpn6_d(s + 0x17) as i32 != -1 {
            continue;
        }
        // setne al sobre o endereço da vaga: os 24 bits altos são os dele
        let tipo = ((s & !0xff) | (cpn6_b(s) != 0xb) as usize) as u32;
        crate::comparacao::ramo("cpn_6 alvo fora do clube");
        atualizar(this, p, clube, 3, tipo);
    }
}

/// Comparador: lado a lado pelo estatuto, pelo cargo de saída e por [0xae1080].
unsafe extern "thiscall" fn comparar_estatuto_no_elenco_pelo_clube(this: usize, pessoa: usize, clube: usize, cargo: *mut u8) -> u8 {
    let o = orig::<unsafe extern "thiscall" fn(usize, usize, usize, *mut u8) -> u8>(961);
    let saida = if cargo.is_null() { 0xae1080 } else { cargo as usize };
    let reg = [(0xae1080usize, 4usize), (saida, 1)];
    let (r, n, igual, mo, mr) = crate::comparacao::lado_a_lado_leve(&reg, || o(this, pessoa, clube, cargo), || estatuto_no_elenco_pelo_clube(this, pessoa, clube, cargo));
    PLACAR.registrar(igual && r == n, || format!("estatuto_no_elenco_pelo_clube({:#x}, {:#x}) original={} rust={} {:x?} x {:x?}", pessoa, clube, r, n, mo, mr));
    r
}

/// Comparador: pelo valor (o byte baixo; a original deixa a palavra de estado do x87 em ah).
unsafe extern "stdcall" fn comparar_estimar_estatuto_no_elenco(pessoa: usize, clube: usize) -> u32 {
    let r = orig::<unsafe extern "stdcall" fn(usize, usize) -> u32>(962)(pessoa, clube);
    let n = estimar_estatuto_no_elenco(pessoa, clube);
    PLACAR.registrar(r as u8 == n as u8, || format!("estimar_estatuto_no_elenco({:#x}, {:#x}) original={:#x} rust={}", pessoa, clube, r, n));
    r
}

/// Comparador: só a original.
// ponytail: a 0x843e10 muda a lista do clube (e outras) a cada evento e não pode rodar duas vezes; a cópia tem o ramo
// e a prova é pela carreira (modo Rust contra a original).
unsafe extern "thiscall" fn comparar_liberar_alvos_da_lista_do_clube(this: usize, clube: usize, entrada: usize) {
    orig::<unsafe extern "thiscall" fn(usize, usize, usize)>(963)(this, clube, entrada)
}

// ---------- 250a leva: a busca do olheiro e os amistosos: se a busca cobre a nação, tirar o amistoso marcado e os pares de nações que não jogam amistoso (player_search.cpp, friendly.cpp) ----------

unsafe fn cpn7_d(a: usize) -> usize {
    core::ptr::read_unaligned(a as *const usize)
}

unsafe fn cpn7_por(a: usize, v: usize) {
    core::ptr::write_unaligned(a as *mut usize, v);
}

unsafe fn cpn7_b(a: usize) -> u8 {
    *(a as *const u8)
}

/// { 0x7b7490 } (thiscall, ret 4, player_search.cpp): `PLAYER_SEARCH::scout_covers_nation(nacao)`: a busca de olheiro
/// (tipo +0xa = 4) com o olheiro conferido (índice +0x180 > −1 e 0x53e990 com os nomes +0x174..+0x17c e a data +0x184)
/// e com clube (+0x39) cobre a `nacao`? Com missão marcada (0x7aefd0, que copia as missões +0x18c..+0x19d sobre elas
/// mesmas): a nação do clube da missão (+0x53 do clube +0x190), a nação da missão (+0x18c = id +0 da nação), a região
/// (+0x194, byte com sinal, = +0x76 da nação), ou com a base (+0x199) a mesma região. Sem missão: as duas nações com
/// +0x7f = 2, a mesma região (+0x76) da nação do clube, a nação não estrangeira para o olheiro (0x53d980 com 1) ou os
/// olheiros do clube cobrindo a nação (0x7f9190 do [0xb74448]). Devolve 1 ou 0.
unsafe extern "thiscall" fn busca_cobre_a_nacao(this: usize, nacao: usize) -> u32 {
    let mut pessoa = 0usize;
    let i = cpn7_d(this + 0x180) as i32;
    if i > -1 {
        let confere: unsafe extern "C" fn(usize, usize, usize, usize, usize) -> u32 = core::mem::transmute(0x53e990usize);
        let p = cpn7_d(0xae23bc).wrapping_add((i as usize).wrapping_mul(0x6e));
        if confere(p, cpn7_d(this + 0x174), cpn7_d(this + 0x178), cpn7_d(this + 0x17c), this + 0x184) != 0 {
            pessoa = cpn7_d(0xae23bc).wrapping_add(cpn7_d(this + 0x180).wrapping_mul(0x6e));
        }
    }
    if cpn7_b(this + 0xa) != 4 || pessoa == 0 || nacao == 0 {
        return 0;
    }
    let clube = cpn7_d(pessoa + 0x39);
    if clube == 0 {
        return 0;
    }
    let missao: unsafe extern "thiscall" fn(usize, usize, usize, usize, usize, usize, usize) -> u32 = core::mem::transmute(0x7aefd0usize);
    if missao(this, this + 0x190, this + 0x18c, this + 0x194, this + 0x195, this + 0x199, this + 0x19d) != 0 {
        let c = cpn7_d(this + 0x190) as i32;
        if c > -1 && cpn7_d(cpn7_d(0xae23b4).wrapping_add((c as usize).wrapping_mul(0x245)) + 0x53) == nacao {
            return 1;
        }
        let n = cpn7_d(this + 0x18c) as i32;
        if n > -1 && cpn7_d(nacao) as i32 == n {
            return 1;
        }
        let r = cpn7_b(this + 0x194);
        if (r as i8) > -1 && cpn7_b(nacao + 0x76) == r {
            return 1;
        }
        // a original compara de novo o mesmo byte quando há base
        if cpn7_d(this + 0x199) != 0 && cpn7_b(nacao + 0x76) == r {
            return 1;
        }
        return 0;
    }
    let nc = cpn7_d(clube + 0x53);
    if cpn7_b(nc + 0x7f) == 2 && cpn7_b(nacao + 0x7f) == 2 {
        return 1;
    }
    if cpn7_b(nc + 0x76) == cpn7_b(nacao + 0x76) {
        crate::comparacao::ramo("cpn_7 mesma regiao");
        return 1; // a mesma região da nação do clube
    }
    let estrangeira: unsafe extern "C" fn(usize, usize, u32) -> u32 = core::mem::transmute(0x53d980usize);
    if estrangeira(pessoa, nacao, 1) == 0 {
        crate::comparacao::ramo("cpn_7 nacao do olheiro");
        return 1; // a nação não é estrangeira para o olheiro
    }
    let cobrem: unsafe extern "thiscall" fn(usize, usize, usize) -> u32 = core::mem::transmute(0x7f9190usize);
    (cobrem(cpn7_d(0xb74448), nacao, clube) != 0) as u32
}

/// { 0x5c87b0 } (thiscall, ret 8, friendly.cpp): `Friendly::remove_friendly_match(jogo, limpar_vaga)`: tira da lista
/// [+0x34d4] cada item que aponta para o `jogo` (0x68d1f0; o cursor +0xa volta ao começo antes, depois de cada um e no
/// fim), com `limpar_vaga` zera a vaga do amistoso marcado (0x5c6740 pelo dia +0, ano +2, clube +0x14 e adversário
/// +0x10 do jogo: +0x10 = 0 e +0x18 = 0) e tira o jogo da lista [+0x34c8] (0x68d1f0, que o libera). Jogo nulo ou sem
/// a lista +0x34c8: a original (caixa "Error").
unsafe extern "thiscall" fn tirar_amistoso_marcado(this: usize, jogo: usize, limpar_vaga: u32) -> u32 {
    if jogo == 0 || cpn7_d(this + 0x34c8) == 0 {
        return orig::<unsafe extern "thiscall" fn(usize, usize, u32) -> u32>(965)(this, jogo, limpar_vaga);
    }
    let proximo: unsafe extern "thiscall" fn(usize) -> usize = core::mem::transmute(0x68d1b0usize);
    let tirar: unsafe extern "thiscall" fn(usize, usize) -> u32 = core::mem::transmute(0x68d1f0usize);
    let recomecar = || {
        let l = cpn7_d(this + 0x34d4);
        cpn7_por(l + 0xa, cpn7_d(l + 2));
    };
    if cpn7_d(this + 0x34d4) != 0 {
        recomecar();
        let mut e = proximo(cpn7_d(this + 0x34d4));
        while e != 0 {
            if cpn7_d(e) == jogo {
                tirar(cpn7_d(this + 0x34d4), e);
                recomecar();
            }
            e = proximo(cpn7_d(this + 0x34d4));
        }
        recomecar();
    }
    if limpar_vaga != 0 {
        // ponytail: a original empurra dia e ano em registradores com os 16 bits altos de outros valores; a 0x5c6740 só
        // lê os 16 bits baixos
        let vaga: unsafe extern "thiscall" fn(usize, u32, u32, usize, usize) -> usize = core::mem::transmute(0x5c6740usize);
        let v = vaga(this, *(jogo as *const u16) as u32, *((jogo + 2) as *const u16) as u32, cpn7_d(jogo + 0x14), cpn7_d(jogo + 0x10));
        if v != 0 {
            cpn7_por(v + 0x10, 0);
            *((v + 0x18) as *mut u8) = 0;
        }
    }
    crate::comparacao::ramo("cpn_7 tirar o amistoso");
    tirar(cpn7_d(this + 0x34c8), jogo) // tira o jogo da lista dos amistosos
}

/// { 0x5cc2d0 } (thiscall, friendly.cpp): `Friendly::init_banned_nation_pairs()`: +0x3506 = 4 pares e +0x3502 um vetor
/// novo de 0x20 bytes (malloc 0x944e46) com os pares de nações que não jogam amistoso entre si: Irã e EUA, Iraque e
/// qualquer uma (−1), Vietnã e EUA, as duas Coreias (as chaves [0x9cf354], [0x9cf4f8], [0x9cf358], [0x9cf508],
/// [0x9cf404], [0x9cf484]). Sem memória: a caixa "Error" (linha 0x1800) e +0x3506 = 0.
unsafe extern "thiscall" fn iniciar_pares_proibidos_de_amistoso(this: usize) {
    *((this + 0x3506) as *mut u8) = 4;
    let alocar: unsafe extern "C" fn(u32) -> usize = core::mem::transmute(0x944e46usize);
    let v = alocar(0x20);
    cpn7_por(this + 0x3502, v);
    if v == 0 {
        aviso_em(0x9cd0a0, 0x1800);
        *((this + 0x3506) as *mut u8) = 0;
        return;
    }
    for (k, chave) in [0x9cf354usize, 0x9cf4f8, 0x9cf358, 0, 0x9cf508, 0x9cf4f8, 0x9cf404, 0x9cf484].into_iter().enumerate() {
        cpn7_por(cpn7_d(this + 0x3502) + 4 * k, if chave == 0 { usize::MAX } else { cpn7_d(chave) });
    }
}

/// Comparador: lado a lado pelo valor e pelas missões +0x18c..+0x1a0 (a 0x7aefd0 as copia sobre elas mesmas).
unsafe extern "thiscall" fn comparar_busca_cobre_a_nacao(this: usize, nacao: usize) -> u32 {
    let o = orig::<unsafe extern "thiscall" fn(usize, usize) -> u32>(964);
    let reg = [(this + 0x18c, 0x15)];
    let (r, n, igual, mo, mr) = crate::comparacao::lado_a_lado_leve(&reg, || o(this, nacao), || busca_cobre_a_nacao(this, nacao));
    PLACAR.registrar(igual && r == n, || format!("busca_cobre_a_nacao(nacao {:#x}) original={} rust={} {:x?} x {:x?}", nacao, r, n, mo, mr));
    r
}

/// Comparador: a 0x68d1f0 libera o que tira: o plano antes (os itens que ficam nas duas listas e a vaga do amistoso);
/// a original roda; confere as listas, o cursor da +0x34d4 no começo e a vaga zerada. Jogo nulo ou sem a lista
/// +0x34c8: só a original (a caixa).
unsafe extern "thiscall" fn comparar_tirar_amistoso_marcado(this: usize, jogo: usize, limpar_vaga: u32) -> u32 {
    let o = orig::<unsafe extern "thiscall" fn(usize, usize, u32) -> u32>(965);
    if jogo == 0 || cpn7_d(this + 0x34c8) == 0 {
        return o(this, jogo, limpar_vaga);
    }
    // ponytail: a 0x68d1f0 acha o nó pelo conteúdo do item; o plano supõe itens de conteúdo distinto (o normal)
    let l4 = cpn7_d(this + 0x34d4);
    let esperado4: Vec<usize> = if l4 != 0 { cpd1_itens(l4).into_iter().filter(|&e| cpn7_d(e) != jogo).collect() } else { Vec::new() };
    let mut esperado8 = cpd1_itens(cpn7_d(this + 0x34c8));
    if let Some(k) = esperado8.iter().position(|&e| e == jogo) {
        esperado8.remove(k);
    }
    let v = if limpar_vaga != 0 {
        let vaga: unsafe extern "thiscall" fn(usize, u32, u32, usize, usize) -> usize = core::mem::transmute(0x5c6740usize);
        vaga(this, *(jogo as *const u16) as u32, *((jogo + 2) as *const u16) as u32, cpn7_d(jogo + 0x14), cpn7_d(jogo + 0x10))
    } else {
        0
    };
    let r = o(this, jogo, limpar_vaga);
    let l4 = cpn7_d(this + 0x34d4);
    let itens4 = if l4 != 0 { cpd1_itens(l4) } else { Vec::new() };
    let itens8 = cpd1_itens(cpn7_d(this + 0x34c8));
    let ok = itens4 == esperado4
        && (l4 == 0 || cpn7_d(l4 + 0xa) == cpn7_d(l4 + 2))
        && itens8 == esperado8
        && (v == 0 || (cpn7_d(v + 0x10) == 0 && cpn7_b(v + 0x18) == 0));
    PLACAR.registrar(ok, || format!("tirar_amistoso_marcado({:#x}, {}) itens {} e {} (esperava {} e {}), vaga {:#x}", jogo, limpar_vaga, itens4.len(), itens8.len(), esperado4.len(), esperado8.len(), v));
    r
}

/// Comparador: o malloc não pode rodar duas vezes: a original roda e confere o vetor e a conta com o plano.
unsafe extern "thiscall" fn comparar_iniciar_pares_proibidos_de_amistoso(this: usize) {
    orig::<unsafe extern "thiscall" fn(usize)>(966)(this);
    let v = cpn7_d(this + 0x3502);
    let ok = if v == 0 {
        cpn7_b(this + 0x3506) == 0
    } else {
        let esperado = [cpn7_d(0x9cf354), cpn7_d(0x9cf4f8), cpn7_d(0x9cf358), usize::MAX, cpn7_d(0x9cf508), cpn7_d(0x9cf4f8), cpn7_d(0x9cf404), cpn7_d(0x9cf484)];
        cpn7_b(this + 0x3506) == 4 && (0..8).all(|k| cpn7_d(v + 4 * k) == esperado[k])
    };
    PLACAR.registrar(ok, || format!("iniciar_pares_proibidos_de_amistoso: conta {} vetor {:#x}", cpn7_b(this + 0x3506), v));
}

// ---------- 249a leva: a copa: quem passa no jogo e no confronto e a ordem dos cabeças de chave no sorteio (Cup.cpp) ----------

unsafe fn cpm1_b(a: usize) -> i8 {
    *(a as *const i8)
}

unsafe fn cpm1_por(a: usize, v: i8) {
    *(a as *mut i8) = v;
}

unsafe fn cpm1_w(a: usize) -> i16 {
    core::ptr::read_unaligned(a as *const i16)
}

unsafe fn cpm1_d(a: usize) -> usize {
    core::ptr::read_unaligned(a as *const usize)
}

/// O corpo da 0x51c020: `Some(lado)`, ou `None` no empate também nos pênaltis com a regra deles (a original mostra a
/// caixa "Error" com a linha 0x97e e segue para W.O. e pontos): quem chama roda a original inteira, que refaz o único
/// que já foi gravado (+0x3d/+0x3e = 1 com o bit 0x10, idempotente).
unsafe fn cpm1_jogo(this: usize, f: usize) -> Option<u32> {
    let fl = cpm1_w(f + 0x38) as u16;
    if fl & 0x10 != 0 {
        cpm1_por(f + 0x3d, 1);
        cpm1_por(f + 0x3e, 1);
    }
    let (g1, g2) = (cpm1_b(f + 0x43), cpm1_b(f + 0x44));
    if g1 > g2 {
        if cpm1_b(f + 0x3d) == 1 {
            cpm1_por(f + 0x3d, 2);
        }
        if fl & 0x2000 != 0 {
            cpm1_por(f + 0x3d, cpm1_b(f + 0x3d).wrapping_sub(3));
        }
        return Some(1);
    }
    if g1 < g2 {
        if cpm1_b(f + 0x3e) == 1 {
            cpm1_por(f + 0x3e, 2);
        }
        if fl & 0x2000 != 0 {
            cpm1_por(f + 0x3e, cpm1_b(f + 0x3e).wrapping_sub(3));
        }
        return Some(2);
    }
    if fl & 2 != 0 {
        let (a1, a2) = (cpm1_b(f + 0x47), cpm1_b(f + 0x48));
        if a1 > a2 {
            crate::comparacao::ramo("cpm_1 jogo na prorrogacao");
            let c = cpm1_b(f + 0x3d);
            if c == 1 {
                cpm1_por(f + 0x3d, 2);
            } else if fl & 0x2000 != 0 {
                cpm1_por(f + 0x3d, c.wrapping_sub(3));
            } else {
                cpm1_por(f + 0x3d, 3);
            }
            return Some(1); // o mandante na prorrogação
        }
        if a1 < a2 {
            let c = cpm1_b(f + 0x3e);
            if c == 1 {
                cpm1_por(f + 0x3e, 2);
            } else if fl & 0x2000 != 0 {
                cpm1_por(f + 0x3e, c.wrapping_sub(3));
            } else {
                cpm1_por(f + 0x3e, 3);
            }
            return Some(2); // o visitante na prorrogação
        }
    }
    if fl & 0x21 != 0 {
        let (p1, p2) = (cpm1_b(f + 0x49), cpm1_b(f + 0x4a));
        // o código dos pênaltis: 4, ou 5 sem o bit 1 da regra (not al; and al, 1; or al, 4)
        let penaltis = ((!(fl as u8)) & 1 | 4) as i8;
        if p1 > p2 {
            let c = cpm1_b(f + 0x3d);
            if c == 1 {
                cpm1_por(f + 0x3d, 2);
            } else if fl & 0x2000 != 0 {
                cpm1_por(f + 0x3d, c.wrapping_sub(3));
            } else {
                cpm1_por(f + 0x3d, penaltis);
            }
            return Some(1);
        }
        if p1 < p2 {
            let c = cpm1_b(f + 0x3e);
            if c == 1 {
                cpm1_por(f + 0x3e, 2);
            } else if fl & 0x2000 != 0 {
                cpm1_por(f + 0x3e, c.wrapping_sub(3));
            } else {
                cpm1_por(f + 0x3e, penaltis);
            }
            return Some(2);
        }
        return None; // empate nos pênaltis: a caixa da original
    }
    if fl & 0x800 != 0 {
        cpm1_por(f + 0x3d, 8); // W.O. a favor do mandante
        return Some(1);
    }
    if fl & 0x1000 != 0 {
        cpm1_por(f + 0x3e, 8);
        return Some(2);
    }
    if fl & 0x2000 == 0 {
        return Some(0);
    }
    let a = cpm1_b(f + 0x3d).wrapping_sub(1);
    let c = cpm1_b(f + 0x3e).wrapping_sub(1);
    cpm1_por(f + 0x3d, a);
    cpm1_por(f + 0x3e, c);
    if a < c {
        return Some(1);
    }
    if a > c {
        return Some(2);
    }
    // empate nos pontos: o cabeça de chave menor (byte +4 da entrada de 6 bytes [this+0xa7], +0x3e entradas)
    let n = cpm1_w(this + 0x3e);
    if n <= 0 {
        return Some(2);
    }
    let (c1, c2) = (cpm1_d(f + 0x1c), cpm1_d(f + 0x20));
    let (mut s1, mut s2) = (0i8, 0i8);
    let t = cpm1_d(this + 0xa7);
    for k in 0..n as usize {
        let e = t + 6 * k;
        if cpm1_d(e) == c1 {
            s1 = cpm1_b(e + 4);
        }
        if cpm1_d(e) == c2 {
            s2 = cpm1_b(e + 4);
        }
    }
    Some(if s1 < s2 { 1 } else { 2 })
}

/// { 0x51c020 } (thiscall, ret 4, Cup.cpp): `Cup::decide_fixture_winner(jogo)`: quem passa num jogo de copa (1
/// mandante, 2 visitante, 0 ninguém) pela regra (+0x38): o placar (+0x43/+0x44), a prorrogação (bit 2, +0x47/+0x48), os
/// pênaltis (bits 0x21, +0x49/+0x4a), o W.O. (0x800/0x1000) e os pontos (0x2000: os códigos −1 e o cabeça de chave),
/// gravando o código de cada lado (+0x3d/+0x3e: 2 venceu, 3 na prorrogação, 4/5 nos pênaltis, 8 W.O.; −3 com 0x2000).
/// Jogo nulo ou empate nos pênaltis: a original (caixa "Error").
unsafe extern "thiscall" fn decidir_jogo_da_copa(this: usize, jogo: usize) -> u32 {
    if jogo != 0 {
        if let Some(r) = cpm1_jogo(this, jogo) {
            return r;
        }
    }
    orig::<unsafe extern "thiscall" fn(usize, usize) -> u32>(925)(this, jogo)
}

/// O corpo da 0x51f2f0: `None` no empate nos pênaltis com a regra deles (a original mostra a caixa "Error" com a linha
/// 0x11d1 e devolve 4; nada foi gravado antes).
unsafe fn cpm1_confronto(conf: usize, j: usize) -> Option<u32> {
    let t = |k: usize| cpm1_b(conf + k);
    let fl = cpm1_w(j + 0x38) as u16;
    if t(0x33) as u8 != 1 {
        // primeiro jogo (ou jogo único) do confronto: 3
        if fl & 0x10 != 0 {
            let lado1 = if t(0x14) != t(0x15) {
                t(0x14) > t(0x15)
            } else if t(0x18) != t(0x19) {
                t(0x18) > t(0x19)
            } else {
                t(0x1a) > t(0x1b)
            };
            cpm1_por(j + if lado1 { 0x3d } else { 0x3e }, 1);
        } else if fl & 0x2000 != 0 {
            let pares = [(0x14, 0x15), (0x18, 0x19), (0x1a, 0x1b)];
            match pares.iter().find(|p| t(p.0) != t(p.1)) {
                Some(&(a, b)) => {
                    let lado = if t(a) > t(b) { 0x3d } else { 0x3e };
                    cpm1_por(j + lado, cpm1_b(j + lado).wrapping_sub(3));
                }
                None => {
                    cpm1_por(j + 0x3d, cpm1_b(j + 0x3d).wrapping_sub(1));
                    cpm1_por(j + 0x3e, cpm1_b(j + 0x3e).wrapping_sub(1));
                }
            }
        }
        return Some(3);
    }
    // o jogo de volta: o agregado (os gols +0x14 e +0x1f contra +0x1e e +0x15, em 16 bits)
    let tot1 = (t(0x14) as i16).wrapping_add(t(0x1f) as i16);
    let tot2 = (t(0x1e) as i16).wrapping_add(t(0x15) as i16);
    let volta2 = t(0x15) as i16;
    if fl & 0x10 != 0 {
        // pontos: quem venceu cada jogo (placar, prorrogação, pênaltis); um de cada: 4
        let lado_volta = if t(0x14) != t(0x15) {
            t(0x14) > t(0x15)
        } else if t(0x18) != t(0x19) {
            t(0x18) > t(0x19)
        } else {
            t(0x1a) > t(0x1b)
        };
        let lado_ida = if t(0x1e) != t(0x1f) {
            t(0x1e) > t(0x1f)
        } else if t(0x22) != t(0x23) {
            t(0x22) > t(0x23)
        } else {
            t(0x24) > t(0x25)
        };
        if lado_volta == lado_ida {
            cpm1_por(j + 0x3d, 1);
            cpm1_por(j + 0x3e, 1);
            return Some(4);
        }
        if lado_volta {
            cpm1_por(j + 0x3e, 2);
            return Some(2);
        }
        cpm1_por(j + 0x3d, 2);
        return Some(1);
    }
    if fl & 0x2000 != 0 {
        let pares = [(0x43, 0x44), (0x47, 0x48), (0x49, 0x4a)];
        match pares.iter().find(|p| cpm1_b(j + p.0) != cpm1_b(j + p.1)) {
            Some(&(a, b)) => {
                let lado = if cpm1_b(j + a) > cpm1_b(j + b) { 0x3d } else { 0x3e };
                cpm1_por(j + lado, cpm1_b(j + lado).wrapping_sub(3));
            }
            None => {
                cpm1_por(j + 0x3d, cpm1_b(j + 0x3d).wrapping_sub(1));
                cpm1_por(j + 0x3e, cpm1_b(j + 0x3e).wrapping_sub(1));
            }
        }
        if cpm1_b(j + 0x3d) < -5 {
            return Some(1);
        }
        return Some(if cpm1_b(j + 0x3e) >= -5 { 4 } else { 2 });
    }
    if tot1 > tot2 {
        return Some(2); // agregado
    }
    if tot1 < tot2 {
        return Some(1);
    }
    crate::comparacao::ramo("cpm_1 confronto empatado no agregado");
    if fl & 0x800 != 0 {
        cpm1_por(j + 0x3d, 8);
        return Some(1);
    }
    if fl & 0x1000 != 0 {
        cpm1_por(j + 0x3e, 8);
        return Some(2);
    }
    if fl & 2 != 0 && t(0x22) as u8 != 0xff {
        if fl & 0x4000 != 0 && (t(0x22) as i32 + t(0x15) as i32) == (t(0x23) as i32 + t(0x14) as i32) {
            if t(0x23) > t(0x15) {
                cpm1_por(j + 0x3e, 6);
                return Some(2);
            }
            if t(0x23) < t(0x15) {
                cpm1_por(j + 0x3d, 6);
                return Some(1);
            }
        }
        let x = t(0x23) as i32 - t(0x1f) as i32;
        let y = t(0x22) as i32 - t(0x1e) as i32;
        if y > x {
            cpm1_por(j + 0x3d, 3);
            return Some(1);
        }
        if y < x {
            cpm1_por(j + 0x3e, 3);
            return Some(2);
        }
    }
    if fl & 4 == 0 && fl & 0x4000 == 0 {
        // os gols fora (o visitante da volta, +0x15, contra o da ida, +0x1f)
        let fora = t(0x1f) as i16;
        if volta2 < fora {
            cpm1_por(j + 0x3e, 6);
            return Some(2);
        }
        if volta2 > fora {
            cpm1_por(j + 0x3d, 6);
            return Some(1);
        }
    }
    if fl & 0x21 == 0 {
        return Some(4);
    }
    let (p1, p2) = (t(0x24), t(0x25));
    let codigo = if fl & 1 != 0 { 4 } else { 5 };
    if p2 < p1 {
        cpm1_por(j + 0x3d, codigo);
        return Some(1);
    }
    if p2 > p1 {
        cpm1_por(j + 0x3e, codigo);
        return Some(2);
    }
    None
}

/// { 0x51f2f0 } (thiscall, ret 8, Cup.cpp; `this` não é lido): `Cup::decide_tie_winner(confronto, jogo)`: no primeiro
/// jogo (+0x33 ≠ 1), só marca o vencedor (pontos 0x10: código 1; 0x2000: −3, ou −1 nos dois) e devolve 3. Na volta,
/// pelo agregado (+0x14 + +0x1f contra +0x1e + +0x15): 2 o primeiro lado à frente, 1 o segundo; empatado: W.O.
/// (0x800/0x1000, código 8), a prorrogação (bit 2 com +0x22 ≠ 0xff: com 0x4000 os gols fora dela; código 6, senão a
/// diferença da prorrogação, código 3), os gols fora (sem 4 nem 0x4000, código 6) e os pênaltis (0x21, +0x24/+0x25:
/// código 4 com o bit 1, senão 5); nada decidido: 4. Pontos (0x10) e regra 0x2000 têm os ramos próprios. Empate nos
/// pênaltis: a original (caixa "Error", 4).
unsafe extern "thiscall" fn decidir_confronto_da_copa(this: usize, confronto: usize, jogo: usize) -> u32 {
    match cpm1_confronto(confronto, jogo) {
        Some(r) => r,
        None => orig::<unsafe extern "thiscall" fn(usize, usize, usize) -> u32>(926)(this, confronto, jogo),
    }
}

/// { 0x51ebc0 } (cdecl, Cup.cpp): `cup_compare_draw_entries_by_seed(a, b)`: a comparação do qsort das entradas de 7
/// bytes do sorteio (0x51d2d0 e 0x51d9f0): o cabeça de chave (byte com sinal +6) de `b` menos o de `a` (maior primeiro).
unsafe extern "C" fn ordem_dos_cabecas_de_chave(a: usize, b: usize) -> i32 {
    crate::comparacao::ramo("cpm_1 ordem dos cabecas de chave");
    cpm1_b(b + 6) as i32 - cpm1_b(a + 6) as i32 // o maior primeiro
}

/// Comparador: lado a lado pelos códigos (+0x3d/+0x3e) e pelo lado devolvido; jogo nulo ou empate nos pênaltis (a
/// caixa): só a original.
unsafe extern "thiscall" fn comparar_decidir_jogo_da_copa(this: usize, jogo: usize) -> u32 {
    let o = orig::<unsafe extern "thiscall" fn(usize, usize) -> u32>(925);
    if jogo == 0 {
        return o(this, jogo);
    }
    let reg = [(jogo + 0x3d, 2)];
    let (r, n, igual, mo, mr) = crate::comparacao::lado_a_lado_leve(&reg, || Some(o(this, jogo)), || cpm1_jogo(this, jogo));
    let r = r.unwrap_or(0);
    if let Some(n) = n {
        PLACAR.registrar(igual && r == n, || format!("decidir_jogo_da_copa(regra {:x}) original={} rust={} {:x?} x {:x?}", cpm1_w(jogo + 0x38) as u16, r, n, mo, mr));
    }
    r
}

/// Comparador: lado a lado pelos códigos (+0x3d/+0x3e) e pelo lado devolvido; empate nos pênaltis (a caixa): só a
/// original.
unsafe extern "thiscall" fn comparar_decidir_confronto_da_copa(this: usize, confronto: usize, jogo: usize) -> u32 {
    let o = orig::<unsafe extern "thiscall" fn(usize, usize, usize) -> u32>(926);
    let reg = [(jogo + 0x3d, 2)];
    let (r, n, igual, mo, mr) = crate::comparacao::lado_a_lado_leve(&reg, || Some(o(this, confronto, jogo)), || cpm1_confronto(confronto, jogo));
    let r = r.unwrap_or(0);
    if let Some(n) = n {
        PLACAR.registrar(igual && r == n, || format!("decidir_confronto_da_copa(regra {:x}, jogo {}) original={} rust={} {:x?} x {:x?}",
            cpm1_w(jogo + 0x38) as u16, cpm1_b(confronto + 0x33), r, n, mo, mr));
    }
    r
}

/// Comparador: pelo valor.
unsafe extern "C" fn comparar_ordem_dos_cabecas_de_chave(a: usize, b: usize) -> i32 {
    let r = orig::<unsafe extern "C" fn(usize, usize) -> i32>(927)(a, b);
    let n = ordem_dos_cabecas_de_chave(a, b);
    PLACAR.registrar(r == n, || format!("ordem_dos_cabecas_de_chave({}, {}) original={} rust={}", cpm1_b(a + 6), cpm1_b(b + 6), r, n));
    r
}

// ---------- 249a leva: a tabela da liga: iniciar a linha do clube, o vetor dos clubes e as posições finais (league.cpp) ----------

unsafe fn cpm2_d(a: usize) -> usize {
    core::ptr::read_unaligned(a as *const usize)
}

unsafe fn cpm2_por(a: usize, v: usize) {
    core::ptr::write_unaligned(a as *mut usize, v);
}

unsafe fn cpm2_w(a: usize) -> i16 {
    core::ptr::read_unaligned(a as *const i16)
}

unsafe fn cpm2_b(a: usize) -> u8 {
    *(a as *const u8)
}

/// Linhas da tabela: 0x3b bytes (+0 clube, +4 posição, +5 confrontos diretos de 14 bytes, +9 histórico das posições,
/// +0x11/+0x1f/+0x2d os totais, em casa e fora, +0x37 situação, +0x38 marca, +0x39, +0x3a clubes).
const CPM2_LINHA: usize = 0x3b;

/// A regra 4 (confrontos diretos) entre as 4 regras de desempate (+0xc5, até a primeira 0).
unsafe fn cpm2_regra_dos_confrontos(this: usize) -> bool {
    for k in 0..4 {
        match cpm2_b(this + 0xc5 + k) {
            0 => return false,
            4 => return true,
            _ => {}
        }
    }
    false
}

/// { 0x687430 } (thiscall, ret 0x10, league.cpp): `League::init_table_row(i, clube, marca, linhas)`: põe o clube na
/// linha `i` (char) da tabela `linhas` (nula: a da liga, +0xb1): o clube com situação +0x64 = 3 passa a 2; o total de
/// rodadas +0xa7 ainda −1 vira (clubes +0x3e − 1) × turnos +0x3c (mais de 50 clubes: caixa e segue); a linha recebe o
/// clube, a posição `i`, os três blocos de totais zerados, a marca (+0x38), situação 0xff, 1 em +0x39 e os clubes
/// (+0x3a); com turnos, o histórico das posições (+9, +0xa7 bytes; sem memória, caixa e fim); com a regra 4, os
/// confrontos diretos (+5, 14 bytes por adversário, zerados). Na última linha com confrontos, cada linha recebe os
/// adversários na ordem da tabela.
unsafe extern "thiscall" fn iniciar_linha_da_tabela(this: usize, i: u32, clube: usize, marca: u32, linhas: usize) {
    let alocar: unsafe extern "C" fn(u32) -> usize = core::mem::transmute(0x944e46usize);
    if clube != 0 && cpm2_b(clube + 0x64) == 3 {
        *((clube + 0x64) as *mut u8) = 2;
    }
    if cpm2_w(this + 0xa7) == -1 && cpm2_w(this + 0x3e) > 0 {
        if cpm2_w(this + 0x3e) > 0x32 {
            aviso_em(0x9f15f4, 0xfe9); // mais de 50 clubes: a caixa, e segue
        }
        let total = (cpm2_w(this + 0x3e) - 1).wrapping_mul(cpm2_w(this + 0x3c));
        core::ptr::write_unaligned((this + 0xa7) as *mut i16, total);
    }
    let tab = if linhas == 0 { cpm2_d(this + 0xb1) } else { linhas };
    let idx = i as u8 as i8 as isize;
    let l = tab.wrapping_add((idx * CPM2_LINHA as isize) as usize);
    cpm2_por(l, clube);
    *((l + 4) as *mut u8) = i as u8;
    for k in 0..3 {
        let e = l + 0x11 + 14 * k;
        cpm2_por(e - 4, 0);
        core::ptr::write_bytes(e as *mut u8, 0, 4);
        core::ptr::write_bytes((e + 4) as *mut u8, 0, 6);
    }
    *((l + 0x38) as *mut u8) = marca as u8;
    *((l + 0x37) as *mut u8) = 0xff;
    *((l + 0x39) as *mut u8) = 1;
    *((l + 0x3a) as *mut u8) = cpm2_b(this + 0x3e);
    cpm2_por(l + 5, 0);
    if cpm2_w(this + 0x3c) > 0 {
        let p = alocar(cpm2_w(this + 0xa7) as i32 as u32);
        cpm2_por(l + 9, p);
        if p == 0 {
            aviso_em(0x9f15f4, 0x100c);
            return;
        }
    } else {
        cpm2_por(l + 9, 0);
    }
    if cpm2_regra_dos_confrontos(this) {
        let n = cpm2_w(this + 0x3e) as i32;
        cpm2_por(l + 5, alocar((n * 14 - 14) as u32));
        // os confrontos zerados (+4..+0xd de cada um; a original grava o +4 duas vezes, sem conferir a memória)
        let mut k = 0i32;
        while k < cpm2_w(this + 0x3e) as i32 - 1 {
            let e = cpm2_d(l + 5) + 14 * k as usize;
            core::ptr::write_bytes((e + 4) as *mut u8, 0, 10);
            k += 1;
        }
    }
    let n = cpm2_w(this + 0x3e) as isize;
    if idx == n - 1 && cpm2_d(l + 5) != 0 {
        crate::comparacao::ramo("cpm_2 confrontos diretos");
        let mut a = 0isize;
        while a < cpm2_w(this + 0x3e) as isize {
            let mut k = 0usize;
            let mut j = 0isize;
            while j < cpm2_w(this + 0x3e) as isize {
                if a != j {
                    let p = cpm2_d(tab + a as usize * CPM2_LINHA + 5);
                    cpm2_por(p + 14 * k, cpm2_d(tab + j as usize * CPM2_LINHA)); // o clube adversário
                    k += 1;
                }
                j += 1;
            }
            a += 1;
        }
    }
}

/// { 0x687a20 } (thiscall, ret 8, league.cpp): `League::get_club_array(saida, n)`: um vetor novo (malloc 0x944e46) com
/// os clubes das linhas da tabela (+0xb1) em `*saida` e a conta (+0x3e) em `*n`; sem memória, caixa e `*n` = 0.
unsafe extern "thiscall" fn vetor_dos_clubes_da_liga(this: usize, saida: *mut usize, n: *mut i16) {
    let alocar: unsafe extern "C" fn(u32) -> usize = core::mem::transmute(0x944e46usize);
    let p = alocar((cpm2_w(this + 0x3e) as i32 * 4) as u32);
    *saida = p;
    if p == 0 {
        aviso_em(0x9f15f4, 0x10cc);
        *n = 0;
        return;
    }
    crate::comparacao::ramo("cpm_2 vetor dos clubes");
    let mut i = 0i16;
    while i < cpm2_w(this + 0x3e) {
        cpm2_por(p + 4 * i as usize, cpm2_d(cpm2_d(this + 0xb1) + i as usize * CPM2_LINHA));
        i += 1;
    }
    *n = cpm2_w(this + 0x3e); // a conta
}

/// { 0x68aa30 } (thiscall, league.cpp): `League::record_final_positions()`: cada clube da tabela (+0xb1, na ordem) que
/// ainda está na divisão da liga (+0x57 = +4 dela) guarda a divisão como a da última temporada (+0x5b) e a posição
/// (linha + 1) em +0x5f.
unsafe extern "thiscall" fn gravar_posicoes_finais_da_liga(this: usize) {
    let mut i = 0i16;
    while i < cpm2_w(this + 0x3e) {
        let divisao = cpm2_d(this + 4);
        let c = cpm2_d(cpm2_d(this + 0xb1) + i as usize * CPM2_LINHA);
        if cpm2_d(c + 0x57) == divisao {
            crate::comparacao::ramo("cpm_2 posicao final");
            cpm2_por(c + 0x5b, divisao);
            *((c + 0x5f) as *mut u8) = (i as u8).wrapping_add(1); // a posição final
        }
        i += 1;
    }
}

/// Comparador: a original aloca (histórico e confrontos): roda só ela e confere a linha com o plano feito antes (o
/// total de rodadas, a situação do clube, os campos, os blocos zerados, os vetores presentes e, na última linha, os
/// adversários de cada linha).
unsafe extern "thiscall" fn comparar_iniciar_linha_da_tabela(this: usize, i: u32, clube: usize, marca: u32, linhas: usize) {
    let o = orig::<unsafe extern "thiscall" fn(usize, u32, usize, u32, usize)>(928);
    let a7 = cpm2_w(this + 0xa7);
    let n = cpm2_w(this + 0x3e);
    let a7_esperado = if a7 == -1 && n > 0 { (n - 1).wrapping_mul(cpm2_w(this + 0x3c)) } else { a7 };
    let situacao = if clube != 0 { cpm2_b(clube + 0x64) } else { 0 };
    let situacao_esperada = if situacao == 3 { 2 } else { situacao };
    let tab = if linhas == 0 { cpm2_d(this + 0xb1) } else { linhas };
    let confrontos = cpm2_regra_dos_confrontos(this);
    o(this, i, clube, marca, linhas);
    let idx = i as u8 as i8 as isize;
    let l = tab.wrapping_add((idx * CPM2_LINHA as isize) as usize);
    let mut ok = cpm2_d(l) == clube && cpm2_b(l + 4) == i as u8 && cpm2_b(l + 0x37) == 0xff && cpm2_b(l + 0x38) == marca as u8
        && cpm2_b(l + 0x39) == 1 && cpm2_b(l + 0x3a) == n as u8 && cpm2_w(this + 0xa7) == a7_esperado
        && (clube == 0 || cpm2_b(clube + 0x64) == situacao_esperada)
        && (cpm2_d(l + 9) != 0) == (cpm2_w(this + 0x3c) > 0) && (cpm2_d(l + 5) != 0) == confrontos;
    for k in 0..3 {
        let e = l + 0x11 + 14 * k;
        ok &= (e - 4..e + 10).all(|a| cpm2_b(a) == 0);
    }
    let ultima = idx == n as isize - 1 && cpm2_d(l + 5) != 0;
    if cpm2_d(l + 5) != 0 && !ultima {
        let p = cpm2_d(l + 5);
        ok &= (0..(n as usize).saturating_sub(1)).all(|k| (p + 14 * k + 4..p + 14 * k + 14).all(|a| cpm2_b(a) == 0));
    }
    if ultima {
        for a in 0..n as usize {
            let p = cpm2_d(tab + a * CPM2_LINHA + 5);
            let outros = (0..n as usize).filter(|&j| j != a);
            ok &= outros.enumerate().all(|(k, j)| cpm2_d(p + 14 * k) == cpm2_d(tab + j * CPM2_LINHA));
        }
    }
    PLACAR.registrar(ok, || format!("iniciar_linha_da_tabela(linha {}, clube {:x}, marca {}) clubes {}, rodadas {} (esperava {}), confrontos {} ({:x}), histórico {:x}",
        idx, clube, marca as u8, n, cpm2_w(this + 0xa7), a7_esperado, confrontos, cpm2_d(l + 5), cpm2_d(l + 9)));
}

/// Comparador: a original aloca o vetor: roda só ela e confere a conta e os clubes, na ordem da tabela.
unsafe extern "thiscall" fn comparar_vetor_dos_clubes_da_liga(this: usize, saida: *mut usize, n: *mut i16) {
    orig::<unsafe extern "thiscall" fn(usize, *mut usize, *mut i16)>(929)(this, saida, n);
    let p = *saida;
    if p == 0 {
        return; // sem memória: a caixa já saiu
    }
    let conta = cpm2_w(this + 0x3e);
    let ok = *n == conta && (0..conta.max(0) as usize).all(|i| cpm2_d(p + 4 * i) == cpm2_d(cpm2_d(this + 0xb1) + i * CPM2_LINHA));
    PLACAR.registrar(ok, || format!("vetor_dos_clubes_da_liga conta {} (tabela {})", *n, conta));
}

/// Comparador: lado a lado pela divisão da última temporada e pela posição (+0x5b..+0x5f) de cada clube da tabela.
unsafe extern "thiscall" fn comparar_gravar_posicoes_finais_da_liga(this: usize) {
    let o = orig::<unsafe extern "thiscall" fn(usize)>(930);
    let reg: Vec<(usize, usize)> = (0..cpm2_w(this + 0x3e).max(0) as usize)
        .map(|i| (cpm2_d(cpm2_d(this + 0xb1) + i * CPM2_LINHA) + 0x5b, 5))
        .collect();
    let (_, _, igual, mo, mr) = crate::comparacao::lado_a_lado(&reg, || o(this), || gravar_posicoes_finais_da_liga(this));
    PLACAR.registrar(igual, || format!("gravar_posicoes_finais_da_liga {:x?} x {:x?}", mo, mr));
}

// ---------- 249a leva: a mudança de divisão do clube e os embaralhamentos das listas de clubes (league.cpp, comp_util.cpp) ----------

unsafe fn cpm3_d(a: usize) -> usize {
    core::ptr::read_unaligned(a as *const usize)
}

unsafe fn cpm3_sorteio(n: i32) -> i32 {
    let f: unsafe extern "C" fn(i32) -> i32 = core::mem::transmute(0x90cfc0usize);
    f(n)
}

/// { 0x6830b0 } (thiscall, ret 0xc, league.cpp; `this` não é lido): `League::move_club_to_division(clube, divisao,
/// vaga)`: a divisão atual (+0x57) vira a da última temporada (+0x5b) e a nova entra; as cláusulas de divisão dos
/// jogadores são limpas (0x4cd120 em [0xae1050]), com os números da camisa também se a divisão velha não os usava e a
/// nova usa (0x85add0 em [0xdd7ef0], antes e depois); com `vaga` e sem técnico (+0xcf), a vaga de técnico (0x69ba50 em
/// [0xb67a44]); numa divisão de liga (+0x43 = 2 na competição [0xadadfc][id]) com estádio mínimo (+0xe2 ≠ −1) e ficha
/// do estádio (+0x69), a obra do estádio (0x599e00 nas finanças 0x5a0590 de [0xae2a38], lugares +0xe4 e +0xe2); e,
/// com a competição carregada, a situação +0x64 = 3 passa a 2.
unsafe extern "thiscall" fn mudar_clube_de_divisao(_this: usize, clube: usize, divisao: usize, vaga: u32) {
    crate::comparacao::ramo("cpm_3 mudar de divisao");
    let usa_numeros: unsafe extern "thiscall" fn(usize, usize, usize) -> u32 = core::mem::transmute(0x85add0usize);
    let limpar_clausulas: unsafe extern "thiscall" fn(usize, usize, u32) -> u32 = core::mem::transmute(0x4cd120usize);
    let antes = usa_numeros(cpm3_d(0xdd7ef0), clube, 0);
    cpm3_por(clube + 0x5b, cpm3_d(clube + 0x57)); // a divisão da última temporada
    cpm3_por(clube + 0x57, divisao);
    let numeros = (antes == 0 && usa_numeros(cpm3_d(0xdd7ef0), clube, 0) != 0) as u32;
    limpar_clausulas(cpm3_d(0xae1050), clube, numeros);
    if vaga != 0 && cpm3_d(clube + 0xcf) == 0 {
        let abrir_vaga: unsafe extern "thiscall" fn(usize, usize, usize) -> u32 = core::mem::transmute(0x69ba50usize);
        abrir_vaga(cpm3_d(0xb67a44), clube, 0);
    }
    if divisao == 0 {
        return;
    }
    let comps = cpm3_d(0xadadfc);
    let id = cpm3_d(divisao);
    if comps != 0 {
        let comp = cpm3_d(comps + 4 * id);
        if comp != 0 && cpm3_d(clube + 0x69) != 0 && *((comp + 0x43) as *const u8) == 2 {
            let lugares = core::ptr::read_unaligned((comp + 0xe2) as *const i16);
            if lugares != -1 {
                crate::comparacao::ramo("cpm_3 estadio da divisao");
                let capacidade = core::ptr::read_unaligned((comp + 0xe4) as *const i16);
                let financas: unsafe extern "thiscall" fn(usize, usize) -> usize = core::mem::transmute(0x5a0590usize);
                let obra: unsafe extern "thiscall" fn(usize, i32, i32, usize, u32) -> u32 = core::mem::transmute(0x599e00usize);
                let f = financas(cpm3_d(0xae2a38), clube);
                obra(f, capacidade as i32, lugares as i32, id, 0); // a obra do estádio
            }
        }
    }
    // a original relê [0xadadfc] depois da obra (sem a obra, o mesmo valor; nulo, ela lê do endereço 0 também)
    if cpm3_d(cpm3_d(0xadadfc) + 4 * id) != 0 && *((clube + 0x64) as *const u8) == 3 {
        *((clube + 0x64) as *mut u8) = 2;
    }
}

unsafe fn cpm3_por(a: usize, v: usize) {
    core::ptr::write_unaligned(a as *mut usize, v);
}

/// As trocas de `vezes` pares sorteados (0x90cfc0(n) duas vezes; a primeira dá o índice que recebe o item do segundo)
/// no vetor de ponteiros `itens`, como as duas originais (índices de 16 bits com sinal).
unsafe fn cpm3_trocar(itens: usize, n: i32) {
    let a = cpm3_sorteio(n) as i16 as isize;
    let b = cpm3_sorteio(n) as i16 as isize;
    let pa = (itens as isize + 4 * a) as usize;
    let pb = (itens as isize + 4 * b) as usize;
    let (va, vb) = (cpm3_d(pa), cpm3_d(pb));
    cpm3_por(pa, vb);
    cpm3_por(pb, va);
}

/// { 0x4afb40 } (cdecl, comp_util.cpp): `comp_util_shuffle_pointer_array(itens, n)`: embaralha o vetor de `n` (curto)
/// ponteiros com 3 × n trocas de pares sorteados (0x90cfc0(n) duas vezes cada).
unsafe extern "C" fn embaralhar_ponteiros(itens: usize, n: u32) {
    let n = n as u16 as i16 as i32;
    if 3 * n <= 0 {
        return;
    }
    crate::comparacao::ramo("cpm_3 embaralhar ponteiros");
    let mut k = 0i16;
    loop {
        cpm3_trocar(itens, n);
        k = k.wrapping_add(1); // mais uma troca
        if k as i32 >= 3 * n {
            break;
        }
    }
}

/// { 0x4afbd0 } (cdecl, comp_util.cpp): `comp_util_sort_and_shuffle_top_clubs(clubes, n, escolhas)`: ordena os `n`
/// clubes pela reputação, maior primeiro e nulos no fim (qsort 0x945333 com 0x4b07d0), e embaralha os m = min(3 ×
/// escolhas, n) primeiros com m trocas de pares sorteados entre eles. `n` negativo ou menor que `escolhas`: caixa
/// "Error" (a original); `escolhas` < 1: nada.
unsafe extern "C" fn ordenar_e_embaralhar_os_melhores(clubes: usize, n: u32, escolhas: u32) {
    let (nn, e) = (n as u16 as i16, escolhas as u16 as i16);
    if nn < 0 || nn < e {
        return orig::<unsafe extern "C" fn(usize, u32, u32)>(933)(clubes, n, escolhas); // a caixa
    }
    if e < 1 {
        return;
    }
    let qsort: unsafe extern "C" fn(usize, u32, u32, usize) = core::mem::transmute(0x945333usize);
    qsort(clubes, nn as i32 as u32, 4, 0x4b07d0);
    let mut m = e.wrapping_mul(3);
    if m > nn {
        m = nn;
    }
    if m <= 0 {
        return;
    }
    crate::comparacao::ramo("cpm_3 embaralhar os melhores");
    for _ in 0..m as i32 { // m trocas
        cpm3_trocar(clubes, m as i32);
    }
}

/// Comparador: a mudança chama as notícias, a vaga de técnico e a obra (não podem rodar duas vezes): só a original (a
/// prova é a carreira e o modo Rust).
unsafe extern "thiscall" fn comparar_mudar_clube_de_divisao(this: usize, clube: usize, divisao: usize, vaga: u32) {
    crate::comparacao::ramo("mudar_clube_de_divisao");
    orig::<unsafe extern "thiscall" fn(usize, usize, usize, u32)>(931)(this, clube, divisao, vaga)
}

/// Comparador: sorteia (0x90cfc0): lado a lado pelo estado do sorteio e pelo vetor, a cópia em sem_contar.
unsafe extern "C" fn comparar_embaralhar_ponteiros(itens: usize, n: u32) {
    let o = orig::<unsafe extern "C" fn(usize, u32)>(932);
    let k = (n as u16 as i16).max(0) as usize;
    let mut reg = crate::aleatorio::REGIOES_DO_ESTADO.to_vec();
    if k > 0 {
        reg.push((itens, 4 * k));
    }
    let (_, _, igual, mo, mr) = crate::comparacao::lado_a_lado_leve(&reg, || o(itens, n),
        || crate::aleatorio::sem_contar(|| embaralhar_ponteiros(itens, n)));
    PLACAR.registrar(igual, || format!("embaralhar_ponteiros({}) {:x?} x {:x?}", k, mo, mr));
}

/// Comparador: ordena (qsort, determinístico) e sorteia: lado a lado pelo estado do sorteio e pelos `n` clubes, a cópia
/// em sem_contar. Caixa (`n` negativo ou menor que `escolhas`): só a original.
unsafe extern "C" fn comparar_ordenar_e_embaralhar_os_melhores(clubes: usize, n: u32, escolhas: u32) {
    let o = orig::<unsafe extern "C" fn(usize, u32, u32)>(933);
    let (nn, e) = (n as u16 as i16, escolhas as u16 as i16);
    if nn < 0 || nn < e {
        return o(clubes, n, escolhas);
    }
    let mut reg = crate::aleatorio::REGIOES_DO_ESTADO.to_vec();
    if nn > 0 {
        reg.push((clubes, 4 * nn as usize));
    }
    let (_, _, igual, mo, mr) = crate::comparacao::lado_a_lado_leve(&reg, || o(clubes, n, escolhas),
        || crate::aleatorio::sem_contar(|| ordenar_e_embaralhar_os_melhores(clubes, n, escolhas)));
    PLACAR.registrar(igual, || format!("ordenar_e_embaralhar_os_melhores({}, {}) {:x?} x {:x?}", nn, e, mo, mr));
}

// ---------- 249a leva: a disciplina: contar o jogo cumprido da suspensão, soltar a suspensão e apagar o histórico de suspensões da pessoa (discipline.cpp) ----------

unsafe fn cpm4_d(a: usize) -> usize {
    core::ptr::read_unaligned(a as *const usize)
}

unsafe fn cpm4_w(a: usize) -> i16 {
    core::ptr::read_unaligned(a as *const i16)
}

/// O registro de 29 bytes da pessoa `id` em [this+0x14] (+0x14/+0x18: o começo e o último deslocamento do histórico).
unsafe fn cpm4_registro(this: usize, id: usize) -> usize {
    cpm4_d(this + 0x14).wrapping_add(id.wrapping_mul(29))
}

/// O órgão disciplinar da regra `regra` (byte com sinal): [[this] + 4 × regra].
unsafe fn cpm4_orgao(this: usize, regra: u8) -> usize {
    cpm4_d(cpm4_d(this).wrapping_add((regra as i8 as isize as usize).wrapping_mul(4)))
}

/// A entrada (14 bytes; +6 o índice da suspensão, −1 sem) da pessoa no órgão: 0x7e82e0 sem criar (só lê).
unsafe fn cpm4_entrada(orgao: usize, id: u32) -> usize {
    let achar: unsafe extern "thiscall" fn(usize, u32, u32) -> usize = core::mem::transmute(0x7e82e0usize);
    achar(orgao, id, 0)
}

/// O item (id, nação) da pessoa no índice das nações (+0xc, 8 bytes por item, conta +0x12 com sinal): bsearch
/// (0x946464 com 0x55e5f0) pela nação (+0x1a) e, sem achar, pela segunda nação (+0x1e, se houver). 0 sem achar.
unsafe fn cpm4_no_indice(this: usize, id: u32) -> usize {
    let bsearch: unsafe extern "C" fn(*const u32, usize, i32, u32, usize) -> usize = core::mem::transmute(0x946464usize);
    let pessoa = cpm4_d(0xae23bc).wrapping_add((id as usize).wrapping_mul(0x6e));
    let mut chave = [id, cpm4_d(cpm4_d(pessoa + 0x1a)) as u32];
    let e = bsearch(chave.as_ptr(), cpm4_d(this + 0xc), cpm4_w(this + 0x12) as i32, 8, 0x55e5f0);
    if e != 0 {
        return e;
    }
    let segunda = cpm4_d(cpm4_d(0xae23bc).wrapping_add((id as usize).wrapping_mul(0x6e)) + 0x1e);
    if segunda == 0 {
        return 0;
    }
    chave[1] = cpm4_d(segunda) as u32;
    bsearch(chave.as_ptr(), cpm4_d(this + 0xc), cpm4_w(this + 0x12) as i32, 8, 0x55e5f0)
}

/// O que a 0x556e90 faz com o jogo: a entrada no órgão, a suspensão (20 bytes em [this+4]), o contador novo de jogos
/// cumpridos (+1) e se a suspensão termina.
struct Cpm4Jogo {
    entrada: usize,
    suspensao: usize,
    contador: Option<u8>,
    cumprida: bool,
}

/// O plano do jogo (só lê; a 0x7e82e0 sem criar e a 0x54c5b0 só gravam a data de rascunho dela): a suspensão da
/// pessoa no órgão da `regra`; por jogos (+0 ≠ 0xff): a partir do começo (dia +4, ano +6; hoje [0xae2c90]: dia +0,
/// ano +2), com `conta`, +1 no contador (+1), e termina ao chegar em +0; por dias (+0 = 0xff): termina quando hoje
/// chega ao começo + dias (+2) (0x54c5b0).
unsafe fn cpm4_jogo(this: usize, id: u32, regra: u32, conta: u32) -> Cpm4Jogo {
    let mut j = Cpm4Jogo { entrada: 0, suspensao: 0, contador: None, cumprida: false };
    let e = cpm4_entrada(cpm4_orgao(this, regra as u8), id);
    if e == 0 || cpm4_w(e + 6) == -1 {
        return j;
    }
    j.entrada = e;
    let cinco = (cpm4_w(e + 6) as i32 as u32).wrapping_mul(5); // o lea da original (o alto vai no edx abaixo)
    let s = cpm4_d(this + 4).wrapping_add((cinco as usize).wrapping_mul(4));
    j.suspensao = s;
    let hoje = cpm4_d(0xae2c90) as u32;
    let (dia, ano) = (hoje as u16 as i16, (hoje >> 16) as u16);
    let jogos = *(s as *const u8);
    if jogos != 0xff {
        let (dia0, ano0) = (cpm4_w(s + 4), cpm4_w(s + 6) as u16);
        if ano < ano0 || (ano == ano0 && dia < dia0) { // ainda não começou
            crate::comparacao::ramo("cpm_4 antes do inicio");
            return j;
        }
        if conta == 0 {
            return j;
        }
        crate::comparacao::ramo("cpm_4 jogo cumprido");
        let n = (*((s + 1) as *const u8)).wrapping_add(1); // mais um jogo cumprido
        j.contador = Some(n);
        j.cumprida = n == jogos;
    } else {
        let mut fim = [0u8; 8];
        let mais_dias: unsafe extern "thiscall" fn(usize, *mut u8, u32) -> usize = core::mem::transmute(0x54c5b0usize);
        // a original empurra o edx com os dias no dx e, no alto, o do índice × 5 (zero abaixo de 13108 suspensões)
        let f = mais_dias(s + 4, fim.as_mut_ptr(), (cinco & 0xffff_0000) | cpm4_w(s + 2) as u16 as u32);
        let (dia1, ano1) = (cpm4_w(f), cpm4_w(f + 2) as u16);
        if ano < ano1 || (ano == ano1 && dia < dia1) {
            return j;
        }
        j.cumprida = true;
    }
    j
}

/// { 0x556e90 } (thiscall, ret 0xc, discipline.cpp): `Discipline::update_ban_progress(id, regra, conta)`: a suspensão
/// da pessoa no órgão da `regra` (plano em `cpm4_jogo`): por jogos, grava o contador novo (+1); cumprida, vai para o
/// histórico (0x58e340 sobre [this+0x18] com o começo e o último deslocamento do registro de 29 bytes) e é solta
/// (0x556d00). Sem SEH, sem sorteio, sem caixa.
unsafe extern "thiscall" fn contar_jogo_da_suspensao(this: usize, id: u32, regra: u32, conta: u32) {
    let j = cpm4_jogo(this, id, regra, conta);
    if let Some(n) = j.contador {
        *((j.suspensao + 1) as *mut u8) = n;
    }
    if !j.cumprida {
        return;
    }
    let r = cpm4_registro(this, id as usize);
    let historico: unsafe extern "thiscall" fn(usize, usize, usize, usize) -> usize = core::mem::transmute(0x58e340usize);
    let g = historico(cpm4_d(this + 0x18), r + 0x14, r + 0x18, j.suspensao);
    let soltar: unsafe extern "thiscall" fn(usize, u32, u32) -> usize = core::mem::transmute(0x556d00usize);
    // o índice vai no ax; o alto do eax é o da devolução da 0x58e340 (a 0x556d00 só lê a palavra)
    soltar(this, id, (g as u32 & 0xffff_0000) | cpm4_w(j.entrada + 6) as u16 as u32);
}

/// { 0x556d00 } (thiscall, ret 8, discipline.cpp): `Discipline::release_ban(id, indice)`: a suspensão `indice` (20
/// bytes em [this+4]; a palavra com sinal): para cada uma das 4 regras (+0xc..+0xf, 0xff = sem), o órgão a esquece
/// (0x7e8590); na quarta, o item da pessoa sai do índice das nações (o último vem para o lugar, conta +0x12 − 1, qsort
/// 0x945333 com 0x55e5f0; sem achar, caixa "Error" e segue). Por fim a suspensão fica livre (+0 = 0xff, +2 = −1).
/// Devolve a suspensão.
unsafe extern "thiscall" fn soltar_suspensao(this: usize, id: u32, indice: u32) -> usize {
    let s = cpm4_d(this + 4).wrapping_add((indice as u16 as i16 as i32 as usize).wrapping_mul(20));
    let esquecer: unsafe extern "thiscall" fn(usize, u32) -> usize = core::mem::transmute(0x7e8590usize);
    for k in 0..4usize {
        let regra = *((s + 0xc + k) as *const u8);
        if regra == 0xff {
            continue;
        }
        crate::comparacao::ramo("cpm_4 soltar do orgao");
        esquecer(cpm4_orgao(this, regra), id); // o órgão esquece a suspensão
        if k != 3 {
            continue;
        }
        let e = cpm4_no_indice(this, id);
        if e == 0 {
            aviso_em(0x9b8f18, 0x47d);
            continue;
        }
        let n = cpm4_w(this + 0x12).wrapping_sub(1);
        core::ptr::write_unaligned((this + 0x12) as *mut i16, n);
        let ultimo = cpm4_d(this + 0xc).wrapping_add((n as i32 as usize).wrapping_mul(8));
        core::ptr::write_unaligned(e as *mut u32, cpm4_d(ultimo) as u32);
        core::ptr::write_unaligned((e + 4) as *mut u32, cpm4_d(ultimo + 4) as u32);
        let qsort: unsafe extern "C" fn(usize, i32, u32, usize) = core::mem::transmute(0x945333usize);
        qsort(cpm4_d(this + 0xc), cpm4_w(this + 0x12) as i32, 8, 0x55e5f0);
    }
    *(s as *mut u8) = 0xff;
    core::ptr::write_unaligned((s + 2) as *mut u16, 0xffff);
    s
}

/// { 0x55e1d0 } (thiscall, ret 4, discipline.cpp): `Discipline::clear_ban_history(pessoa)`: o histórico de suspensões
/// da pessoa (registro de 29 bytes do id em [this+0x14]) fica sem o último (0x58f110 sobre [this+0x18]: +0x18 = −1).
/// Devolve o que a 0x58f110 devolve. Pessoa nula ou não jogadora (+0x61): a original (caixa fatal).
unsafe extern "thiscall" fn apagar_historico_de_suspensoes(this: usize, pessoa: usize) -> usize {
    if pessoa == 0 || cpm4_d(pessoa + 0x61) == 0 {
        return orig::<unsafe extern "thiscall" fn(usize, usize) -> usize>(936)(this, pessoa); // caixa fatal: só a original
    }
    let r = cpm4_registro(this, cpm4_d(pessoa));
    let sem_ultimo: unsafe extern "thiscall" fn(usize, usize, usize) -> usize = core::mem::transmute(0x58f110usize);
    sem_ultimo(cpm4_d(this + 0x18), r + 0x14, r + 0x18)
}

/// Comparador: a 0x58e340 grava o histórico no arquivo (não pode rodar duas vezes): o plano antes, a original roda;
/// confere o contador, ou a suspensão solta (livre e a entrada do órgão sem índice), ou nada mudado.
unsafe extern "thiscall" fn comparar_contar_jogo_da_suspensao(this: usize, id: u32, regra: u32, conta: u32) {
    let j = cpm4_jogo(this, id, regra, conta);
    let antes = if j.suspensao != 0 { *((j.suspensao + 1) as *const u8) } else { 0 };
    orig::<unsafe extern "thiscall" fn(usize, u32, u32, u32)>(934)(this, id, regra, conta);
    if j.suspensao == 0 {
        return;
    }
    let s = j.suspensao;
    let (jogos, contador, dias) = (*(s as *const u8), *((s + 1) as *const u8), cpm4_w(s + 2));
    let ok = if j.cumprida {
        jogos == 0xff && dias == -1 && cpm4_w(j.entrada + 6) == -1
    } else {
        contador == j.contador.unwrap_or(antes)
    };
    PLACAR.registrar(ok, || {
        format!("contar_jogo_da_suspensao({}, {}, {}) contador {} (esperava {:?}, antes {}), cumprida={} suspensão {:#x}/{} entrada {}",
            id, regra as u8, conta, contador, j.contador, antes, j.cumprida, jogos, dias, cpm4_w(j.entrada + 6))
    });
}

/// Comparador: lado a lado pela suspensão, o índice das nações (conta e itens) e as entradas da pessoa nos órgãos das
/// regras (achadas antes, sem criar). Quarta regra sem o item no índice: só a original (caixa).
unsafe extern "thiscall" fn comparar_soltar_suspensao(this: usize, id: u32, indice: u32) -> usize {
    let o = orig::<unsafe extern "thiscall" fn(usize, u32, u32) -> usize>(935);
    let s = cpm4_d(this + 4).wrapping_add((indice as u16 as i16 as i32 as usize).wrapping_mul(20));
    if *((s + 0xf) as *const u8) != 0xff && cpm4_no_indice(this, id) == 0 {
        return o(this, id, indice);
    }
    let mut reg = vec![(s, 20), (this + 0x10, 4)];
    let n = cpm4_w(this + 0x12);
    if n > 0 {
        reg.push((cpm4_d(this + 0xc), n as usize * 8));
    }
    for k in 0..4usize {
        let regra = *((s + 0xc + k) as *const u8);
        if regra != 0xff {
            let e = cpm4_entrada(cpm4_orgao(this, regra), id);
            if e != 0 {
                reg.push((e, 14));
            }
        }
    }
    let (r, m, igual, mo, mr) = crate::comparacao::lado_a_lado(&reg, || o(this, id, indice), || soltar_suspensao(this, id, indice));
    PLACAR.registrar(igual && r == m, || format!("soltar_suspensao({}, {}) {:x?} x {:x?}", id, indice as u16 as i16, mo, mr));
    r
}

/// Comparador: lado a lado pelo começo e o último deslocamento do histórico (8 bytes; a 0x58f110 só grava o segundo).
unsafe extern "thiscall" fn comparar_apagar_historico_de_suspensoes(this: usize, pessoa: usize) -> usize {
    let o = orig::<unsafe extern "thiscall" fn(usize, usize) -> usize>(936);
    if pessoa == 0 || cpm4_d(pessoa + 0x61) == 0 {
        return o(this, pessoa);
    }
    let r = cpm4_registro(this, cpm4_d(pessoa));
    let (a, b, igual, mo, mr) = crate::comparacao::lado_a_lado_leve(&[(r + 0x14, 8)], || o(this, pessoa), || apagar_historico_de_suspensoes(this, pessoa));
    PLACAR.registrar(igual && a == b, || format!("apagar_historico_de_suspensoes({}) {:x?} x {:x?}", cpm4_d(pessoa), mo, mr));
    a
}

// ---------- 249a leva: as lesões: sortear a lesão recorrente, recomeçar o histórico de lesões e reiniciar o físico do jogador (injury.cpp) ----------

unsafe fn cpm5_d(a: usize) -> usize {
    core::ptr::read_unaligned(a as *const usize)
}

unsafe fn cpm5_b(a: usize) -> u8 {
    *(a as *const u8)
}

/// O registro de 31 bytes do físico da pessoa `id` em [this] (+0x12 o tipo da lesão recorrente, 0xff sem; +0x13 o
/// nível; +0x14/+0x18 o começo e o último deslocamento do histórico de lesões).
unsafe fn cpm5_registro(this: usize, id: usize) -> usize {
    cpm5_d(this).wrapping_add(id.wrapping_mul(31))
}

unsafe fn cpm5_sorteio(n: i32) -> i32 {
    let f: unsafe extern "C" fn(i32) -> i32 = core::mem::transmute(0x90cfc0usize);
    f(n)
}

/// O que a 0x62e500 decide depois de sortear.
#[derive(Clone, Copy, PartialEq, Debug)]
enum Cpm5Recorrente {
    Nada,
    Marcada,
    Limpar(usize),
    Tratar(usize),
}

/// O plano da 0x62e500 (os sorteios e as marcas do registro; o resto fica para quem chama): 1 em 20 (sorteio 0x14) e
/// a lesão `tipo` podendo voltar ([0x9e7ae0 + 13 × tipo]), o registro sem recorrente fica com ela (+0x12 = tipo,
/// +0x13 = 0). Dos registros com recorrente (+0x12 ≠ 0xff), o de maior nota (sorteio 0x65 − 5 × nível − pessoa +0x2d
/// do jogador; 100 sem jogador, bytes com sinal), parando no primeiro com 95 ou mais. Achado: jogador de clube (+0x39)
/// de reputação (+0x80) acima de 4250, clube sem humano (0x600a50) e 1 em 3 (sorteio 3): tratar; senão limpar a marca
/// dele.
unsafe fn cpm5_plano(this: usize, registro: usize, lesao: *const u8) -> Cpm5Recorrente {
    if cpm5_b(registro + 0x12) != 0xff || cpm5_d((0x9e7ae0isize + *lesao as i8 as isize * 13) as usize) == 0 {
        return Cpm5Recorrente::Nada;
    }
    let s = cpm5_sorteio(0x14);
    if s != 0 { // 1 em 20
        return Cpm5Recorrente::Nada;
    }
    crate::comparacao::ramo("cpm_5 lesao recorrente");
    *((registro + 0x13) as *mut u8) = s as u8;
    *((registro + 0x12) as *mut u8) = *lesao;
    if *(0xae2364 as *const i32) <= 0 {
        return Cpm5Recorrente::Marcada;
    }
    let (mut melhor, mut escolhido, mut pessoa) = (0i8, 0usize, 0usize);
    let mut r = cpm5_d(this);
    let mut i = 0i32;
    while i < *(0xae2364 as *const i32) {
        if cpm5_b(r + 0x12) != 0xff {
            let p = cpm5_d(0xae23bc).wrapping_add(i as usize * 0x6e);
            let v = cpm5_sorteio(0x65) as u8;
            let jogador = cpm5_d(p + 0x61);
            let nota = if jogador == 0 { 0x64 } else { v.wrapping_add(cpm5_b(r + 0x13).wrapping_mul(0xfb)).wrapping_sub(cpm5_b(jogador + 0x2d)) };
            if nota as i8 > melhor {
                (melhor, escolhido, pessoa) = (nota as i8, r, p);
            }
            if melhor >= 0x5f { // forte o bastante: para
                crate::comparacao::ramo("cpm_5 recorrente forte");
                break;
            }
        }
        i += 1;
        r += 0x1f;
    }
    if escolhido == 0 {
        return Cpm5Recorrente::Marcada;
    }
    let clube = cpm5_d(pessoa + 0x39);
    if cpm5_d(pessoa + 0x61) != 0 && clube != 0 && core::ptr::read_unaligned((clube + 0x80) as *const i16) > 0x109a {
        let humano: unsafe extern "C" fn(usize, u32, u32, u32, u32) -> u32 = core::mem::transmute(0x600a50usize);
        if humano(clube, 0, 1, 0, 0) == 0 && cpm5_sorteio(3) == 0 && pessoa != 0 {
            return Cpm5Recorrente::Tratar(pessoa);
        }
    }
    Cpm5Recorrente::Limpar(escolhido)
}

/// { 0x62e500 } (thiscall, ret 8, injury.cpp): `Injury::roll_recurring_injury(registro, lesao)`: o plano
/// (`cpm5_plano`); tratar: a lesão nova da pessoa (0x62d250 com 0x4e, 0x4f ou 0x4d pelo tipo recorrente do registro
/// dela, 0xff fora das pessoas ou sem jogador; o tipo vai no byte baixo do argumento `registro`, como a original);
/// limpar: o registro escolhido sem recorrente (+0x12 = 0xff, +0x13 = 0).
unsafe extern "thiscall" fn sortear_lesao_recorrente(this: usize, registro: usize, lesao: *const u8) {
    match cpm5_plano(this, registro, lesao) {
        Cpm5Recorrente::Tratar(p) => {
            let id = cpm5_d(p) as i32;
            let tipo = if id < *(0xae2364 as *const i32) && cpm5_d(p + 0x61) != 0 {
                cpm5_b(cpm5_registro(this, id as usize) + 0x12)
            } else {
                0xff
            };
            let nova: u8 = match tipo {
                0x0b | 0x11 | 0x17 | 0x1e | 0x23 | 0x29 => 0x4e,
                0x0c | 0x0d | 0x12 | 0x14 | 0x19..=0x1c | 0x1f | 0x24 | 0x25 | 0x2c | 0x2d | 0x3b => 0x4f,
                _ => 0x4d,
            };
            let lesionar: unsafe extern "thiscall" fn(usize, u32, u32, usize, u32, u32, i32, u32, u32) -> u32 = core::mem::transmute(0x62d250usize);
            lesionar(this, (registro as u32 & 0xffff_ff00) | nova as u32, 0, p, 0, 1, -1, 0, 0);
        }
        Cpm5Recorrente::Limpar(r) => {
            *((r + 0x12) as *mut u8) = 0xff;
            *((r + 0x13) as *mut u8) = 0;
        }
        _ => {}
    }
}

/// { 0x631f90 } (thiscall, ret 4, injury.cpp): `Injury::reset_player_history(pessoa)`: o histórico de lesões da pessoa
/// (registro de 31 bytes do id em [this]) fica sem o último (0x58f110 sobre [this+0xc]: +0x18 = −1). Devolve o que a
/// 0x58f110 devolve. Pessoa nula: a original (caixa fatal).
unsafe extern "thiscall" fn recomecar_historico_de_lesoes(this: usize, pessoa: usize) -> usize {
    if pessoa == 0 {
        return orig::<unsafe extern "thiscall" fn(usize, usize) -> usize>(938)(this, pessoa); // caixa fatal: só a original
    }
    let r = cpm5_registro(this, cpm5_d(pessoa));
    let sem_ultimo: unsafe extern "thiscall" fn(usize, usize, usize) -> usize = core::mem::transmute(0x58f110usize);
    sem_ultimo(cpm5_d(this + 0xc), r + 0x14, r + 0x18)
}

/// { 0x62bfa0 } (thiscall, ret 4, injury.cpp): `Injury::reset_player(id)`: tira da lista [this+0x28] (do começo: o
/// cursor +0xa volta a +2) cada item do id (0x68d1f0); com lesão (+0xe ≠ −1), termina (0x62e700, sem notícia);
/// recomeça o histórico (0x631f90); o registro de 31 bytes recomeça: data de hoje (0x417c10 de [0xae2c90]), condição
/// e forma 10000 (+8, +0xa), desgaste 0 (+0xc), sem lesão (+0xe −1), sem recorrente (+0x12 0xff), histórico −1 (+0x14,
/// +0x18), +0x1d 0xff. O bit 0 do +0xc do registro de 79 bytes ([0xae2d0c]) cai. Devolve o endereço desse byte.
unsafe extern "thiscall" fn reiniciar_fisico_do_jogador(this: usize, id: u32) -> usize {
    crate::comparacao::ramo("cpm_5 reiniciar jogador");
    if cpm5_d(this + 0x28) != 0 {
        let l = cpm5_d(this + 0x28);
        core::ptr::write_unaligned((l + 0xa) as *mut usize, cpm5_d(l + 2));
        let proximo: unsafe extern "thiscall" fn(usize) -> usize = core::mem::transmute(0x68d1b0usize);
        let tirar: unsafe extern "thiscall" fn(usize, usize) -> u32 = core::mem::transmute(0x68d1f0usize);
        let mut e = proximo(cpm5_d(this + 0x28));
        while e != 0 {
            if cpm5_d(e) as u32 == id {
                tirar(cpm5_d(this + 0x28), e);
            }
            e = proximo(cpm5_d(this + 0x28));
        }
    }
    let r = cpm5_registro(this, id as usize);
    let pessoa = cpm5_d(0xae23bc).wrapping_add((id as usize).wrapping_mul(0x6e));
    if cpm5_d(r + 0xe) as i32 != -1 {
        let terminar: unsafe extern "thiscall" fn(usize, usize, u32) = core::mem::transmute(0x62e700usize);
        terminar(this, pessoa, 0);
    }
    let recomecar: unsafe extern "thiscall" fn(usize, usize) -> usize = core::mem::transmute(0x631f90usize);
    recomecar(this, cpm5_d(0xae23bc).wrapping_add((id as usize).wrapping_mul(0x6e)));
    let copiar: unsafe extern "thiscall" fn(usize, *mut u8, usize) -> usize = core::mem::transmute(0x417c10usize);
    let mut rascunho = [0u8; 8];
    copiar(r, rascunho.as_mut_ptr(), 0xae2c90); // a data de hoje
    core::ptr::write_unaligned((r + 8) as *mut u16, 10000);
    core::ptr::write_unaligned((r + 0xa) as *mut u16, 10000);
    core::ptr::write_unaligned((r + 0xc) as *mut i16, 0); // sem desgaste
    core::ptr::write_unaligned((r + 0xe) as *mut i32, -1);
    *((r + 0x12) as *mut u8) = 0xff;
    core::ptr::write_unaligned((r + 0x14) as *mut i32, -1);
    core::ptr::write_unaligned((r + 0x18) as *mut i32, -1);
    *((r + 0x1d) as *mut u8) = 0xff;
    let g = cpm5_d(0xae2d0c).wrapping_add((id as usize).wrapping_mul(79)) + 0xc;
    *(g as *mut u8) &= 0xfe;
    g
}

/// Comparador: a 0x62d250 (tratar) não pode rodar duas vezes: o plano antes, com o estado do sorteio guardado (sem
/// contar nem rastrear) e as marcas do registro devolvidas; a original roda. Confere as marcas do registro e do
/// escolhido e, fora do tratar, o estado do sorteio igual ao do plano (os mesmos sorteios).
unsafe extern "thiscall" fn comparar_sortear_lesao_recorrente(this: usize, registro: usize, lesao: *const u8) {
    let estado = crate::comparacao::Memoria::ler(&crate::aleatorio::REGIOES_DO_ESTADO);
    let marcas = (cpm5_b(registro + 0x12), cpm5_b(registro + 0x13));
    let plano = crate::aleatorio::pausar_rastro(|| crate::aleatorio::sem_contar(|| cpm5_plano(this, registro, lesao)));
    let depois_do_plano = crate::comparacao::Memoria::ler(&crate::aleatorio::REGIOES_DO_ESTADO);
    estado.escrever();
    *((registro + 0x12) as *mut u8) = marcas.0;
    *((registro + 0x13) as *mut u8) = marcas.1;
    let tipo = *lesao;
    orig::<unsafe extern "thiscall" fn(usize, usize, *const u8)>(937)(this, registro, lesao);
    let agora = (cpm5_b(registro + 0x12), cpm5_b(registro + 0x13));
    let mesmo_sorteio = crate::comparacao::Memoria::ler(&crate::aleatorio::REGIOES_DO_ESTADO) == depois_do_plano;
    let ok = match plano {
        Cpm5Recorrente::Nada => agora == marcas && mesmo_sorteio,
        Cpm5Recorrente::Marcada => agora == (tipo, 0) && mesmo_sorteio,
        Cpm5Recorrente::Limpar(r) => {
            (cpm5_b(r + 0x12), cpm5_b(r + 0x13)) == (0xff, 0) && (r == registro || agora == (tipo, 0)) && mesmo_sorteio
        }
        Cpm5Recorrente::Tratar(_) => true, // a 0x62d250 sorteia e grava o resto
    };
    PLACAR.registrar(ok, || {
        format!("sortear_lesao_recorrente(tipo {}) plano {:x?}, marcas {:?} -> {:?}, mesmo sorteio={}", tipo, plano, marcas, agora, mesmo_sorteio)
    });
}

/// Comparador: lado a lado pelo começo e o último deslocamento do histórico (8 bytes; a 0x58f110 só grava o segundo).
unsafe extern "thiscall" fn comparar_recomecar_historico_de_lesoes(this: usize, pessoa: usize) -> usize {
    let o = orig::<unsafe extern "thiscall" fn(usize, usize) -> usize>(938);
    if pessoa == 0 {
        return o(this, pessoa);
    }
    let r = cpm5_registro(this, cpm5_d(pessoa));
    let (a, b, igual, mo, mr) = crate::comparacao::lado_a_lado_leve(&[(r + 0x14, 8)], || o(this, pessoa), || recomecar_historico_de_lesoes(this, pessoa));
    PLACAR.registrar(igual && a == b, || format!("recomecar_historico_de_lesoes({}) {:x?} x {:x?}", cpm5_d(pessoa), mo, mr));
    a
}

/// Comparador: a 0x68d1f0 libera o item tirado e a 0x62e700 grava o histórico no arquivo: o plano antes (os itens
/// que ficam, o byte do registro de 79 bytes, os bytes do registro que não mudam); a original roda; confere.
unsafe extern "thiscall" fn comparar_reiniciar_fisico_do_jogador(this: usize, id: u32) -> usize {
    let l = cpm5_d(this + 0x28);
    let esperado: Vec<usize> = if l != 0 { cpd1_itens(l).into_iter().filter(|&e| cpm5_d(e) as u32 != id).collect() } else { Vec::new() };
    let r = cpm5_registro(this, id as usize);
    let g = cpm5_d(0xae2d0c).wrapping_add((id as usize).wrapping_mul(79)) + 0xc;
    let (byte, nivel, b1c) = (cpm5_b(g) & 0xfe, cpm5_b(r + 0x13), cpm5_b(r + 0x1c));
    let ret = orig::<unsafe extern "thiscall" fn(usize, u32) -> usize>(939)(this, id);
    let itens = if l != 0 { cpd1_itens(l) } else { Vec::new() };
    let w = |o: usize| core::ptr::read_unaligned((r + o) as *const i16);
    let dd = |o: usize| cpm5_d(r + o) as i32;
    let ok = itens == esperado && ret == g && cpm5_b(g) == byte
        && cpm5_d(r) == cpm5_d(0xae2c90) && cpm5_d(r + 4) == cpm5_d(0xae2c94)
        && w(8) == 10000 && w(0xa) == 10000 && w(0xc) == 0 && dd(0xe) == -1 && cpm5_b(r + 0x12) == 0xff
        && cpm5_b(r + 0x13) == nivel && dd(0x14) == -1 && dd(0x18) == -1 && cpm5_b(r + 0x1c) == b1c && cpm5_b(r + 0x1d) == 0xff;
    PLACAR.registrar(ok, || {
        let v: Vec<u8> = (0..31).map(|o| cpm5_b(r + o)).collect();
        format!("reiniciar_fisico_do_jogador({}) itens {} (esperava {}), byte {:#x} (esperava {:#x}), registro {:02x?}", id, itens.len(), esperado.len(), cpm5_b(g), byte, v)
    });
    ret
}

// ---------- 249a leva: os recordes do clube: somar o valor da transferência aos totais de compra e venda, os recordes de jogos e gols na carreira pelo clube e o recorde de nota da temporada (club_records.cpp) ----------

unsafe fn cpm6_d(a: usize) -> usize {
    core::ptr::read_unaligned(a as *const usize)
}

unsafe fn cpm6_por(a: usize, v: usize) {
    core::ptr::write_unaligned(a as *mut usize, v);
}

unsafe fn cpm6_w(a: usize) -> i16 {
    core::ptr::read_unaligned(a as *const i16)
}

unsafe fn cpm6_por_w(a: usize, v: i16) {
    core::ptr::write_unaligned(a as *mut i16, v);
}

/// A notícia de recorde (id do clube, tipo) já está no vetor de 6 bytes [this+0x24] (conta +0x2c)?
unsafe fn cpm6_noticia_na_fila(this: usize, id: usize, tipo: u8) -> bool {
    let n = cpm6_d(this + 0x2c) as i32;
    let v = cpm6_d(this + 0x24);
    (0..n.max(0) as usize).any(|k| cpm6_d(v + 6 * k) == id && *((v + 6 * k + 4) as *const u8) == tipo)
}

/// { 0x448ad0 } (thiscall, ret 0xc, club_records.cpp): `Club_Records::add_transfer_totals(valor, comprador,
/// vendedor)`: o vendedor soma o `valor` ao recebido na temporada (+0x36b do registro da temporada 0x4528d0; −1 =
/// ainda nada: fica o valor) e zera o ano (+0x36f); acima do recorde de sempre (0x452710, mesmo campo), o recorde passa
/// a ser o da temporada com o ano da temporada do clube (0x669950), e com o total no mínimo (+0x80 do clube + 500) ×
/// 1000 e o ano diferente do recorde, a notícia de recorde 0x1f (0x452cb0) se ainda não está na fila. O comprador, o
/// mesmo pelo gasto (+0x365, ano +0x369, notícia 0x1e), mas o mínimo é conferido com o recorde ANTIGO e sem o ano. Os
/// registros são criados se faltarem (o segundo argumento 1). Comprador ou vendedor nulo: nada, 1. Devolve 1.
unsafe extern "thiscall" fn somar_totais_de_transferencia(this: usize, valor: i32, comprador: usize, vendedor: usize) -> u32 {
    if comprador == 0 || vendedor == 0 {
        return 1;
    }
    let temporada: unsafe extern "thiscall" fn(usize, usize, u32) -> usize = core::mem::transmute(0x4528d0usize);
    let sempre: unsafe extern "thiscall" fn(usize, usize, u32) -> usize = core::mem::transmute(0x452710usize);
    let ano_do_clube: unsafe extern "C" fn(usize) -> u32 = core::mem::transmute(0x669950usize);
    let noticia: unsafe extern "thiscall" fn(usize, u32, u32) -> u32 = core::mem::transmute(0x452cb0usize);
    let somar = |campo: usize| {
        let v = cpm6_d(campo) as i32;
        cpm6_por(campo, if v == -1 { valor } else { v.wrapping_add(valor) } as usize);
    };
    // o vendedor: o recebido
    let t = temporada(this, vendedor, 1);
    let s = sempre(this, vendedor, 1);
    somar(t + 0x36b);
    cpm6_por_w(t + 0x36f, 0);
    let ano = ano_do_clube(vendedor) as i16;
    if (cpm6_d(s + 0x36b) as i32) < cpm6_d(t + 0x36b) as i32 {
        let minimo = (cpm6_w(vendedor + 0x80) as i32 + 500).wrapping_mul(1000);
        if cpm6_d(t + 0x36b) as i32 >= minimo && ano != cpm6_w(s + 0x36f) && !cpm6_noticia_na_fila(this, cpm6_d(vendedor), 0x1f) {
            crate::comparacao::ramo("cpm_6 noticia de recorde recebido");
            noticia(this, cpm6_d(vendedor) as u32, 0x1f); // recorde de valor recebido
        }
        cpm6_por(s + 0x36b, cpm6_d(t + 0x36b));
        cpm6_por_w(s + 0x36f, ano);
    }
    // o comprador: o gasto
    let t = temporada(this, comprador, 1);
    let s = sempre(this, comprador, 1);
    somar(t + 0x365);
    cpm6_por_w(t + 0x369, 0);
    let ano = ano_do_clube(comprador) as i16;
    if (cpm6_d(t + 0x365) as i32) > cpm6_d(s + 0x365) as i32 {
        let minimo = (cpm6_w(comprador + 0x80) as i32 + 500).wrapping_mul(1000);
        // a original confere o mínimo com o recorde antigo (o ecx que ainda tem o de sempre)
        if cpm6_d(s + 0x365) as i32 >= minimo && !cpm6_noticia_na_fila(this, cpm6_d(comprador), 0x1e) {
            crate::comparacao::ramo("cpm_6 noticia de recorde pago");
            noticia(this, cpm6_d(comprador) as u32, 0x1e); // recorde de valor pago
        }
        cpm6_por(s + 0x365, cpm6_d(t + 0x365));
        cpm6_por_w(s + 0x369, ano);
    }
    1
}

/// { 0x448cb0 } (thiscall, ret 0x10, club_records.cpp): `club_records_update_career_records(jogador, clube, jogos,
/// gols)`: nos recordes de sempre do clube (0x452710, criados se faltarem), se o tipo 0x17 vale para o clube (0x449590)
/// e os `jogos` passam o recorde (+0x247; −1 = sem recorde), o recorde = `jogos` e a referência do jogador em +0x249
/// (0x7e4920); o mesmo com o tipo 0x18 e os `gols` (+0x261, referência +0x263). Devolve 1. Jogador ou clube nulo, ou
/// sem registro: a caixa "Error" (linhas 0x6fa e 0x702) e 0.
unsafe extern "thiscall" fn recordes_de_carreira_no_clube(this: usize, jogador: usize, clube: usize, jogos: u32, gols: u32) -> u32 {
    if jogador == 0 || clube == 0 {
        aviso_em(0x98b6a0, 0x6fa);
        return 0;
    }
    let sempre: unsafe extern "thiscall" fn(usize, usize, u32) -> usize = core::mem::transmute(0x452710usize);
    let r = sempre(this, clube, 1);
    if r == 0 {
        aviso_em(0x98b6a0, 0x702);
        return 0;
    }
    let vale: unsafe extern "stdcall" fn(u32, usize, u32) -> u32 = core::mem::transmute(0x449590usize);
    let referencia: unsafe extern "C" fn(usize, usize) -> u32 = core::mem::transmute(0x7e4920usize);
    for (tipo, campo, n) in [(0x17u32, 0x247usize, jogos as i16), (0x18, 0x261, gols as i16)] {
        if vale(tipo, clube, 1) != 0 {
            let v = cpm6_w(r + campo);
            if v == -1 || n > v {
                cpm6_por_w(r + campo, n);
                referencia(jogador, r + campo + 2);
            }
        }
    }
    1
}

/// { 0x452a90 } (thiscall, ret 4, club_records.cpp): `Club_Records::update_season_rating_record(clube)`: com jogos
/// na temporada (o byte +0x10 da entrada do clube, [this+0x1c] + id × 0x6a) e o registro da temporada (0x4528d0, sem
/// criar), a nota do recorde (+0x1f1) volta a −1.0 e, pelas 50 vagas do elenco (+0xd7), o jogador (não técnico humano:
/// id < [0xae2364]) com estatísticas (+0x61) no clube (+0x39 = clube ou o ligado a ele, 0x540a50) e registro de
/// estatísticas da temporada (0x7c3920, tipo 6) que jogou ao menos metade dos jogos (estatística 1, truncada, 0x7c2150 com
/// 6.5) e tem a maior média (estatística 0x11) vira o recorde: a nota (+0x1f1, float), os jogos (+0x20d), a referência
/// (+0x1f5, 0x7e4920) e +0x20e = 0. Devolve 1 se alguém virou recorde. Sem jogos ou sem registro: 0. Clube nulo: a
/// original (caixa 0x16f2, 0).
unsafe extern "thiscall" fn recorde_de_nota_da_temporada(this: usize, clube: usize) -> u32 {
    if clube == 0 {
        return orig::<unsafe extern "thiscall" fn(usize, usize) -> u32>(942)(this, clube); // caixa: só a original
    }
    let entrada = cpm6_d(this + 0x1c).wrapping_add(cpm6_d(clube).wrapping_mul(0x6a));
    if *((entrada + 0x10) as *const u8) == 0 {
        return 0;
    }
    let temporada: unsafe extern "thiscall" fn(usize, usize, u32) -> usize = core::mem::transmute(0x4528d0usize);
    let r = temporada(this, clube, 0);
    if r == 0 {
        return 0;
    }
    let ligado: unsafe extern "C" fn(usize, u32, u32) -> usize = core::mem::transmute(0x540a50usize);
    let registro: unsafe extern "thiscall" fn(usize, usize, u32) -> usize = core::mem::transmute(0x7c3920usize);
    let estatistica: unsafe extern "stdcall" fn(usize, u32, f32) -> f64 = core::mem::transmute(0x7c2150usize);
    let referencia: unsafe extern "C" fn(usize, usize) -> u32 = core::mem::transmute(0x7e4920usize);
    let nota = (r + 0x1f1) as *mut f32;
    cpm6_por(r + 0x1f1, 0xbf800000); // −1.0f
    let mut achou = 0;
    for k in 0..50usize {
        let p = cpm6_d(clube + 0xd7 + 4 * k);
        if p == 0 {
            continue;
        }
        let est = cpm6_d(p + 0x61);
        if est == 0 || cpm6_d(p) as i32 >= cpm6_d(0xae2364) as i32 {
            continue;
        }
        if cpm6_d(p + 0x39) != clube && cpm6_d(p + 0x39) != ligado(clube, 0, 1) {
            continue;
        }
        let reg = registro(cpm6_d(0xb74350), est, 6);
        if reg == 0 {
            continue;
        }
        let jogou = ftol(estatistica(reg, 1, 6.5)) as u8;
        if (jogou as i32) < *((entrada + 0x10) as *const i8) as i32 / 2 { // menos da metade dos jogos
            continue;
        }
        let media = estatistica(reg, 0x11, 6.5);
        // fcomp com o −1.0 (double) e fcom com o float guardado: passa só com a média maior
        if *nota as f64 == f64_em(0x968948) || media > *nota as f64 {
            crate::comparacao::ramo("cpm_6 recorde de nota da temporada");
            *nota = media as f32;
            *((r + 0x20d) as *mut u8) = jogou;
            referencia(p, r + 0x1f5);
            cpm6_por_w(r + 0x20e, 0);
            achou = 1;
        }
    }
    achou
}

/// Comparador: os registros podem ser criados (realloc) e a notícia realoca: os quatro registros são pedidos antes, na
/// ordem da original (vendedor: temporada, sempre; comprador: temporada, sempre; a segunda vez só acha), e com a fila
/// de notícias sem folga para duas, só a original. Lado a lado pelos quatro registros (+0x365, 12 bytes), a conta das
/// notícias e as duas vagas seguintes.
unsafe extern "thiscall" fn comparar_somar_totais_de_transferencia(this: usize, valor: i32, comprador: usize, vendedor: usize) -> u32 {
    let o = orig::<unsafe extern "thiscall" fn(usize, i32, usize, usize) -> u32>(940);
    if comprador == 0 || vendedor == 0 || (cpm6_d(this + 0x28).wrapping_sub(cpm6_d(this + 0x2c)) as i32) < 2 {
        return o(this, valor, comprador, vendedor); // ponytail: com realloc da fila, só a original
    }
    let temporada: unsafe extern "thiscall" fn(usize, usize, u32) -> usize = core::mem::transmute(0x4528d0usize);
    let sempre: unsafe extern "thiscall" fn(usize, usize, u32) -> usize = core::mem::transmute(0x452710usize);
    let regs = [temporada(this, vendedor, 1), sempre(this, vendedor, 1), temporada(this, comprador, 1), sempre(this, comprador, 1)];
    let fila = cpm6_d(this + 0x24).wrapping_add(cpm6_d(this + 0x2c).wrapping_mul(6));
    let reg = [(regs[0] + 0x365, 12), (regs[1] + 0x365, 12), (regs[2] + 0x365, 12), (regs[3] + 0x365, 12), (this + 0x2c, 4), (fila, 12)];
    let (r, n, igual, mo, mr) = crate::comparacao::lado_a_lado_leve(&reg, || o(this, valor, comprador, vendedor), || somar_totais_de_transferencia(this, valor, comprador, vendedor));
    PLACAR.registrar(igual && r == n, || format!("somar_totais_de_transferencia({}, {}, {}) {:x?} x {:x?}", valor, cpm6_d(comprador), cpm6_d(vendedor), mo, mr));
    r
}

/// Comparador: o registro de sempre é pedido antes (pode ser criado; a segunda vez só acha); lado a lado pelos dois
/// recordes e as referências (+0x247 a +0x27b). Nulos ou sem registro: só a original (a caixa).
unsafe extern "thiscall" fn comparar_recordes_de_carreira_no_clube(this: usize, jogador: usize, clube: usize, jogos: u32, gols: u32) -> u32 {
    let o = orig::<unsafe extern "thiscall" fn(usize, usize, usize, u32, u32) -> u32>(941);
    if jogador == 0 || clube == 0 {
        return o(this, jogador, clube, jogos, gols);
    }
    let sempre: unsafe extern "thiscall" fn(usize, usize, u32) -> usize = core::mem::transmute(0x452710usize);
    let reg = sempre(this, clube, 1);
    if reg == 0 {
        return o(this, jogador, clube, jogos, gols);
    }
    let (r, n, igual, mo, mr) = crate::comparacao::lado_a_lado_leve(&[(reg + 0x247, 0x34)], || o(this, jogador, clube, jogos, gols), || recordes_de_carreira_no_clube(this, jogador, clube, jogos, gols));
    PLACAR.registrar(igual && r == n, || format!("recordes_de_carreira_no_clube({}, {}, {}, {}) {:x?} x {:x?}", cpm6_d(jogador), cpm6_d(clube), jogos as i16, gols as i16, mo, mr));
    r
}

/// Comparador: lado a lado pelo recorde de nota (+0x1f1 a +0x210 do registro da temporada, pedido antes sem criar).
unsafe extern "thiscall" fn comparar_recorde_de_nota_da_temporada(this: usize, clube: usize) -> u32 {
    let o = orig::<unsafe extern "thiscall" fn(usize, usize) -> u32>(942);
    if clube == 0 {
        return o(this, clube);
    }
    let temporada: unsafe extern "thiscall" fn(usize, usize, u32) -> usize = core::mem::transmute(0x4528d0usize);
    let t = temporada(this, clube, 0);
    let reg: &[(usize, usize)] = if t == 0 { &[] } else { &[(t + 0x1f1, 0x1f)] };
    let (r, n, igual, mo, mr) = crate::comparacao::lado_a_lado_leve(reg, || o(this, clube), || recorde_de_nota_da_temporada(this, clube));
    PLACAR.registrar(igual && r == n, || format!("recorde_de_nota_da_temporada({}) original={} rust={} {:x?} x {:x?}", cpm6_d(clube), r, n, mo, mr));
    r
}

// ---------- 249a leva: os amistosos: se a competição vale na data, se o clube já tem amistoso perto da data e acrescentar o amistoso planejado (friendly.cpp) ----------

unsafe fn cpm7_d(a: usize) -> usize {
    core::ptr::read_unaligned(a as *const usize)
}

unsafe fn cpm7_por(a: usize, v: usize) {
    core::ptr::write_unaligned(a as *mut usize, v);
}

/// (dia, ano) de uma data (+0 dia, palavra com sinal; +2 ano, palavra sem sinal).
unsafe fn cpm7_data(a: usize) -> (i16, u16) {
    (core::ptr::read_unaligned(a as *const i16), core::ptr::read_unaligned((a + 2) as *const u16))
}

/// { 0x5c29b0 } (thiscall, ret 8, friendly.cpp): `Friendly::is_comp_current_on_date(comp, data)`: competição que não
/// é a do amistoso ([this+4]) e de id abaixo de [0xae2378] − 0x7f: 1. Senão, a vaga do torneio (this + 0x69 × (byte do
/// id − byte +0xaf), +0xb1 ocupada, +0xb5 a data): 1 se a `data` está depois da data da vaga − 7 dias (0x54c8e0) e
/// antes dela + 7 (0x54c5b0), pelo ano (sem sinal) e depois o dia (com sinal); vaga vazia: 0. O quadro SEH só guarda
/// as datas locais (os destrutores são vazios).
unsafe extern "thiscall" fn competicao_na_data_do_amistoso(this: usize, comp: usize, data: usize) -> u32 {
    if comp != cpm7_d(this + 4) && (cpm7_d(comp) as i32) < (cpm7_d(0xae2378) as i32).wrapping_sub(0x7f) {
        return 1;
    }
    let k = (*(comp as *const u8)).wrapping_sub(*((this + 0xaf) as *const u8)) as i8 as isize;
    let e = this.wrapping_add((k * 0x69) as usize);
    if cpm7_d(e + 0xb1) == 0 {
        return 0;
    }
    let menos: unsafe extern "thiscall" fn(usize, *mut [u8; 8], u32) -> usize = core::mem::transmute(0x54c8e0usize);
    let mais: unsafe extern "thiscall" fn(usize, *mut [u8; 8], u32) -> usize = core::mem::transmute(0x54c5b0usize);
    let (dia, ano) = cpm7_data(data);
    let mut a = [0u8; 8];
    let (adia, aano) = cpm7_data(menos(e + 0xb5, &mut a, 7));
    if ano < aano || (ano == aano && dia <= adia) {
        return 0;
    }
    let (dia, ano) = cpm7_data(data);
    let mut b = [0u8; 8];
    let (bdia, bano) = cpm7_data(mais(e + 0xb5, &mut b, 7));
    (ano < bano || (ano == bano && dia < bdia)) as u32
}

/// { 0x5c45a0 } (thiscall sem usar o this, ret 8, friendly.cpp): `Friendly::candidate_has_nearby_date(clube, data)`:
/// 1 se a lista de amistosos planejados do candidato (+0x12; itens com dia +0 e ano +2) tem a `data`, o dia antes
/// (0x54c8e0) ou o dia depois (0x54c5b0). Percorre do começo (o cursor +0xa = a cabeça +2; 0x68d1b0). Sem lista: 0. As
/// datas locais vêm antes (como a original); o quadro SEH é delas (destrutores vazios).
unsafe extern "thiscall" fn amistoso_perto_da_data(_this: usize, clube: usize, data: usize) -> u32 {
    let menos: unsafe extern "thiscall" fn(usize, *mut [u8; 8], u32) -> usize = core::mem::transmute(0x54c8e0usize);
    let mais: unsafe extern "thiscall" fn(usize, *mut [u8; 8], u32) -> usize = core::mem::transmute(0x54c5b0usize);
    let (mut antes, mut depois) = ([0u8; 8], [0u8; 8]);
    menos(data, &mut antes, 1);
    mais(data, &mut depois, 1);
    let l = cpm7_d(clube + 0x12);
    if l == 0 {
        return 0;
    }
    cpm7_por(l + 0xa, cpm7_d(l + 2));
    let proximo: unsafe extern "thiscall" fn(usize) -> usize = core::mem::transmute(0x68d1b0usize);
    let antes = cpm7_data(antes.as_ptr() as usize);
    let depois = cpm7_data(depois.as_ptr() as usize);
    let mut e = proximo(l);
    while e != 0 {
        let item = cpm7_data(e);
        if item == cpm7_data(data) {
            return 1;
        }
        if item == antes {
            crate::comparacao::ramo("cpm_7 amistoso no dia antes");
            return 1;
        }
        if item == depois {
            crate::comparacao::ramo("cpm_7 amistoso no dia depois");
            return 1;
        }
        e = proximo(l);
    }
    0
}

/// { 0x5c4b60 } (thiscall, ret 0x10, friendly.cpp): `Friendly::add_planned_friendly(anfitriao, mandante, visitante,
/// data)`: acrescenta ao vetor de 0x14 bytes [this+0x34d8] (conta +0x34e0, capacidade +0x34e4; cheio: cresce de 100
/// em 100, realloc 0x945667; sem memória, a caixa "Error" 0x797 e volta) o amistoso: a data em +0 (0x417c10, a cópia
/// devolvida fica na pilha) e os ids (o dword apontado por cada argumento) em +8, +0xc e +0x10; a conta sobe.
unsafe extern "thiscall" fn acrescentar_amistoso_planejado(this: usize, anfitriao: usize, mandante: usize, visitante: usize, data: usize) {
    if cpm7_d(this + 0x34e0) == cpm7_d(this + 0x34e4) {
        crate::comparacao::ramo("cpm_7 amistosos crescem");
        let cap = cpm7_d(this + 0x34e4).wrapping_add(100);
        cpm7_por(this + 0x34e4, cap);
        let realocar: unsafe extern "C" fn(usize, u32) -> usize = core::mem::transmute(0x945667usize);
        let p = realocar(cpm7_d(this + 0x34d8), cap.wrapping_mul(0x14) as u32);
        cpm7_por(this + 0x34d8, p);
        if p == 0 {
            aviso_em(0x9cd0a0, 0x797);
            return;
        }
    }
    crate::comparacao::ramo("cpm_7 amistoso planejado");
    let n = cpm7_d(this + 0x34e0);
    let item = cpm7_d(this + 0x34d8).wrapping_add(n.wrapping_mul(0x14));
    cpm7_por(item + 8, cpm7_d(anfitriao));
    cpm7_por(item + 0xc, cpm7_d(mandante)); // o mandante
    cpm7_por(item + 0x10, cpm7_d(visitante)); // o visitante
    let copiar: unsafe extern "thiscall" fn(usize, *mut [u8; 8], usize) -> usize = core::mem::transmute(0x417c10usize);
    let mut copia = [0u8; 8];
    copiar(item, &mut copia, data);
    cpm7_por(this + 0x34e0, n.wrapping_add(1)); // mais um amistoso
}

/// Comparador: pelo valor (as datas e a vaga só são lidas). Chamada pelas copas e ligas a cada data: sem contador.
unsafe extern "thiscall" fn comparar_competicao_na_data_do_amistoso(this: usize, comp: usize, data: usize) -> u32 {
    let r = orig::<unsafe extern "thiscall" fn(usize, usize, usize) -> u32>(943)(this, comp, data);
    let n = competicao_na_data_do_amistoso(this, comp, data);
    PLACAR.registrar(r == n, || format!("competicao_na_data_do_amistoso({}, {:?}) original={} rust={}", cpm7_d(comp), cpm7_data(data), r, n));
    r
}

/// Comparador: lado a lado pelo cursor da lista (+0xa) e o valor.
unsafe extern "thiscall" fn comparar_amistoso_perto_da_data(this: usize, clube: usize, data: usize) -> u32 {
    let o = orig::<unsafe extern "thiscall" fn(usize, usize, usize) -> u32>(944);
    let l = cpm7_d(clube + 0x12);
    let reg: &[(usize, usize)] = if l == 0 { &[] } else { &[(l + 0xa, 4)] };
    let (r, n, igual, mo, mr) = crate::comparacao::lado_a_lado_leve(reg, || o(this, clube, data), || amistoso_perto_da_data(this, clube, data));
    PLACAR.registrar(igual && r == n, || format!("amistoso_perto_da_data({:?}) original={} rust={} {:x?} x {:x?}", cpm7_data(data), r, n, mo, mr));
    r
}

/// Comparador: a original acrescenta (pode realocar, não roda duas vezes): o plano antes (a conta, os ids e a data),
/// a original roda, confere o item novo e a conta.
unsafe extern "thiscall" fn comparar_acrescentar_amistoso_planejado(this: usize, anfitriao: usize, mandante: usize, visitante: usize, data: usize) {
    let n = cpm7_d(this + 0x34e0);
    let esperado = [cpm7_d(data), cpm7_d(data + 4), 0, cpm7_d(anfitriao), cpm7_d(mandante), cpm7_d(visitante)];
    orig::<unsafe extern "thiscall" fn(usize, usize, usize, usize, usize)>(945)(this, anfitriao, mandante, visitante, data);
    let v = cpm7_d(this + 0x34d8);
    if v == 0 {
        return; // sem memória: a caixa já saiu
    }
    let item = v.wrapping_add(n.wrapping_mul(0x14));
    let feito = [cpm7_d(item), cpm7_d(item + 4), 0, cpm7_d(item + 8), cpm7_d(item + 0xc), cpm7_d(item + 0x10)];
    PLACAR.registrar(feito == esperado && cpm7_d(this + 0x34e0) == n.wrapping_add(1), || {
        format!("acrescentar_amistoso_planejado conta {} -> {}, item {:x?} (esperava {:x?})", n, cpm7_d(this + 0x34e0), feito, esperado)
    });
}

// ---------- 248a leva: as ofertas pelo jogador: se o clube tem oferta por ele, a oferta do clube e se ele tem oferta pendente (transfer_manager.cpp) ----------

unsafe fn cpl1_d(a: usize) -> usize {
    core::ptr::read_unaligned(a as *const usize)
}

/// A marca "sob oferta" da pessoa (bit 0 do byte [this+0x86e] + id × 8).
unsafe fn cpl1_marcada(this: usize, id: usize) -> bool {
    *((cpl1_d(this + 0x86e).wrapping_add(id.wrapping_mul(8))) as *const u8) & 1 != 0
}

/// A oferta do índice `k` (vetor de ponteiros [this]).
unsafe fn cpl1_oferta(this: usize, k: usize) -> usize {
    cpl1_d(cpl1_d(this).wrapping_add(k.wrapping_mul(4)))
}

/// A lista local de índices das ofertas pela pessoa (0x68d020, que a 0x8c5cf0 enche com `todas`), com o cursor
/// (+0xa) reposto no começo (+2) como a original; `f` percorre e a lista é destruída (0x68d040) no fim. Nas saídas
/// antes da 0x8c5cf0 a original constrói e destrói a lista vazia, sem efeito (não aloca): aqui não nasce.
unsafe fn cpl1_com_ofertas<R>(this: usize, pessoa: usize, todas: u32, f: impl FnOnce(usize) -> R) -> R {
    let lista_nova: unsafe extern "thiscall" fn(usize) -> usize = core::mem::transmute(0x68d020usize);
    let destruir: unsafe extern "thiscall" fn(usize) = core::mem::transmute(0x68d040usize);
    let ofertas: unsafe extern "thiscall" fn(usize, usize, usize, u32) -> u32 = core::mem::transmute(0x8c5cf0usize);
    let mut l = [0u8; 0x10];
    let lista = l.as_mut_ptr() as usize;
    lista_nova(lista);
    ofertas(this, pessoa, lista, todas);
    core::ptr::write_unaligned((lista + 0xa) as *mut u32, core::ptr::read_unaligned((lista + 2) as *const u32));
    let r = f(lista);
    destruir(lista);
    r
}

/// O próximo nó da lista (0x68d1b0), ou 0.
unsafe fn cpl1_proximo(lista: usize) -> usize {
    let proximo: unsafe extern "thiscall" fn(usize) -> usize = core::mem::transmute(0x68d1b0usize);
    proximo(lista)
}

/// A pessoa fora da tabela (id ≥ [0xae2364]); pessoa nula passa e é lida como na original.
unsafe fn cpl1_fora(pessoa: usize) -> bool {
    pessoa != 0 && cpl1_d(pessoa) as i32 >= cpl1_d(0xae2364) as i32
}

/// { 0x8cdc90 } (thiscall, ret 8, transfer_manager.cpp): `TRANSFER_MANAGER::club_has_offer_for_player(pessoa,
/// clube)`: 1 se a pessoa marcada como sob oferta (bit 0 de [this+0x86e] + id × 8) tem, entre as ofertas em aberto
/// (0x8c5cf0 sem `todas`), uma do clube (+8 da oferta = id do clube); senão 0 (id fora da tabela também).
unsafe extern "thiscall" fn clube_tem_oferta_pelo_jogador(this: usize, pessoa: usize, clube: usize) -> u32 {
    if cpl1_fora(pessoa) || !cpl1_marcada(this, cpl1_d(pessoa)) {
        return 0;
    }
    cpl1_com_ofertas(this, pessoa, 0, |lista| loop {
        let no = cpl1_proximo(lista);
        if no == 0 {
            return 0;
        }
        if cpl1_d(cpl1_oferta(this, cpl1_d(no)) + 8) == cpl1_d(clube) { // a oferta é do clube
            crate::comparacao::ramo("cpl_1 clube tem oferta");
            return 1;
        }
    })
}

/// { 0x8cdd80 } (thiscall, ret 0xc, transfer_manager.cpp): `TRANSFER_MANAGER::find_club_offer_for_player(pessoa,
/// clube, todas)`: a oferta do clube pela pessoa (a primeira da lista da 0x8c5cf0, com `todas` também as encerradas),
/// ou 0. Sem `todas`, a pessoa tem de estar marcada como sob oferta; id fora da tabela: 0.
unsafe extern "thiscall" fn oferta_do_clube_pelo_jogador(this: usize, pessoa: usize, clube: usize, todas: u32) -> usize {
    if cpl1_fora(pessoa) || (todas == 0 && !cpl1_marcada(this, cpl1_d(pessoa))) {
        return 0;
    }
    cpl1_com_ofertas(this, pessoa, todas, |lista| loop {
        let no = cpl1_proximo(lista);
        if no == 0 {
            return 0;
        }
        let o = cpl1_oferta(this, cpl1_d(no));
        if cpl1_d(o + 8) == cpl1_d(clube) { // a oferta do clube
            crate::comparacao::ramo("cpl_1 oferta do clube");
            return o;
        }
    })
}

/// { 0x8cd150 } (thiscall, ret 4, transfer_manager.cpp): `TRANSFER_MANAGER::player_has_pending_offer(pessoa)`: 1 se
/// a pessoa está sob oferta (0x8cde70 sem a visão do humano) e uma das ofertas em aberto (0x8c5cf0) está na situação
/// (+0x2c) 0, 1, 5 ou 6; senão 0. O índice além da conta (+4) lê a oferta 0, como a original.
unsafe extern "thiscall" fn jogador_com_oferta_pendente(this: usize, pessoa: usize) -> u32 {
    let sob_oferta: unsafe extern "thiscall" fn(usize, usize, u32) -> u32 = core::mem::transmute(0x8cde70usize);
    // ponytail: a original constrói a lista antes de perguntar; vazia, a 0x68d020/0x68d040 não alocam (nada a imitar)
    if sob_oferta(this, pessoa, 0) == 0 {
        return 0;
    }
    cpl1_com_ofertas(this, pessoa, 0, |lista| loop {
        let no = cpl1_proximo(lista);
        if no == 0 {
            return 0;
        }
        let k = cpl1_d(no) as i32;
        let o = if k < cpl1_d(this + 4) as i32 { cpl1_oferta(this, k as usize) } else { cpl1_d(cpl1_d(this)) };
        if matches!(*((o + 0x2c) as *const u8), 0 | 1 | 5 | 6) { // a situação pendente
            crate::comparacao::ramo("cpl_1 oferta pendente");
            return 1;
        }
    })
}

/// As regiões que a 0x8c5cf0 mexe: o cursor da lista própria da oferta da pessoa (+0xa..+0xe; a 0x8c5cf0 o repõe).
unsafe fn cpl1_regioes(this: usize, pessoa: usize) -> [(usize, usize); 1] {
    let e = oferta_pelo_jogador(this, cpl1_d(pessoa) as i32);
    let l = if e == 0 { 0 } else { cpl1_d(e) };
    if l == 0 { [(0xae2364, 4)] } else { [(l, 0xe)] }
}

// ponytail: as três só leem (a lista local nasce e morre nelas); com a pessoa nula, só a original (lê o endereço 0)
unsafe extern "thiscall" fn comparar_clube_tem_oferta_pelo_jogador(this: usize, pessoa: usize, clube: usize) -> u32 {
    let o = orig::<unsafe extern "thiscall" fn(usize, usize, usize) -> u32>(904);
    if pessoa == 0 {
        return o(this, pessoa, clube);
    }
    let reg = cpl1_regioes(this, pessoa);
    let (r, n, igual, mo, mr) = crate::comparacao::lado_a_lado_leve(&reg, || o(this, pessoa, clube), || clube_tem_oferta_pelo_jogador(this, pessoa, clube));
    PLACAR.registrar(igual && r == n, || format!("clube_tem_oferta_pelo_jogador({}, clube {}) original={} rust={} {:x?} x {:x?}", cpl1_d(pessoa), cpl1_d(clube), r, n, mo, mr));
    r
}

