    let menu_da_partida = |bit: u8| {
        let q = parametro_da_tela(0);
        g(0xb6b7ac) != 0 && rb(rd(q + 0x5b)) & bit != 0
    };
    let refazer = |f: usize| {
        let r: unsafe extern "C" fn() = core::mem::transmute(f);
        r();
        por(0xb6b7a8, 1);
    };
