// ---------- 194a leva: as listas de reserva do gerador de jogadores e o prêmio da liga (player_regen.cpp, league.cpp) ----------

/// O comum das duas: tira da lista de registros de 16 bytes ([regen+`lista`], quantos em
/// [regen+`quantos`]) o de chave `id` (+0), puxa os seguintes uma vaga para trás, marca o último com −1
/// em +0, +4 e +8 e diminui a conta.
unsafe fn tirar_da_lista_de_16(regen: usize, id: i32, lista: usize, quantos: usize) {
    let n = || *((regen + quantos) as *const i32);
    let base = || *((regen + lista) as *const usize);
    let Some(i) = (0..n().max(0) as usize).find(|&i| *((base() + i * 16) as *const i32) == id) else {
        return;
    };
    let mut j = i;
    while (j as i32) < n() - 1 {
        core::ptr::copy((base() + (j + 1) * 16) as *const u8, (base() + j * 16) as *mut u8, 16);
        j += 1;
    }
    let ultimo = (base() as isize + (n() as isize - 1) * 16) as usize;
    for o in [0, 4, 8] {
        *((ultimo + o) as *mut i32) = -1;
    }
    *((regen + quantos) as *mut i32) -= 1;
}

/// { 0x7a82b0 } (thiscall, ret 4, player_regen.cpp): tira o registro de reserva de não jogador (técnicos
/// e afins) de id `id` (lista +0x1c, quantos +0x20).
unsafe extern "thiscall" fn tirar_reserva_de_tecnico(regen: usize, id: i32) {
    tirar_da_lista_de_16(regen, id, 0x1c, 0x20);
}

/// { 0x7a8470 } (thiscall, ret 4, player_regen.cpp): tira do banco de jogadores livres o registro dos
/// dados de jogador `id` (lista +0x3c, quantos +0x40).
unsafe extern "thiscall" fn tirar_jogador_do_banco(regen: usize, id: i32) {
    tirar_da_lista_de_16(regen, id, 0x3c, 0x40);
}

/// { 0x682f70 } (thiscall, ret 4, league.cpp): o prêmio total da liga: `cota` para o último colocado e
/// uma cota a mais por posição acima (cota × (1 + 2 + … + times), times = +0x3e). Sem times: a
/// original (caixa de erro, devolve 0).
unsafe extern "thiscall" fn premio_da_liga(liga: usize, cota: i32) -> i32 {
    let times = *((liga + 0x3e) as *const i16);
    if times == 0 {
        return orig::<unsafe extern "thiscall" fn(usize, i32) -> i32>(456)(liga, cota);
    }
    let mut total = 0i32;
    let mut parcela = cota;
    for _ in 0..times.max(0) {
        total = total.wrapping_add(parcela);
        parcela = parcela.wrapping_add(cota);
    }
    total
}

/// As regiões das duas listas: a lista inteira e o contador.
unsafe fn regioes_da_lista_de_16(regen: usize, lista: usize, quantos: usize) -> Vec<(usize, usize)> {
    let n = (*((regen + quantos) as *const i32)).max(0) as usize;
    let mut r = vec![(regen + quantos, 4)];
    if n > 0 {
        r.push((*((regen + lista) as *const usize), n * 16));
    }
    r
}

unsafe extern "thiscall" fn comparar_tirar_reserva_de_tecnico(regen: usize, id: i32) {
    let o = orig::<unsafe extern "thiscall" fn(usize, i32)>(454);
    let (_, _, igual, mo, mr) = crate::comparacao::lado_a_lado(&regioes_da_lista_de_16(regen, 0x1c, 0x20), || o(regen, id), || tirar_reserva_de_tecnico(regen, id));
    PLACAR.registrar(igual, || format!("tirar_reserva_de_tecnico({}) {:x?} x {:x?}", id, mo, mr));
}

unsafe extern "thiscall" fn comparar_tirar_jogador_do_banco(regen: usize, id: i32) {
    let o = orig::<unsafe extern "thiscall" fn(usize, i32)>(455);
    let (_, _, igual, mo, mr) = crate::comparacao::lado_a_lado(&regioes_da_lista_de_16(regen, 0x3c, 0x40), || o(regen, id), || tirar_jogador_do_banco(regen, id));
    PLACAR.registrar(igual, || format!("tirar_jogador_do_banco({}) {:x?} x {:x?}", id, mo, mr));
}

unsafe extern "thiscall" fn comparar_premio_da_liga(liga: usize, cota: i32) -> i32 {
    let r = orig::<unsafe extern "thiscall" fn(usize, i32) -> i32>(456)(liga, cota);
    if *((liga + 0x3e) as *const i16) == 0 {
        return r;
    }
    let n = premio_da_liga(liga, cota);
    PLACAR.registrar(r == n, || format!("premio_da_liga({}) original={} rust={}", cota, r, n));
    r
}

// ---------- 193a leva: as cláusulas do contrato no gerente de transferências: percentual da próxima venda, bônus por jogo e bônus pela seleção (transfer_manager.cpp) ----------

/// O comum das três: desliga o bit `bit` das marcas do jogador `*id` (+0x86e, 8 bytes por pessoa) e
/// tira o registro dele (13 bytes, o id em `chave`) da lista [gerente+`lista`] (quantos em
/// [gerente+`quantos`]), puxando os seguintes uma vaga para trás.
unsafe fn tirar_da_lista_de_pagamentos(gerente: usize, id: *const i32, bit: u8, lista: usize, quantos: usize, chave: usize) {
    let marcas = (*((gerente + 0x86e) as *const usize) as isize + *id as isize * 8) as *mut u8;
    if *marcas & bit != 0 {
        *marcas -= bit;
    }
    let n = *((gerente + quantos) as *const i32);
    let base = *((gerente + lista) as *const usize);
    let Some(i) = (0..n.max(0) as usize).find(|&i| core::ptr::read_unaligned((base + i * 13 + chave) as *const i32) == *id) else {
        return;
    };
    let mut j = i + 1;
    while (j as i32) < *((gerente + quantos) as *const i32) {
        let origem = *((gerente + lista) as *const usize) + j * 13;
        core::ptr::copy(origem as *const u8, (base + (j - 1) * 13) as *mut u8, 13);
        j += 1;
    }
    *((gerente + quantos) as *mut i32) -= 1;
}

/// { 0x8cb4f0 } (thiscall, ret 4, transfer_manager.cpp): tira o percentual da próxima venda (bit 8;
/// lista +0x880, quantos +0x888, o id em +9).
unsafe extern "thiscall" fn tirar_percentual_da_proxima_venda(gerente: usize, id: *const i32) {
    tirar_da_lista_de_pagamentos(gerente, id, 8, 0x880, 0x888, 9);
}

/// { 0x8cb590 } (thiscall, ret 4, transfer_manager.cpp): tira o bônus por jogo no time principal (bit 2;
/// lista +0x88c, quantos +0x894, o id em +0).
unsafe extern "thiscall" fn tirar_bonus_por_jogo(gerente: usize, id: *const i32) {
    tirar_da_lista_de_pagamentos(gerente, id, 2, 0x88c, 0x894, 0);
}

/// { 0x8cb630 } (thiscall, ret 4, transfer_manager.cpp): tira o bônus por jogo pela seleção (bit 4;
/// lista +0x898, quantos +0x8a0, o id em +0).
unsafe extern "thiscall" fn tirar_bonus_pela_selecao(gerente: usize, id: *const i32) {
    tirar_da_lista_de_pagamentos(gerente, id, 4, 0x898, 0x8a0, 0);
}

/// As regiões das três: o byte das marcas, a lista inteira e o contador.
unsafe fn regioes_da_lista_de_pagamentos(gerente: usize, id: *const i32, lista: usize, quantos: usize) -> Vec<(usize, usize)> {
    let marcas = (*((gerente + 0x86e) as *const usize) as isize + *id as isize * 8) as usize;
    let n = (*((gerente + quantos) as *const i32)).max(0) as usize;
    let mut r = vec![(marcas, 1), (gerente + quantos, 4)];
    if n > 0 {
        r.push((*((gerente + lista) as *const usize), n * 13));
    }
    r
}

unsafe fn comparar_lista_de_pagamentos(nome: &str, k: usize, rust: unsafe extern "thiscall" fn(usize, *const i32), gerente: usize, id: *const i32, lista: usize, quantos: usize) {
    let o = orig::<unsafe extern "thiscall" fn(usize, *const i32)>(k);
    let reg = regioes_da_lista_de_pagamentos(gerente, id, lista, quantos);
    let (_, _, igual, mo, mr) = crate::comparacao::lado_a_lado(&reg, || o(gerente, id), || rust(gerente, id));
    PLACAR.registrar(igual, || format!("{}({}) {:x?} x {:x?}", nome, *id, mo, mr));
}

unsafe extern "thiscall" fn comparar_tirar_percentual_da_proxima_venda(gerente: usize, id: *const i32) {
    comparar_lista_de_pagamentos("tirar_percentual_da_proxima_venda", 451, tirar_percentual_da_proxima_venda, gerente, id, 0x880, 0x888);
}

unsafe extern "thiscall" fn comparar_tirar_bonus_por_jogo(gerente: usize, id: *const i32) {
    comparar_lista_de_pagamentos("tirar_bonus_por_jogo", 452, tirar_bonus_por_jogo, gerente, id, 0x88c, 0x894);
}

unsafe extern "thiscall" fn comparar_tirar_bonus_pela_selecao(gerente: usize, id: *const i32) {
    comparar_lista_de_pagamentos("tirar_bonus_pela_selecao", 453, tirar_bonus_pela_selecao, gerente, id, 0x898, 0x8a0);
}

// ---------- 192a leva: a entrada da aposentadoria, as competições do amistoso e a vaga da notícia (player_regen.cpp, friendly.cpp, news.cpp) ----------

/// { 0x7a7ed0 } (thiscall, ret 8, player_regen.cpp): a entrada da pessoa `*id` na lista das
/// aposentadorias ([+4], 0x1a bytes cada, [+8] quantas): com `por_lesao`, só se o motivo (+0x18) for 8;
/// senão só se já anunciada (+0x19). Fora isso, 0.
unsafe extern "thiscall" fn entrada_da_aposentadoria(regen: usize, id: *const i32, por_lesao: u32) -> usize {
    let lista = *((regen + 4) as *const usize);
    let n = *((regen + 8) as *const i32);
    for i in 0..n.max(0) as usize {
        let e = lista + i * 0x1a;
        if core::ptr::read_unaligned(e as *const i32) == *id {
            let ok = if por_lesao != 0 { *((e + 0x18) as *const u8) == 8 } else { *((e + 0x19) as *const u8) != 0 };
            return if ok { e } else { 0 };
        }
    }
    0
}

/// { 0x5ca030 } (thiscall, friendly.cpp): grava na tabela das competições ([0xadadfc]) o objeto dos
/// amistosos ([0xae2c74]) na chave [0x9cf668] e os torneios do amistoso (127 vagas de 0x69 bytes a partir
/// de +0xb1; com +0xb1 e +0x116 não nulos, +0x116 vai para a chave [+0xaf] + vaga).
unsafe extern "thiscall" fn registrar_competicoes_do_amistoso(amistoso: usize) {
    let tabela = || *(0xadadfc as *const usize) as isize;
    *((tabela() + *(0x9cf668 as *const i32) as isize * 4) as *mut usize) = *(0xae2c74 as *const usize);
    for i in 0..0x7fusize {
        let p = amistoso + 0x116 + i * 0x69;
        let objeto = core::ptr::read_unaligned(p as *const usize);
        if core::ptr::read_unaligned((p - 0x65) as *const usize) != 0 && objeto != 0 {
            let chave = core::ptr::read_unaligned((amistoso + 0xaf) as *const i16) as isize + i as isize;
            *((tabela() + chave * 4) as *mut usize) = objeto;
        }
    }
}

/// { 0x785830 } (thiscall, ret 4, news.cpp): o valor da vaga `vaga` (0 a 49) da notícia (+5, 4 bytes
/// cada). Fora da faixa: a original (caixa de erro, devolve 0).
unsafe extern "thiscall" fn vaga_da_noticia(noticia: usize, vaga: i8) -> u32 {
    if !(0..0x32).contains(&vaga) {
        return orig::<unsafe extern "thiscall" fn(usize, i8) -> u32>(450)(noticia, vaga);
    }
    core::ptr::read_unaligned((noticia + 5 + vaga as usize * 4) as *const u32)
}

unsafe extern "thiscall" fn comparar_entrada_da_aposentadoria(regen: usize, id: *const i32, por_lesao: u32) -> usize {
    let r = orig::<unsafe extern "thiscall" fn(usize, *const i32, u32) -> usize>(448)(regen, id, por_lesao);
    let n = entrada_da_aposentadoria(regen, id, por_lesao);
    PLACAR.registrar(r == n, || format!("entrada_da_aposentadoria({}, {}) original={:#x} rust={:#x}", *id, por_lesao, r, n));
    r
}

unsafe extern "thiscall" fn comparar_registrar_competicoes_do_amistoso(amistoso: usize) {
    let o = orig::<unsafe extern "thiscall" fn(usize)>(449);
    let tabela = *(0xadadfc as *const usize) as isize;
    let base = core::ptr::read_unaligned((amistoso + 0xaf) as *const i16) as isize;
    let reg = [((tabela + *(0x9cf668 as *const i32) as isize * 4) as usize, 4), ((tabela + base * 4) as usize, 0x7f * 4)];
    let (_, _, igual, mo, mr) = crate::comparacao::lado_a_lado(&reg, || o(amistoso), || registrar_competicoes_do_amistoso(amistoso));
    PLACAR.registrar(igual, || format!("registrar_competicoes_do_amistoso {:x?} x {:x?}", mo, mr));
}

unsafe extern "thiscall" fn comparar_vaga_da_noticia(noticia: usize, vaga: i8) -> u32 {
    let r = orig::<unsafe extern "thiscall" fn(usize, i8) -> u32>(450)(noticia, vaga);
    if !(0..0x32).contains(&vaga) {
        return r;
    }
    let n = vaga_da_noticia(noticia, vaga);
    PLACAR.registrar(r == n, || format!("vaga_da_noticia({}) original={:#x} rust={:#x}", vaga, r, n));
    r
}

// ---------- 191a leva: o clube do contrato acertado, o jogo pela seleção e a punição guardada (transfer_manager.cpp, discipline.cpp) ----------

/// { 0x8c5450 } (thiscall, ret 8, transfer_manager.cpp): com a marca de contrato acertado (0x40) da
/// pessoa `*id`, procura o contrato (0x4cca30 em [0xae1050]): achou, grava em `clube` (se não nulo) o
/// clube do contrato ([0xae23b4], 581 bytes por clube, pelo id em +4) e devolve 1; não achou, desliga a
/// marca e devolve 0.
unsafe extern "thiscall" fn clube_do_contrato_acertado(gerente: usize, id: *const i32, clube: *mut usize) -> u32 {
    let marcas = |g: usize| (*((g + 0x86e) as *const usize) as isize + *id as isize * 8) as *mut u8;
    if *marcas(gerente) & 0x40 == 0 {
        return 0;
    }
    let procurar: unsafe extern "thiscall" fn(usize, i32) -> usize = core::mem::transmute(0x4cca30usize);
    let contrato = procurar(*(0xae1050 as *const usize), *id);
    if contrato == 0 {
        *marcas(gerente) &= 0xbf;
        return 0;
    }
    if !clube.is_null() {
        *clube = (*(0xae23b4 as *const usize) as isize + *((contrato + 4) as *const i32) as isize * 581) as usize;
    }
    1
}

/// O registro de 8 bytes da pessoa `*id` no gerente de transferências (+0x86e).
unsafe fn registro_da_pessoa(gerente: usize, id: *const i32) -> usize {
    (*((gerente + 0x86e) as *const usize) as isize + *id as isize * 8) as usize
}

/// { 0x8ce920 } (thiscall, ret 8, transfer_manager.cpp): registra que o jogador jogou o jogo `numero`
/// da seleção: os bits dos últimos jogos (+3, 16 bits) andam um por jogo desde o último registrado
/// (+5), o mais novo é ligado e o número fica em +5.
unsafe extern "thiscall" fn registrar_jogo_pela_selecao(gerente: usize, id: *const i32, numero: i16) {
    let r = registro_da_pessoa(gerente, id);
    let bits = (r + 3) as *mut u16;
    let ultimo = (r + 5) as *mut i16;
    let d = numero.wrapping_sub(core::ptr::read_unaligned(ultimo));
    for _ in 0..d.max(0) {
        core::ptr::write_unaligned(bits, core::ptr::read_unaligned(bits) << 1);
        *(bits as *mut u8) &= 0xfe;
    }
    *(bits as *mut u8) |= 1;
    core::ptr::write_unaligned(ultimo, numero);
}

/// { 0x55cb60 } (thiscall, ret 8, discipline.cpp): a punição guardada do jogador `id` na vaga `vaga`:
/// percorre a lista das guardadas (+0x1c, do começo, 0x68d1b0) enquanto o jogador tem alguma
/// (byte +0x1c do registro de 29 bytes em [+0x14]) e devolve a de mesmo jogador e vaga; 0 se nenhuma.
unsafe extern "thiscall" fn punicao_guardada(disciplina: usize, id: i32, vaga: i8) -> usize {
    let lista = disciplina + 0x1c;
    let registro = (*((disciplina + 0x14) as *const usize) as isize + id as isize * 29) as usize;
    core::ptr::write_unaligned((lista + 0xa) as *mut u32, core::ptr::read_unaligned((lista + 2) as *const u32));
    let proxima: unsafe extern "thiscall" fn(usize) -> usize = core::mem::transmute(0x68d1b0usize);
    let mut p = proxima(lista);
    while p != 0 {
        if *((registro + 0x1c) as *const i8) <= 0 {
            return 0;
        }
        if *(p as *const i32) == id && *((p + 4) as *const i8) == vaga {
            return p;
        }
        p = proxima(lista);
    }
    0
}

unsafe extern "thiscall" fn comparar_clube_do_contrato_acertado(gerente: usize, id: *const i32, clube: *mut usize) -> u32 {
    let o = orig::<unsafe extern "thiscall" fn(usize, *const i32, *mut usize) -> u32>(445);
    let mut reg = vec![(registro_da_pessoa(gerente, id), 1)];
    if !clube.is_null() {
        reg.push((clube as usize, 4));
    }
    let (ro, rr, igual, mo, mr) = crate::comparacao::lado_a_lado(&reg, || o(gerente, id, clube), || clube_do_contrato_acertado(gerente, id, clube));
    PLACAR.registrar(igual && ro == rr, || format!("clube_do_contrato_acertado({}) original={} rust={} {:x?} x {:x?}", *id, ro, rr, mo, mr));
    ro
}

unsafe extern "thiscall" fn comparar_registrar_jogo_pela_selecao(gerente: usize, id: *const i32, numero: i16) {
    let o = orig::<unsafe extern "thiscall" fn(usize, *const i32, i16)>(446);
    let reg = [(registro_da_pessoa(gerente, id) + 3, 4)];
    let (_, _, igual, mo, mr) = crate::comparacao::lado_a_lado(&reg, || o(gerente, id, numero), || registrar_jogo_pela_selecao(gerente, id, numero));
    PLACAR.registrar(igual, || format!("registrar_jogo_pela_selecao({}, {}) {:x?} x {:x?}", *id, numero, mo, mr));
}

unsafe extern "thiscall" fn comparar_punicao_guardada(disciplina: usize, id: i32, vaga: i8) -> usize {
    let o = orig::<unsafe extern "thiscall" fn(usize, i32, i8) -> usize>(447);
    // a lista guarda o cursor: as duas partem do mesmo e têm de deixá-lo igual
    let (ro, rr, igual, mo, mr) = crate::comparacao::lado_a_lado(&[(disciplina + 0x1c, 0x12)], || o(disciplina, id, vaga), || punicao_guardada(disciplina, id, vaga));
    PLACAR.registrar(igual && ro == rr, || format!("punicao_guardada({}, {}) original={:#x} rust={:#x} {:x?} x {:x?}", id, vaga, ro, rr, mo, mr));
    ro
}

// ---------- 190a leva: o contrato de empréstimo, as marcas de lance da lista de observados e o técnico substituto (contract_manager.cpp, shortlist_manager.cpp, human_manager.cpp) ----------

/// A entrada de 79 bytes da pessoa `*id` na tabela [0xae2d0c] (em +4 a vaga do empréstimo, −1 sem).
unsafe fn entrada_do_emprestimo(id: *const i32) -> usize {
    (*(0xae2d0c as *const usize) as isize + *id as isize * 79) as usize
}

/// { 0x4d0bd0 } (thiscall, ret 4, contract_manager.cpp): libera a vaga do contrato de empréstimo da
/// pessoa, se ela tiver uma: −1 no começo da vaga (80 bytes cada, em [gerente]) e na entrada da pessoa.
unsafe extern "thiscall" fn tirar_contrato_de_emprestimo(gerente: usize, id: *const i32) {
    let e = entrada_do_emprestimo(id);
    let vaga = core::ptr::read_unaligned((e + 4) as *const i32);
    if vaga != -1 {
        *((*(gerente as *const usize) as isize + vaga as isize * 80) as *mut i32) = -1;
        core::ptr::write_unaligned((entrada_do_emprestimo(id) + 4) as *mut i32, -1);
    }
}

/// A lista de observados do clube `*clube` (9 bytes por clube em [gerente+0xdc]: +0 as vagas, +4 a marca).
unsafe fn lista_do_clube(gerente: usize, clube: *const i32) -> usize {
    (*((gerente + 0xdc) as *const usize) as isize + *clube as isize * 9) as usize
}

/// { 0x84aeb0 } (thiscall, ret 8, shortlist_manager.cpp): com a lista do clube ativa (marca 1), tira a
/// marca de lance (+0x17 = −1) das 40 vagas (0x25 bytes cada) cujo alvo (+0xf) é o jogador `*jogador`.
unsafe extern "thiscall" fn desmarcar_lances_pelo_jogador(gerente: usize, clube: *const i32, jogador: *const i32) {
    let l = lista_do_clube(gerente, clube);
    if *((l + 4) as *const u8) != 1 {
        return;
    }
    for i in 0..40 {
        let v = core::ptr::read_unaligned(l as *const usize) + i * 0x25;
        if core::ptr::read_unaligned((v + 0xf) as *const i32) == *jogador {
            core::ptr::write_unaligned((v + 0x17) as *mut i32, -1);
        }
    }
}

/// { 0x600e90 } (cdecl, human_manager.cpp): quem responde pelo técnico do clube: o auxiliar (+0xd3)
/// se houver; senão, dos cinco da comissão (+0x19f) com dados (+0x69), o de maior reputação (+0xa,
/// ficando o primeiro no empate); 0 se nenhum.
unsafe extern "C" fn tecnico_substituto(clube: usize) -> usize {
    let auxiliar = core::ptr::read_unaligned((clube + 0xd3) as *const usize);
    if auxiliar != 0 {
        return auxiliar;
    }
    let reputacao = |p: usize| core::ptr::read_unaligned((core::ptr::read_unaligned((p + 0x69) as *const usize) + 0xa) as *const i16);
    let mut melhor = 0usize;
    for k in 0..5 {
        let c = core::ptr::read_unaligned((clube + 0x19f + k * 4) as *const usize);
        if c == 0 || core::ptr::read_unaligned((c + 0x69) as *const usize) == 0 {
            continue;
        }
        if melhor == 0 || reputacao(c) > reputacao(melhor) {
            melhor = c;
        }
    }
    melhor
}

unsafe extern "thiscall" fn comparar_tirar_contrato_de_emprestimo(gerente: usize, id: *const i32) {
    let o = orig::<unsafe extern "thiscall" fn(usize, *const i32)>(442);
    let e = entrada_do_emprestimo(id);
    let mut reg = vec![(e + 4, 4)];
    let vaga = core::ptr::read_unaligned((e + 4) as *const i32);
    if vaga != -1 {
        reg.push(((*(gerente as *const usize) as isize + vaga as isize * 80) as usize, 4));
    }
    let (_, _, igual, mo, mr) = crate::comparacao::lado_a_lado(&reg, || o(gerente, id), || tirar_contrato_de_emprestimo(gerente, id));
    PLACAR.registrar(igual, || format!("tirar_contrato_de_emprestimo({}) {:x?} x {:x?}", *id, mo, mr));
}

unsafe extern "thiscall" fn comparar_desmarcar_lances_pelo_jogador(gerente: usize, clube: *const i32, jogador: *const i32) {
    let o = orig::<unsafe extern "thiscall" fn(usize, *const i32, *const i32)>(443);
    let l = lista_do_clube(gerente, clube);
    let reg = if *((l + 4) as *const u8) == 1 { vec![(core::ptr::read_unaligned(l as *const usize), 40 * 0x25)] } else { vec![(l, 9)] };
    let (_, _, igual, mo, mr) = crate::comparacao::lado_a_lado(&reg, || o(gerente, clube, jogador), || desmarcar_lances_pelo_jogador(gerente, clube, jogador));
    PLACAR.registrar(igual, || format!("desmarcar_lances_pelo_jogador({}, {}) {:x?} x {:x?}", *clube, *jogador, mo, mr));
}

unsafe extern "C" fn comparar_tecnico_substituto(clube: usize) -> usize {
    let r = orig::<unsafe extern "C" fn(usize) -> usize>(444)(clube);
    let n = tecnico_substituto(clube);
    PLACAR.registrar(r == n, || format!("tecnico_substituto({:#x}) original={:#x} rust={:#x}", clube, r, n));
    r
}

// ---------- 189a leva: a competição do amistoso, a data internacional e o registro de técnico (friendly.cpp, staff_records.cpp) ----------

/// { 0x5c2990 } (thiscall, ret 4, friendly.cpp): `competicao` é a competição dos amistosos (+4)?
unsafe extern "thiscall" fn e_competicao_do_amistoso(amistoso: usize, competicao: usize) -> u32 {
    (competicao == *((amistoso + 4) as *const usize)) as u32
}

/// { 0x5cb9b0 } (thiscall, ret 0x18, friendly.cpp): preenche a data internacional de 20 bytes: dia,
/// mês e duração (+0..+2), o ano a somar (+0xb), o continente (+0xc) e a competição (+0x10).
unsafe extern "thiscall" fn preencher_data_internacional(data: usize, dia: u8, mes: u8, duracao: u8, ano: u8, continente: u32, competicao: u32) {
    let b = data as *mut u8;
    *b = dia;
    *b.add(1) = mes;
    *b.add(2) = duracao;
    *b.add(0xb) = ano;
    core::ptr::write_unaligned(b.add(0xc) as *mut u32, continente);
    core::ptr::write_unaligned(b.add(0x10) as *mut u32, competicao);
}

/// O registro de técnico de 210 bytes da entrada `*id` ([registros+8]).
unsafe fn registro_de_tecnico(registros: usize, id: *const i32) -> usize {
    (*((registros + 8) as *const usize) as isize + *id as isize * 210) as usize
}

/// { 0x86fc20 } (thiscall, ret 4, staff_records.cpp): zera o registro de técnico da entrada e põe −1
/// nos ids do dono, da liga e dos clubes das passagens (+0x4a, +0x5e, +0x72, +0x86, +0xc2, +0xc6).
unsafe extern "thiscall" fn limpar_registro_de_tecnico(registros: usize, id: *const i32) {
    let r = registro_de_tecnico(registros, id);
    core::ptr::write_bytes(r as *mut u8, 0, 210);
    for o in [0x86, 0xc2, 0xc6, 0x4a, 0x5e, 0x72] {
        core::ptr::write_unaligned((r + o) as *mut i32, -1);
    }
}

unsafe extern "thiscall" fn comparar_e_competicao_do_amistoso(amistoso: usize, competicao: usize) -> u32 {
    let r = orig::<unsafe extern "thiscall" fn(usize, usize) -> u32>(439)(amistoso, competicao);
    let n = e_competicao_do_amistoso(amistoso, competicao);
    PLACAR.registrar(r == n, || format!("e_competicao_do_amistoso({:#x}) original={} rust={}", competicao, r, n));
    r
}

unsafe extern "thiscall" fn comparar_preencher_data_internacional(data: usize, dia: u8, mes: u8, duracao: u8, ano: u8, continente: u32, competicao: u32) {
    let o = orig::<unsafe extern "thiscall" fn(usize, u8, u8, u8, u8, u32, u32)>(440);
    let (_, _, igual, mo, mr) = crate::comparacao::lado_a_lado(&[(data, 0x14)], || o(data, dia, mes, duracao, ano, continente, competicao),
        || preencher_data_internacional(data, dia, mes, duracao, ano, continente, competicao));
    PLACAR.registrar(igual, || format!("preencher_data_internacional {:x?} x {:x?}", mo, mr));
}

unsafe extern "thiscall" fn comparar_limpar_registro_de_tecnico(registros: usize, id: *const i32) {
    let o = orig::<unsafe extern "thiscall" fn(usize, *const i32)>(441);
    let r = registro_de_tecnico(registros, id);
    let (_, _, igual, mo, mr) = crate::comparacao::lado_a_lado(&[(r, 210)], || o(registros, id), || limpar_registro_de_tecnico(registros, id));
    PLACAR.registrar(igual, || format!("limpar_registro_de_tecnico({}) {:x?} x {:x?}", *id, mo, mr));
}

// ---------- 188a leva: a lista de observados do gerente de transferências, a entrada do treino e a carga de treino (game.cpp, injury.cpp) ----------

/// { 0x5d5ab0 } (thiscall, game.cpp): o gerente da lista de observados guardado em +0x856 do gerente
/// de transferências.
unsafe extern "thiscall" fn lista_de_observados(gerente: usize) -> usize {
    core::ptr::read_unaligned((gerente + 0x856) as *const usize)
}

/// { 0x5d5ac0 } (thiscall, ret 4, game.cpp): a entrada de 6 bytes do jogador na tabela do treino
/// ([treino+0x651d]), pelo id dos dados do jogador ([[jogador+0x61]]).
unsafe extern "thiscall" fn entrada_do_treino(treino: usize, jogador: usize) -> usize {
    let tabela = core::ptr::read_unaligned((treino + 0x651d) as *const usize);
    let id = *(core::ptr::read_unaligned((jogador + 0x61) as *const usize) as *const i32);
    (tabela as isize + id as isize * 6) as usize
}

/// O byte da carga de treino do jogador `*id` no registro de condição (31 bytes por jogador, +0x1e).
unsafe fn byte_da_carga(lesoes: usize, id: *const i32) -> *mut u8 {
    (*(lesoes as *const usize) as isize + *id as isize * 31 + 0x1e) as *mut u8
}

/// { 0x62c660 } (thiscall, ret 8, injury.cpp): grava a carga de treino `valor` do jogador `*id`.
unsafe extern "thiscall" fn gravar_carga_de_treino(lesoes: usize, id: *const i32, valor: u8) {
    *byte_da_carga(lesoes, id) = valor;
}

unsafe extern "thiscall" fn comparar_lista_de_observados(gerente: usize) -> usize {
    let r = orig::<unsafe extern "thiscall" fn(usize) -> usize>(436)(gerente);
    let n = lista_de_observados(gerente);
    PLACAR.registrar(r == n, || format!("lista_de_observados original={:#x} rust={:#x}", r, n));
    r
}

unsafe extern "thiscall" fn comparar_entrada_do_treino(treino: usize, jogador: usize) -> usize {
    let r = orig::<unsafe extern "thiscall" fn(usize, usize) -> usize>(437)(treino, jogador);
    let n = entrada_do_treino(treino, jogador);
    PLACAR.registrar(r == n, || format!("entrada_do_treino original={:#x} rust={:#x}", r, n));
    r
}

unsafe extern "thiscall" fn comparar_gravar_carga_de_treino(lesoes: usize, id: *const i32, valor: u8) {
    let o = orig::<unsafe extern "thiscall" fn(usize, *const i32, u8)>(438);
    let a = byte_da_carga(lesoes, id) as usize;
    let (_, _, igual, mo, mr) = crate::comparacao::lado_a_lado(&[(a, 1)], || o(lesoes, id, valor), || gravar_carga_de_treino(lesoes, id, valor));
    PLACAR.registrar(igual, || format!("gravar_carga_de_treino({}, {}) {:x?} x {:x?}", *id, valor, mo, mr));
}

// ---------- 187a leva: as telas da partida (5): o painel dos últimos placares, a tela seguinte e a cor do título (match_screens.cpp, scrman.cpp, Setup.cpp) ----------

/// { 0x7febb0 } (thiscall, scrman.cpp): o gerente de telas não tem para onde avançar? (o bloco de
/// parâmetros da tela atual sem a tela seguinte em +0x1f8). Sem bloco: a original (caixa de erro e saída).
unsafe extern "thiscall" fn sem_tela_seguinte(gerente: usize) -> u32 {
    let vaga = *((gerente + 0x382a) as *const i16) as isize;
    let bloco = core::ptr::read_unaligned((gerente as isize + 0x7e2 + vaga * 0x300) as *const usize);
    if bloco == 0 {
        return orig::<unsafe extern "thiscall" fn(usize) -> u32>(434)(gerente);
    }
    (*((bloco + 0x1f8) as *const usize) == 0) as u32
}

/// { 0x839590 } (cdecl, Setup.cpp): a cor do título: [0xae3184] com `x` ≠ 0, senão [0xae31a8]. A
/// original só troca `ax`: os 16 bits de cima da devolução são os de `x`.
unsafe extern "C" fn cor_do_titulo(x: u32) -> u32 {
    let c = if x != 0 { *(0xae3184 as *const u16) } else { *(0xae31a8 as *const u16) };
    (x & 0xffff_0000) | c as u32
}

/// Copia o texto C de `origem` (com o zero) para o texto de trabalho 0xde1f64.
unsafe fn copiar_para_o_texto(origem: usize) {
    let mut i = 0;
    loop {
        let b = *((origem + i) as *const u8);
        *((0xde1f64 + i) as *mut u8) = b;
        if b == 0 {
            break;
        }
        i += 1;
    }
}

/// O nome da competição do registro `c` (107 bytes) no texto 0xde1f64 do jeito do painel: "Friendlies"
/// e "Reserves" para as dos amistosos ([0x9cf668]) e reservas ([0x9cf684]) com mais de uma rodada
/// (+8 > +4 de `rodadas`); senão o nome (+0x38).
unsafe fn nome_da_competicao_no_painel(c: usize, rodadas: usize) {
    let texto: unsafe extern "C" fn(usize, usize, ...) -> i32 = core::mem::transmute(0x66f4e0usize);
    let mais_de_uma = core::ptr::read_unaligned((rodadas + 8) as *const i32) > core::ptr::read_unaligned((rodadas + 4) as *const i32);
    let chave = *(c as *const usize);
    if chave == *(0x9cf668 as *const usize) && mais_de_uma {
        texto(0xde1f64, 0xa1631c);
    } else if chave == *(0x9cf684 as *const usize) && mais_de_uma {
        texto(0xde1f64, 0xa16310);
    } else {
        copiar_para_o_texto(c + 0x38);
    }
}

/// { 0x723d20 } (cdecl, match_screens.cpp): desenha o painel dos últimos placares a partir de `*topo`
/// até `*base`. Título (dentro da partida, parâmetro 0 ≠ 0: "<competição> Latest" à esquerda 0x6e e
/// largura 0x30c, `*topo` += 0x28; na tela avulsa o nome em 0x64/0x316, += 0x41) e o selo da competição
/// (0x804030, fora dos amistosos 0x5c2990 e das seleções 0x7e6f20). Com mais de uma rodada no dia
/// ([[0xb67a50]+0x2a] > 1) a lista dos grupos do dia ([+1], 0x18 bytes, [+9] quantos) com as partidas
/// de cada um ([+0xd], 84 bytes, de +4 a +8 do grupo): cabeçalho do grupo (Copa do Mundo, Internacional,
/// Continental ou o nome da nação) e uma linha por partida (0x55f990). Depois a tabela de 4 colunas
/// com as linhas que cabem (0x5e5cd0, a altura da fonte 3; quantas no parâmetro 0xf, o primeiro item no 0x10),
/// os três botões do alto (0x804030, 6 a 8) e o redesenho dos placares (0x724520).
unsafe extern "C" fn painel_dos_ultimos_placares(topo: *mut i32, base: *mut i32) {
    crate::comparacao::ramo("telas painel dos ultimos placares");
    type T9 = unsafe extern "thiscall" fn(usize, usize, usize, usize, usize, usize, usize, usize, usize, usize) -> usize;
    type T11 = unsafe extern "thiscall" fn(usize, usize, usize, usize, usize, usize, usize, usize, usize, usize, usize, usize) -> usize;
    type T12 = unsafe extern "thiscall" fn(usize, usize, usize, usize, usize, usize, usize, usize, usize, usize, usize, usize, usize) -> usize;
    type T18 = unsafe extern "thiscall" fn(usize, usize, usize, usize, usize, usize, usize, usize, usize, usize, usize, usize, usize, usize, usize, usize, usize, usize, usize) -> usize;
    let titulo: T11 = core::mem::transmute(0x803fd0usize);
    let caixa: T12 = core::mem::transmute(0x804030usize);
    let celula: T11 = core::mem::transmute(0x8040a0usize);
    let texto_da_celula: T9 = core::mem::transmute(0x804100usize);
    let linha: T18 = core::mem::transmute(0x55f990usize);
    let lista: T11 = core::mem::transmute(0x55fba0usize);
    let texto: unsafe extern "C" fn(usize, usize, ...) -> i32 = core::mem::transmute(0x66f4e0usize);
    let cor = |a: usize| *(a as *const u16) as usize;
    let display = || *((0xb74c4c + *(0xb77c7a as *const i16) as isize * 0x300) as *const usize);
    let sm = GERENTE_DE_TELAS;
    const BUF: usize = 0xde1f64;
    let sem_selo = |c: usize| {
        let amistoso: unsafe extern "thiscall" fn(usize, usize) -> u32 = core::mem::transmute(0x5c2990usize);
        let selecao: unsafe extern "thiscall" fn(usize, usize) -> u32 = core::mem::transmute(0x7e6f20usize);
        amistoso(*(0xae2c74 as *const usize), c) == 0 && selecao(*(0xb74434 as *const usize), c) == 0
    };

    let partida = parametro_da_tela(0);
    let entrada = parametro_da_tela(0xe);
    let comp = (*(0xae23d0 as *const usize) as isize + *(entrada as *const i32) as isize * 107) as usize;
    let t = *topo as usize;
    let (esquerda, largura);
    if partida != 0 {
        esquerda = 0x6e;
        largura = 0x30c;
        let mais_de_uma = core::ptr::read_unaligned((entrada + 8) as *const i32) > core::ptr::read_unaligned((entrada + 4) as *const i32);
        let chave = *(comp as *const usize);
        if chave == *(0x9cf668 as *const usize) && mais_de_uma {
            texto(BUF, 0xa16b28, 0xad9c64);
        } else if chave == *(0x9cf684 as *const usize) && mais_de_uma {
            texto(BUF, 0xa16aec, 0xad9c64);
        } else {
            let g = *((comp + 0x52) as *const i8) as i32;
            texto(BUF, 0xa16ac8, g, g, comp + 0x38);
        }
        titulo(sm, 0x6e, t, 0x30c, t + 0x23, 2, 0, 0xc, 3, cor(0xaebdec), BUF, 1);
        if sem_selo(comp) {
            caixa(sm, 0x9b, t, 0x276, t + 0x23, 1, 0, 0xc, 3, cor(0xaebdec), 0, 0x7d0, comp);
        }
        *topo += 0x28;
    } else {
        esquerda = 0x64;
        largura = 0x316;
        nome_da_competicao_no_painel(comp, entrada);
        titulo(sm, 0x64, t, 0x316, t + 0x2d, 2, 0, 0xc, 6, cor(0xaebdec), BUF, 1);
        if sem_selo(comp) {
            caixa(sm, 0x91, t, 0x280, t + 0x2d, 1, 0, 0xc, 6, cor(0xaebdec), 0, 0x7d0, comp);
        }
        *topo += 0x41;
    }

    let md = *(0xb67a50 as *const usize);
    if *((md + 0x2a) as *const i8) > 1 {
        let cabeca = caixa(sm, esquerda + 5, t + 5, esquerda + 0x14, t + 0x19, 0x30, cor(0xaebdea), 0xc, 1, cor(0xae3184), 0, 0, 0);
        let h = lista(display(), 0, 0, 0, 0, 0, 0, 0, 0, 0x30, cor(0xae31aa), cabeca);
        let grupos = core::ptr::read_unaligned((md + 9) as *const i32);
        for i in 0..grupos.max(0) as usize {
            let g = core::ptr::read_unaligned((md + 1) as *const usize) + i * 0x18;
            if *((g + 0x14) as *const u32) == 0 {
                continue;
            }
            let pai = if *((md + 0x29) as *const u8) == 1 {
                h
            } else {
                let tipo = *(g as *const i32);
                match tipo {
                    0 => {
                        texto(BUF, 0xa16284);
                    }
                    1 => {
                        texto(BUF, 0xa16248, 0xad9c64);
                    }
                    3..=7 => {
                        texto(BUF, 0xa16a90, 0xad9c64);
                    }
                    _ => {
                        let nacao = *((0xb63d60 + tipo as isize * 72) as *const usize);
                        if nacao != 0 {
                            copiar_para_o_texto(nacao + 4);
                        } else {
                            texto(BUF, 0xa16a90, 0xad9c64);
                        }
                    }
                }
                let r = linha(display(), 2, 0, 0, 0, 0, 0, 0, 0x10, cor(0xae31aa), cor(0xaebdec), 1, 1, cor(0xaebdea), BUF, 0, 0, 0, h);
                lista(display(), 0, 0, 0, 0, 0, 0, 0, 0, 0x30, cor(0xae31aa), r)
            };
            let mut k = *((g + 4) as *const i32);
            while k <= *((g + 8) as *const i32) {
                let m = (core::ptr::read_unaligned((md + 0xd) as *const usize) as isize + k as isize * 84) as usize;
                if *((m + 0x10) as *const u32) != 0 {
                    let c = (*(0xae23d0 as *const usize) as isize + *(m as *const i32) as isize * 107) as usize;
                    nome_da_competicao_no_painel(c, m);
                    linha(display(), 2, 0, 0, 0, 0, 0, 0, 0x10, cor(0xae31aa), cor(0xaebdec), 1, 1, cor(0xaebdea), BUF, 0, 5, m, pai);
                }
                k += 1;
            }
        }
    }

    let altura: unsafe extern "C" fn(i32) -> i32 = core::mem::transmute(0x5e5cd0usize);
    let a = altura(3);
    let n = ((*base - *topo - 0x10) / a) as u8;
    gravar_parametro_da_tela(0xf, n as usize);
    let mut colunas: [u8; 4] = [0x16, 4, 0x16, 4];
    // a original passa o byte das linhas por cima do ponteiro `base` na pilha (os 3 bytes de cima ficam)
    let linhas = (base as usize & !0xff) | n as usize;
    let tabela = lista(display(), 0x6e, *topo as usize, 0x30c, *base as usize, 4, colunas.as_mut_ptr() as usize, linhas, 0, 2, 0, usize::MAX);
    for s in 0..n as usize {
        let r = celula(sm, tabela, 0, s, 1, 0, 1, 3, cor(0xaebde8), 0, 0, 0) as u16 as i16;
        if s == 0 {
            gravar_parametro_da_tela(0x10, r as i32 as usize);
        }
        for _ in 0..3 {
            texto_da_celula(sm, tabela, 1, s, 1, 0, 0xc, 3, cor(0xaebdec), 0);
        }
        celula(sm, tabela, 2, s, 1, 0, 1, 3, cor(0xaebde8), 0, 0, 0);
        texto_da_celula(sm, tabela, 3, s, 1, 0, 0xc, 2, cor(0xae3184), 0);
    }
    let marca = if *(0x9cc2c4 as *const i32) != -1 { 0 } else { 1 };
    caixa(sm, largura - 0x7c, t + 5, largura - 0x68, t + 0x19, 1, cor(0xaebe04), 0xc, marca, cor(0xae3184), 0, 6, 0);
    caixa(sm, largura - 0x66, t + 5, largura - 0x1b, t + 0x19, 1, 0, 0xc, 2, cor(0xaebdec), 0, 7, 0);
    caixa(sm, largura - 0x19, t + 5, largura - 5, t + 0x19, 1, cor(0xaebe04), 0xc, marca, cor(0xae3184), 0, 8, 0);
    let redesenhar: unsafe extern "C" fn() = core::mem::transmute(0x724520usize);
    redesenhar();
}

unsafe extern "thiscall" fn comparar_sem_tela_seguinte(gerente: usize) -> u32 {
    let r = orig::<unsafe extern "thiscall" fn(usize) -> u32>(434)(gerente);
    let n = sem_tela_seguinte(gerente);
    PLACAR.registrar(r == n, || format!("sem_tela_seguinte original={} rust={}", r, n));
    r
}

unsafe extern "C" fn comparar_cor_do_titulo(x: u32) -> u32 {
    let r = orig::<unsafe extern "C" fn(u32) -> u32>(435)(x);
    let n = cor_do_titulo(x);
    PLACAR.registrar(r == n, || format!("cor_do_titulo({:#x}) original={:#x} rust={:#x}", x, r, n));
    r
}

/// O painel é comparado de verdade: as duas desenham a partir do mesmo estado e o gerente de telas, o
/// `Display` da tela atual, os parâmetros (menos o 0x14, a hora que o redesenho 0x724520 grava), o
/// `*topo` e o texto 0xde1f64 têm de sair iguais.
unsafe extern "C" fn comparar_painel_dos_ultimos_placares(topo: *mut i32, base: *mut i32) {
    let o = orig::<unsafe extern "C" fn(*mut i32, *mut i32)>(433);
    let mut reg = regioes_da_tela();
    let vaga = *((GERENTE_DE_TELAS + 0x382a) as *const i16) as isize;
    let bloco = core::ptr::read_unaligned((GERENTE_DE_TELAS as isize + 0x7e2 + vaga * 0x300) as *const usize);
    if bloco != 0 {
        reg.push((bloco, 0xb4));
        reg.push((bloco + 0xb8, 0x200 - 0xb8));
    }
    reg.push((topo as usize, 4));
    reg.push((0xde1f64, 0x100));
    // a lista (0x55fba0) escreve num buffer de rede ([0xae2908] na posicao [0xae290c]): a posicao volta
    // para a segunda rodada escrever no mesmo lugar
    reg.push((0xae290c, 4));
    let (_, _, igual, mo, mr) = crate::comparacao::lado_a_lado(&reg, || o(topo, base), || painel_dos_ultimos_placares(topo, base));
    PLACAR.registrar(igual, || {
        let dif: Vec<String> = mo.0.iter().zip(mr.0.iter()).filter_map(|((a, x), (_, y))| {
            let k = x.iter().zip(y.iter()).position(|(p, q)| p != q)?;
            Some(format!("{:#x}+{:#x}", a, k))
        }).collect();
        format!("painel_dos_ultimos_placares: diferencas em {:?}", dif)
    });
}

// ---------- 186a leva: as telas da partida (4): abrir a tela da partida e as respostas dos últimos placares e das estatísticas do time (match_screens.cpp) ----------

/// O bloco de parâmetros da tela atual ([gerente + 0x7e2 + 0x300 x vaga]; o parâmetro k em +0x14 + 8k,
/// a marca de "liberar ao trocar" em +0x18 + 8k, 60 parâmetros) e as marcas 0xb6b7a8/ac/b0.
unsafe fn regioes_dos_parametros() -> Vec<(usize, usize)> {
    let vaga = *((GERENTE_DE_TELAS + 0x382a) as *const i16) as isize;
    let bloco = core::ptr::read_unaligned((GERENTE_DE_TELAS as isize + 0x7e2 + vaga * 0x300) as *const usize);
    let mut r = vec![(0xb6b7a8, 12)];
    if bloco != 0 {
        r.push((bloco, 0x200));
    }
    r
}

/// O id do item `item` na lista de exibição do humano da vez (0 vira o padrão [0xdd6bde]).
unsafe fn id_do_item(item: i16) -> u16 {
    let display = *((0xb74c4c + *(0xb77c7a as *const i16) as isize * 0x300) as *const usize);
    let w = core::ptr::read_unaligned((display as isize + item as isize * 0x18c + 0xba966) as *const u16);
    if w == 0 { *(0xdd6bde as *const u16) } else { w }
}

/// { 0x718aa0 } (cdecl, match_screens.cpp): abre a tela da partida `partida` na vaga `vaga` (0x7fe4a0
/// com a montagem 0x718e90, a resposta 0x71a240 e o fechamento 0x71b120) e grava os parâmetros dela
/// (0x7ff130; o 0xe é [partida+0x63]); marca o humano da vez como espectador ([[partida+0x5b]+0xc5+4h],
/// contando em +0x108) e, sem confirmação ([partida+0x57]), confirma pela rede (0x6b5260) e, se
/// confirmou, grava 2 no parâmetro 1. Vaga ou partida nula: a original (caixa de erro).
unsafe extern "C" fn abrir_tela_da_partida(vaga: u32, partida: usize) {
    if vaga == 0 || partida == 0 {
        return orig::<unsafe extern "C" fn(u32, usize)>(430)(vaga, partida);
    }
    crate::comparacao::ramo("telas abrir a partida");
    let abrir: unsafe extern "thiscall" fn(usize, u32, usize, usize, u32, usize, u32) -> u32 = core::mem::transmute(0x7fe4a0usize);
    if abrir(GERENTE_DE_TELAS, vaga, 0x718e90, 0x71a240, 1, 0x71b120, 0) == 0 {
        return;
    }
    let gravar: unsafe extern "thiscall" fn(usize, u32, u32, usize, u32) = core::mem::transmute(0x7ff130usize);
    const M: usize = usize::MAX;
    let e = *((partida + 0x63) as *const usize);
    for (k, v) in [
        (0u32, partida), (1, 1), (2, 1), (3, M), (4, M), (5, M), (6, M), (7, 0), (8, M), (9, M), (0xa, 3), (0xb, M), (0xc, 0), (0xd, M),
        (0xe, e), (0xf, 0), (0x10, M), (0x11, 1), (0x12, 0), (0x13, 1), (0x14, 0), (0x15, 0), (0x16, 0), (0x17, 0), (0x18, 0), (0x19, 0),
        (0x1a, M), (0x1b, 0), (0x1c, 1), (0x1d, 0), (0x21, M), (0x22, 0), (0x23, M), (0x24, 0), (0x25, 0), (0x26, 0), (0x27, 0),
        (0x28, 0), (0x29, 0), (0x2d, 0), (0x2f, 0), (0x30, 0),
    ] {
        gravar(GERENTE_DE_TELAS, vaga, k, v, 0);
    }
    let espectadores = *((partida + 0x5b) as *const usize);
    let marca = (espectadores as isize + 0xc5 + *(0xb77c7a as *const i16) as isize * 4) as *mut u32;
    if *marca == 0 {
        *marca = 1;
        let n = (espectadores + 0x108) as *mut u8;
        *n = (*n).wrapping_add(1);
    }
    if *((partida + 0x57) as *const u32) == 0 {
        let confirmar: unsafe extern "thiscall" fn(usize, usize) = core::mem::transmute(0x6b5260usize);
        confirmar(*(0xb67a50 as *const usize), partida);
        if *((partida + 0x57) as *const u32) != 0 {
            let gravar_atual: unsafe extern "thiscall" fn(usize, u32, usize, u32) = core::mem::transmute(0x7ff270usize);
            gravar_atual(GERENTE_DE_TELAS, 1, 2, 0);
        }
    }
}

/// { 0x725860 } (cdecl, match_screens.cpp): a resposta do painel dos últimos placares ao item `item`.
/// A cada 5 s (parâmetro 0x14 + 5000 ms, 0x90c510) passa à página seguinte (parâmetro 0x11, de 1 até
/// o 0x13, se não estiver parado pelo 0x12) e, sem [0xb6b7b0], redesenha o painel (0x724520) e liga
/// [0xb6b7a8]. Itens: 5 troca a competição (0xe) e volta à página 1, 6 e 8 a página anterior e a
/// seguinte (em círculo), 7 para ou solta a troca automática; cada um liga [0xb6b7b0]. Devolve 0.
unsafe extern "C" fn responder_ultimos_placares_da_partida(item: u32) -> i32 {
    crate::comparacao::ramo("telas responder ao painel dos placares");
    let pagina = parametro_da_tela(0x11) as u8 as i8;
    let parado = parametro_da_tela(0x12);
    let paginas = parametro_da_tela(0x13) as u8 as i8;
    let quando = parametro_da_tela(0x14) as u32;
    let agora: unsafe extern "C" fn() -> u32 = core::mem::transmute(0x90c510usize);
    let seguinte = if pagina == paginas { 1 } else { (pagina as i32 + 1) as usize };
    if agora() >= quando.wrapping_add(5000) {
        if paginas > 1 && parado == 0 {
            gravar_parametro_da_tela(0x11, seguinte);
        }
        if *(0xb6b7b0 as *const u32) == 0 {
            let redesenhar: unsafe extern "C" fn() = core::mem::transmute(0x724520usize);
            redesenhar();
            *(0xb6b7a8 as *mut u32) = 1;
        }
    }
    let item16 = item as u16 as i16;
    if item16 == -1 {
        return 0;
    }
    let b0 = 0xb6b7b0 as *mut u32;
    if id_do_item(item16) == 5 {
        let display = *((0xb74c4c + *(0xb77c7a as *const i16) as isize * 0x300) as *const usize);
        let dado = core::ptr::read_unaligned((display as isize + item16 as isize * 0x18c + 0xba9a6) as *const usize);
        gravar_parametro_da_tela(0xe, dado);
        gravar_parametro_da_tela(0x11, 1);
        *b0 = 1;
    }
    if id_do_item(item16) == 6 {
        // a página lida no início (a original não relê depois do item 5)
        gravar_parametro_da_tela(0x11, if pagina == 1 { paginas as i32 as usize } else { (pagina as i32 - 1) as usize });
        *b0 = 1;
    }
    if id_do_item(item16) == 7 {
        gravar_parametro_da_tela(0x12, (parado == 0) as usize);
        *b0 = 1;
    }
    if id_do_item(item16) == 8 {
        gravar_parametro_da_tela(0x11, seguinte);
        *b0 = 1;
    }
    0
}

/// { 0x722dc0 } (cdecl, match_screens.cpp): a resposta das estatísticas do time ao item `item`. Com
/// dados novos ([0xb6b7ac]) e a marca 4 do menu da partida ([[parâmetro 0]+0x5b]), sem [0xb6b7b0],
/// redesenha o painel (0x721cd0 com 0 e −1) e liga [0xb6b7a8]; os itens 9 e 0xa descem e sobem a
/// linha do parâmetro 0x1c e ligam [0xb6b7b0]. Devolve 0.
unsafe extern "C" fn responder_estatisticas_do_time(item: u32) -> i32 {
    crate::comparacao::ramo("telas responder as estatisticas do time");
    let p0 = parametro_da_tela(0);
    let linha = parametro_da_tela(0x1c) as u8 as i8;
    if *(0xb6b7ac as *const u32) != 0 && *(*((p0 + 0x5b) as *const usize) as *const u8) & 4 != 0 && *(0xb6b7b0 as *const u32) == 0 {
        let redesenhar: unsafe extern "C" fn(u32, i32) = core::mem::transmute(0x721cd0usize);
        redesenhar(0, -1);
        *(0xb6b7a8 as *mut u32) = 1;
    }
    let item16 = item as u16 as i16;
    if item16 == -1 {
        return 0;
    }
    if id_do_item(item16) == 9 {
        gravar_parametro_da_tela(0x1c, (linha as i32 - 1) as usize);
        *(0xb6b7b0 as *mut u32) = 1;
    }
    if id_do_item(item16) == 0xa {
        gravar_parametro_da_tela(0x1c, (linha as i32 + 1) as usize);
        *(0xb6b7b0 as *mut u32) = 1;
    }
    0
}

// ponytail: abrir a tela mexe em telas e na rede (não roda duas vezes): no modo comparação só a original
unsafe extern "C" fn comparar_abrir_tela_da_partida(vaga: u32, partida: usize) {
    orig::<unsafe extern "C" fn(u32, usize)>(430)(vaga, partida)
}

/// As duas respostas são comparadas de verdade nos cliques (o bloco de parâmetros da tela e as marcas
/// 0xb6b7a8/ac/b0, mais a devolução); quando há redesenho (a troca de 5 s dos placares, os dados novos
/// das estatísticas) só a original roda, porque o redesenho grava a hora no parâmetro 0x14 e mexe na
/// lista de exibição.
unsafe fn comparar_resposta(nome: &str, item: u32, o: unsafe extern "C" fn(u32) -> i32, r: unsafe extern "C" fn(u32) -> i32, redesenha: bool) -> i32 {
    if item as u16 == 0xffff || redesenha {
        return o(item);
    }
    let (ro, rr, igual, mo, mr) = crate::comparacao::lado_a_lado(&regioes_dos_parametros(), || o(item), || r(item));
    PLACAR.registrar(igual && ro == rr, || format!("{}(item {:#x}) original={} rust={} {:?} x {:?}", nome, item, ro, rr, mo, mr));
    ro
}

unsafe extern "C" fn comparar_responder_ultimos_placares_da_partida(item: u32) -> i32 {
    let agora: unsafe extern "C" fn() -> u32 = core::mem::transmute(0x90c510usize);
    // folga de 1 s: a hora pode virar entre os dois lados
    let redesenha = agora().wrapping_add(1000) >= (parametro_da_tela(0x14) as u32).wrapping_add(5000);
    comparar_resposta("responder_ultimos_placares_da_partida", item, orig(431), responder_ultimos_placares_da_partida, redesenha)
}

unsafe extern "C" fn comparar_responder_estatisticas_do_time(item: u32) -> i32 {
    let p0 = parametro_da_tela(0);
    let redesenha = *(0xb6b7ac as *const u32) != 0 && *(*((p0 + 0x5b) as *const usize) as *const u8) & 4 != 0;
    comparar_resposta("responder_estatisticas_do_time", item, orig(432), responder_estatisticas_do_time, redesenha)
}

// ---------- 185a leva: a marca de contrato acertado e a vaga da oferta (transfer_manager.cpp) ----------

/// O byte das marcas da pessoa `*id` no gerente de transferências (+0x86e, 8 bytes por pessoa).
unsafe fn marcas_da_pessoa(gerente: usize, id: *const i32) -> *mut u8 {
    (*((gerente + 0x86e) as *const usize) as isize + *id as isize * 8) as *mut u8
}

/// { 0x8c5410 } (thiscall, ret 4, transfer_manager.cpp): liga a marca de contrato acertado (0x40).
unsafe extern "thiscall" fn marcar_contrato_acertado(gerente: usize, id: *const i32) {
    *marcas_da_pessoa(gerente, id) |= 0x40;
}

/// { 0x8c5430 } (thiscall, ret 4, transfer_manager.cpp): desliga a marca de contrato acertado.
unsafe extern "thiscall" fn desmarcar_contrato_acertado(gerente: usize, id: *const i32) {
    *marcas_da_pessoa(gerente, id) &= 0xbf;
}

/// { 0x8c61e0 } (thiscall, ret 4, transfer_manager.cpp): o endereço da vaga `k` das ofertas (+0,
/// +4 quantas); fora da faixa, o próprio começo da tabela (o valor de +0, não o endereço).
unsafe extern "thiscall" fn vaga_da_oferta(tabela: usize, k: i32) -> usize {
    let base = *(tabela as *const usize);
    if k < *((tabela + 4) as *const i32) { (base as isize + 4 * k as isize) as usize } else { base }
}

unsafe extern "thiscall" fn comparar_marcar_contrato_acertado(gerente: usize, id: *const i32) {
    let o = orig::<unsafe extern "thiscall" fn(usize, *const i32)>(427);
    let a = marcas_da_pessoa(gerente, id) as usize;
    let (_, _, igual, mo, mr) = crate::comparacao::lado_a_lado(&[(a, 1)], || o(gerente, id), || marcar_contrato_acertado(gerente, id));
    PLACAR.registrar(igual, || format!("marcar_contrato_acertado({}) {:x?} x {:x?}", *id, mo, mr));
}

unsafe extern "thiscall" fn comparar_desmarcar_contrato_acertado(gerente: usize, id: *const i32) {
    let o = orig::<unsafe extern "thiscall" fn(usize, *const i32)>(428);
    let a = marcas_da_pessoa(gerente, id) as usize;
    let (_, _, igual, mo, mr) = crate::comparacao::lado_a_lado(&[(a, 1)], || o(gerente, id), || desmarcar_contrato_acertado(gerente, id));
    PLACAR.registrar(igual, || format!("desmarcar_contrato_acertado({}) {:x?} x {:x?}", *id, mo, mr));
}

unsafe extern "thiscall" fn comparar_vaga_da_oferta(tabela: usize, k: i32) -> usize {
    let r = orig::<unsafe extern "thiscall" fn(usize, i32) -> usize>(429)(tabela, k);
    let n = vaga_da_oferta(tabela, k);
    PLACAR.registrar(r == n, || format!("vaga_da_oferta({}) original={:#x} rust={:#x}", k, r, n));
    r
}

// ---------- 184a leva: a disciplina (discipline.cpp): a temporada nova, o dia e a vaga da tabela ----------

/// { 0x556210 } (thiscall, ret 4, discipline.cpp): começa a temporada nova da competição `*id`: as
/// regras da disciplina dela (índice +0x50 da competição em [0xadadfc], 0xff sem) recebem o método 0
/// da tabela virtual.
unsafe extern "thiscall" fn disciplina_temporada_nova(this: usize, id: *const i32) {
    let competicao = *((*(0xadadfc as *const usize) as isize + 4 * *id as isize) as *const usize);
    if competicao == 0 {
        return;
    }
    let k = *((competicao + 0x50) as *const i8);
    if k == -1 {
        return;
    }
    let regras = *((*(this as *const usize) as isize + 4 * k as isize) as *const usize);
    if regras != 0 {
        let metodo: unsafe extern "thiscall" fn(usize) = core::mem::transmute(*(*(regras as *const usize) as *const usize));
        metodo(regras);
    }
}

/// { 0x556240 } (thiscall, ret 4, discipline.cpp): o dia da disciplina: cada uma das 43 regras ([this],
/// as não nulas) recebe o método 1 da tabela virtual com a data `hoje`.
unsafe extern "thiscall" fn disciplina_do_dia(this: usize, hoje: usize) {
    for k in 0..43usize {
        let regras = *((*(this as *const usize) + 4 * k) as *const usize);
        if regras != 0 {
            let metodo: unsafe extern "thiscall" fn(usize, usize) = core::mem::transmute(*((*(regras as *const usize) + 4) as *const usize));
            metodo(regras, hoje);
        }
    }
}

/// { 0x55cb20 } (thiscall, ret 0x10, discipline.cpp): grava a vaga `vaga` (5 bytes: o byte `tipo` e o
/// valor) da pessoa `id` na tabela +0x14 (29 bytes por pessoa).
unsafe extern "thiscall" fn disciplina_gravar_vaga(this: usize, id: i32, vaga: i8, tipo: u8, valor: u32) {
    let a = (*((this + 0x14) as *const usize) as isize + id as isize * 29 + vaga as isize * 5) as usize;
    *(a as *mut u8) = tipo;
    core::ptr::write_unaligned((a + 1) as *mut u32, valor);
}

// ponytail: as duas primeiras só despacham pela tabela virtual (efeitos fora): provadas pela carreira
unsafe extern "thiscall" fn comparar_disciplina_temporada_nova(this: usize, id: *const i32) {
    orig::<unsafe extern "thiscall" fn(usize, *const i32)>(424)(this, id)
}

unsafe extern "thiscall" fn comparar_disciplina_do_dia(this: usize, hoje: usize) {
    orig::<unsafe extern "thiscall" fn(usize, usize)>(425)(this, hoje)
}

unsafe extern "thiscall" fn comparar_disciplina_gravar_vaga(this: usize, id: i32, vaga: i8, tipo: u8, valor: u32) {
    let o = orig::<unsafe extern "thiscall" fn(usize, i32, i8, u8, u32)>(426);
    let a = (*((this + 0x14) as *const usize) as isize + id as isize * 29 + vaga as isize * 5) as usize;
    let (_, _, igual, mo, mr) = crate::comparacao::lado_a_lado(&[(a, 5)], || o(this, id, vaga, tipo, valor), || disciplina_gravar_vaga(this, id, vaga, tipo, valor));
    PLACAR.registrar(igual, || format!("disciplina_gravar_vaga({}, {}) {:x?} x {:x?}", id, vaga, mo, mr));
}

// ---------- 183a leva: as telas da partida (3): a tela de detalhes da partida (match_screens.cpp) ----------

/// Lê e grava os parâmetros da tela atual do gerente de telas [0xb74450] (0x7ff010, 0x7ff270).
unsafe fn parametro_da_tela(k: u32) -> usize {
    let ler: unsafe extern "thiscall" fn(usize, u32) -> usize = core::mem::transmute(0x7ff010usize);
    ler(0xb74450, k)
}
unsafe fn gravar_parametro_da_tela(k: u32, v: usize) {
    let gravar: unsafe extern "thiscall" fn(usize, u32, usize, u32) = core::mem::transmute(0x7ff270usize);
    gravar(0xb74450, k, v, 0);
}

/// { 0x71b4a0 } (cdecl, match_screens.cpp): abre a tela de detalhes da partida `partida` (0x7fe600 com a
/// montagem 0x71b630, a resposta 0x71bdc0 e o fechamento 0x71c170) e grava os parâmetros dela (a
/// partida em 0x1e; a aba 2 começa em 6).
unsafe extern "C" fn abrir_detalhes_da_partida(partida: usize) {
    crate::comparacao::ramo("telas abrir os detalhes");
    let abrir: unsafe extern "thiscall" fn(usize, usize, usize, u32, usize, u32) -> u32 = core::mem::transmute(0x7fe600usize);
    if abrir(0xb74450, 0x71b630, 0x71bdc0, 0, 0x71c170, 0) == 0 {
        return;
    }
    const MENOS1: usize = usize::MAX;
    for (k, v) in [
        (0u32, 0usize), (2, 6), (9, MENOS1), (0xa, 3), (0xb, MENOS1), (0xc, 0), (0xd, MENOS1), (0x16, 0), (0x17, 0), (0x18, 0), (0x19, 0),
        (0x1a, MENOS1), (0x1b, 0), (0x1c, 1), (0x1d, 0), (0x1e, partida), (0x1f, 0), (0x20, 0), (0x21, MENOS1), (0x22, 0), (0x23, MENOS1), (0x2d, 0),
    ] {
        gravar_parametro_da_tela(k, v);
    }
}

/// { 0x71bdc0 } (cdecl, match_screens.cpp): a resposta da tela de detalhes ao item `item` (−1 nenhum).
/// Sem [0xb77c84]: zera 0xb6b7a8/ac/b0; um item de id 1 (ou [0xdd6bde]) troca a aba (parâmetro 2) pelo
/// dado do item (+0x48 do item no `Display` do humano da vez) e pede −11; de id 2 abre a tática do clube
/// do item (0x899a50) e devolve −4. Depois, pela aba: 1 posse (0x71d9e0), 2 estatísticas (0x71e750), 3
/// zonas de ação (0x720320; e um item de id 4 troca a ação do parâmetro 0xa), 4 relatório, 5 e 7 as
/// estatísticas do time (0x722dc0), 6 as notas (0x723350); os redesenhos só com a marca 4 do menu da
/// partida ([[parâmetro 0]+0x5b]) e [0xb6b7ac]. Por fim −11, o redesenho (0x802d00) e a barra de menu.
unsafe extern "C" fn responder_detalhes_da_partida(item: u32) -> i32 {
    crate::comparacao::ramo("telas responder aos detalhes");
    let g = |a: usize| *(a as *const u32);
    let item16 = item as u16 as i16;
    let display_do_humano = || *((0xb74c4c + *(0xb77c7a as *const i16) as isize * 0x300) as *const usize);
    let id_ou_padrao = |w: u16| if w == 0 { *(0xdd6bde as *const u16) } else { w };
    if g(0xb77c84) == 0 {
        let aba = parametro_da_tela(2) as u8 as i8;
        let v1e = parametro_da_tela(0x1e);
        let p1f = parametro_da_tela(0x1f);
        *(0xb6b7ac as *mut u32) = 0;
        *(0xb6b7b0 as *mut u32) = 0;
        *(0xb6b7a8 as *mut u32) = 0;
        if item16 != -1 {
            let deslocamento = item16 as isize * 0x18c;
            let registro = |d: usize| (d as isize + deslocamento) as usize;
            let e = registro(display_do_humano());
            if id_ou_padrao(core::ptr::read_unaligned((e + 0xba966) as *const u16)) == 1 {
                let dado = core::ptr::read_unaligned((e + 0xba9a6) as *const usize);
                if dado != parametro_da_tela(2) {
                    gravar_parametro_da_tela(2, dado);
                    *(0xb6b7b0 as *mut u32) = 1;
                }
            }
            let e = registro(display_do_humano());
            if id_ou_padrao(core::ptr::read_unaligned((e + 0xba966) as *const u16)) == 2 {
                let clube = core::ptr::read_unaligned((e + 0xba9a6) as *const usize);
                let marca = if clube == *((p1f + 0x1c) as *const usize) { *((p1f + 0x40) as *const u8) } else { *((p1f + 0x41) as *const u8) };
                let tatica: unsafe extern "C" fn(usize, u32, u32, u32, usize, u32) = core::mem::transmute(0x899a50usize);
                tatica(clube, (marca == 0) as u32, 0, 0, v1e, 0);
                return -4;
            }
        }
        let menu_da_partida = |bit: u8| {
            let p = parametro_da_tela(0);
            g(0xb6b7ac) != 0 && *(*((p + 0x5b) as *const usize) as *const u8) & bit != 0
        };
        let refazer = |f: usize| -> bool {
            // os redesenhos de aba: com a marca 4; com [0xb6b7b0] ligado a resposta é −11
            if g(0xb6b7b0) != 0 {
                return true;
            }
            let r: unsafe extern "C" fn() = core::mem::transmute(f);
            r();
            *(0xb6b7a8 as *mut u32) = 1;
            false
        };
        let estatisticas_do_time: unsafe extern "C" fn(u32) -> i32 = core::mem::transmute(0x722dc0usize);
        match aba {
            1 => {
                let p = parametro_da_tela(0);
                if g(0xb6b7ac) != 0 {
                    let m = *(*((p + 0x5b) as *const usize) as *const u8);
                    if m & 0x20 != 0 || m & 0x10 != 0 {
                        *(0xb6b7b0 as *mut u32) = 1;
                    }
                    if m & 4 != 0 && refazer(0x71d9e0) {
                        return -11;
                    }
                }
            }
            2 => {
                if menu_da_partida(4) && refazer(0x71e750) {
                    return -11;
                }
            }
            3 => {
                if menu_da_partida(4) && g(0xb6b7b0) == 0 {
                    refazer(0x720320);
                }
                if item16 != -1 {
                    let d = display_do_humano();
                    let id: unsafe extern "thiscall" fn(usize, u32) -> u16 = core::mem::transmute(0x468b10usize);
                    if id_ou_padrao(id(d, item)) == 4 {
                        let dado: unsafe extern "thiscall" fn(usize, u32) -> usize = core::mem::transmute(0x4739a0usize);
                        if dado(d, item) != parametro_da_tela(0xa) {
                            let acao: unsafe extern "thiscall" fn(usize, u32) -> usize = core::mem::transmute(0x468b90usize);
                            gravar_parametro_da_tela(0xa, acao(0xb74450, item));
                            *(0xb6b7b0 as *mut u32) = 1;
                            return -11;
                        }
                    }
                }
            }
            4 => {
                if menu_da_partida(0x20) {
                    *(0xb6b7b0 as *mut u32) = 1;
                    return -11;
                }
            }
            5 | 7 => {
                let r = estatisticas_do_time(item);
                if r != 0 {
                    return r;
                }
            }
            6 => {
                if menu_da_partida(4) && refazer(0x723350) {
                    return -11;
                }
            }
            _ => {}
        }
        if g(0xb6b7b0) != 0 {
            return -11;
        }
        if g(0xb6b7a8) != 0 {
            let redesenhar: unsafe extern "thiscall" fn(usize, u32, u32) = core::mem::transmute(0x802d00usize);
            redesenhar(0xb74450, 0, 0);
        }
    }
    let comando: unsafe extern "C" fn(u32) -> i32 = core::mem::transmute(0x7615d0usize);
    let r = comando(item);
    if r != 0 {
        return r;
    }
    let ligacao: unsafe extern "C" fn(u32) -> i32 = core::mem::transmute(0x7643d0usize);
    ligacao(item)
}

/// { 0x71c170 } (cdecl, match_screens.cpp): fecha a tela de detalhes: os parâmetros 0x2d (0x5a8f60),
/// 0x1d e 0x20 (0x453bc0) são destruídos e liberados, o 0x1f só liberado (0x944c94), e todos zerados.
unsafe extern "C" fn fechar_detalhes_da_partida() {
    crate::comparacao::ramo("telas fechar os detalhes");
    let liberar: unsafe extern "C" fn(usize) = core::mem::transmute(0x944c94usize);
    for (k, destrutor) in [(0x2du32, Some(0x5a8f60usize)), (0x1d, Some(0x453bc0)), (0x1f, None), (0x20, Some(0x453bc0))] {
        if parametro_da_tela(k) == 0 {
            continue;
        }
        let p = parametro_da_tela(k);
        match destrutor {
            Some(d) => {
                if p != 0 {
                    let destruir: unsafe extern "thiscall" fn(usize) = core::mem::transmute(d);
                    destruir(p);
                    liberar(p);
                }
            }
            None => liberar(p),
        }
        gravar_parametro_da_tela(k, 0);
    }
}

